(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("josephus-antiquities-5-e", [{"sp": "HDR", "t": "Ἰουδαϊκὴ Ἀρχαιολογία"}, {"sp": "HDR", "t": "Βιβλίον ΙΕʹ", "st": "15"}, {"sp": "N", "t": "Σόσσιος μὲν οὖν καὶ Ἡρώδης ὡς κατὰ κράτος ἔλαβον Ἱεροσόλυμα καὶ πρὸς τούτοις αἰχμάλωτον Ἀντίγονον, ἡ πρὸ ταύτης ἡμῖν ἐδήλωσεν βίβλος· τὰ δ’ ἐκείνῃ συνεχῆ νῦν ἐροῦμεν. ἐπειδὴ γὰρ τῆς ὅλης Ἰουδαίας ἐνεχειρίσθη τὴν ἀρχὴν Ἡρώδης, τοῦ κατὰ τὴν πόλιν πλήθους ὅσοι μὲν ἦσαν ἰδιωτεύοντες ἔτι τἀκείνου φρονοῦντες ἐν προαγωγῇ τούτους ἐποιεῖτο, τοὺς δὲ τὰ τῶν ἐναντίων ἑλομένους οὐκ ἐπέλιπε τιμωρούμενος καὶ κολάζων καθ’ ἑκάστην ἡμέραν. ἐτιμῶντο δὲ μάλιστα παρ’ αὐτῷ Πολλίων ὁ Φαρισαῖος καὶ Σαμαίας ὁ τούτου μαθητής· πολιορκουμένων γὰρ τῶν Ἱεροσολύμων οὗτοι συνεβούλευον τοῖς πολίταις δέξασθαι τὸν Ἡρώδην, ἀνθ’ ὧν καὶ τὰς ἀμοιβὰς ἀπελάμβανον. ὁ δὲ Πολλίων οὗτος καὶ κρινομένου ποτὲ Ἡρώδου τὴν ἐπὶ θανάτῳ προεῖπεν ὀνειδίζων Ὑρκανῷ καὶ τοῖς δικάζουσιν, ὡς περισωθεὶς Ἡρώδης ἅπαντας αὐτοὺς ἐπεξελεύσεται· καὶ τοῦτο χρόνῳ προύβη τοῦ θεοῦ τοὺς λόγους αὐτοῦ τελειώσαντος.", "st": "15.1.1"}, {"sp": "N", "t": "Ἐν δὲ τῷ τότε κρατήσας τῶν Ἱεροσολύμων πάντα συνεφόρει τὸν ἐν τῇ βασιλείᾳ κόσμον ἔτι καὶ τοὺς εὐπόρους ἀφαιρούμενος, καὶ συναγαγὼν πλῆθος ἀργυρίου καὶ χρυσίου παντὶ τούτῳ τὸν Ἀντώνιον ἐδωρεῖτο καὶ τοὺς περὶ αὐτὸν φίλους. ἀπέκτεινε δὲ τεσσαρακονταπέντε τοὺς πρώτους ἐκ τῆς αἱρέσεως Ἀντιγόνου φύλακας περιστήσας ταῖς πύλαις τῶν τειχῶν, ἵνα μή τις συνεκκομισθῇ τοῖς τεθνεῶσι, καὶ τοὺς νεκροὺς ἠρεύνων, καὶ πᾶν τὸ εὑρισκόμενον ἀργύριον ἢ χρυσίον ἤ τι κειμήλιον ἀνεφέρετο τῷ βασιλεῖ, πέρας τε κακῶν οὐδὲν ἦν· τὰ μὲν γὰρ ἡ πλεονεξία τοῦ κρατοῦντος ἐν χρείᾳ γεγενημένου διεφόρει, τὴν δὲ χώραν μένειν ἀγεώργητον τὸ ἑβδοματικὸν ἠνάγκαζεν ἔτος· ἐνεστήκει γὰρ τότε, καὶ σπείρειν ἐν ἐκείνῳ τὴν γῆν ἀπηγορευμένον ἐστὶν ἡμῖν. Ἀντώνιος δὲ λαβὼν αἰχμάλωτον τὸν Ἀντίγονον δέσμιον ἔγνω μέχρι θριάμβου φυλάττειν, ἐπεὶ δ’ ἤκουσεν νεωτερίζειν τὸ ἔθνος κἀκ τοῦ πρὸς Ἡρώδην μίσους εὔνουν Ἀντιγόνῳ διαμένον, ἔγνω τοῦτον ἐν Ἀντιοχείᾳ πελεκίσαι· σχεδὸν γὰρ οὐδαμῶς ἠρεμεῖν ἠδύναντο οἱ Ἰουδαῖοι. μαρτυρεῖ δέ μου τῷ λόγῳ Στράβων ὁ Καππάδοξ λέγων οὕτως· Ἀντώνιος δὲ Ἀντίγονον τὸν Ἰουδαῖον ἀχθέντα εἰς Ἀντιόχειαν πελεκίζει. καὶ ἔδοξε μὲν οὗτος πρῶτος Ῥωμαίων βασιλέα πελεκίσαι, οὐκ οἰηθεὶς ἕτερον τρόπον μεταθεῖναι ἂν τὰς γνώμας τῶν Ἰουδαίων, ὥστε δέξασθαι τὸν ἀντ’ ἐκείνου καθεσταμένον Ἡρώδην· οὐδὲ γὰρ βασανιζόμενοι βασιλέα ἀναγορεύειν αὐτὸν ὑπέμειναν· οὕτως μέγα τι ἐφρόνουν περὶ τοῦ πρώτου βασιλέως. τὴν οὖν ἀτιμίαν ἐνόμισε μειώσειν τῆς πρὸς αὐτὸν μνήμης, μειώσειν δὲ καὶ τὸ πρὸς Ἡρώδην μῖσος. ταῦτα μὲν ὁ Στράβων.", "st": "15.1.2"}, {"sp": "N", "t": "Κατασχόντος δὲ τὴν βασιλείαν Ἡρώδου πυθόμενος Ὑρκανὸς ὁ ἀρχιερεύς, ἦν δὲ παρὰ Πάρθοις αἰχμάλωτος, ἀφικνεῖται πρὸς Ἡρώδην τῆς αἰχμαλωσίας ἀπολυθεὶς τρόπῳ τοιούτῳ· Βαζαφράνης καὶ Πάκορος οἱ τῶν Πάρθων στρατηγοί, λαβόντες αἰχμαλώτους Ὑρκανὸν τὸν πρῶτον ἀρχιερέα γενόμενον εἶτα βασιλέα καὶ τὸν ἀδελφὸν Ἡρώδου Φασάηλον εἰς Πάρθους ἀνῆγον. καὶ Φασάηλος μὲν οὐ φέρων τὴν ἐν τοῖς δεσμοῖς αἰσχύνην, πάσης δὲ ζωῆς κρείττονα τὸν μετὰ δόξης ἡγούμενος θάνατον αὐτὸς ἑαυτοῦ γίνεται φονεύς, καθὼς προεῖπον.", "st": "15.2.1"}, {"sp": "N", "t": "Ὑρκανῷ δ’ ἀναχθέντι Φραάτης ὁ τῶν Πάρθων βασιλεὺς ἐπ’ αὐτὸν ἐπιεικέστερον προσηνέχθη, τὸ τῆς εὐγενείας αὐτοῦ διάσημον προπεπυσμένος. διὰ τοῦτο δεσμῶν μὲν ἀφῆκεν, ἐν Βαβυλῶνι δὲ κατάγεσθαι παρεῖχεν, ἔνθα καὶ πλῆθος ἦν Ἰουδαίων. οὗτοι τὸν Ὑρκανὸν ἐτίμων ὡς ἀρχιερέα καὶ βασιλέα καὶ πᾶν τὸ μέχρις Εὐφράτου νεμόμενον Ἰουδαίων ἔθνος· τῷ δ’ ἦν ἀγαπητὰ ταῦτα. πυθόμενος δὲ τὸν Ἡρώδην παρειληφέναι τὴν βασιλείαν ἀντιμετεχώρει ταῖς ἐλπίσιν ἐξ ἀρχῆς τε φιλοστόργως διακείμενος καὶ τῆς χάριτος ἀπομνησθήσεσθαι προσδοκῶν, κρινόμενον ὅτι καὶ μέλλοντα θανάτῳ ζημιοῦσθαι τοῦ κινδύνου καὶ τῆς κολάσεως ἐρρύσατο. λόγους οὖν προσέφερε τοῖς Ἰουδαίοις ἰέναι παρ’ αὐτὸν ἐσπουδακώς. οἱ δὲ περιείχοντο καὶ μένειν ἠξίουν τὰς ὑπουργίας ἅμα καὶ τὰς τιμὰς λέγοντες, ὡς οὐδὲν ἐνδεὲς αὐτῷ τῆς εἰς τοὺς ἀρχιερεῖς ἢ βασιλεῖς τιμῆς ἐξ αὐτῶν εἴη, καὶ τὸ μεῖζον, ὅτι μηδὲ ἐκεῖ τούτων μεταλαβεῖν δύναται κατὰ λώβην τοῦ σώματος, ἣν ὑπ’ Ἀντιγόνου πάθοι, τάς τε χάριτας οὐχ ὁμοίως ἀποδίδοσθαι παρὰ τῶν βασιλέων, ἃς ἔλαβον ἰδιωτεύοντες, ἐξαλλαττούσης αὐτοὺς οὐκ ἀλόγως τῆς τύχης.", "st": "15.2.2"}, {"sp": "N", "t": "Τοιαῦτα κατὰ τὸ συμφέρον ὑποτεινόντων Ὑρκανὸς πόθον εἶχεν ἀπιέναι, καὶ γράφων Ἡρώδης παρεκάλει δεῖσθαι Φραάτου καὶ τῶν ἐκεῖ Ἰουδαίων μὴ φθονῆσαι δυνάμει κοινὴν ἕξοντι τὴν βασιλείαν· ἄρτι γὰρ εἶναι καιρὸν αὐτῷ μὲν ἐκτῖσαι τὰς χάριτας ὧν εὖ πάθοι καὶ τραφεὶς ὑπ’ αὐτοῦ καὶ περισωθείς, ἐκείνῳ δὲ κομίζεσθαι. ταῦτα γράφων Ὑρκανῷ πέμπει καὶ παρὰ τὸν Φραάτην πρεσβευτὴν Σαραμάλλαν καὶ δῶρα πλείω, μὴ διακωλῦσαι τὰς εἰς τὸν εὐεργέτην αὐτοῦ χάριτας ὁμοίως φιλανθρωπευόμενον. ἦν δ’ οὐκ ἐντεῦθεν ἡ σπουδή, διὰ δὲ τὸ μὴ κατ’ ἀξίαν αὐτὸς ἄρχειν δεδοίκει τὰς ἐξ εὐλόγων μεταβολὰς καὶ τὸν Ὑρκανὸν ὑποχείριον ἔχειν ἔσπευδεν ἢ καὶ παντάπασιν ἐκποδὼν ποιήσασθαι· τοῦτο γὰρ ἔπραξεν ἐν ὑστέρῳ.", "st": "15.2.3"}, {"sp": "N", "t": "Τότε μέντοι γε ἐπειδὴ παρῆν πεπεισμένος ἐφέντος τε τοῦ Πάρθου καὶ τῶν Ἰουδαίων χρήματα παρασχομένων, ἁπάσῃ τιμῇ δεξάμενος αὐτὸν ἔν τε τοῖς συλλόγοις τὸν πρῶτον ἔνεμε τόπον καὶ παρὰ τὰς ἑστιάσεις προκατακλίνων ἐξηπάτα πατέρα καλῶν καὶ παντοδαπῶς τὸ τῆς ἐπιβουλῆς ἀνύποπτον πραγματευόμενος. ὑποκαθίστατο δὲ καὶ τἆλλα πρὸς τὸ συμφέρον τῆς ἀρχῆς, ἐξ ὧν αὐτῷ καὶ τὰ περὶ τὴν οἰκίαν ἐστασιάσθη· φυλαττόμενος γάρ τινα τῶν ἐπισήμων ἀποδεικνύειν ἀρχιερέα τοῦ θεοῦ, μεταπεμψάμενος ἐκ τῆς Βαβυλῶνος ἱερέα τῶν ἀσημοτέρων Ἀνάνηλον ὀνόματι τούτῳ τὴν ἀρχιερωσύνην δίδωσιν.", "st": "15.2.4"}, {"sp": "N", "t": "Εὐθὺς οὖν οὐκ ἤνεγκεν Ἀλεξάνδρα τὴν ἐπήρειαν, θυγάτηρ μὲν Ὑρκανοῦ, γυνὴ δὲ Ἀλεξάνδρου τοῦ Ἀριστοβούλου βασιλέως, ἐξ Ἀλεξάνδρου παῖδας ἔχουσα τὸν μὲν ὥρᾳ κάλλιστον Ἀριστόβουλον καλούμενον, τὴν δὲ Ἡρώδῃ συνοικοῦσαν Μαριάμμην εὐμορφίᾳ διάσημον. ἐτετάρακτο δὲ καὶ χαλεπῶς ἔφερεν τὴν ἀτιμίαν τοῦ παιδός, εἰ περιόντος ἐκείνου τῶν ἐπικλήτων τις ἀξιοῦται τῆς ἀρχιερωσύνης, καὶ γράφει Κλεοπάτρᾳ μουσουργοῦ τινος αὐτῇ συμπραγματευομένου τὰ περὶ τὴν κομιδὴν τῶν γραμμάτων αἰτεῖσθαι παρ’ Ἀντωνίου τῷ παιδὶ τὴν ἀρχιερωσύνην.", "st": "15.2.5"}, {"sp": "N", "t": "Ἀντωνίου δὲ ῥαθυμότερον ὑπακούοντος, ὁ φίλος αὐτοῦ Δέλλιος εἰς Ἰουδαίαν ἐλθὼν ἐπί τινας χρείας ὡς εἶδεν τὸν Ἀριστόβουλον, ἠγάσθη τε τῆς ὥρας καὶ τὸ μέγεθος καὶ κάλλος τοῦ παιδὸς ἐθαύμασεν, οὐχ ἧττον δὲ τὴν Μαριάμμην συνοικοῦσαν τῷ βασιλεῖ, καὶ δῆλος ἦν καλλίπαιδά τινα τὴν Ἀλεξάνδραν διειληφώς. ἐκείνης δὲ εἰς λόγους ἐλθούσης αὐτῷ πείθει γραψαμένην ἀμφοτέρων εἰκόνας Ἀντωνίῳ διαπέμψασθαι· θεασαμένου γὰρ οὐδενὸς ἀτευκτήσειν ὧν ἀξιοῖ. τούτοις ἐπαρθεῖσα τοῖς λόγοις Ἀλεξάνδρα πέμπει τὰς εἰκόνας Ἀντωνίῳ· καὶ Δέλλιος ἐτερατεύετο λέγων οὐκ ἐξ ἀνθρώπων αὐτῷ δοκεῖν, ἀλλά τινος θεοῦ γενέσθαι τοὺς παῖδας. ἐπραγματεύετο δὲ δι’ ἑαυτοῦ πρὸς τὰς ἡδονὰς ἑλκύσαι τὸν Ἀντώνιον. ὁ δὲ τὴν μὲν κόρην ᾐδέσθη μεταπέμπεσθαι γεγαμημένην Ἡρώδῃ καὶ τὰς εἰς Κλεοπάτραν ἐκ τοῦ τοιούτου διαβολὰς φυλαττόμενος, ἐπέστελλε δὲ πέμπειν τὸν παῖδα σὺν εὐπρεπείᾳ προστιθείς, εἰ μὴ βαρὺ δοκοίη. τούτων ἀπενεχθέντων πρὸς Ἡρώδην οὐκ ἀσφαλὲς ἔκρινεν ὥρᾳ τε κάλλιστον ὄντα τὸν Ἀριστόβουλον ἑκκαιδεκαέτης γὰρ ὢν ἐτύγχανεν, καὶ γένει προύχοντα πέμπειν παρὰ τὸν Ἀντώνιον, ἰσχύοντα μὲν ὡς οὐκ ἄλλος ἐν τῷ τότε Ῥωμαίων, ἕτοιμον δὲ τοῖς ἐρωτικοῖς αὐτὸν ὑποθεῖναι καὶ τὰς ἡδονὰς ἀπαρακαλύπτως ἐκ τοῦ δύνασθαι ποριζόμενον. ἀντέγραψεν οὖν ὡς, εἰ μόνον ἐξέλθοι τῆς χώρας τὸ μειράκιον, ἅπαντα πολέμου καὶ ταραχῆς ἀναπλησθήσεται Ἰουδαίων ἐλπισάντων μεταβολὴν καὶ νεωτερισμὸν ἐπ’ ἄλλῳ βασιλεῖ.", "st": "15.2.6"}, {"sp": "N", "t": "Τούτοις δὲ παραιτησάμενος τὸν Ἀντώνιον ἔγνω μὴ μέχρι παντὸς ἀτιμάζειν τὸν παῖδα καὶ τὴν Ἀλεξάνδραν, ἀλλὰ καὶ τῆς γυναικὸς Μαριάμμης ἐγκειμένης λιπαρῶς ἀποδοῦναι τἀδελφῷ τὴν ἀρχιερωσύνην, καὶ συμφέρειν αὐτῷ κρίνων, ἵνα μηδ’ ἀποδημῆσαι δυνατὸν ᾖ τετιμημένῳ, σύλλογον ποιήσας τῶν φίλων ᾐτιᾶτο πολλὰ τὴν Ἀλεξάνδραν, κρύφα τε ἐπιβουλεῦσαι λέγων τῇ βασιλείᾳ καὶ διὰ τῆς Κλεοπάτρας πράττειν, ὅπως αὐτὸς μὲν ἀφαιρεθῇ τὴν ἀρχήν, τὸ δὲ μειράκιον ἀντ’ αὐτοῦ παραλάβῃ τὰ πράγματα δι’ Ἀντωνίου. καὶ ταῦτα βούλεσθαι μὲν ἐκείνην οὐ δικαίως, ὁπότε καὶ τὴν θυγατέρα συναποστεροίη τῆς οὔσης αὐτῇ τιμῆς καὶ ταραχὰς ἐπὶ τῇ βασιλείᾳ πραγματεύοιτο, πολλὰ πονήσαντος αὐτοῦ καὶ κτησαμένου κινδύνοις οὐ τοῖς τυχοῦσιν. οὐ μὴν ἀπομνημονεύσας αὐτὸς ὧν οὐ καλῶς ἐκείνη πράξειεν ἀποστήσεσθαι τοῦ δίκαιος εἶναι περὶ αὐτούς, ἀλλὰ καὶ νῦν ἔφη διδόναι τῷ παιδὶ τὴν ἀρχιερωσύνην καὶ πάλαι προκαταστήσασθαι τὸν Ἀνάνηλον παιδίου παντάπασιν ὄντος Ἀριστοβούλου. τοιαῦτα δὲ λέγοντος οὐκ ἀσκέπτως, ἀλλ’ ὅπερ ἠξίου μάλιστα πεφροντισμένως εἰς ἀπάτην γυναικῶν καὶ τῶν συμπαραληφθέντων φίλων, περιπαθὴς ἅμα καὶ χαρᾷ τῶν οὐ προσδοκηθέντων καὶ δέει τῆς ὑποψίας Ἀλεξάνδρα μετὰ δακρύων ἀπελογεῖτο, περὶ μὲν τῆς ἱερωσύνης φαμένη πᾶν ὁτιοῦν ὑπ’ ἀδοξίας σπουδάσαι, βασιλείᾳ δὲ μήτε ἐπιτίθεσθαι μήτ’ ἄν, εἰ καὶ προσίοι, βούλεσθαι λαβεῖν, καὶ νῦν ἀποχρώντως τιμῆς ἔχουσα διὰ τὴν ἀρχὴν τὴν ἐκείνου καὶ τὴν ἀσφάλειαν τὴν ἐκ τοῦ δύνασθαι μᾶλλον ἑτέρων ἄρχειν αὐτὸν ἅπαντι τῷ γένει περιοῦσαν. νῦν τε νενικημένη ταῖς εὐεργεσίαις δέχεσθαι μὲν εἰς τὸν υἱὸν τὴν τιμήν, ἔσεσθαι δὲ πρὸς πᾶν ὑπήκοος, παραιτεῖσθαι δὲ κἂν εἴ τι διὰ γένος καὶ τὴν οὖσαν αὐτῇ παρρησίαν προπετέστερον ὑπ’ ἀναξιοπαθείας δράσειεν. οὕτως ἀλλήλοις ὁμιλήσαντες καὶ σπουδαιότερον ἢ θᾶττον ἐν δεξιαῖς διελύοντο πάσης ὑποψίας, ὡς ἐδόκουν, ἐξῃρημένης.", "st": "15.2.7"}, {"sp": "N", "t": "Ὁ δὲ βασιλεὺς Ἡρώδης εὐθὺς μὲν ἀφαιρεῖται τὴν ἀρχιερωσύνην Ἀνάνηλον ὄντα μέν, ὡς καὶ πρότερον εἴπομεν, οὐκ ἐπιχώριον, ἀλλὰ τῶν ὑπὲρ Εὐφράτην ἀπῳκισμένων Ἰουδαίων· οὐ γὰρ ὀλίγαι μυριάδες τοῦδε τοῦ λαοῦ περὶ τὴν Βαβυλωνίαν ἀπῳκίσθησαν. ἔνθεν ἦν Ἀνάνηλος ἀρχιερατικοῦ γένους καὶ πάλαι κατὰ συνήθειαν Ἡρώδῃ σπουδαζόμενος. τοῦτον αὐτὸς μὲν ἐτίμησεν, ὅτε τὴν βασιλείαν παρέλαβεν, αὐτὸς δὲ κατέλυσεν ἐπὶ τῷ παῦσαι τὰς οἰκείας ταραχὰς παράνομα ποιῶν· οὐ γὰρ ἄλλος γέ τις ἀφῃρέθη τὴν τιμὴν ἅπαξ παραλαβών. ἀλλὰ πρῶτος μὲν Ἀντίοχος ὁ Ἐπιφανὴς ἔλυσε τὸν νόμον ἀφελόμενος μὲν Ἰησοῦν, καταστήσας δὲ τὸν ἀδελφὸν Ὀνίαν, δεύτερος δὲ Ἀριστόβουλος Ὑρκανὸν ἀφείλετο τὸν ἀδελφόν, Ἡρώδης δὲ τρίτος ἀντιπαρέδωκεν τὴν ἀρχὴν Ἀριστοβούλῳ τῷ παιδί.", "st": "15.3.1"}, {"sp": "N", "t": "Καὶ τότε μὲν ἐδόκει τεθεραπευκέναι τὰ περὶ τὴν οἰκίαν. οὐ μὴν ὅπερ εἰκὸς ἦν ἐν διαλλαγαῖς ἀνυπόπτως διετέλει, τὴν Ἀλεξάνδραν ἐπί τε τοῖς ἐγχειρηθεῖσιν ἤδη καὶ καιρὸν εἰ λάβοιτο νεωτέρων πραγμάτων ἠξιωκὼς δεδοικέναι. προσέταττεν οὖν ἔν τε τοῖς βασιλείοις διατρίβειν καὶ μηδὲν ἀπ’ ἐξουσίας δρᾶν, ἐπιμελεῖς τε ἦσαν φυλακαί, λανθάνοντος οὐδ’ εἴ τι πρὸς τὴν καθ’ ἡμέραν δίαιταν ἐπιτηδεύοιτο. ταῦτα πάντα κατὰ μικρὸν ἐξηγρίου αὐτὴν καὶ μῖσος ἐπεφύετο· φρονήματος γὰρ ἔμπλεως οὖσα γυναικείου τὰς ἐκ τῆς ὑποψίας ἐπιμελείας ἀνηξιοπάθει, παντὸς οὑτινοσοῦν ἀξιοῦσα μᾶλλον ἢ τῆς παρρησίας στερομένη τιμῆς εὐπρεπείᾳ μετὰ δουλείας καὶ φόβων καταζῆν. ἔπεμπεν οὖν παρὰ τὴν Κλεοπάτραν ἐν οἷς εἴη συνεχὲς ὀδυρομένη καὶ παρακαλοῦσα προσβοηθεῖν αὐτῇ κατὰ δύναμιν. ἡ δὲ λαθοῦσαν ἐκέλευσεν ἐπ’ Αἰγύπτου σὺν τῷ παιδὶ πρὸς αὐτὴν ἀποδιδράσκειν. ἐδόκει ταῦτα καὶ τεχνάζεται τοιάδε· δύο λάρνακας ὡς εἰς ἐκκομιδὴν νεκρῶν παρασκευασαμένη ταύταις αὐτὴν καὶ τὸν υἱὸν ἐνέβαλεν, ἐπιτάξασα τῶν οἰκετῶν τοῖς συνειδόσιν διὰ νυκτὸς ἐκφέρειν. ἦν δὲ τοὐντεῦθεν ἐπὶ θάλατταν ὁδὸς αὐτοῖς καὶ πλοῖον, ὃ διαπλεύσειν εἰς τὴν Αἴγυπτον ἔμελλεν, παρεσκευασμένον. ταῦτα Σαββίωνι τῶν ἐκείνης φίλων Αἴσωπος οἰκέτης αὐτῆς ἀπαγγέλλει προπεσὼν ὡς εἰδότι φράσαι. πυθόμενος δὲ Σαββίων, καὶ γὰρ ἦν ἐχθρὸς Ἡρώδου [πρότερον], ὅτι τῶν ἐπιβουλευσάντων Ἀντιπάτρῳ κατὰ τὴν φαρμακείαν εἷς ἐνομίζετο, τὸ μῖσος ὑπαλλάξεσθαι τῇ περὶ τὴν μήνυσιν εὐνοίᾳ προσεδόκησεν καὶ καταλέγει τῷ βασιλεῖ τὴν τῆς Ἀλεξάνδρας ἐπιβουλήν. ὁ δὲ τὴν μὲν ἕως τῆς ἐγχειρήσεως ἐάσας προελθεῖν ἐπ’ αὐτοφώρῳ τοῦ δρασμοῦ συνέλαβεν, παρῆκεν δὲ τὴν ἁμαρτίαν, χαλεπὸν μὲν οὐδέν, εἰ καὶ σφόδρα βουλομένῳ ἦν αὐτῷ, διαθεῖναι τολμήσας, οὐ γὰρ ἂν ἀνασχέσθαι Κλεοπάτραν αἰτίαν ἐπὶ τῷ πρὸς αὐτὸν μίσει λαβοῦσαν, ἐμφαίνων δὲ μεγαλοψυχίαν μᾶλλον ἐξ ἐπιεικείας αὐτοῖς συνεγνωκέναι. προύκειτο μέντοι παντάπασιν αὐτῷ τὸ μειράκιον ἐκποδὼν ποιεῖσθαι, τὸ δὲ μὴ ταχὺ μηδ’ ἅμα τοῖς πεπραγμένοις ἐδόκει πιθανώτερον εἰς τὸ λανθάνειν.", "st": "15.3.2"}, {"sp": "N", "t": "Καὶ τῆς σκηνοπηγίας ἐπεχούσης, ἑορτὴ δέ ἐστιν αὕτη παρ’ ἡμῖν εἰς τὰ μάλιστα τηρουμένη, ταύτας τὰς ἡμέρας ὑπερεβάλλετο καὶ πρὸς εὐφροσύναις αὐτός τε καὶ τὸ λοιπὸν πλῆθος ἦν. ἐκίνησεν δ’ αὐτὸν ὅμως κἀκ τῶν τοιούτων ἐπισπεῦσαι τὰ περὶ τὴν προαίρεσιν ἐμφανῶς παροξύνων ὁ φθόνος. τὸ γὰρ μειράκιον Ἀριστόβουλος ἕβδομον ἐπὶ τοῖς δέκα γεγονὸς ἔτος, ἐπειδὴ κατὰ τὸν νόμον ἀνῆλθεν ἐπὶ τὸν βωμὸν συντελέσων τὰ θύματα, τόν τε κόσμον ἔχων τὸν τῶν ἀρχιερέων καὶ τὰ περὶ τὴν θρησκείαν ἐκτελῶν, κάλλει τε κάλλιστος καὶ μεγέθει πλέον ἢ πρὸς τὴν ἡλικίαν ὑπεράγων, τοῦ γε μὴν περὶ τὸ γένος ἀξιώματος πλεῖστον ἐν τῇ μορφῇ διαφαίνων, ὁρμή τε τῷ πλήθει πρὸς αὐτὸν εὐνοίας ἐγένετο καὶ τῶν Ἀριστοβούλῳ τῷ πάππῳ πεπραγμένων ἐναργὴς ἡ μνήμη παρέστη, νικώμενοί τε κατὰ μικρὸν ἐξηλέγχοντο τὰς διαθέσεις χαίροντες ὁμοῦ καὶ συγχεόμενοι καὶ φωνὰς εὐφήμους εἰς αὐτὸν ἀφιέντες εὐχαῖς μεμιγμένας, ὡς ἐμφανῆ γενέσθαι τὴν εὔνοιαν τῶν ὄχλων καὶ προπετεστέραν ἐν βασιλείᾳ δοκεῖν τὴν ὧν πεπόνθεσαν ὁμολογίαν. ἐπὶ τούτοις ἅπασιν Ἡρώδης ἔγνω τὴν προαίρεσιν, ἣν εἶχεν εἰς τὸ μειράκιον, ἐξεργάσασθαι. καὶ τῆς ἑορτῆς παρελθούσης εἱστιᾶτο μὲν ἐν Ἱεριχοῦντι δεχομένης αὐτοὺς τῆς Ἀλεξάνδρας, φιλοφρονούμενος δὲ τὸ μειράκιον καὶ προέλκων εἰς ἀδεῆ πότον ἕτοιμος ἦν συμπαίζειν καὶ νεανιεύεσθαι κεχαρισμένως ἐκείνῳ. τοῦ δὲ περὶ τὸν τόπον ἰδιώματος θερινωτέρου τυγχάνοντος συνειλεγμένοι τάχιον ἐξῆλθον ἀλύοντες, καὶ ταῖς κολυμβήθραις ἐπιστάντες, αἳ μεγάλαι περὶ τὴν αὐλὴν ἐτύγχανον, ἀνέψυχον τὸ θερμότατον τῆς μεσημβρίας. καὶ πρῶτον μὲν ἑώρων τοὺς νέοντας τῶν οἰκετῶν καὶ φίλων, ἔπειτα προαχθέντος καὶ τοῦ μειρακίου τῷ καὶ τὸν Ἡρώδην παροξῦναι, τῶν φίλων οἷς ταῦτα ἐπιτέτακτο σκότους ἐπέχοντος βαροῦντες ἀεὶ καὶ βαπτίζοντες ὡς ἐν παιδιᾷ νηχόμενον οὐκ ἀνῆκαν, ἕως καὶ παντάπασιν ἀποπνῖξαι. καὶ διεφθάρη μὲν οὕτως Ἀριστόβουλος, ὀκτωκαίδεκα μὲν οὐ πάντα βιοὺς ἔτη, τὴν δ’ ἱερωσύνην κατασχὼν ἐνιαυτόν, ἣν Ἀνάνηλος ἐκομίσατο πάλιν.", "st": "15.3.3"}, {"sp": "N", "t": "Ἐξαγγελθέντος δὲ τοῦ πάθους ταῖς γυναιξὶν εὐθὺς μὲν ἐκ μεταβολῆς θρῆνος ἦν ἐπὶ προκειμένῳ τῷ νεκρῷ καὶ πένθος ἄσχετον, ἥ τε πόλις τοῦ λόγου διαδοθέντος ὑπερήλγει πάσης ἑστίας οἰκειουμένης τὴν συμφορὰν ὡς οὐκ ἐπ’ ἀλλοτρίῳ γενομένην. Ἀλεξάνδρα δὲ καὶ μᾶλλον ἐκπαθὴς ἦν συνέσει τῆς ἀπωλείας, τὸ μὲν ἀλγοῦν ἐκ τοῦ γινώσκειν ὅπως ἐπράχθη πλεῖον ἔχουσα, τὸ δ’ ἐγκαρτερεῖν ἀναγκαῖον ἐπὶ μείζονος κακοῦ προσδοκίᾳ ποιουμένη. καὶ πολλάκις μὲν ἦλθεν αὐτοχειρίᾳ περιγράψασθαι τὸν βίον, ἐπέστη δ’ ὅμως, εἰ δύναιτο ζῶσα προσαρκέσαι τῷ κατ’ ἐπιβουλὰς ἀνόμως διεφθαρμένῳ, τό τε πλέον ἐντεῦθεν αὐτῇ παρεκρότει τὸν βίον, καὶ τὸ μηδεμίαν ὑποψίαν ἐνδοῦναι τοῦ κατὰ πρόνοιαν ἀπολέσθαι τὸν υἱὸν ἱκανὸν εἰς εὐκαιρίαν ἀμύνης ἐνόμιζε. κἀκείνη μὲν ἐγκρατῶς ἔφερε τὴν ὑποψίαν. Ἡρώδης δὲ πᾶσι τοῖς ἔξωθεν πιθανῶς ἀπεσκευάζετο, μὴ μετὰ προνοίας γενέσθαι τῷ παιδὶ τὸν θάνατον, οὐχ ὅσα πρὸς πένθος ἐπιτηδεύων μόνον, ἀλλὰ καὶ δάκρυσι χρώμενος καὶ σύγχυσιν τῆς ψυχῆς ἐμφαίνων ἀληθινήν, τάχα μὲν καὶ τοῦ πάθους ἀπονικῶντος αὐτὸν ἐν ὄψει τῆς τε ὥρας καὶ τοῦ κάλλους, εἰ καὶ πρὸς ἀσφάλειαν ὁ θάνατος τοῦ παιδὸς ἐνομίζετο, δῆλον δ’ ὡς ἀπολογίαν αὐτὰ πραγματευόμενος. τά γε μὴν εἰς τὴν πολυτέλειαν τῆς ἐκφορᾶς καὶ μᾶλλον ἐπεδείξατο, πολλὴν μὲν τὴν παρασκευὴν περί τε τὰς θήκας καὶ τὸ πλῆθος τῶν θυμιαμάτων ποιησάμενος, πολὺν δὲ συγκαταθάπτων κόσμον, ὡς ἐκπλῆξαι τὸ λυπηρὸν τῆς ἐν ταῖς γυναιξὶν ἀλγηδόνος καὶ παραμυθήσασθαι τούτῳ τῷ μέρει.", "st": "15.3.4"}, {"sp": "N", "t": "Τὴν δ’ Ἀλεξάνδραν ἥττησε μὲν οὐδὲν τῶν τοιούτων, ἀεὶ δὲ καὶ μᾶλλον ἡ μνήμη τοῦ κακοῦ παρέχουσα τὴν ὀδύνην ὀδυρτικὴν ἐποίει καὶ φιλόνεικον, καὶ γράφει τὴν ἐπιβουλὴν Ἡρώδου τῇ Κλεοπάτρᾳ καὶ τὴν ἀπώλειαν τοῦ παιδός. ἡ δὲ καὶ πάλαι σπεύδουσα προσαρκέσαι δεομένῃ καὶ τὰς ἀτυχίας οἰκτείρουσα τῆς Ἀλεξάνδρας αὐτῆς ἐποιεῖτο τὸ πᾶν πρᾶγμα καὶ Ἀντώνιον οὐκ ἀνίει τίσασθαι τὸν φόνον τοῦ παιδὸς παροξύνουσα· οὐ γὰρ ἄξιον Ἡρώδην δι’ αὐτοῦ καταστάντα βασιλέα τῆς οὐδὲν προσηκούσης ἀρχῆς εἰς τοὺς ὄντως βασιλεῖς τοιαύτας ἐπιδείκνυσθαι παρανομίας. τούτοις ἀναπειθόμενος Ἀντώνιος ὡς ἐπὶ Λαοδικείας ἐστάλη, πέμπει κελεύων Ἡρώδην ἐλθόντα τῶν εἰς Ἀριστόβουλον ἀπολύσασθαι· πεπρᾶχθαι γὰρ οὐκ ὀρθῶς τὴν ἐπιβουλήν, εἰ δι’ αὐτοῦ γέγονεν. ὁ δὲ τήν τε αἰτίαν δεδοικὼς καὶ τὴν Κλεοπάτρας δυσμένειαν, ὡς οὐκ ἀνῆκεν ἐξεργαζομένη κακῶς αὐτῷ τὸν Ἀντώνιον ἔχειν, ἔγνω μὲν ὑπακούειν, οὐδὲ γὰρ ἄλλο τι πράττειν ἐνῆν, καταλιπὼν δὲ τὸν θεῖον αὐτοῦ Ἰώσηπον ἐπίτροπον τῆς ἀρχῆς καὶ τῶν ἐκεῖ πραγμάτων ἐνετείλατο λεληθότως, εἰ πάθοι τι παρ’ Ἀντωνίῳ, παραχρῆμα καὶ τὴν Μαριάμμην ἀνελεῖν· αὐτός τε γὰρ ἔχειν φιλοστόργως πρὸς τὴν γυναῖκα καὶ δεδοικέναι τὴν ὕβριν, εἰ καὶ τεθνηκότος ἐκείνη κατ’ εὐμορφίαν ἄλλῳ τινὶ σπουδάζοιτο. τὸ δὲ σύμπαν ἐνέφαινεν ὁρμὴν Ἀντωνίου περὶ τὴν ἄνθρωπον, ὅτι καὶ πάλαι παρακηκοὼς ὑπὲρ τῆς εὐμορφίας ἐτύγχανεν. Ἡρώδης μὲν [οὖν] ἐπιστείλας ταῦτα καὶ τὰς ἐλπίδας οὐκ ἀσφαλεῖς ἔχων ὑπὲρ τῶν ὅλων ἀπῄει πρὸς Ἀντώνιον.", "st": "15.3.5"}, {"sp": "N", "t": "Ὁ δὲ Ἰώσηπος ἐπὶ τῆς διοικήσεως ὢν τῶν ἐν τῇ βασιλείᾳ πραγμάτων καὶ διὰ τοῦτο συνεχὲς ἐντυγχάνων τῇ Μαριάμμῃ περί τε τὰς πραγματείας καὶ τιμῆς ἕνεκεν, ἣν ἔδει βασιλευούσῃ παρ’ αὐτοῦ γενέσθαι, καθίει συνεχεῖς ὁμιλίας ὑπὲρ τῆς Ἡρώδου πρὸς αὐτὴν εὐνοίας καὶ φιλοστοργίας. ἐξειρωνευομένων δὲ γυναικείως τοὺς λόγους καὶ μάλιστα τῆς Ἀλεξάνδρας, ὑπερεσπουδακὼς ὁ Ἰώσηπος ἐπιδεῖξαι τὴν διάνοιαν τοῦ βασιλέως προήχθη καὶ τὰ περὶ τὴν ἐντολὴν εἰπεῖν, πίστιν αὐτὰ ποιούμενος ὡς οὐδὲ χωρὶς ἐκείνης ζῆν δύναται κἂν εἰ πάσχοι δεινόν τι οὐκ ἀξιοῦντος οὐδὲ θανάτῳ διεζεῦχθαι. ταῦτα μὲν Ἰώσηπος. αἱ δὲ γυναῖκες, ὡς εἰκός, οὐ τὸ φιλόστοργον τῆς περὶ τὸν Ἡρώδην διαθέσεως, τὸ δὲ χαλεπόν, εἰ μηδ’ ἀποθνήσκοντος ὑστερήσειεν ἀπωλείας καὶ θανάτου τυραννικοῦ, προλαμβάνουσαι χαλεπὴν τὴν ὑπόνοιαν τοῦ ῥηθέντος εἶχον.", "st": "15.3.6"}, {"sp": "N", "t": "Ἐν δὲ τούτῳ καὶ λόγος ἐγένετο κατὰ τὴν πόλιν τῶν Ἱεροσολυμιτῶν παρὰ τῶν ἐν ἔχθει τὸν Ἡρώδην ἐχόντων, ὡς Ἀντώνιος αἰκισάμενος αὐτὸν ἀποκτείνειεν. ἡ δὲ φήμη πάντας μὲν ἐτάραξεν, ὡς εἰκός, τοὺς περὶ τὸ βασίλειον, μάλιστα δὲ καὶ τὰς γυναῖκας. Ἀλεξάνδρα δὲ καὶ τὸν Ἰώσηπον ἀναπείθει τῶν βασιλείων ἐξελθόντα σὺν αὐταῖς προσφυγεῖν τοῖς σημείοις τοῦ Ῥωμαϊκοῦ τάγματος, ὃ τότε περὶ τὴν πόλιν ἐπὶ φρουρᾷ τῆς βασιλείας ἐστρατοπέδευεν ἡγουμένου υἱοῦ ἰούδα· διὰ γὰρ τοῦτο πρῶτον μέν, εἰ καί τις ἀπαντήσειεν ταραχὴ περὶ τὴν αὐλήν, ἐν ἀσφαλεστέρῳ διάξειν αὐτοὶ Ῥωμαίους εὐμενεῖς ἔχοντες· ἔπειτα καὶ τεύξεσθαι παντὸς ἠλπικέναι τὴν Μαριάμμην Ἀντωνίου θεασαμένου, δι’ οὗ καὶ τὴν ἀρχὴν ἀναλήψεσθαι καὶ μηδενὸς ὑστερήσειν ὧν εἰκὸς τοῖς ἐν εὐγενείᾳ βασιλικῇ γεγονόσιν.", "st": "15.3.7"}, {"sp": "N", "t": "Ἐπὶ τούτων δὲ τῶν λογισμῶν τετυχηκόσιν αὐτοῖς γράμματα παρ’ Ἡρώδου περὶ τῶν ὅλων ἀφίκετο τῆς φήμης ἐναντία καὶ τῶν προλαληθέντων. ἐπειδὴ γὰρ ἐγένετο παρ’ Ἀντωνίῳ, ταχὺ μὲν αὐτὸν ἀνεκτήσατο τοῖς δώροις ἃ φέρων ἧκεν ἐκ τῶν Ἱεροσολύμων, ταχὺ δὲ ταῖς ὁμιλίαις παρεστήσατο χαλεπῶς ἔχειν εἰς αὐτόν, οἵ τε τῆς Κλεοπάτρας λόγοι πρὸς τὴν ἐξ ἐκείνου θεραπείαν ἧττον ἠδυνήθησαν· οὐ γὰρ ἔφη καλῶς ἔχειν Ἀντώνιος βασιλέα περὶ τῶν κατὰ τὴν ἀρχὴν γεγενημένων εὐθύνας ἀπαιτεῖν· οὕτως γὰρ ἂν οὐδὲ βασιλεὺς εἴη· δόντας δὲ τὴν τιμὴν καὶ τῆς ἐξουσίας καταξιώσαντας ἐᾶν αὐτῇ χρῆσθαι. τὸ δ’ αὐτὸ καὶ τῇ Κλεοπάτρᾳ μὴ πολυπραγμονεῖσθαι τὰ περὶ τὰς ἀρχὰς συμφέρειν. ὑπὲρ τούτων Ἡρώδης ἔγραφεν καὶ τὰς ἄλλας διεξῄει τιμάς, ἃς ἔχοι παρ’ Ἀντωνίῳ συνθακῶν ἐν ταῖς διαγνώσεσιν καὶ συνεστιώμενος ἐφ’ ἑκάστης ἡμέρας, καὶ τούτων ὅπως τυγχάνοι χαλεπῆς εἰς τὰς διαβολὰς αὐτῷ τῆς Κλεοπάτρας οὔσης· πόθῳ γὰρ τῆς χώρας ἐξαιτουμένη τὴν βασιλείαν αὐτῇ προσγενέσθαι πάντα τρόπον ἐκποδὼν αὐτὸν ἐσπουδάκει ποιεῖσθαι. δικαίου μέντοι τυγχάνων Ἀντωνίου μηδὲν ἔτι δυσχερὲς προσδοκᾶν, ἀλλὰ καὶ θᾶττον ἥξειν βεβαιοτέραν τὴν εὔνοιαν τὴν παρ’ αὐτοῦ προσειληφὼς τῇ βασιλείᾳ καὶ τοῖς πράγμασιν. καὶ τῇ Κλεοπάτρᾳ μηκέτι προσεῖναι τὴν ἐλπίδα τῆς πλεονεξίας Ἀντωνίου δόντος ἀνθ’ ὧν ἠξίου τὴν κοίλην Συρίαν καὶ διὰ τούτου παρηγορήσαντος ὁμοῦ καὶ ἀποσκευασαμένου τὰς ἐντεύξεις, ἃς ὑπὲρ τῆς Ἰουδαίας ἐποιεῖτο.", "st": "15.3.8"}, {"sp": "N", "t": "Τούτων τῶν γραμμάτων ἀπενεχθέντων ἐπαύσαντο μὲν ἐκείνης τῆς ὁρμῆς, ἣν ὡς ἀπολωλότος εἶχον καταφυγεῖν ἐπὶ τοὺς Ῥωμαίους, οὐ μὴν ἔλαθεν αὐτῶν ἡ προαίρεσις, ἀλλ’ ἐπεὶ παραπέμψας ὁ βασιλεὺς Ἀντώνιον ἐπὶ Πάρθους εἰς τὴν Ἰουδαίαν ὑπέστρεψεν, εὐθὺς μὲν ἥ τε ἀδελφὴ Σαλώμη καὶ ἡ μήτηρ αὐτῷ τὴν διάνοιαν ἣν ἔσχον οἱ περὶ τὴν Ἀλεξάνδραν ἀπεσήμηναν, ἡ δὲ Σαλώμη καὶ κατὰ τἀνδρὸς Ἰωσήπου λόγον εἶπεν τὸ ἐν διαβολῇ ποιοῦσα καὶ τῇ Μαριάμμῃ συγγενόμενον διατελεῖν. ἔλεγεν δὲ ταῦτα χαλεπῶς ἔχουσα πρὸς αὐτὴν ἐκ πλείονος, ὅτι κατὰ τὰς διαφορὰς φρονήματι χρωμένη μείζονι τὴν ἐκείνων ἐξωνείδιζεν δυσγένειαν. Ἡρώδης δὲ θερμῶς ἀεὶ καὶ ἐρωτικῶς πρὸς τὴν Μαριάμμην ἔχων εὐθὺς ἐξετετάρακτο καὶ τὴν ζηλοτυπίαν οὐκ ἔφερεν, ἐπικρατούμενος δ’ ἀεὶ τοῦ μὴ προπετές τι ποιῆσαι διὰ τὸν ἔρωτα, συντόνῳ τῷ πάθει καὶ τῷ ζήλῳ παρωξυμμένος ἰδίᾳ τὴν Μαριάμμην ἀνέκρινεν ὑπὲρ τῶν πρὸς τὸν Ἰώσηπον. ἀπομνυμένης δ’ ἐκείνης καὶ πάνθ’ ὅσα τῇ μηδὲν ἁμαρτούσῃ προσῆν εἰς ἀπολογίαν καταλογιζομένης, ἀνεπείθετο κατὰ μικρὸν ὁ βασιλεὺς καὶ μετέβαινεν ἐκ τῆς ὀργῆς ἡττώμενος τῆς περὶ τὴν γυναῖκα φιλοστοργίας, ὡς ἀπολογεῖσθαι περὶ ὧν ἔδοξεν ἀκούσας πεπιστευκέναι καὶ περὶ τῆς κοσμιότητος αὐτῇ πολλὴν ὁμολογεῖν χάριν. αὐτός τε ὅπως ἔχοι στοργῆς καὶ εὐνοίας πρὸς αὐτὴν ἀνωμολογεῖτο καὶ τέλος, ὡς ἐν τοῖς ἐρωτικοῖς φιλεῖ, προύπιπτον εἰς δάκρυα μετὰ πολλῆς σπουδῆς ἐμπεφυκότες ἀλλήλοις. ἀεὶ δὲ καὶ μᾶλλον τοῦ βασιλέως πιστουμένου τὴν αὐτοῦ διάθεσιν οὐ φιλοῦντος, εἶπεν ἡ Μαριάμμη, τὸ κατὰ τὴν ἐντολήν, εἰ πάσχοι τι χαλεπὸν ὑπ’ Ἀντωνίου, κἀμὲ συναπολέσθαι τὴν οὐδενὸς αἰτίαν. τούτου προπεσόντος τοῦ λόγου περιπαθήσας ὁ βασιλεὺς εὐθὺς μὲν ἐκ τῶν χειρῶν αὐτὴν ἀφῆκεν, ἐβόα δὲ καὶ τῶν αὐτὸς ἑαυτοῦ τριχῶν ἐδράττετο, περιφανὲς φώριον ἔχειν τῆς τοῦ Ἰωσήπου πρὸς αὐτὴν κοινωνίας λέγων· οὐ γὰρ ἂν ἐξειπεῖν ἃ κατ’ ἰδίαν ἤκουσεν μὴ μεγάλης αὐτοῖς πίστεως ἐγγενομένης. οὕτως δ’ ἔχων ὀλίγου μὲν ἀπέκτεινε τὴν γυναῖκα, νικώμενος δὲ τῷ πρὸς αὐτὴν ἔρωτι ταύτης μὲν τῆς ὁρμῆς ἐκράτησεν ἑαυτοῦ διακαρτερήσας ὀδυνηρῶς καὶ δυσχερῶς, τὸν μέντοι Ἰώσηπον οὐδ’ εἰς ὄψιν ἐλθόντα διαχρήσασθαι προσέταξεν καὶ τὴν Ἀλεξάνδραν ὡς ἁπάντων παραιτίαν δήσας ἐφύλαττεν.", "st": "15.3.9"}, {"sp": "N", "t": "Ἐν δὲ τούτῳ καὶ τὰ περὶ τὴν Συρίαν ταραχὰς εἶχεν οὐκ ἀνιείσης τῆς Κλεοπάτρας τὸν Ἀντώνιον μὴ πᾶσιν ἐπιχειρεῖν· ἔπειθεν γὰρ ἀφαιρούμενον ἑκάστων τὰς δυναστείας αὐτῇ διδόναι καὶ πλεῖστον ἴσχυεν ἐκ τῆς ἐκείνου πρὸς αὐτὴν ἐπιθυμίας. φύσει δὲ πλεονεξίᾳ χαίρουσα παρανομίας οὐδὲν ἔλιπεν, τὸν μὲν ἀδελφόν, ᾧ τὴν βασιλείαν ᾔδει γενησομένην, προανελοῦσα φαρμάκοις πεντεκαιδέκατον ἔτος ἔχοντα, τὴν δ’ ἀδελφὴν Ἀρσινόην ἱκετεύουσαν ἐν Ἐφέσῳ πρὸς τῷ τῆς Ἀρτέμιδος ἀποκτείνασα δι’ Ἀντωνίου· χρημάτων μὲν γὰρ εἵνεκεν, εἴ που μόνον ἐλπισθείη, καὶ ναοὶ καὶ τάφοι παρενομήθησαν, οὔθ’ ἱεροῦ τινος οὕτως ἀσύλου δόξαντος, ὡς μὴ περιαιρεθῆναι τὸν ἐν αὐτῷ κόσμον, οὔτε βεβήλου μὴ πᾶν ὁτιοῦν τῶν ἀπηγορευμένων παθόντος, εἰ μέλλοι μόνον εἰς εὐπορίαν τῇ τῆς ἀδικούσης πλεονεξίᾳ. τὸ δ’ ὅλον οὐδὲν αὔταρκες ἦν γυναικὶ καὶ πολυτελεῖ καὶ δουλευούσῃ ταῖς ἐπιθυμίαις, μὴ καὶ τὰ πάντα πρὸς τὴν ἐπίνοιαν ἐνδεῖν ὧν ἐσπουδάκει. διὰ ταῦτα καὶ τὸν Ἀντώνιον ἤπειγεν ἀεί τι τῶν ἄλλων ἀφαιρούμενον αὐτῇ χαρίζεσθαι, καὶ διαβᾶσα σὺν ἐκείνῳ τὴν Συρίαν ἐπενόει κτῆμα ποιήσασθαι. Λυσανίαν μὲν οὖν τὸν Πτολεμαίου Πάρθους αἰτιασαμένη τοῖς πράγμασιν ἐπάγειν ἀποκτίννυσιν, ᾔτει δὲ παρ’ Ἀντωνίου τήν τε Ἰουδαίαν καὶ τὴν τῶν Ἀράβων ἀξιοῦσα τοὺς βασιλεύοντας αὐτῶν ἀφελέσθαι. τῷ δ’ Ἀντωνίῳ τὸ μὲν ὅλον ἡττᾶσθαι συνέβαινεν τῆς γυναικός, ὡς μὴ μόνον ἐκ τῆς ὁμιλίας, ἀλλὰ καὶ φαρμάκοις δοκεῖν ὑπακούειν εἰς ὅ τι ἂν ἐκείνη θέλῃ, τὸ μέντοι περιφανὲς τῆς ἀδικίας ἐξεδυσώπει μὴ μέχρι τοσούτου κατήκοον γινόμενον ἐπὶ μεγίστοις ἁμαρτάνειν. ἵν’ οὖν μήτ’ ἀρνηθῇ παντάπασιν μήθ’ ὅσα προσέταττεν ἐκείνη διαπραξάμενος ἐκ φανεροῦ δόξῃ κακός, μέρη τῆς χώρας ἑκατέρου παρελόμενος τούτοις αὐτὴν ἐδωρήσατο. δίδωσιν δὲ καὶ τὰς ἐντὸς Ἐλευθέρου ποταμοῦ πόλεις ἄχρις Αἰγύπτου χωρὶς Τύρου καὶ Σιδῶνος, ἐκ προγόνων εἰδὼς ἐλευθέρας, πολλὰ λιπαρούσης αὐτῆς αὐτῇ δοθῆναι.", "st": "15.4.1"}, {"sp": "N", "t": "Τούτων ἡ Κλεοπάτρα τυχοῦσα καὶ παραπέμψασα μέχρις Εὐφράτου τὸν Ἀντώνιον ἐπ’ Ἀρμενίαν στρατευόμενον ἀνέστρεφεν καὶ γίνεται μὲν ἐν Ἀπαμείᾳ καὶ Δαμασκῷ, παρῆλθεν δὲ καὶ εἰς τὴν Ἰουδαίαν Ἡρώδου συντυχόντος αὐτῇ καὶ τῆς τε Ἀραβίας τὰ δοθέντα καὶ τὰς περὶ τὸν Ἱεριχοῦντα προσόδους [Ἡρώδου] μισθωσαμένου· φέρει δ’ ἡ χώρα τὸ βάλσαμον, ὃ τιμιώτατον τῶν ἐκεῖ καὶ παρὰ μόνοις φύεται, τόν τε φοίνικα πολὺν καὶ καλόν. ἐν τούτοις οὖσα καὶ πλείονος αὐτῇ συνηθείας πρὸς τὸν Ἡρώδην γινομένης διεπείραζεν εἰς συνουσίαν ἐλθεῖν τῷ βασιλεῖ, φύσει μὲν ἀπαρακαλύπτως ταῖς ἐντεῦθεν ἡδοναῖς χρωμένη, τάχα δέ τι καὶ παθοῦσα πρὸς αὐτὸν ἐρωτικὸν ἢ καὶ τὸ πιθανώτερον ἀρχὴν ἐνέδρας τὴν ἐπ’ αὐτῇ γενησομένην ὕβριν ὑποκατασκευάζουσα· τὸ δὲ σύμπαν ἐξ ἐπιθυμίας ἡττῆσθαι διέφαινεν. Ἡρώδης δὲ καὶ πάλαι μὲν οὐκ εὔνους ἦν τῇ Κλεοπάτρᾳ χαλεπὴν εἰς ἅπαντας ἐπιστάμενος, τότε δὲ καὶ μισεῖν ἀξιῶν, εἰ δι’ ἀσέλγειαν εἰς τοῦτο πρόεισιν, καὶ φθῆναι τιμωρούμενος, εἰ ἐνεδρεύουσα τοιούτοις ἐγχειροίη, τοὺς μὲν λόγους αὐτῆς διεκρούσατο, βουλὴν δ’ ἐποιήσατο σὺν τοῖς φίλοις ὑποχείριον ἔχων ἀποκτεῖναι· πολλῶν γὰρ ἀπαλλάξειν κακῶν ἅπαντας οἷς ἐγένετό τε ἤδη χαλεπὴ καὶ προσεδοκᾶτο· τὸ δ’ αὐτὸ τοῦτο καὶ Ἀντωνίῳ λυσιτελήσειν οὐδ’ ἐκείνῳ πιστῆς ἐσομένης, εἴ τις αὐτὸν καιρὸς ἢ χρεία κατάσχοι τοιούτων δεησόμενον. ταῦτα βουλευόμενον ἐκώλυον οἱ φίλοι, πρῶτον μὲν διδάσκοντες, ὡς οὐκ ἄξιον μείζω πράττοντα κινδύνων τὸν φανερώτατον ἀναλαμβάνειν, ἐγκείμενοι δὲ καὶ δεόμενοι μηδὲν ἐκ προπετείας ἐπιτηδεύειν· οὐ γὰρ ἂν ἀνασχέσθαι τὸν Ἀντώνιον, οὐδ’ εἰ σφόδρα τις αὐτῷ τὸ συμφέρον στήσειε πρὸ τῶν ὀμμάτων· τόν τε γὰρ ἔρωτα μᾶλλον ὑπεκκαύσειν τὸ δοκεῖν βίᾳ καὶ κατ’ ἐπιβουλὴν αὐτῆς στέρεσθαι, μέτριον δὲ οὐδὲν εἰς τὴν ἀπολογίαν φανεῖσθαι, τοῦ μὲν ἐπιχειρήματος εἰς γυναῖκα γεγενημένου μέγιστον ἀξίωμα τῶν κατ’ ἐκεῖνον ἐσχηκυῖαν τὸν χρόνον, τῆς δ’ ὠφελείας, εἰ καὶ ταύτην τις οἰηθείη, σὺν αὐθαδείᾳ καὶ καταγνώσει τῆς ἐκείνου διαθέσεως φανουμένης. ἐξ ὧν οὐκ ἄδηλον, ὡς μεγάλων καὶ ἀπαύστων κακῶν ἀναπλησθήσεται τὰ περὶ τὴν ἀρχὴν αὐτῷ καὶ τὸ γένος, ἐξὸν ἀποκρουσάμενον τὴν ἁμαρτίαν, εἰς ἣν ἐκείνη παρακαλεῖ, θέσθαι τὸν καιρὸν εὐσχημόνως. τοιαῦτα δεδιττόμενοι καὶ τὸ κινδυνῶδες ἐξ εἰκότος παραδηλοῦντες ἐπέσχον αὐτὸν τῆς ἐπιχειρήσεως. ὁ δὲ τὴν Κλεοπάτραν δωρεαῖς θεραπεύσας ἐπ’ Αἰγύπτου προύπεμψεν.", "st": "15.4.2"}, {"sp": "N", "t": "Ἀντώνιος δὲ τὴν Ἀρμενίαν λαβὼν Ἀρταβάζην τὸν Τιγράνου σὺν τοῖς παισὶν σατράπαις δέσμιον εἰς Αἴγυπτον ἀποπέμπει, δωρούμενος τούτοις τὴν Κλεοπάτραν καὶ τῷ παντὶ κόσμῳ τῆς βασιλείας, ὃν ἐξ αὐτῆς ἔλαβεν. Ἀρμενίας δὲ ἐβασίλευσεν Ἀρταξίας ὁ πρεσβύτατος τῶν ἐκείνου παίδων διαδρὰς ἐν τῷ τότε. καὶ τοῦτον Ἀρχέλαος καὶ Νέρων Καῖσαρ ἐκβαλόντες Τιγράνην τὸν νεώτερον ἀδελφὸν ἐπὶ τὴν βασιλείαν κατήγαγον. ταῦτα μὲν οὖν ἐν ὑστέρῳ.", "st": "15.4.3"}, {"sp": "N", "t": "Περὶ δὲ τοὺς φόρους, οὓς ἔδει τελεῖν τῆς ὑπ’ Ἀντωνίου δοθείσης χώρας, ὁ μὲν Ἡρώδης δίκαιος ἦν οὐκ ἀσφαλὲς ἡγούμενος διδόναι τῇ Κλεοπάτρᾳ μίσους αἰτίαν. ὁ δ’ Ἄραψ Ἡρώδου τὴν φορὰν ἐπιδεξαμένου χρόνον μέν τινα παρεῖχεν ἐκείνῳ τὰ διακόσια τάλαντα, μετὰ ταῦτα δὲ κακοήθης ἦν καὶ βραδὺς εἰς τὰς ἀποδόσεις καὶ μόλις εἰ καὶ μέρη τινὰ διαλύσειεν οὐδὲ ταῦτα διδόναι δοκῶν ἀζημίως.", "st": "15.4.4"}, {"sp": "N", "t": "Ἡρώδης δὲ τοῦτον τὸν τρόπον ἀγνωμονοῦντος καὶ τὸ τελευταῖον οὐδὲν ἔτι τῶν δικαίων ποιεῖν ἐθέλοντος εἶχεν μὲν ὡς ἐπεξελευσόμενος, προθεσμίᾳ δὲ ἐχρήσατο τῷ Ῥωμαϊκῷ πολέμῳ. τῆς γὰρ ἐπ’ Ἀκτίῳ μάχης προσδοκωμένης, ἣν ἐπὶ τῆς ἑβδόμης καὶ ὀγδοηκοστῆς πρὸς ταῖς ἑκατὸν ὀλυμπιάδος συνέβη γενέσθαι, Καῖσαρ μὲν Ἀντωνίῳ περὶ τῶν ὅλων ἔμελλεν ἀγωνιεῖσθαι πραγμάτων, Ἡρώδης δὲ καὶ τῆς χώρας εὐβοτουμένης αὐτῷ πολὺν ἤδη χρόνον καὶ προσόδων καὶ δυνάμεως εὑρημένων, Ἀντωνίῳ συμμαχίαν κατέλεξεν ἐπιμελέστατα ταῖς παρασκευαῖς χρησάμενος. Ἀντώνιος δὲ τῆς μὲν ἐκείνου συμμαχίας οὐδὲν ἔφη δεῖσθαι, τὸν δὲ Ἄραβα, καὶ γὰρ ἀκηκόει παρ’ αὐτοῦ καὶ τῆς Κλεοπάτρας τὴν ἀπιστίαν, ἐπεξελθεῖν προσέταττεν. ἠξίου γὰρ ἡ Κλεοπάτρα ταῦτα λυσιτελεῖν αὐτῇ τὸν ἕτερον ὑπὸ θατέρου κακῶς πάσχειν ἡγουμένη. τούτων αὐτῷ παρ’ Ἀντωνίου λεχθέντων ὑποστρέψας Ἡρώδης συνεῖχεν τὸ στρατιωτικὸν ὡς εὐθὺς εἰς τὴν Ἀραβίαν ἐμβαλῶν, καὶ παρασκευασθέντος ἱππικοῦ καὶ πεζῆς δυνάμεως εἰς Διόσπολιν ἀφικνεῖται τῶν Ἀράβων ἐκεῖ συναντώντων· οὐ γὰρ ἐλελήθει τὰ περὶ τὸν πόλεμον αὐτούς· καὶ μάχης καρτερᾶς γενομένης ἐκράτησαν οἱ Ἰουδαῖοι. μετὰ δὲ ταῦτα πολλὴ στρατιὰ τῶν Ἀράβων εἰς Κάνατα συνῄει· χωρία δ’ ἐστὶ ταῦτα τῆς κοίλης Συρίας· Ἡρώδης τε προπεπυσμένος ἧκεν ἄγων ἐπ’ αὐτοὺς τὸ πλεῖστον ἧς εἶχεν δυνάμεως, καὶ πλησιάσας ἐν καλῷ στρατοπεδεύεσθαι διεγνώκει χάρακά τε βαλόμενος ἐξ εὐκαίρου ταῖς μάχαις ἐπιχειρεῖν. ταῦτα δὲ αὐτοῦ διατάττοντος ἐβόα τὸ πλῆθος τῶν Ἰουδαίων παρελόμενον τῆς τριβῆς ἄγειν ἐπὶ τοὺς Ἄραβας· ὥρμητο δὲ καὶ τῷ συντετάχθαι πιστεύειν καλῶς καὶ ταῖς προθυμίαις ἄμεινον ἐχόντων ὅσοι τὴν πρώτην μάχην νενικήκεσαν οὐδ’ εἰς χεῖρας ἐλθεῖν ἐπιτρέψαντες τοῖς ἐναντίοις. θορυβούντων οὖν καὶ πᾶσαν ἐπιδεικνυμένων σπουδὴν ἔγνω τῇ προθυμίᾳ τοῦ πλήθους ὁ βασιλεὺς ἀποχρήσασθαι, καὶ προειπών, ὡς οὐ λελείψεται τῆς ἐκείνων ἀρετῆς, πρῶτος ἐν τοῖς ὅπλοις ἡγήσατο πάντων κατ’ οἰκεῖα τέλη συνακολουθησάντων. ἔκπληξις δ’ εὐθὺς ἐμπίπτει τοῖς Ἄραψιν· ἀντιστάντες γὰρ εἰς ὀλίγον ὡς ἑώρων ἀμάχους ὄντας καὶ μεστοὺς φρονήματος, ἔφευγον οἱ πλείους ἐγκλίναντες κἂν διεφθάρησαν Ἀθηνίωνος μὴ κακώσαντος Ἡρώδην καὶ τοὺς Ἰουδαίους. οὗτος γὰρ ὢν στρατηγὸς μὲν Κλεοπάτρας ἐπὶ τῶν ἐκεῖ, διάφορος δὲ Ἡρώδῃ, τὸ μέλλον οὐκ ἀπαρασκεύως ἐσκόπει, δρασάντων μέν τι λαμπρὸν τῶν Ἀράβων ἐγνωκὼς ἡσυχίαν ἄγειν, ἡττωμένων δέ, ὃ καὶ συνέβη, τοῖς ἀπὸ τῆς χώρας συνεληλυθόσι τῶν οἰκείων παρεσκευασμένος ἐπιτίθεσθαι τοῖς Ἰουδαίοις. καὶ τότε κεκμηκόσι τε καὶ νικᾶν οἰομένοις ἀπροσδοκήτως ἐπιπεσὼν πολὺν ἐποίει φόνον· τάς τε γὰρ προθυμίας εἰς τοὺς ὁμολογουμένους ἐχθροὺς ἐκδαπανήσαντες οἱ Ἰουδαῖοι καὶ τῷ νικᾶν ἐπ’ ἀδείας χρώμενοι ταχὺ τῶν ἐπιχειρησάντων ἡττῶντο καὶ πολλὰς ἐλάμβανον πληγὰς ἐν χωρίοις ἀφίπποις καὶ πετρώδεσιν, ὧν πλείω τὴν ἐμπειρίαν εἶχον οἱ τὴν ἐπίθεσιν ποιησάμενοι. κακῶς δὲ πασχόντων οἵ τε Ἄραβες αὑτοὺς ἀνειλήφεσαν καὶ πάλιν ὑποστρέψαντες ἔκτεινον ἤδη τετραμμένους. ἐγένοντο δὲ παντοδαπαὶ κτιννυμένων ἀπώλειαι, καὶ τῶν διαπιπτόντων οὐ πολλοὶ συνέφευγον εἰς τὸ στρατόπεδον. ὁ δὲ βασιλεὺς Ἡρώδης ἀπεγνωκὼς τὰ κατὰ τὴν μάχην ἀφιππάζεται βοήθειαν ἄξων· οὐ μὴν ἔφθη καίπερ ἐσπουδακὼς ἐπαρκεῖν, ἀλλὰ τὸ μὲν στρατόπεδον ἥλω τῶν Ἰουδαίων, οἱ δ’ Ἄραβες οὐδὲ μετρίως εὐτυχήκεσαν ἐκ παραλόγου νίκην τε ἧς πλεῖστον ἀπεδέησαν ἀνειληφότες καὶ πολλὴν τῶν ἐναντίων ἀφῃρημένοι δύναμιν. τοὐντεῦθεν ὁ μὲν Ἡρώδης λῃστείαις ἐχρῆτο καὶ τὰ πολλὰ κατατρέχων τὴν τῶν Ἀράβων ἐκάκου ταῖς ἐπιδρομαῖς στρατοπεδευόμενος ἐπὶ τῶν ὅρων, καὶ τὸ μὲν σύμπαν ἐξίστατο κατὰ τοὐμφανὲς εἰς χεῖρας ἐλθεῖν, οὐκ ἀζήμιος δὲ γινόμενος τῇ συνεχείᾳ καὶ τῷ φιλοπόνῳ τῶν τε οἰκείων ἐπεμελεῖτο παντὶ τρόπῳ τὸ πταῖσμα διορθούμενος.", "st": "15.5.1"}, {"sp": "N", "t": "Ἐν τούτῳ καὶ τῆς ἐπ’ Ἀκτίῳ μάχης συνεσταμένης Καίσαρι πρὸς Ἀντώνιον ἑβδόμου δ’ ὄντος Ἡρώδῃ τῆς βασιλείας ἔτους σεισθεῖσα ἡ γῆ τῶν Ἰουδαίων, ὡς οὐκ ἄλλοτε ἐδόκει, τῶν ἐν τῇ χώρᾳ κτηνῶν πολὺν φθόρον ἐποίησεν. ἐφθάρησαν δὲ καὶ τῶν ἀνθρώπων ὑπὸ ταῖς πεπτωκυίαις οἰκίαις περὶ τρισμυρίους· τὸ μέντοι στρατιωτικὸν ἐν ὑπαίθρῳ διαιτώμενον οὐδὲν ὑπὸ τοῦ πάθους κατεβλάβη. ταῦτα πυνθανομένοις τοῖς Ἄραψιν καὶ μᾶλλον ἢ κατ’ ἀλήθειαν ἐξαγγελλόντων αὐτοῖς ὅσοι τοὺς ὑπὲρ τῶν γεγονότων λόγους τῷ μίσει τῶν ἀκουσομένων ἐχαρίζοντο μεῖζον ἐπῄει φρονεῖν, ὡς τῆς τε χώρας ἀνατετραμμένης τοῖς πολεμίοις καὶ διεφθορότων τῶν ἀνθρώπων μηδὲν ἔτι μηδ’ εἰς αὐτοὺς ἀντίπαλον καταλελεῖφθαι δοκεῖν. καὶ τῶν τε Ἰουδαίων τοὺς πρέσβεις, ἧκον γὰρ ἐπὶ τοῖς γεγενημένοις, συλλαβόντες ἀπέκτειναν καὶ μετὰ πάσης προθυμίας ἐχώρουν ἐπὶ τὸ στρατιωτικὸν αὐτῶν. οἱ δ’ οὔτε τὴν ἔφοδον ἐξεδέξαντο καὶ πρὸς τὰς συμφορὰς ἀθύμως διακείμενοι προΐεντο τὰ πράγματα, πλεῖστον ἀπογνώσεως ἐπ’ αὐτοῖς πεπονθότες· οὐ γὰρ ἦν οὔτε ἰσοτιμίας ἐλπὶς προηττημένοις ἐν ταῖς μάχαις οὔτε βοηθείας κεκακωμένων αὐτοῖς τῶν οἴκοι πραγμάτων. οὕτως οὖν ἐχόντων ἐπῆγεν ὁ βασιλεὺς λόγῳ τε πείθων τοὺς ἡγεμόνας καὶ πειρώμενος ἀναλαμβάνειν αὐτῶν πεπτωκότα τὰ φρονήματα. προδιακινήσας δὲ καὶ παραθαρρύνας τινὰς τῶν ἀμεινόνων ἐτόλμησεν ἤδη καὶ τῷ πλήθει διαλέγεσθαι πρότερον ὀκνῶν αὐτό, μὴ καὶ χαλεπῷ χρήσηται διὰ τὰς ἀτυχίας. παρεκάλει δὲ τοιούτους ποιούμενος εἰς τὸν ὄχλον τοὺς λόγους·", "st": "15.5.2"}, {"sp": "N", "t": "οὐκ ἀγνοῶ μὲν, ἄνδρες, ὅτι πολλὰ παρὰ τόνδε τὸν καιρὸν γεγένηται πρὸς τὰς πράξεις ἡμῖν ἐναντιώματα, καὶ θαρρεῖν εἰκὸς ἐν τοῖς τοιούτοις οὐδὲ τοὺς πλεῖστον ἀνδραγαθίᾳ διενηνοχότας. ἀλλ’ ἐπειδὴ κατεπείγει τε πολεμεῖν καὶ τῶν γεγονότων οὐδέν ἐστιν τοιοῦτον, ὃ μὴ δι’ ἑνὸς ἔργου καλῶς πραχθέντος ἐπανορθώσεται, παρακαλέσαι προειλόμην ὑμᾶς ἅμα καὶ διδάξαι δι’ ὧν ἂν ἐμμείναιτε τοῖς οἰκείοις φρονήμασιν. βούλομαι δὲ πρῶτον μὲν ὑπὲρ τοῦ πολεμεῖν ὡς δικαίως αὐτὸ ποιοῦμεν ἐπιδεῖξαι, διὰ τὴν ὕβριν τῶν ἐναντίων ἠναγκασμένοι· μέγιστον γὰρ εἰ μάθοιτε τοῦτο προθυμίας ὑμῖν αἴτιον ἔσται· μετὰ δὲ τοῦτο δεῖξαι, διότι καὶ τῶν ἐν ἡμῖν δεινὸν οὐδέν ἐστιν καὶ πλείστας εἰς τὸ νικᾶν ἔχομεν τὰς ἐλπίδας. ἄρξομαι δ’ ἀπὸ τοῦ πρώτου μάρτυρας ὑμᾶς ποιούμενος ὧν λέγω· τὴν γὰρ τῶν Ἀράβων παρανομίαν ἴστε μὲν δήπου καὶ πρὸς τοὺς ἄλλους ἅπαντας οὕτως ἀπίστως διακειμένων, ὡς εἰκὸς ἔχειν τὸ βάρβαρον καὶ ἀνεννόητον θεοῦ, πλεῖστα μέντοι προσέκρουσαν ἡμῖν πλεονεξίᾳ καὶ φθόνῳ καὶ ταῖς ταραχαῖς ἐφεδρεύοντες ἐξ ὑπογύου. καὶ τὰ μὲν πολλὰ τί δεῖ λέγειν; ἀλλὰ κινδυνεύοντας αὐτοὺς τῆς οἰκείας ἀρχῆς ἐκπεσεῖν καὶ δουλεύειν Κλεοπάτρᾳ τίνες ἄλλοι τοῦ δέους ἀπήλλαξαν; ἡ γὰρ ἐμὴ πρὸς Ἀντώνιον φιλία κἀκείνου πρὸς ἡμᾶς διάθεσις αἰτία γεγένηται μηδὲ τούτους ἀνήκεστόν τι παθεῖν, φυλαττομένου τἀνδρὸς μηδὲν ἐπιτηδεύειν, ὃ δύναιτ’ ἂν ὕποπτον ἡμῖν γενέσθαι. βουληθέντος δὲ ὅμως Κλεοπάτρᾳ μέρη τινὰ παρασχεῖν ἀφ’ ἑκατέρας τῆς ἀρχῆς, καὶ τοῦτο διῳκησάμην ἐγώ, καὶ πολλὰ δῶρα δοὺς ἰδίᾳ τὸ μὲν ἀσφαλὲς ἀμφοτέροις ἐπορισάμην, τὰς δὲ δαπάνας αὐτὸς ἀνέλαβον, διακόσια μὲν δοὺς τάλαντα, διακοσίων δ’ ἐγγυητὴς γενόμενος, ἃ τῇ μὲν προσοδευομένῃ γέγονεν, αὐτοὶ δ’ ὑπὸ τούτων ἀπεστερήμεθα. καίτοι γε ἄξιον ἦν μηδενὶ τῶν ὄντων Ἰουδαίους φόρον ἢ τῆς χώρας ἀπόμοιραν τελεῖν, εἰ δ’ οὖν, ἀλλ’ οὐχ ὑπέρ γε τούτων οὓς αὐτοὶ σεσώκαμεν, οὐδὲ τοὺς Ἄραβας ὁμολογήσαντας ἐντεύξεως καὶ χάριτος ὅτι τὴν ἀρχὴν ἐδόκουν τυγχάνειν ἀδικεῖν ἡμᾶς ἀποστεροῦντας, καὶ ταῦτα οὐ πολεμίους ὄντας, ἀλλὰ φίλους. ὡς ἥ γε πίστις ἔχουσα καὶ πρὸς τοὺς πολεμιωτάτους τόπον τοῖς γε φίλοις ἀναγκαιοτάτη τετηρῆσθαι, ἀλλ’ οὐ παρὰ τούτοις, οἳ τὸ μὲν κερδαίνειν ἐκ παντὸς τρόπου κάλλιστον ὑπειλήφασιν, τὸ δ’ ἄδικον οὐκ ἐπιζήμιον, εἰ μόνον κερδαίνειν δυνηθεῖεν. ἔστιν οὖν ἔτι ζήτησις ὑμῖν, εἰ δεῖ τοὺς ἀδίκους τιμωρεῖσθαι, τοῦτο καὶ τοῦ θεοῦ βουλομένου καὶ παραγγέλλοντος ἀεὶ μισεῖν τὴν ὕβριν καὶ τὴν ἀδικίαν, καὶ ταῦτα οὐ μόνον δίκαιον, ἀλλὰ καὶ ἀναγκαῖον πόλεμον ἐξιόντων; ἃ γὰρ ὁμολογεῖται παρανομώτατα τοῖς τε Ἕλλησιν καὶ τοῖς βαρβάροις, ταῦτα ἔπραξαν εἰς τοὺς ἡμετέρους πρέσβεις ἀποσφάξαντες αὐτούς, τῶν μὲν Ἑλλήνων ἱεροὺς καὶ ἀσύλους εἶναι φαμένων τοὺς κήρυκας, ἡμῶν δὲ τὰ κάλλιστα τῶν δογμάτων καὶ τὰ ὁσιώτατα τῶν ἐν τοῖς νόμοις δι’ ἀγγέλων παρὰ τοῦ θεοῦ μαθόντων· τοῦτο γὰρ τὸ ὄνομα καὶ ἀνθρώποις θεὸν εἰς ἐμφάνειαν ἄγει καὶ πολεμίους πολεμίοις διαλλάττειν δύναται. ποῖον οὖν μεῖζον ἂν γένοιτο ἀσέβημα ἢ πρέσβεις ἀποκτεῖναι τοὺς ὑπὲρ τοῦ δικαίου διαλεγομένους; πῶς δ’ ἂν ἔτι δύναιντο ἢ περὶ τὸν βίον εὐσταθεῖν ἢ περὶ τὸν πόλεμον εὐτυχεῖν τοιούτων αὐτοῖς πεπραγμένων; ἐμοὶ μὲν οὐδαμῶς δοκοῦσιν. ἴσως τοίνυν τὸ μὲν ὅσιον καὶ δίκαιόν ἐστιν μεθ’ ἡμῶν, ἀνδρειότεροι δὲ ἢ πλείους ἐκεῖνοι τετυχήκασιν. ἀλλὰ πρῶτον μὲν ἀνάξιον ὑμῖν ταῦτα λέγειν· μεθ’ ὧν γὰρ τὸ δίκαιόν ἐστιν μετ’ ἐκείνων ὁ θεός, θεοῦ δὲ παρόντος καὶ πλῆθος καὶ ἀνδρεία πάρεστιν. ἵνα δὲ καὶ τὰ καθ’ αὑτοὺς ἐξετάσωμεν, ἐνικήσαμεν τῇ πρώτῃ μάχῃ· συμβαλόντες τὴν δευτέραν οὐδὲ ἀντέσχον ἡμῖν, ἀλλ’ ἔφυγον εὐθὺς οὐχ ὑπομείναντες τὴν ἔφοδον καὶ τὰ φρονήματα· νικῶσιν ἡμῖν Ἀθηνίων ἐπέθετο πόλεμον ἀκήρυκτον ἐπάγων. πότερον ἀνδραγαθία τοῦτ’ ἔστιν ἐκείνων ἢ δευτέρα παρανομία καὶ ἐνέδρα; τί οὖν ἔλαττον φρονοῦμεν ἐφ’ οἷς μείζους ἔχειν δεῖ τὰς ἐλπίδας; πῶς δ’ ἂν καταπλαγείημεν τοὺς ὅταν μὲν ἐξ ἀληθείας ἀγωνίζωνται πάντοτε νικωμένους, ὅταν δὲ κρατεῖν νομισθῶσιν ἐξ ἀδικίας αὐτὸ ποιοῦντας; πῶς δ’ ἄν, εἰ καὶ γενναίους ἡγεῖταί τις αὐτούς, οὐ παρ’ αὐτὸ τοῦτο καὶ μᾶλλον ὁρμηθείη; τὸ γὰρ εὔψυχον οὐκ ἐν τῷ τοῖς ἀσθενεστέροις ἐπιχειρεῖν, ἀλλ’ ἐν τῷ δύνασθαι καὶ τῶν ἰσχυροτέρων κρατεῖν. εἰ δέ τινα καταπλήξεται τὰ οἰκεῖα πάθη καὶ τὰ περὶ τὸν σεισμὸν συμβεβηκότα, πρῶτον μὲν ἐννοηθήτω, διότι τοῦτ’ αὐτὸ καὶ τοὺς Ἄραβας ἐξαπατᾷ μείζω τὰ γενόμενα τῆς ἀληθείας ὑπειληφότας, ἔπειτα ὡς οὐ καλὸν ἐκείνοις τε τόλμης καὶ ἡμῖν δειλίας τὴν αὐτὴν αἰτίαν γενέσθαι· οἱ μὲν γὰρ οὐκ ἐξ οἰκείου τινὸς ἀγαθοῦ τὸ εὔψυχον ἔχουσιν, ἀλλ’ ἐκ τῆς περὶ ἡμᾶς ὡς κάμνοντας ἤδη τοῖς κακοῖς ἐλπίδος, ἡμεῖς δὲ χωρήσαντες ἐπ’ αὐτοὺς παραιρησόμεθα μὲν ἐκείνων τὸ μεῖζον φρονεῖν, ἀναληψόμεθα δ’ αὐτοὶ τὸ μηκέτι θαρροῦσιν μάχεσθαι. καὶ γὰρ οὔτε κεκακώμεθα τοσοῦτον οὔθ’, ὅπερ οἴονταί τινες, ὀργὴν θεοῦ παρέχει τὸ γεγονός, ἀλλὰ ταῦτα συμπτώματα γίνεται καὶ πάθη τινά. καὶ εἰ κατὰ θεοῦ γνώμην πέπρακται, δῆλον ὡς καὶ πέπαυται κατὰ τὴν ἐκείνου γνώμην ἀρκουμένου τοῖς γεγονόσιν· βουλόμενος γὰρ ἔτι μᾶλλον ἀδικεῖν, οὐκ ἂν μετεβάλετο. τὸν δὲ πόλεμον ὅτι καὶ θέλει τοῦτον ἐνεργεῖσθαι καὶ δίκαιον οἶδεν, δεδήλωκεν αὐτός· ἐνίων γὰρ ἐν τῷ σεισμῷ περὶ τὴν χώραν ἀπολομένων οὐδεὶς οὐδὲν ἔπαθεν τῶν ἐν τοῖς ὅπλοις, ἀλλὰ πάντες ἐσώθητε, φανερὸν ποιοῦντος τοῦ θεοῦ, διότι κἂν εἰ πανδημεὶ μετὰ τέκνων καὶ γυναικῶν ἐστρατεύεσθε, περιῆν ἂν ὑμῖν μηδὲν ἀνήκεστον παθεῖν. ταῦτα ἐνθυμηθέντες καὶ τὸ μεῖζον ὅτι παρὰ πάντα καιρὸν προϊστάμενον ἔχετε τὸν θεόν, ἐπεξέλθετε δικαίαις ἀνδραγαθίαις τοὺς ἀδίκους μὲν πρὸς φιλίαν, ἀσπόνδους δὲ ἐν ταῖς μάχαις, ἀνοσίους δὲ εἰς πρέσβεις, ἀεὶ δὲ τῆς ὑμετέρας ἀρετῆς ἡττημένους.", "st": "15.5.3"}, {"sp": "N", "t": "Ταῦτα ἀκούσαντες οἱ Ἰουδαῖοι πολὺ τὰς ψυχὰς ἀμείνους ἐγίνοντο πρὸς τὴν μάχην. Ἡρώδης δὲ θυσίας κατὰ τὰ νομιζόμενα ποιήσας καὶ μετὰ σπουδῆς ἀναλαβὼν αὐτοὺς ἦγεν ἐπὶ τοὺς Ἄραβας διαβὰς τὸν Ἰορδάνην ποταμὸν καὶ τῶν πολεμίων στρατοπεδεύεται πλησίον. ἐδόκει δ’ αὐτῷ φρούριον ἐν μέσῳ κείμενον καταλαβεῖν· οὕτως γὰρ αὐτὸς μὲν ὠφεληθήσεσθαι καὶ πρὸς τὸ θᾶττον συνάψαι τὴν μάχην καὶ εἰ παρέλκειν δέοι ἐρυμνὸν αὐτῷ πεπορισμένος τὸ στρατόπεδον. τὸ δ’ αὐτὸ καὶ τῶν Ἀράβων προνοούντων ἅμιλλα γίνεται περὶ τοῦ χωρίου καὶ πρῶτον μὲν ἀκροβολισμοῖς, εἶτα δὴ καὶ πλείους εἰς χεῖρας ἐρχόμενοι παρ’ ἀμφοτέρων ἕως ἡττηθέντες οἱ παρὰ τῶν Ἀράβων ἀπεχώρουν. τοῦτο εὐθὺς εἰς ἐλπίδας τοῖς Ἰουδαίοις οὐ μικρὸν ἐγεγόνει. καὶ τὴν δύναμιν αὐτοῦ ἐννοούμενον πάντα μᾶλλον ἢ πρὸς μάχην ἰέναι βουλόμενον θρασύτερον ἐπεχείρησεν αὐτῶν τὸν χάρακα διασπᾶν καὶ τοῦ στρατοπέδου προσάγων ἅπτεσθαι· τούτοις γὰρ ἐκβιασθέντες προῄεσαν ἄτακτοι καὶ προθυμίας ἢ τῆς εἰς τὸ νικᾶν ἐλπίδος οὐδ’ ὁτιοῦν ἐσχηκότες. ὅμως δ’ οὖν εἰς χεῖρας ᾔεσαν πλείους τε ὄντες καὶ διὰ τὸ κατεπείγειν ἐπὶ τὸ τολμηρὸν ὑπὸ τῆς ἀνάγκης στρατηγούμενοι, καὶ μάχη γίνεται καρτερὰ πιπτόντων ἑκατέρωθεν οὐκ ὀλίγων, τέλος δὲ τραπέντες οἱ Ἄραβες ἔφευγον. ἦν δὲ φόνος ἐγκλινάντων, ὡς μὴ μόνον ὑπὸ τῶν πολεμίων θνήσκειν, ἀλλὰ καὶ σφίσιν αὐτοῖς παραιτίους γίνεσθαι τῶν κακῶν, ὑπό τε πλήθους καὶ φορᾶς ἀτάκτου συμπατουμένων καὶ περιπιπτόντων τοῖς οἰκείοις ὅπλοις· πεντακισχίλιοι γοῦν αὐτῶν ἐγένοντο νεκροί. τὸ δ’ ἄλλο πλῆθος ἔφθη μὲν εἰς τὸ χαράκωμα συμφυγεῖν, εἶχεν δ’ οὐκ ἐν βεβαίῳ τὴν ἐλπίδα τῆς σωτηρίας ἀπορίᾳ τῶν ἐπιτηδείων καὶ μᾶλλον ὕδατος. οἵ τε Ἰουδαῖοι διώκοντες συνεισπεσεῖν μὲν οὐ κατίσχυσαν, περικαθεζόμενοι δὲ τῷ χάρακι καὶ παρατηροῦντες εἰσόδου τε τοὺς ἐπαρκοῦντας καὶ ἐξόδου φυγεῖν βουλομένους εἶργον.", "st": "15.5.4"}, {"sp": "N", "t": "Ἐν τοιούτοις οὖν ὄντες οἱ Ἄραβες ἐπρεσβεύοντο πρὸς τὸν Ἡρώδην, τὸ μὲν πρῶτον ὑπὲρ διαλύσεως, ἔπειτα, τὸ γὰρ δίψος ἤπειγεν, πᾶν ὁτιοῦν ὑφιστάμενοι καὶ τυχεῖν εἰς τὸ παρὸν ἀδείας ἠξιωκότες. ὁ δ’ οὔτε πρέσβεις οὔτε λύτρα τῶν ἡλωκότων οὔτ’ ἄλλο τι μέτριον προσίετο φιλόνεικος ὢν ἐκδικῆσαι τὰς παρανομίας τὰς εἰς αὐτοὺς ἐξ ἐκείνων γεγενημένας. καταναγκαζόμενοί τε τοῖς τε ἄλλοις καὶ τῷ δίψει προϊόντες αὑτοὺς ἐνεχείριζον ἄγειν καὶ δεῖν, [καὶ] πέντε μὲν ἡμέραις τετρακισχίλιοι τὸ πλῆθος οὕτως ἑάλωσαν, τῇ δ’ ἕκτῃ πάντες οἱ λοιποὶ διέγνωσαν ἐξιέναι πολέμου νόμῳ χωρήσαντες ἐπὶ τοὺς ἐναντίους ἐγχειρεῖν, καὶ εἰ δέοι τι πάσχειν, αἱρούμενοι καὶ μὴ διαφθείρεσθαι κατ’ ὀλίγους ἀδόξως. ταῦτα δὲ γνόντες ἐξῆλθον μὲν τοῦ χαρακώματος, διήρκεσαν δ’ οὐδαμῶς τῇ μάχῃ, λαμπρῶς μὲν ἀγωνίσασθαι κεκακωμένοι καὶ τὰς ψυχὰς καὶ τὰ σώματα τόπον οὐκ ἔχοντες, κέρδος δ’ εἰ θνήσκοιεν ἐν συμφορᾷ τὸ ζῆν ποιούμενοι, καὶ πίπτουσιν αὐτῶν ἐν τῇ προτέρᾳ μάχῃ περὶ ἑπτακισχιλίους. τοιαύτῃ δὲ πληγῇ χρησαμένων φρονήματος μὲν ὅσον ἦν πρότερον αὐτοῖς ἀφῄρηντο, τεθαυμακότες δὲ ἐν ταῖς οἰκείαις συμφοραῖς τὴν Ἡρώδου στρατηγίαν εἴς τε τὸ λοιπὸν εἶξαν καὶ προστάτην ἀπεφήναντο τοῦ ἔθνους. ὁ δὲ πλεῖστον ἐπὶ τοῖς εὐημερήμασιν ἠξιωκὼς φρονεῖν ἀνέστρεψεν εἰς τὴν οἰκείαν, προσειληφὼς ἀξίωμα καὶ διὰ ταύτην τὴν ἀνδραγαθίαν.", "st": "15.5.5"}, {"sp": "N", "t": "Τὰ μὲν οὖν ἄλλα καλῶς εἶχεν αὐτῷ δυσεπιχειρήτῳ κατὰ πάντα γεγενημένῳ, κίνδυνος δ’ ἐμπίπτει τὴν ὑπὲρ τῶν ὅλων κρίσιν ἐξάγων Ἀντώνιον Καίσαρος ἐν τῇ κατ’ Ἄκτιον μάχῃ νενικηκότος· τότε γὰρ ἀπέγνωστο αὐτῷ τε Ἡρώδῃ τὰ πράγματα καὶ τοῖς περὶ αὐτὸν ὁμοίως ἐχθροῖς τε καὶ φίλοις· οὐ γὰρ ἦν εἰκὸς ἀτιμώρητον μενεῖν τοσαύτης αὐτῷ φιλίας πρὸς Ἀντώνιον γεγενημένης. ἦν οὖν τοῖς μὲν φίλοις ἀπόγνωσις τῶν κατ’ αὐτὸν ἐλπίδων, ὅσοι δ’ ἐχθρῶς εἶχον ἐδόκουν μὲν ἐξ ἐμφανοῦς συνάχθεσθαι, πάθος δὲ λεληθὸς ἐφηδομένων εἶχον ὡς ἀμείνονος τευξόμενοι τῆς μεταβολῆς. αὐτός τε Ἡρώδης τὸν Ὑρκανὸν ὁρῶν μόνον ἐπ’ ἀξιώματος βασιλικοῦ συμφέρειν ᾤετο μηκέτ’ ἐμποδὼν ἐᾶν, εἰ μὲν περισωθείη καὶ διαφύγοι τὸν κίνδυνον, ἀσφαλὲς ἡγούμενος πρὸς τὸ μὴ τοῖς τοιούτοις αὐτοῦ καιροῖς ἐφορμεῖν ἄνδρα τυχεῖν τῆς βασιλείας ἀξιώτερον, εἰ δὲ καὶ πάσχοι τι διὰ Καίσαρος, φθόνῳ τὸν μόνον ἐπὶ τῆς βασιλείας γενησόμενον ἐπιθυμῶν ἐξελεῖν.", "st": "15.6.1"}, {"sp": "N", "t": "Ταῦτα δ’ αὐτοῦ δι’ ἐννοίας ἔχοντος ἐνεδόθη τι καὶ παρ’ ἐκείνων· ὁ μὲν γὰρ Ὑρκανὸς ἐπιεικείᾳ τρόπου καὶ τότε καὶ τὸν ἄλλον χρόνον οὐκ ἠξίου πολυπραγμονεῖν οὐδὲ νεωτέρων ἅπτεσθαι, συγχωρῶν τῇ τύχῃ πᾶν τὸ δι’ ἐκείνης γινόμενον ἠγαπηκέναι. φιλόνεικος δ’ ἦν Ἀλεξάνδρα καὶ τὴν ἐλπίδα τῆς μεταβολῆς ἀκρατῶς φέρουσα λόγους ἐποιεῖτο πρὸς τὸν πατέρα, μὴ μέχρι παντὸς ἀναμεῖναι τὴν Ἡρώδου παρανομίαν εἰς τὸν αὐτῶν οἶκον, ἀλλὰ προλαβεῖν ἀσφαλείᾳ τὰς αὖθις ἐλπίδας, καὶ γράφειν ἠξίου περὶ τούτων Μάλχῳ τῷ τὴν ἀραβαρχίαν ἔχοντι δέξασθαί τε αὐτὸν καὶ δι’ ἀσφαλείας ἔχειν· ὑπεξελθόντων γὰρ εἰ τὰ περὶ τὸν Ἡρώδην οὕτως χωρήσειεν, ὡς εἰκὸς ἐν ἔχθρᾳ Καίσαρος, αὐτοὺς ἔσεσθαι τοὺς τὴν ἀρχὴν ἀπολαμβάνοντας μόνους καὶ διὰ τὸ γένος καὶ διὰ τὴν εὔνοιαν τῶν ὄχλων. ταῦτα πειθούσης ὁ μὲν Ὑρκανὸς διωθεῖτο τοὺς λόγους, φιλόνεικον δέ τι καὶ γυναικεῖον αὐτῆς πεπονθυίας καὶ μήτε νύκτα μήθ’ ἡμέραν ἀπολειπομένης, ἀλλ’ ἀεὶ περὶ τούτων καὶ τῆς Ἡρώδου πρὸς αὐτοὺς ἐπιβουλῆς διαλεγομένης, ἀνεπείσθη τέλος ἐπιστολὴν δοῦναι Δοσιθέῳ τινὶ τῶν περὶ αὐτὸν φίλων, ἐν ᾗ συντέτακτο πέμπειν αὐτῷ τὸν Ἄραβα τοὺς ἀναληψομένους καὶ παραπέμψοντας ἱππέας ἐπὶ τὴν Ἀσφαλτῖτιν λίμνην· αὕτη δ’ ἀπέχει τῶν Ἱεροσολυμιτῶν ὅρων σταδίους τριακοσίους. ἐπίστευεν δὲ τῷ Δοσιθέῳ θεραπεύοντος αὐτοῦ καὶ αὐτὸν καὶ τὴν Ἀλεξάνδραν καὶ τῆς πρὸς Ἡρώδην δυσνοίας οὐ μικρὰς αἰτίας ἔχοντος· Ἰωσήπου τε γάρ, ὃν ἐκεῖνος ἀνῃρήκει, συγγενὴς ἦν καὶ τῶν ἐν Τύρῳ φονευθέντων ὑπ’ Ἀντωνίου πρότερον ἀδελφός. οὐ μὴν ἐπήγαγεν ταῦτα τὸν Δοσίθεον Ὑρκανῷ πιστὸν εἰς τὴν ὑπηρεσίαν γενέσθαι, προτιμήσας δὲ τῶν ἐκείνου τὰς ἐκ τοῦ βασιλεύοντος ἐλπίδας ἐπιδίδωσιν Ἡρώδῃ τὴν ἐπιστολήν. ὁ δὲ τῆς εὐνοίας ἀποδεξάμενος ἔτι καὶ τοῦτο προσυπουργῆσαι παρεκελεύετο, πτύξαντα τὴν ἐπιστολὴν καὶ κατασημηνάμενον ἀποδοῦναι τῷ Μάλχῳ καὶ τὰ παρ’ ἐκείνου γράμματα λαβεῖν· οὐ γὰρ μικρὸν τὸ διάφορον καὶ τὴν ἐκείνου γνώμην αὐτὸν εἰδέναι. ταῦτα δὲ τοῦ Δοσιθέου προθύμως ὑπουργήσαντος ὁ μὲν Ἄραψ ἀντεπέστελλεν αὐτόν τε Ὑρκανὸν δέχεσθαι καὶ τοὺς σὺν αὐτῷ πάντας καὶ Ἰουδαίων ὅσοι τὰ ἐκείνου φρονοῦσιν, δύναμίν τε πέμψειν τὴν μετ’ ἀσφαλείας αὐτοὺς κομιοῦσαν καὶ πρὸς μηδὲν ἐνδεήσειν ὧν ἠξίου. ὡς δὲ καὶ ταύτην Ἡρώδης ἐδέξατο τὴν ἐπιστολήν, εὐθύς τε μεταπέμπεται τὸν Ὑρκανὸν καὶ περὶ τῶν γενομένων αὐτῷ συνθηκῶν πρὸς τὸν Μάλχον ἀνέκρινεν. ἀρνησαμένου δὲ τὰς ἐπιστολὰς δείξας τῷ συνεδρίῳ διεχειρίσατο τὸν ἄνδρα.", "st": "15.6.2"}, {"sp": "N", "t": "Ταῦτα δὲ γράφομεν ἡμεῖς, ὡς ἐν τοῖς ὑπομνήμασιν τοῖς τοῦ βασιλέως Ἡρώδου περιείχετο. τοῖς δ’ ἄλλοις οὐ κατὰ ταῦτα συμφωνεῖ· τὸν γὰρ Ἡρώδην οὐκ ἐπὶ τοιούτοις δοκοῦσιν, ἀλλ’ ἐξ ἐπιβουλῆς μᾶλλον Ὑρκανῷ τὴν αἰτίαν ἐπάγοντα κατὰ τὸν αὐτοῦ τρόπον ἀποκτεῖναι· γράφουσι γὰρ οὕτως, ἐν συμποσίῳ τινὶ μηδὲν ὑποψίας ἐνδιδόντα λόγον Ὑρκανῷ προσφέρειν, εἴ τινας ἐπιστολὰς παρὰ τοῦ Μάλχου λάβοι, καὶ τὸν μὲν ὁμολογῆσαι προσαγορευτικὰ γράμματα κομίσασθαι, τὸν δ’, εἰ καί τινα δωρεὰν εἰληφὼς εἴη, πάλιν ἐπερέσθαι· τοῦ δὲ μηδὲν πλέον ἢ κτηνῶν ἀναβατικῶν τέτταρα πέμψαντος αὐτῷ λαβεῖν, εἰς αἰτίαν τὸ τοιοῦτον ἐπαναφέροντα δωροδοκίας καὶ προδοσίας ἀπάγχειν προστάξαι τὸν ἄνδρα. τεκμήρια δὲ τοῦ μηδὲν ἁμαρτόντα τοιούτῳ τέλει περιπεσεῖν καταλογίζονται τὴν ἐπιείκειαν τοῦ τρόπου καὶ τὸ μήτ’ ἐν νεότητι θράσους ἢ προπετείας ἐπίδειξιν πεποιῆσθαι μήθ’ ὅτε τὴν βασιλείαν αὐτὸς εἶχεν, ἀλλὰ κἀν ταύτῃ τὰ πλεῖστα τῶν κατὰ τὴν διοίκησιν Ἀντιπάτρῳ παρακεχωρηκέναι. τότε δ’ ἐντῶ πλείω μὲν ἢ ὀγδοήκοντα γεγονὼς ἐτύγχανεν ἔτη, κρατοῦντα δὲ μετὰ πάσης ἀσφαλείας τὸν Ἡρώδην ἠπίστατο, διαβεβήκει δὲ καὶ τὸν Εὐφράτην τοὺς ἐν τῷ πέραν τιμῶντας αὐτὸν καταλιπὼν ὡς ὅλος ἐπ’ ἐκείνῳ γενησόμενος· ἐγχειρεῖν οὖν τι καὶ καινοτέρων ἅπτεσθαι πάντων ἀπιθανώτατον καὶ οὐ πρὸς τῆς ἐκείνου φύσεως, ἀλλὰ ταῦτα σκῆψιν Ἡρώδου γενέσθαι.", "st": "15.6.3"}, {"sp": "N", "t": "Τοῦτο μὲν τὸ τέλος Ὑρκανῷ συνέπεσεν τοῦ βίου ποικίλαις καὶ πολυτρόποις χρησαμένῳ ταῖς ἐν τῷ ζῆν τύχαις· εὐθὺς μὲν [γὰρ] ἐν ἀρχῇ βασιλευούσης αὐτῷ τῆς μητρὸς Ἀλεξάνδρας ἀρχιερεὺς καταστὰς τοῦ Ἰουδαίων ἔθνους ἔτεσιν ἐννέα τὴν τιμὴν κατέσχεν. παραλαβὼν δὲ τὴν βασιλείαν ἀποθανούσης τῆς μητρὸς αὐτῷ καὶ ταύτην κατασχὼν τρεῖς μῆνας ἐκπίπτει μὲν ὑπ’ Ἀριστοβούλου τοῦ ἀδελφοῦ, κατάγεται δ’ αὖθις ὑπὸ Πομπηίου καὶ πάσας τὰς τιμὰς ἀπολαβὼν ἔτη τεσσαράκοντα διετέλεσεν ἐν αὐτοῖς. ἀφαιρεθεὶς δὲ τὸ δεύτερον ὑπ’ Ἀντιγόνου καὶ λωβηθεὶς τὸ σῶμα παρὰ Πάρθοις αἰχμάλωτος ἐγένετο. κἀκεῖθεν εἰς τὴν οἰκείαν ἐπανῄει χρόνῳ διὰ τὰς ἐξ Ἡρώδου προτεινομένας ἐλπίδας, ὧν οὐδὲν αὐτῷ κατὰ προσδοκίαν ἀπήντα πολυπαθείᾳ βίου χρησαμένῳ, τὸ δυσχερέστατον δέ, ὡς προειρήκαμεν, ἐν γήρᾳ τέλους οὐκ ἀξίου τυχεῖν· δοκεῖ γὰρ ἐπιεικὴς καὶ μέτριος ἐν πᾶσιν γενέσθαι καὶ τὰ πλεῖστα τῆς ἀρχῆς ὑπὸ διοικηταῖς ἄγειν, οὐ πολυπράγμων οὐδὲ δεινὸς ὢν βασιλείας ἐπιστατεῖν, Ἀντιπάτρῳ τε καὶ Ἡρώδῃ μέχρι τοῦδε προελθεῖν ἐγένετο διὰ τὴν ἐπιείκειαν τὴν ἐκείνου, καὶ τὸ πέρας οὔτε δίκαιον οὔτ’ εὐσεβὲς ἐξ αὐτῶν εὕρατο τοιούτου τέλους.", "st": "15.6.4"}, {"sp": "N", "t": "Ὁ δὲ Ἡρώδης ὡς καὶ τὸν Ὑρκανὸν ἐκποδὼν ἐποιήσατο, σπεύδων πρὸς Καίσαρα καὶ μηδὲν ἐλπίσαι περὶ τῶν αὐτοῦ πραγμάτων δυνάμενος χρηστὸν ἐκ τῆς γενομένης αὐτῷ πρὸς Ἀντώνιον φιλίας, ὕποπτον μὲν εἶχεν τὴν Ἀλεξάνδραν, μὴ τῷ καιρῷ συνεπιθεμένη τὸ πλῆθος ἀποστήσῃ καὶ στασιάσῃ τὰ περὶ τὴν βασιλείαν πράγματα. παρετίθετο δὲ πάντα Φερώρᾳ τἀδελφῷ, καὶ τὴν μητέρα Κύπρον καὶ τὴν ἀδελφὴν καὶ τὴν γενεὰν ἅπασαν ἐν Μασάδοις κατεστήσατο παρακελευσάμενος, εἴ τι περὶ αὐτὸν ἀκούσαιεν δυσχερές, ἔχεσθαι τῶν πραγμάτων. Μαριάμμην δὲ τὴν αὐτοῦ γυναῖκα, δυνατὸν γὰρ οὐκ ἦν ἐν διαφορᾷ τῇ πρὸς τὴν ἀδελφὴν καὶ τὴν μητέρα τὴν ἐκείνου δίαιταν τὴν αὐτὴν ἔχειν, ἐν Ἀλεξανδρείῳ σὺν Ἀλεξάνδρᾳ τῇ μητρὶ κατεστήσατο Ἰώσηπον τὸν ταμιαίαν καὶ τὸν Ἰτουραῖον Σόαιμον ἐπ’ αὐτῶν καταλιπών, πιστοτάτους μὲν ἐξ ἀρχῆς γενομένους αὐτῷ, τότε δὲ προφάσει τιμῆς φρουρεῖν ἀπολειφθέντας τὰς γυναῖκας. ἦν δὲ κἀκείνοις ἐντολὴ μαθόντας τι περὶ αὐτοῦ δυσχερὲς ἐξ αὐτῆς ἀμφοτέρας μεταχειρίσασθαι, τὴν δὲ βασιλείαν εἰς δύναμιν τοῖς παισὶν αὐτοῦ σὺν τἀδελφῷ Φερώρᾳ διατηρεῖν.", "st": "15.6.5"}, {"sp": "N", "t": "Ταύτας δοὺς τὰς ἐντολὰς αὐτὸς εἰς Ῥόδον ἠπείγετο Καίσαρι συντυχεῖν. κἀπειδὴ κατέπλευσεν εἰς τὴν πόλιν, ἀφῄρητο μὲν τὸ διάδημα, τοῦ δ’ ἄλλου περὶ αὐτὸν ἀξιώματος οὐδὲν ὑφεικώς, ὅτε καὶ κοινωνῆσαι λόγου κατὰ τὴν συντυχίαν ἠξιώθη, πολὺ μᾶλλον ἐνέφηνεν τὸ μεγαλεῖον τοῦ κατ’ αὐτὸν φρονήματος, οὔτ’ εἰς ἱκεσίαν, ὡς εἰκὸς ἐπὶ τοιούτοις, τραπόμενος οὔτε δέησίν τινα προτείνων ὡς ἐφ’ ἡμαρτημένοις, ἀποδοὺς δὲ τὸν λογισμὸν τῶν πεπραγμένων ἀνυποτιμήτως. ἔλεγεν γὰρ τῷ Καίσαρι καὶ φιλίαν αὐτῷ γενέσθαι μεγίστην πρὸς Ἀντώνιον καὶ πάντα πρᾶξαι κατὰ τὴν αὐτοῦ δύναμιν, ὡς ἐπ’ ἐκείνῳ γενήσεται τὰ πράγματα, στρατείας μὲν οὐ κοινωνήσας κατὰ περιολκὰς τῶν Ἀράβων, πέμψας δὲ καὶ χρήματα καὶ σῖτον ἐκείνῳ. καὶ ταῦτ’ εἶναι μετριώτερα τῶν ἐπιβαλλόντων αὐτῷ γενέσθαι· τὸν γὰρ ὁμολογοῦντα μὲν εἶναι φίλον, εὐεργέτην δ’ ἐκεῖνον ἐπιστάμενον, παντὶ μέρει καὶ ψυχῆς καὶ σώματος καὶ περιουσίας συγκινδυνεύειν δέον ὧν αὐτὸς ἔλαττον ἢ καλῶς εἶχεν ἀναστραφεὶς ἀλλ’ ἐκεῖνό γε συνειδέναι καλῶς ἑαυτῷ πεποιηκότι τὸ μηδ’ ἡττηθέντα τὴν ἐν Ἀκτίῳ μάχην καταλιπεῖν, μηδὲ συμμεταβῆναι ταῖς ἐλπίσιν φανερῶς ἤδη μεταβαινούσης καὶ τῆς τύχης, φυλάξαι δ’ αὑτὸν, εἰ καὶ μὴ συναγωνιστὴν ἀξιόχρεων, ἀλλὰ σύμβουλόν γε δεξιώτατον Ἀντωνίῳ τὴν μίαν αἰτίαν τοῦ κἂν σώζεσθαι καὶ μὴ τῶν πραγμάτων ἐκπεσεῖν ὑποδεικνύντα, Κλεοπάτραν ἐπανελέσθαι· προανῃρημένης γὰρ ἐκείνης αὐτῷ τε τῶν πραγμάτων ἄρχειν ὑπεῖναι καὶ τὰς πρὸς σὲ συμβάσεις ῥᾷον εὑρίσκεσθαι τῆς ἔχθρας. ὧν οὐδὲν ἐκεῖνος ἐννοηθεὶς ἀλυσιτελῶς μὲν αὐτῷ, συμφερόντως δὲ σοὶ προετίμησεν τὴν ἀβουλίαν. νῦν οὖν εἰ μὲν τῇ πρὸς Ἀντώνιον ὀργῇ κρίνεις καὶ τὴν ἐμὴν προθυμίαν, οὐκ ἂν εἴη μοι τῶν πεπραγμένων ἄρνησις οὐδ’ ἀπαξιώσω τὴν ἐμαυτοῦ πρὸς ἐκεῖνον εὔνοιαν ἐκ τοῦ φανεροῦ λέγειν, εἰ δὲ τὸ πρόσωπον ἀνελών, τίς εἰμι πρὸς τοὺς εὐεργέτας καὶ ποῖος φίλος ἐξετάζοις, ἐνέσται σοι πείρᾳ τῶν ἤδη γεγενημένων ἡμᾶς εἰδέναι· τοῦ γὰρ ὀνόματος ὑπαλλαγέντος οὐδὲν ἔλαττον αὐτὸ τὸ τῆς φιλίας βέβαιον ἐν ἡμῖν εὐδοκιμεῖν δυνήσεται.", "st": "15.6.6"}, {"sp": "N", "t": "Τοιαῦτα λέγων καὶ παράπαν ἐμφαίνων τὸ τῆς ψυχῆς ἐλευθέριον οὐ μετρίως ἐπεσπᾶτο τὸν Καίσαρα φιλότιμον ὄντα καὶ λαμπρόν, ὥστ’ αὐτῷ τὰς τῶν ἐγκλημάτων αἰτίας σύστασιν ἤδη τῆς πρὸς ἐκεῖνον εὐνοίας πραγματεύεσθαι. καὶ τό τε διάδημα πάλιν ἀποκαθίστησιν αὐτῷ καὶ προτρεψάμενος μηδὲν ἐλάττω περὶ αὐτὸν ἢ πρότερον ἦν περὶ τὸν Ἀντώνιον φαίνεσθαι, διὰ πάσης ἦγε τιμῆς, προσθεὶς ὅτι καιταιδιος γράψειεν, ἁπάσῃ προθυμίᾳ τὰ πρὸς τοὺς μονομάχους αὐτῷ συλλαβέσθαι τὸν Ἡρώδην. τοσαύτης ἀποδοχῆς ἠξιωμένος καὶ παρ’ ἐλπίδας ὁρῶν αὐτῷ πάλιν ἐξ ὑπαρχῆς βεβαιοτέραν τὴν βασιλείαν δόσει Καίσαρος καὶ δόγματι Ῥωμαίων, ὅπερ ἐκεῖνος αὐτῷ πρὸς τὸ βέβαιον ἐπραγματεύσατο, παρέπεμψεν ἐπ’ Αἰγύπτου Καίσαρα, δωρησάμενος ὑπὲρ δύναμιν αὐτόν τε καὶ τοὺς φίλους καὶ πᾶσαν ἐμφαίνων μεγαλοψυχίαν. ᾐτεῖτο δὲ καὶ τῶν Ἀντωνίῳ συνήθων Ἀλέξανδρον ὡς μηδὲν ἀνήκεστον παθεῖν, ἀλλὰ τούτου μὲν οὐκ ἔτυχεν ὅρκῳ προκατειλημμένου Καίσαρος· ἐπανῄει δὲ πάλιν εἰς τὴν Ἰουδαίαν πλείονί τε τιμῇ καὶ παρρησίᾳ καὶ τοῖς τὰ ἐναντία προσδοκήσασιν ἔκπληξιν παρέσχεν ὡς ἀεὶ τὸ λαμπρότερον ἐκ τῶν κινδύνων κατ’ εὐμένειαν τοῦ θεοῦ προσεπικτώμενος. εὐθὺς οὖν περὶ τὴν ὑποδοχὴν ἐγεγόνει Καίσαρος ἀπὸ Συρίας εἰς Αἴγυπτον εἰσβαλεῖν μέλλοντος. κἀπειδὴ παρῆν, δέχεται μὲν αὐτὸν ἐν Πτολεμαΐδι πάσῃ τῇ βασιλικῇ θεραπείᾳ, παρέσχεν δὲ καὶ τῷ στρατεύματι ξένια καὶ τῶν ἐπιτηδείων ἀφθονίαν. κἀν τοῖς εὐνουστάτοις ἐξητάζετο τάς τε δυνάμεις ἐκτάττοντος συνιππαζόμενος καὶ δεχόμενος αὐτὸν καὶ φίλους ἀνδρῶσιν ἑκατὸν καὶ πεντήκοντα πᾶσιν εἰς πολυτέλειαν καὶ πλοῦτον ὑπηρεσίας ἠσκημένοις. παρέσχεν δὲ καὶ τὴν ἄνυδρον διερχομένοις τὴν τῶν ἐπειγόντων χορηγίαν, ὡς μήτε οἴνου μήτε ὕδατος, ὃ καὶ μᾶλλον ἦν ἐν χρείᾳ τοῖς στρατιώταις, ὑστερηθῆναι. αὐτόν γε μὴν Καίσαρα ταλάντοις ὀκτακοσίοις ἐδωρήσατο καὶ παρέστησεν ἅπασιν ἔννοιαν λαβεῖν, ὅτι τῆς βασιλείας ἧς εἶχεν πολὺ μείζω καὶ λαμπρότερα κατὰ τὰς ὑπουργίας ἐπεδείκνυτο. τοῦτ’ αὐτὸν καὶ μᾶλλον εἰς πίστιν εὐνοίας καὶ προθυμίας ἐπισυνίστη καὶ πλεῖστον ἠνέγκατο τῇ χρείᾳ τοῦ καιροῦ τὸ μεγαλόψυχον ἁρμόσας. ὁ δὲ καὶ πάλιν ἐπανιόντων ἀπ’ Αἰγύπτου τῶν πρώτων οὐδενὸς τὰς ὑπηρεσίας ἥττων ἐφάνη.", "st": "15.6.7"}, {"sp": "N", "t": "Τότε μέντοι γενόμενος ἐν τῇ βασιλείᾳ τεταραγμένην αὐτῷ τὴν οἰκίαν καταλαμβάνει καὶ χαλεπῶς ἐχούσας τήν τε γυναῖκα Μαριάμμην καὶ τὴν μητέρα τὴν ἐκείνης Ἀλεξάνδραν. οἰηθεῖσαι γάρ, ὅπερ ἦν ὕποπτον, οὐκ εἰς ἀσφάλειαν τῶν σωμάτων εἰς ἐκεῖνο κατατεθῆναι τὸ χωρίον, ἀλλ’ ὡς φρουρᾷ μηθενὸς μήτε τῶν ἄλλων μήθ’ αὑτῶν ἐξουσίαν ἔχοιεν, χαλεπῶς ἔφερον. ἥ τε Μαριάμμη τὸν μὲν ἔρωτα τοῦ βασιλέως ὑπόκρισιν ἄλλως καὶ πρὸς τὸ συμφέρον αὐτῷ γινομένην ἀπάτην ὑπελάμβανεν, ἤχθετο δὲ τῷ μηδ’ εἰ πάσχοι τι δεινὸν ἐκεῖνος ἐλπίδα τοῦ βιώσεσθαι δι’ αὐτὸν ἐσχηκέναι καὶ τὰς Ἰωσήπῳ δοθείσας ἐντολὰς ἀνεμνημόνευεν, ὥστ’ ἤδη διὰ θεραπείας εἶχεν τοὺς φρουροὺς καὶ μᾶλλον τὸν Σόαιμον, ἐν ἐκείνῳ τὸ πᾶν ἐπισταμένη. Σόαιμος δὲ κατὰ μὲν τὰς ἀρχὰς πιστὸς ἦν οὐδὲν ὧν Ἡρώδης ἐνετέταλτο παριείς, λόγοις δὲ καὶ δωρεαῖς λιπαρέστερον τῶν γυναικῶν ἐκθεραπευουσῶν αὐτὸν ἡττᾶτο κατὰ μικρὸν ἤδη καὶ τέλος ἐξεῖπεν ἁπάσας τὰς ἐντολὰς τοῦ βασιλέως, μάλιστα μὲν οὐδ’ ἐλπίσας αὐτὸν ἐπὶ τῆς αὐτῆς ὑποστρέψειν ἐξουσίας· ἐν ᾧ καὶ μᾶλλον ἐκφυγὼν τὸν ἀπ’ αὐτοῦ κίνδυνον οὐ μικρὰ χαριεῖσθαι ταῖς γυναιξὶν ὑπελάμβανεν, αἷς ἦν εἰκὸς οὐκ ἀποτεύξεσθαι τοῦ περιόντος ἀξιώματος, ἀλλὰ καὶ πλέον εἰς τὴν ἀμοιβὴν ἕξειν εἰ βασιλευούσας ἢ τοῦ βασιλεύοντος ἀγχοῦ γενησομένας. ἐπήλπιζε δ’ αὐτὸν οὐχ ἧττον, εἰ καὶ πάντα κατὰ νοῦν πράξας ὑποστρέψειεν Ἡρώδης, μηδὲν ὅτι τῇ γυναικὶ δυνήσεσθαι βουλομένῃ γε ἀντειπεῖν· ἠπίστατο γὰρ τὸν πρὸς τὴν Μαριάμμην ἔρωτα μείζονα λόγου τῷ βασιλεῖ. ταῦτα προσεκλύσαντα τὰς ἐντολὰς ἐξαγγεῖλαι Μαριάμμη χαλεπῶς ἤκουσεν, εἰ μηδὲν πέρας αὐτῇ τῶν ἐξ Ἡρώδου κινδύνων ἔσται, χαλεπῶς δὲ διέκειτο, μηδενὸς μὲν τυχεῖν αὐτὸν τῶν ἴσων εὐχομένη, δυσύποιστον δ’ εἰ τύχοι τὸν μετ’ αὐτοῦ βίον κρίνουσα. καὶ τοῦτο διέδειξεν ἐν ὑστέρῳ μηδὲν ἐπικρυψαμένη τοῦ κατ’ αὐτὴν πάθους.", "st": "15.7.1"}, {"sp": "N", "t": "Ὁ μὲν γὰρ ἐπὶ μεγάλοις οἷς παρ’ ἐλπίδας εὐτυχήκει καταπεπλευκὼς πρώτῃ μέν, ὡς εἰκός, τῇ γυναικὶ περὶ τούτων εὐηγγελίζετο, μόνην δὲ ἐκ πάντων διὰ τὸν ἔρωτα καὶ τὴν οὖσαν αὐτῷ συνήθειαν προτιμῶν ἠσπάζετο. τῇ δ’ οὔτε τὰς εὐημερίας διηγουμένου χαίρειν μᾶλλον ἢ χαλεπῶς φέρειν συνέβαινεν οὔτ’ ἐπικρύπτεσθαι τὸ πάθος δυνατὸν ἦν. ἀλλ’ ὑπ’ ἀδοξίας καὶ τῆς περιούσης εὐγενείας πρὸς μὲν τοὺς ἀσπασμοὺς ἀνέστενεν, τοῖς δὲ διηγήμασιν ἄχθεσθαι μᾶλλον ἢ συγχαίρειν ἐνέφαινεν, ὡς οὐχ ὕποπτα μόνον ἀλλὰ καὶ καταφανῆ γινόμενα τὸν Ἡρώδην ἐπιταράττειν. ἠδημόνει μὲν γὰρ ὁρῶν τὸ παράλογον τῆς γυναικὸς εἰς αὐτὸν μῖσος οὐκ ἀποκεκρυμμένον, ἤχθετο δὲ τῷ πράγματι καὶ τὸν ἔρωτα φέρειν ἀδυνατῶν ταῖς τε ὀργαῖς καὶ ταῖς διαλλαγαῖς οὐκ ἐνέμενεν, ἀεὶ δὲ ἀπὸ θατέρου μεταβαίνων εἰς θάτερον ἐφ’ ἑκατέρῳ πολλὴν εἶχεν ἀπορίαν. οὕτως οὖν ἐν μέσῳ τοῦ στυγεῖν καὶ στέργειν ἀποληφθεὶς καὶ πολλάκις ἕτοιμος ὢν ἀμύνασθαι τῆς ὑπερηφανίας αὐτὴν διὰ τὸ προκατειλῆφθαι τὴν ψυχὴν ἀσθενέστερος εἰς τὸ μεταστήσασθαι τὴν ἄνθρωπον ἐγίνετο. τὸ δὲ σύμπαν ἡδέως ἂν ἐκείνην κολάσας ἐδεδοίκει, μὴ λάθοι μείζονα παρ’ αὐτοῦ τὴν τιμωρίαν ἀποθανούσης εἰσπραττόμενος.", "st": "15.7.2"}, {"sp": "N", "t": "Συνιδοῦσαι δ’ οὕτως αὐτὸν ἔχοντα πρὸς τὴν Μαριάμμην ἥ τε ἀδελφὴ καὶ ἡ μήτηρ κάλλιστον ᾠήθησαν τὸν καιρὸν τοῦ πρὸς ἐκείνην μίσους εἰληφέναι καὶ διελάλουν οὐ μικρῶς παροξύνουσαι τὸν Ἡρώδην διαβολαῖς μῖσος ὁμοῦ καὶ ζηλοτυπίαν ἐμποιεῖν δυνησομέναις. ὁ δ’ οὔτε τῶν τοιούτων ἀηδῶς ἤκουσεν λόγων οὔτε δρᾶν τι κατὰ τῆς γυναικὸς ὡς πεπιστευκὼς ἀπεθάρρει, χεῖρον μέντοι πρὸς αὐτὴν εἶχεν ἀεὶ καὶ τὸ πάθος ἀντεξεκαίετο, τῆς μὲν οὐκ ἀποκρυπτομένης τὴν διάθεσιν, τοῦ δὲ τὸν ἔρωτα πρὸς ὀργὴν ἀεὶ μεταλαμβάνοντος. κἂν εὐθὺς ἐπράχθη τι τῶν ἀνηκέστων· νῦν δὲ Καίσαρος ἀγγελθέντος κρατεῖν τῷ πολέμῳ καὶ τεθνηκότων Ἀντωνίου καὶ Κλεοπάτρας ἔχειν Αἴγυπτον, ἐπειγόμενος εἰς τὸ Καίσαρι ἀπαντᾶν κατέλιπεν ὡς εἶχεν τὰ περὶ τὴν οἰκίαν. ἐξιόντι δὲ Μαριάμμη παραστησομένη τὸν Σόαιμον πολλήν τε χάριν τῆς ἐπιμελείας ὡμολόγει καὶ μεριδαρχίαν αὐτῷ παρὰ τοῦ βασιλέως ᾐτήσατο. κἀκεῖνος μὲν τυγχάνει τῆς τιμῆς. Ἡρώδης δὲ γενόμενος ἐν Αἰγύπτῳ Καίσαρί τε μετὰ πλείονος παρρησίας εἰς λόγους ἦλθεν ὡς ἤδη φίλος καὶ μεγίστων ἠξιώθη· τῶν τε γὰρ Κλεοπάτραν δορυφορούντων Γαλατῶν τετρακοσίοις αὐτὸν ἐδωρήσατο καὶ τὴν χώραν ἀπέδωκεν αὐτῷ πάλιν, ἣν δι’ ἐκείνης ἀφῃρέθη. προσέθηκεν δὲ καὶ τῇ βασιλείᾳ Γάδαρα καὶ Ἵππον καὶ Σαμάρειαν ἔτι δὲ τῆς παραλίου Γάζαν καὶ Ἀνθηδόνα καὶ Ἰόπην καὶ Στράτωνος πύργον.", "st": "15.7.3"}, {"sp": "N", "t": "Ἐπιτυχὼν δὲ καὶ τούτων λαμπρότερος ἦν, καὶ τὸν μὲν Καίσαρα παρέπεμψεν ἐπ’ Ἀντιοχείας, αὐτὸς δ’ ἐπανελθὼν ὅσον ᾤετο τὰ πράγματα αὐτῷ διὰ τῶν ἔξωθεν ἐπιδιδόναι πρὸς εὐδαιμονίαν, τοσοῦτον ἔκαμνεν τοῖς οἰκείοις καὶ μάλιστα περὶ τὸν γάμον, ἐν ᾧ καὶ μᾶλλον εὐτυχεῖν ἐδόκει πρότερον· ἔρωτα γὰρ οὐδενὸς ἐλάττω τῶν ἱστορουμένων ἐπεπόνθει μετὰ τοῦ δικαίου τῆς Μαριάμμης. ἡ δὲ τὰ μὲν ἄλλα σώφρων καὶ πιστὴ πρὸς αὐτὸν ἦν, εἶχεν δέ τι καὶ γυναικεῖον ὁμοῦ καὶ χαλεπὸν ἐκ φύσεως, ἱκανῶς μὲν ἐντρυφῶσα δεδουλωμένῳ διὰ τὴν ἐπιθυμίαν καὶ τὸ βασιλεύεσθαι καὶ κρατεῖν ἄλλον αὐτῆς οὐ συγκαταλογιζομένη τῷ καιρῷ πολλάκις μὲν ὑβριστικῶς αὐτῷ προσηνέχθη καὶ τοῦτ’ ἐκεῖνος ἐξειρωνευόμενος ἔφερεν ἐγκρατῶς καὶ μειζόνως, ἀναφανδὸν δὲ τήν τε μητέρα καὶ τὴν ἀδελφὴν ἐπὶ δυσγενείᾳ διεχλεύαζεν καὶ κακῶς ἔλεγεν, ὥστ’ ἤδη στάσιν ἐν ταῖς γυναιξὶν εἶναι καὶ μῖσος ἄσπονδον, ἐν δὲ τῷ τότε καὶ διαβολὰς μείζονας. ἥ τε ὑποψία τρεφομένη παρέτεινεν ἐνιαυτοῦ μῆκος ἐξ οὗ παρὰ Καίσαρος Ἡρώδης ὑπεστρόφει. τέλεον μέντοι προοικονομούμενον ἐκ πλείονος ἐξερράγη τοιαύτης ἀφορμῆς ἐγγενομένης· κατακλινόμενος ὁ βασιλεὺς ὡς ἀναπαύσασθαι μεσημβρίας οὔσης ἐκάλει τὴν Μαριάμμην ὑπὸ φιλοστοργίας, ἧς ἀεὶ περὶ αὐτὴν εἶχεν. ἡ δὲ εἰσῆλθεν μέν, οὐ μὴν καὶ κατεκλίθη σπουδάζοντος ἐκφαυλίσασα καὶ προσλοιδορηθεῖσα, τόν τε πατέρα καὶ τὸν ἀδελφὸν αὐτῆς ὡς ἀπεκτόνοι. χαλεπῶς δ’ ἐκείνου τὴν ὕβριν ἐνηνοχότος καὶ γεγονότος εἰς προπέτειαν ἑτοίμου, τῆς ταραχῆς αἰσθομένη μείζονος ἡ τοῦ βασιλέως ἀδελφὴ Σαλώμη παρεσκευασμένον ἐκ πλείστου τὸν οἰνοχόον εἰσπέμπει κελεύουσα λέγειν, ὡς πείθοι Μαριάμμη φίλτρον αὐτῇ συγκατασκευάσαι τῷ βασιλεῖ. κἂν ταραχθῇ καὶ πυνθάνηται, τί ποτε τοῦτ’ ἦν, λέγειν ὅτι φάρμακον ἐκείνης μὲν ἐχούσης αὐτοῦ δὲ διακονῆσαι παρακαλουμένου, μὴ κινηθέντος δ’ ἐπὶ τῷ φίλτρῳ τὸν λόγον ἀργὸν ἐᾶν· οὐδένα γὰρ αὐτῷ κίνδυνον φέρειν. τοιαῦτα προδιδάξασα κατ’ ἐκεῖνον τὸν καιρὸν εἰσπέμπει διαλεξόμενον. ὁ δὲ πιθανῶς ἅμα καὶ μετὰ σπουδῆς εἰσῄει, δῶρα μὲν αὐτῷ τὴν Μαριάμμην παρεσχῆσθαι λέγων, ἀναπείθειν δὲ φίλτρον αὐτῷ διδόναι. πρὸς τοῦτο διακινηθέντος καὶ τί τὸ φίλτρον εἴη ἐρωτήσαντος, φάρμακον εἶπεν ὑπ’ ἐκείνης διδόμενον, οὗ τὴν δύναμιν αὐτὸς οὐκ εἰδέναι, διὸ καὶ προσαγγεῖλαι τοῦτ’ ἀσφαλέστερον αὐτῷ καὶ τῷ βασιλεῖ διειληφότα. τοιούτων ἀκούσας Ἡρώδης λόγων καὶ πρότερον κακῶς διακείμενος ἔτι μᾶλλον ἠρεθίσθη, τόν τ’ εὐνοῦχον, ὃς ἦν τῇ Μαριάμμῃ πιστότατος, ἐβασάνιζεν ὑπὲρ τοῦ φαρμάκου γινώσκων, ὡς οὐ χωρὶς ἐκείνου τι δυνατὸν ἦν οὔτε μεῖζον οὔτε ἔλαττόν τι πεπρᾶχθαι. γενόμενος δὲ ἐν ταῖς ἀνάγκαις ὁ ἄνθρωπος, οὐδὲν μὲν ὧν ἕνεκεν ἐβασανίζετο λέγειν εἶχεν, τὸ μέντοι τῆς γυναικὸς ἔχθος εἰς αὐτὸν ἔφη γενέσθαι διὰ τοὺς λόγους, οὓς ὁ Σόαιμος αὐτῇ φράσαι. ταῦτα δ’ ἔτι λέγοντος μέγα βοήσας ὁ βασιλεὺς οὐκ ἂν ἔφη Σόαιμον πιστότατον ὄντα τόν γε ἄλλον χρόνον αὐτῷ καὶ τῇ βασιλείᾳ καταπροδοῦναι τὰς ἐντολάς, εἰ μὴ καὶ περαιτέρω προεληλύθει τῆς πρὸς τὴν Μαριάμμην κοινωνίας. καὶ τὸν μὲν Σόαιμον εὐθὺς ἐκέλευσεν ἀποκτεῖναι συλλαβόντας· τῇ δὲ γυναικὶ κρίσιν ἀπεδίδου συναγαγὼν τοὺς οἰκειοτάτους αὐτῷ καὶ τὴν κατηγορίαν ἐσπουδασμένην ποιούμενος ὑπὲρ τῶν κατὰ τὰς διαβολὰς φίλτρων καὶ φαρμάκων. ἦν δὲ ἀκρατὴς ἐν τῷ λόγῳ καὶ κρίσεως ὀργιλαίτερος, καὶ τέλος οὕτως ἔχοντα γινώσκοντες αὐτὸν οἱ παρόντες θάνατον αὐτῆς κατεψηφίσαντο. διενεχθείσης δὲ τῆς γνώμης ὑπεγίνετο μέν τι καὶ τοιοῦτον αὐτῷ τε καί τισιν τῶν παρόντων μὴ προπετῶς οὕτως ἀναιρεῖν, καταθέσθαι δὲ εἰς ἕν τι τῶν ἐν τῇ βασιλείᾳ φρουρίων. ἐσπουδάσθη δὲ ταῖς περὶ τὴν Σαλώμην ἐκποδὼν ποιήσασθαι τὴν ἄνθρωπον καὶ μᾶλλον ἔπεισαν τὸν βασιλέα τὰς ταραχὰς τοῦ πλήθους, εἰ ζῶσα τύχοι, φυλάξασθαι συμβουλεύουσαι. Μαριάμμη μὲν οὖν οὕτως ἤγετο τὴν ἐπὶ θανάτῳ.", "st": "15.7.4"}, {"sp": "N", "t": "Συνθεωρήσασα δὲ τὸν καιρὸν ἡ Ἀλεξάνδρα, καὶ διότι μικρὰς ἐλπίδας ἔχοι μὴ καὶ αὐτὴ τῶν ὁμοίων ἐξ Ἡρώδου τυχεῖν, ἐναντίως πρὸς τὸ πρῶτον θράσος καὶ λίαν ἀπρεπῶς μετεβάλετο· βουλομένη γὰρ ἐμφῆναι τὴν ἄγνοιαν ὧν ἐκείνη τὰς αἰτίας εἶχεν, ἐκπηδήσασα καὶ λοιδορουμένη τῇ θυγατρὶ πάντων ἀκουόντων ἐβόα κακὴν πρὸς τὸν ἄνδρα καὶ ἀχάριστον γενέσθαι καὶ δίκαια πάσχειν ἐπὶ τοῖς τοιούτοις τολμήσασαν· οὐ γὰρ ἀμείψασθαι δεόντως τὸν πάντων αὐτῶν εὐεργέτην. τοιαῦτα μεταξὺ καθυποκρινομένης ἀσχημόνως καὶ τολμώσης ἐφάπτεσθαι καὶ τῶν τριχῶν, πολλὴ μέν, ὡς εἰκός, καὶ παρὰ τῶν ἄλλων ἡ κατάγνωσις ἦν τῆς ἀπρεποῦς προσποιήσεως, μᾶλλον δὲ ἐνεφάνη παρ’ αὐτῆς τῆς ἀπολλυμένης· οὔτε γὰρ λόγον δοῦσα τὴν ἀρχὴν οὔτε ταραχθεῖσα πρὸς τὴν ἐκείνης δυσχέρειαν ἐπέβλεπεν ἀλλ’ ὡς ὑπὸ φρονήματος τὴν ἁμαρτίαν καὶ μᾶλλον ἄχθεσθαι περιφανῶς ἀσχημονούσης ἐνέφηνεν. αὐτή γε μὴν ἀτρεμαίῳ τῷ καταστήματι καὶ τῇ χρόᾳ τῆς σαρκὸς ἀμεταβλήτῳ πρὸς τὸν θάνατον ἀπῄει, τὴν εὐγένειαν οὐδ’ ἐν τοῖς ἐσχάτοις ἄδηλον τοῖς ἐπιθεωροῦσιν αὐτὴν ἐμφαίνουσα.", "st": "15.7.5"}, {"sp": "N", "t": "Κἀκείνη μὲν οὕτως ἀπέθανεν γυνὴ καὶ πρὸς ἐγκράτειαν καὶ πρὸς μεγαλοψυχίαν ἄριστα γεγενημένη, τὸ δ’ ἐπιεικὲς ἔλιπεν αὐτῇ καὶ πλεῖον ἦν ἐν τῇ φύσει τὸ φιλόνεικον· κάλλει δὲ σώματος καὶ τῷ περὶ τὰς ἐντεύξεις ἀξιώματι μειζόνως φράσαι τὰς κατ’ αὐτὴν ὑπερῆγεν, ἥ τε πλείων ἀφορμὴ τοῦ μὴ κεχαρισμένως τῷ βασιλεῖ μηδὲ πρὸς ἡδονὴν ζῆν ἐντεῦθεν ἐγεγόνει· θεραπευομένη γὰρ διὰ τὸν ἔρωτα καὶ δυσχερὲς οὐδὲν ἐξ ἐκείνου προσδοκῶσα τὴν παρρησίαν ἀσύμμετρον εἶχεν. ἠνία δ’ αὐτὴν καὶ τὰ περὶ τοὺς οἰκείους καὶ ταῦτα πάντα πρὸς ἐκεῖνον ὡς ἐπεπόνθει λέγειν ἠξίου, καὶ πέρας ἐξενίκησεν ἐχθρὰς αὐτῇ γενέσθαι τήν τε μητέρα καὶ τὴν ἀδελφὴν τοῦ βασιλέως κἀκεῖνον αὐτόν, ᾧ μόνῳ τὸ μὴ παθεῖν τι δυσχερὲς ἀπεπίστευεν.", "st": "15.7.6"}, {"sp": "N", "t": "Ἀναιρεθείσης δ’ αὐτῆς τότε καὶ μᾶλλον ἐξήφθη τὰ περὶ τὴν ἐπιθυμίαν τοῦ βασιλέως ἔχοντος μὲν οὕτως, ὡς καὶ πρότερον ἐδηλώσαμεν· οὐ γὰρ ἀπαθὴς οὐδ’ οἷος ἂν ἐκ συνηθείας ἦν ὁ πρὸς αὐτὴν ἔρως, ἀλλὰ καὶ πρότερον ἦρξεν ἐνθουσιαστικῶς καὶ τῇ παρρησίᾳ τῆς συμβιώσεως οὐκ ἀπενικήθη μὴ πλείων ἀεὶ γίνεσθαι· τότε μέντοι καὶ μᾶλλον ἐδόκει κατὰ νέμεσίν τινα τῆς κατὰ τὴν Μαριάμμην ἀπωλείας ἐπιθέσθαι, καὶ πολλάκις μὲν ἀνακλήσεις ἦσαν αὐτῆς, πολλάκις δὲ καὶ θρῆνος ἀσχήμων, ἐπενόει δὲ πᾶν εἴ τι δυνατὸν εἰς ψυχαγωγίαν πότους καὶ συνουσίας αὐτῷ πραγματευόμενος, καὶ τούτων οὐδὲν ἤρκει. τὰς οὖν διοικήσεις τῶν κατὰ τὴν βασιλείαν παρῃτεῖτο καὶ τοσοῦτον ἥττητο τοῦ πάθους, ὥστ’ αὐτὸν ἤδη καὶ καλεῖν τὴν Μαριάμμην προστάξαι τοῖς ὑπηρέταις ὡς ζῶσαν ἔτι καὶ δυναμένην ὑπακούειν. οὕτως δὲ ἔχοντος ἐπιγίνεται λοιμώδης νόσος, ἣ καὶ τῶν ὄχλων τοὺς πλείους καὶ τῶν φίλων αὐτοῦ τοὺς ἐντιμοτάτους διέφθειρεν καὶ παρέσχεν ἅπασιν ἐξυπονοῆσαι κατὰ μῆνιν τοῦτο συνενεχθῆναι τῶν κατὰ τὴν γενομένην παρανομίαν ἐπὶ τῇ Μαριάμμῃ. χεῖρον οὖν διετίθει καὶ τοῦτ’ αὐτὸ τὸν βασιλέα, καὶ τέλος εἰς τὰς ἐρημίας αὑτὸν διδοὺς καὶ προφάσει κυνηγεσίων ταύταις ἐναδημονῶν οὐκ ἔφθη πλείους διενεγκεῖν ἡμέρας καὶ περιπίπτει νόσῳ δυσχερεστάτῃ· φλόγωσις γὰρ ἦν καὶ πεῖσις ἰνίου καὶ τῆς διανοίας παραλλαγή· τῶν τε θεραπευμάτων οὐδὲν ὅ τι καὶ πρὸς ὠφέλειαν ἐξήνυεν, ἀλλ’ ἐναντιούμενα τέως εἰς ἀπόγνωσιν ἦγεν. ὅσοι τε περὶ αὐτὸν ἦσαν ἰατροὶ τὰ μὲν οἷς αὐτοὶ προσέφερον βοηθήμασιν οὐδὲν ὑπεικούσης τῆς νόσου, τὰ δὲ καὶ τοῦ βασιλέως οὐκ ἔχοντος ἄλλως ἢ κατὰ τὸ βιαζόμενον τῆς ἀρρωστίας διαιτᾶσθαι, πάνθ’ οἷς ἐκεῖνος ἐπενεχθείη παρέχειν ἠξίουν, τὸ δύσελπι τῆς σωτηρίας ἐν ἐξουσίᾳ τῆς διαίτης ἀνατιθέντες τῇ τύχῃ. κἀκεῖνος μὲν ἐν Σαμαρείᾳ τῇ κληθείσῃ Σεβαστῇ τοῦτον τὸν τρόπον ἐνοσηλεύετο.", "st": "15.7.7"}, {"sp": "N", "t": "Διατρίβουσα δὲ ἐν τοῖς Ἱεροσολύμοις Ἀλεξάνδρα καὶ πυνθανομένη τὰ κατ’ αὐτὸν ἐσπουδάκει τῶν περὶ τὴν πόλιν φρουρίων ἐγκρατὴς γενέσθαι. δύο δ’ ἦν, ἓν μὲν αὐτῆς τῆς πόλεως, ἕτερον δὲ τοῦ ἱεροῦ, καὶ τούτων οἱ κρατοῦντες ὑποχείριον τὸ πᾶν ἔθνος ἐσχήκασιν· τὰς μὲν γὰρ θυσίας οὐκ ἄνευ τούτων οἷόν τε γενέσθαι, τὸ δὲ μὴ ταύτας συντελεῖν οὐδενὶ Ἰουδαίων δυνατὸν τοῦ ζῆν ἑτοιμότερον ἂν παραχωρησάντων ἢ τῆς θρησκείας, ἣν εἰς τὸν θεὸν εἰώθασιν συντελεῖν. τοῖς οὖν ἐπὶ τούτων τῶν φυλακτηρίων Ἀλεξάνδρα προσήνεγκεν τοὺς λόγους, ὡς δέον αὐτῇ καὶ τοῖς ἐξ Ἡρώδου παιδίοις παραδοῦναι, μὴ καὶ φθῇ τις ἐκείνου μεταλλάξαντος ἕτερος ἀντιλαμβάνεσθαι τῶν πραγμάτων· ῥωσθέντι μὲν γὰρ οὐδεὶς ἀσφαλέστερον τῶν οἰκειοτάτων διατηρήσει. τούτους τοὺς λόγους αὐτῆς οὐκ ἐπιεικῶς ἤνεγκαν, ἀλλὰ πιστοὶ καὶ τὸν ἔμπροσθεν χρόνον ὄντες ἔτι μᾶλλον ἐν τῷ τότε διέμειναν μίσει τε τῆς Ἀλεξάνδρας καὶ τῷ μηδ’ ὅσιον ὑπολαμβάνειν ζῶντα τὸν Ἡρώδην ἀπεγνωκέναι· φίλοι γὰρ ἄνωθεν ἦσαν, εἷς δ’ αὐτῶν καὶ ἀνεψιὸς τοῦ βασιλέως Ἀχίαβος. εὐθὺς οὖν ἐξήγγειλαν πέμψαντες ἐκείνῳ τὴν γνώμην τῆς Ἀλεξάνδρας. ὁ δὲ τὴν μὲν οὐδὲν ἀναβαλλόμενος ἀποκτεῖναι προσέταξεν, αὐτὸς δὲ μόλις καὶ σὺν κακοπαθείᾳ διαφυγὼν τὴν νόσον χαλεπὸς ἦν ψυχῇ καὶ σώματι κεκακωμένος ὁμοῦ πρὸς τὸ δυσάρεστον καὶ πάσαις ταῖς αἰτίαις ἑτοιμοτέρως εἰς τιμωρίαν τῶν ὑποπεσόντων ἐχρῆτο. φονεύει δὲ καὶ τοὺς ἀναγκαιοτάτους αὐτῷ φίλους Κοστόβαρον καὶ Λυσίμαχον καὶ τὸν Γαδία καλούμενον Ἀντίπατρον ἔτι δὲ Δοσίθεον ἐξ αἰτίας τοιαύτης·", "st": "15.7.8"}, {"sp": "N", "t": "Κοστόβαρος ἦν γένει μὲν Ἰδουμαῖος, ἀξιώματος τῶν πρώτων παρ’ αὐτοῖς καὶ προγόνων ἱερατευσάντων τῷ Κωζαι· θεὸν δὲ τοῦτον Ἰδουμαῖοι νομίζουσιν. Ὑρκανοῦ δὲ τὴν πολιτείαν αὐτῶν εἰς τὰ Ἰουδαίων ἔθη καὶ νόμιμα μεταστήσαντος Ἡρώδης παραλαβὼν τὴν βασιλείαν ἄρχοντα τῆς Ἰδουμαίας καὶ Γάζης ἀποδείκνυσιν τὸν Κοστόβαρον καὶ δίδωσιν αὐτῷ τὴν ἀδελφὴν Σαλώμην Ἰώσηπον ἀνελὼν τὸν εἰληφότα πρότερον αὐτήν, ὡς ἐδηλώσαμεν. Κοστόβαρος δὲ τούτων τυχὼν ἀσμένως καὶ παρὰ δόξαν ἤρθη μᾶλλον ὑπὸ τῆς εὐτυχίας καὶ κατὰ μικρὸν ἐξέβαινεν, οὔθ’ αὑτῷ καλὸν ἡγούμενος ἄρχοντος Ἡρώδου τὸ προσταττόμενον ποιεῖν οὔτε τοῖς Ἰδουμαίοις τὰ Ἰουδαίων μεταλαβοῦσιν ὑπ’ ἐκείνοις εἶναι. καὶ διαπέμπεται πρὸς Κλεοπάτραν τὴν Ἰδουμαίαν φάμενος ἀεὶ τῶν ἐκείνης προγόνων γεγενῆσθαι, καὶ διὰ τοῦτ’ εἶναι δίκαιον αἰτεῖσθαι παρ’ Ἀντωνίου τὴν χώραν· αὐτὸς γὰρ ἕτοιμος εἶναι μεταφέρειν τὴν εὔνοιαν εἰς ἐκείνην. ἔπραττεν δὲ ταῦτα τῇ Κλεοπάτρᾳ μὲν οὐδέν τι μᾶλλον εἰς τὴν ἀρχὴν ἀρεσκόμενος, εἰ δὲ παραιρεθείη τῶν πλειόνων Ἡρώδης, εὐεπιχείρητον ἤδη νομίζων καὶ κατ’ αὐτὸν ἄρξαι τοῦ τῶν Ἰδουμαίων γένους καὶ μεῖζον πράξειν· ἐπιδιέβαινεν γὰρ ταῖς ἐλπίσιν οὐκ ὀλίγας ἀφορμὰς ἔχων γένους καὶ χρημάτων, ἃ μετὰ διηνεκοῦς αἰσχροκερδείας ἐπεπόριστο, καὶ μικρὸν οὐδὲν ἐπενόει. Κλεοπάτρα μὲν οὖν Ἀντωνίου δεηθεῖσα περὶ τῆς χώρας ταύτης ἀποτυγχάνει. λέγονται δὲ πρὸς Ἡρώδην οἱ λόγοι κἀκεῖνος ἕτοιμος ὢν ἀποκτεῖναι τὸν Κοστόβαρον ὅμως τῆς ἀδελφῆς αὐτοῦ δεηθείσης καὶ τῆς μητρὸς ἀφίησιν καὶ συγγνώμης ἠξίωσεν, οὐκ ἀνύποπτον αὐτὸν εἰς τὸ λοιπὸν ἔχων τῆς ἐπιχειρήσεως τῆς τότε.", "st": "15.7.9"}, {"sp": "N", "t": "Χρόνου δὲ διελθόντος ἐπισυνέβη τὴν Σαλώμην στασιάσαι πρὸς τὸν Κοστόβαρον, καὶ πέμπει μὲν εὐθὺς αὐτῷ γραμμάτιον ἀπολυομένη τὸν γάμον οὐ κατὰ τοὺς Ἰουδαίων νόμους· ἀνδρὶ μὲν γὰρ ἔξεστιν παρ’ ἡμῖν τοῦτο ποιεῖν, γυναικὶ δὲ οὐδὲ διαχωρισθείσῃ καθ’ αὑτὴν γαμηθῆναι μὴ τοῦ πρότερον ἀνδρὸς ἐφιέντος. οὐ μὴν ἡ Σαλώμη τὸν ἐγγενῆ νόμον, ἀλλὰ τὸν ἀπ’ ἐξουσίας ἑλομένη τήν τε συμβίωσιν προαπηγόρευσεν καὶ πρὸς τὸν ἀδελφὸν Ἡρώδην ἔλεγεν ὑπὸ τῆς εἰς ἐκεῖνον εὐνοίας ἀποστῆναι τἀνδρός· ἐγνωκέναι γὰρ αὐτὸν μετ’ Ἀντιπάτρου καὶ Λυσιμάχου καὶ Δοσιθέου νεωτέρων ἐφιέμενον. καὶ πίστιν παρεῖχεν τοῦ λόγου τοὺς Σάββα παῖδας, ὅτι διασώζοιντο παρ’ αὐτῷ χρόνον ἐνιαυτῶν ἤδη δεκαδύο. τοῦτο δὲ εἶχεν οὕτως καὶ πολλὴν ἔκπληξιν ἐνεποίησεν τῷ βασιλεῖ παρ’ ἐλπίδας ἀκουσθέν, ἐκεκίνητό τε μᾶλλον ἐπὶ τῷ παραδόξῳ τοῦ λόγου· τὰ γὰρ περὶ τοὺς Σάββα παῖδας ἐσπουδάσθη μὲν αὐτῷ πρότερον ἐπεξελθεῖν αὐτοὺς δυσμενεῖς γενομένους τῇ διαθέσει, τότε δὲ διὰ τὸ μῆκος τοῦ χρόνου καὶ τῆς μνήμης ἐξεληλύθεσαν. ἡ δὲ ἔχθρα πρὸς αὐτοὺς καὶ τὸ μῖσος ἀπὸ τοιούτων ἦν· Ἀντιγόνου τὴν βασιλείαν ἔχοντος Ἡρώδης μὲν ἐπολιόρκει δυνάμει τὴν τῶν Ἱεροσολυμιτῶν πόλιν, ὑπὸ δὲ χρείας κακῶν, ὅσα τοῖς πολιορκουμένοις παρίσταται, πλείους ἦσαν οἱ τὸν Ἡρώδην ἐπικαλούμενοι καὶ πρὸς ἐκεῖνον ἀπονεύοντες ἤδη ταῖς ἐλπίσιν. ὄντες δὲ ἐπ’ ἀξιώματος οἱ τοῦ Σάββα παῖδες καὶ παρὰ τῷ πλήθει δυνατοί, πιστοὶ διετέλουν Ἀντιγόνῳ τόν τε Ἡρώδην διέβαλλον ἀεὶ καὶ συμφυλάττειν τοῖς βασιλεῦσιν τὴν ἐκ γένους ἀρχὴν προύτρεπον. ἐκεῖνοι μὲν οὖν ἅμα καὶ συμφέρειν αὐτὰ νομίζοντες ἐπὶ τοιούτων ἐπολιτεύοντο. τῆς δὲ πόλεως ἁλισκομένης καὶ κρατοῦντος τῶν πραγμάτων Ἡρώδου Κοστόβαρος ἀποδειχθεὶς τὰς διεκβολὰς ἀναφράττειν καὶ φρουρεῖν τὴν πόλιν, ὡς μὴ διαπίπτειν ἐξ αὐτῆς τοὺς ὑπόχρεως τῶν πολιτῶν ἢ τἀναντία τῷ βασιλεῖ πολιτευομένους, εἰδὼς ἐν ὑπολήψει καὶ τιμῇ τοὺς Σάββα τῷ παντὶ πλήθει καὶ νομίζων μέγα μέρος αὐτῷ γενήσεσθαι πρὸς τὰς μεταβολὰς τῶν πραγμάτων τὴν ἐκείνων σωτηρίαν ὑπεξέθετο καὶ κατέκρυψεν ἐν οἰκείοις χωρίοις. καὶ τότε μὲν Ἡρώδην, διεληλύθει γὰρ ἡ τῆς ἀληθείας ὑποψία, πιστωσάμενος ὅρκοις ἦ μὴν οὐδὲν εἰδέναι τῶν κατ’ ἐκείνους ἀφεῖτο τῆς ὑπονοίας. αὖθις δὲ κηρύγματα καὶ μήνυτρα τοῦ βασιλέως ἐκτιθέντος καὶ πάντα τρόπον ἐρεύνης ἐπινοοῦντος οὐκ ἦλθεν εἰς ὁμολογίαν, ἀλλὰ τῷ τὸ πρῶτον ἔξαρνος γενέσθαι τὸ φωραθῆναι τοὺς ἄνδρας οὐκ ἀνυποτίμητον αὐτῷ πεπεισμένος οὐ μόνον ἐκ τῆς εὐνοίας, ἀλλὰ καὶ τῆς ἀνάγκης ἤδη τοῦ λανθάνειν αὐτοὺς περιείχετο. περὶ τούτων ἐξαγγελθέντων αὐτῷ διὰ τῆς ἀδελφῆς ὁ βασιλεὺς πέμψας εἰς τοὺς τόπους, ἐν οἷς διατρίβειν ἐμηνύθησαν, ἐκείνους τε καὶ τοὺς συγκαταιτιαθέντας ἀπέκτεινεν, ὥστ’ εἶναι μηδὲν ὑπόλοιπον ἐκ τῆς Ὑρκανοῦ συγγενείας, ἀλλὰ τὴν βασιλείαν αὐτεξούσιον αὐτῷ μηδενὸς ὄντος ἐπ’ ἀξιώματος ἐμποδὼν ἵστασθαι τοῖς παρανομουμένοις.", "st": "15.7.10"}, {"sp": "N", "t": "Διὰ τοῦτο καὶ μᾶλλον ἐξέβαινεν τῶν πατρίων ἐθῶν καὶ ξενικοῖς ἐπιτηδεύμασιν ὑποδιέφθειρεν τὴν πάλαι κατάστασιν ἀπαρεγχείρητον οὖσαν, ἐξ ὧν οὐ μικρὰ καὶ πρὸς τὸν αὖθις χρόνον ἠδικήθημεν ἀμεληθέντων ὅσα πρότερον ἐπὶ τὴν εὐσέβειαν ἦγεν τοὺς ὄχλους· πρῶτον μὲν γὰρ ἀγῶνα πενταετηρικὸν ἀθλημάτων κατεστήσατο Καίσαρι καὶ θέατρον ἐν Ἱεροσολύμοις ᾠκοδόμησεν, αὖθίς τ’ ἐν τῷ πεδίῳ μέγιστον ἀμφιθέατρον, περίοπτα μὲν ἄμφω τῇ πολυτελείᾳ, τοῦ δὲ κατὰ τοὺς Ἰουδαίους ἔθους ἀλλότρια· χρῆσίς τε γὰρ αὐτῶν καὶ θεαμάτων τοιούτων ἐπίδειξις οὐ παραδίδοται. τὴν μέντοι πανήγυριν ἐκεῖνος ἐπιφανεστάτην τὴν τῆς πενταετηρίδος συνετέλει καταγγείλας τε τοῖς πέριξ καὶ συγκαλῶν ἀπὸ τοῦ παντὸς ἔθνους. οἱ δ’ ἀθληταὶ καὶ τὰ λοιπὰ τῶν ἀγωνισμάτων ἀπὸ πάσης γῆς ἐκαλοῦντο κατ’ ἐλπίδα τῶν προκειμένων καὶ τῆς νίκης εὐδοξίᾳ, συνελέγησάν τε οἱ κορυφαιότατοι τῶν ἐν τοῖς ἐπιτηδεύμασιν· οὐ γὰρ μόνον τοῖς περὶ τὰς γυμνικὰς ἀσκήσεις, ἀλλὰ καὶ τοῖς ἐν τῇ μουσικῇ διαγινομένοις καὶ θυμελικοῖς καλουμένοις προυτίθει μέγιστα νικητήρια· καὶ διεσπούδαστο πάντας τοὺς ἐπισημοτάτους ἐλθεῖν ἐπὶ τὴν ἅμιλλαν. προύθηκεν δὲ καὶ τεθρίπποις καὶ συνωρίσιν καὶ κέλησιν οὐ μικρὰς δωρεάς, καὶ πάνθ’, ὅσα κατὰ πολυτέλειαν ἢ σεμνοπρέπειαν παρ’ ἑκάστοις ἐσπούδαστο φιλοτιμίᾳ τοῦ διάσημον αὐτῷ γενέσθαι τὴν ἐπίδειξιν ἐξεμιμήσατο. τό γε μὴν θέατρον ἐπιγραφαὶ κύκλῳ περιεῖχον Καίσαρος καὶ τρόπαια τῶν ἐθνῶν, ἃ πολεμήσας ἐκεῖνος ἐκτήσατο, χρυσοῦ τε ἀπέφθου καὶ ἀργύρου πάντων αὐτῷ πεποιημένων. τὰ δ’ εἰς ὑπηρεσίαν οὐδὲν οὕτως ἦν οὔτ’ ἐσθῆτος τίμιον οὔτε σκευῆς λίθων, ὃ μὴ τοῖς ὁρωμένοις ἀγωνίσμασιν συνεπεδείκνυτο. παρασκευὴ δὲ καὶ θηρίων ἐγένετο λεόντων τε πλείστων αὐτῷ συναχθέντων καὶ τῶν ἄλλων, ὅσα καὶ τὰς ἀλκὰς ὑπερβαλλούσας ἔχει καὶ τὴν φύσιν ἐστὶν σπανιώτερα· τούτων αὐτῶν τε πρὸς ἄλληλα συμπλοκαὶ καὶ μάχαι πρὸς αὐτὰ τῶν κατεγνωσμένων ἀνθρώπων ἐπετηδεύοντο, τοῖς μὲν ξένοις ἔκπληξις ὁμοῦ τῆς δαπάνης καὶ ψυχαγωγία τῶν περὶ τὴν θέαν κινδύνων, τοῖς δ’ ἐπιχωρίοις φανερὰ κατάλυσις τῶν τιμωμένων παρ’ αὐτοῖς ἐθῶν· ἀσεβὲς μὲν γὰρ ἐκ προδήλου κατεφαίνετο θηρίοις ἀνθρώπους ὑπορρίπτειν ἐπὶ τέρψει τῆς ἀνθρώπων θέας, ἀσεβὲς δὲ ξενικοῖς ἐπιτηδεύμασιν ἐξαλλάττειν τοὺς ἐθισμούς. πάντων δὲ μᾶλλον ἐλύπει τὰ τρόπαια· δοκοῦντες γὰρ εἰκόνας εἶναι τὰς τοῖς ὅπλοις περιειλημμένας, ὅτι μὴ πάτριον ἦν αὐτοῖς τὰ τοιαῦτα σέβειν, οὐ μετρίως ἐδυσχέραινον.", "st": "15.8.1"}, {"sp": "N", "t": "Ἐλάνθανον δ’ οὐδὲ τὸν Ἡρώδην ἐκταραττόμενοι· καὶ βίαν μὲν ἐπάγειν ἄκαιρον ᾤετο, καθωμίλει δ’ ἐνίους καὶ παρηγόρει τῆς δεισιδαιμονίας ἀφαιρούμενος. οὐ μὴν ἔπειθεν, ἀλλ’ ὑπὸ δυσχερείας ὧν ἐδόκουν ἐκεῖνον πλημμελεῖν ὁμοθυμαδὸν ἐξεβόων, εἰ καὶ πάντα δοκοῖεν οἰστά, μὴ φέρειν εἰκόνας ἀνθρώπων ἐν τῇ πόλει, τὰ τρόπαια λέγοντες· οὐ γὰρ εἶναι πάτριον αὐτοῖς. Ἡρώδης δὲ τεταραγμένους ὁρῶν καὶ μὴ ῥᾳδίως ἂν μεταπεσόντας, εἰ μὴ τύχοιεν παρηγορίας, καλέσας αὐτῶν τοὺς ἐπιφανεστάτους εἰς τὸ θέατρον παρήγαγεν καὶ δείξας τὰ τρόπαια, τί ποτ’ ἔστιν ὃ δοκεῖ ταῦτα αὐτοῖς ἐπύθετο. τῶν δὲ ἐκβοησάντων ἀνθρώπων εἰκόνες, ἐπιτάξας ἀφαιρεθῆναι τὸν περιθέσιμον κόσμον ἐπιδείκνυσιν αὐτοῖς γυμνὰ τὰ ξύλα. τὰ δ’ εὐθὺς ἦν ἀποσυληθέντα γέλως καὶ πλεῖστον εἰς διάχυσιν ἐδυνήθη τὸ καὶ πρότερον αὐτοὺς ἐν εἰρωνείᾳ τίθεσθαι τὰς κατασκευὰς τῶν ἀγαλμάτων.", "st": "15.8.2"}, {"sp": "N", "t": "Τοῦτον δὲ τὸν τρόπον αὐτοῦ παρακρουσαμένου τὸ πλῆθος καὶ τὴν ὁρμὴν ἣν ἐπεπόνθεισαν ἐξ ὀργῆς διαχέαντος, οἱ μὲν πλείους εἶχον ὡς μεταβεβλῆσθαι καὶ μὴ χαλεπαίνειν ἔτι, τινὲς δ’ αὐτῶν ἐπέμενον τῇ δυσχερείᾳ τῶν οὐκ ἐξ ἔθους ἐπιτηδευμάτων, καὶ τὸ καταλύεσθαι τὰ πάτρια μεγάλων ἡγούμενοι ἀρχὴν κακῶν ὅσιον ᾠήθησαν ἀποκινδυνεῦσαι μᾶλλον ἢ δοκεῖν ἐξαλλαττομένης αὐτοῖς τῆς πολιτείας περιορᾶν Ἡρώδην πρὸς βίαν ἐπεισάγοντα τὰ μὴ δι’ ἔθους ὄντα, καὶ λόγῳ μὲν βασιλέα, τῷ δ’ ἔργῳ πολέμιον φαινόμενον τοῦ παντὸς ἔθνους. ἐκ δὲ τούτου συνομοσάμενοι πάντα κίνδυνον ὑποδύεσθαι δέκα τῶν πολιτῶν ἄνδρες, ξιφίδια τοῖς ἱματίοις ὑποβαλόντες, ἦν δ’ αὐτοῖς δι’ ἀναξιοπάθειαν ὧν ἤκουεν καὶ τῶν διεφθορότων τις τοὺς ὀφθαλμοὺς συνομωμοσμένος, οὐχ ὡς ἐνεργῆσαί τι καὶ δρᾶν εἰς τὴν ἐπιχείρησιν ἱκανός, ἀλλ’ ἐν ἑτοίμῳ κατατιθεὶς αὑτὸν παθεῖν εἴ τι κἀκείνοις συμβαίνοι δυσχερές, ὥστε μὴ μετρίαν τὴν ὁρμὴν τοῖς ἐπιχειροῦσι δι’ αὐτὸν γενέσθαι,", "st": "15.8.3"}, {"sp": "N", "t": "ταῦτα γνόντες ἀπὸ συνθήματος εἰς τὸ θέατρον ἐχώρουν, ἐλπίσαντες μὲν οὐδ’ αὐτὸν Ἡρώδην διαφευξεῖσθαι προσπεσόντων ἐξ ἀφανοῦς, πολλοὺς δ’, εἰ καὶ μὴ τυγχάνοιεν ἐκείνου, τῶν περὶ αὐτὸν ἀναιρήσειν οἰόμενοι· καὶ ταῦτ’ αὐτοῖς ἀρκέσειν, εἰ καὶ θνήσκοιεν, εἰς ἔννοιαν ὧν ὁ βασιλεὺς ἐξυβρίζειν ἐδόκει τὸ πλῆθος καὶ αὐτὸν ἐκεῖνον ἀγαγεῖν. ἐκεῖνοι μὲν οὖν προκαταστάντες ἐπὶ τοιαύτης ἦσαν προθυμίας· εἷς δὲ τῶν ὑφ’ Ἡρώδου πολυπραγμονεῖν καὶ διαγγέλλειν τὰ τοιαῦτα τεταγμένων ἐξευρηκὼς ὅλην τὴν ἐπίθεσιν εἰς τὸ θέατρον εἰσιέναι μέλλοντι τῷ βασιλεῖ κατεμήνυσεν. ὁ δ’, οὐ γὰρ ἀνοίκειον ᾠήθη τὸν λόγον εἴς τε τὸ μῖσος ἀφορῶν, ὃ συνῄδει παρὰ τῶν πλειόνων αὐτῷ, καὶ τὰς ταραχὰς τὰς ἐπὶ τοῖς καθ’ ἕκαστα γινομένοις παρυφισταμένας, ἀναχωρήσας εἰς τὸ βασίλειον ὀνομαστὶ τοὺς ἐν ταῖς αἰτίαις ἐκάλει. προσπιπτόντων δ’ αὐτοῖς τῶν ὑπηρετῶν αὐτόφωροι λαμβανόμενοι τὸ μὲν ὡς οὐκ ἂν διαφύγοιεν ᾔδεσαν, ἐπεκόσμησαν δὲ τὴν ἀναγκαίαν καταστροφὴν τοῦ τέλους τῷ μηδὲν ὑφιέναι τοῦ φρονήματος· οὐ γὰρ ἐντραπέντες οὐδ’ ἀρνησάμενοι τὴν πρᾶξιν ἀνέδειξαν μὲν ἤδη κρατούμενα τὰ ξίφη, διωμολογήσαντο δὲ καλῶς καὶ σὺν εὐσεβείᾳ τὴν συνωμοσίαν αὐτοῖς γενέσθαι, κέρδους μὲν οὐδενὸς οὐδ’ οἰκείων ἕνεκεν παθῶν, τὸ δὲ πλέον ὑπὲρ τῶν κοινῶν ἐθῶν, ἃ καὶ πᾶσιν ἢ φυλάττειν ἢ θνήσκειν πρὸ αὐτῶν ἄξιον. τοιαῦτα μὲν ἐκεῖνοι τῇ προαιρέσει τῆς ἐπιβουλῆς ἐμπαρρησιασάμενοι περιστάντων αὐτοῖς τῶν βασιλικῶν ἤγοντο καὶ πᾶσαν αἰκίαν ὑπομείναντες διεφθάρησαν. μετ’ οὐ πολὺ δὲ καὶ τὸν ταῦτα μηνύσαντα κατὰ μῖσος ἁρπασάμενοί τινες οὐκ ἀπέκτειναν μόνον, ἀλλὰ καὶ μελιστὶ διελόντες προύθεσαν κυσίν. ἑωρᾶτο δὲ πολλοῖς τῶν πολιτῶν τὰ γινόμενα καὶ κατεμήνυσεν οὐδείς, ἕως Ἡρώδου πικροτέραν καὶ φιλόνεικον ποιουμένου τὴν ἔρευναν ἐκβασανισθεῖσαι γυναῖκές τινες ὡμολόγησαν ἃ πραχθέντα εἶδον. καὶ τῶν μὲν ἐνεργησάντων ἐγένετο τιμωρία πανοικὶ τὴν προπέτειαν αὐτῶν ἐπεξιόντος, ἡ δ’ ἐπιμονὴ τοῦ πάθους καὶ τὸ τῆς ὑπὲρ τῶν νόμων πίστεως ἀκατάπληκτον οὐ ῥᾴδιον ἐποίει τὸν Ἡρώδην, εἰ μὴ μετὰ πάσης ἀσφαλείας κρατοίη, καὶ διέγνω πάντοθεν περιειληφέναι τὸ πλῆθος, ὡς μὴ νεωτεριζόντων φανερὰν γενέσθαι τὴν ἀπόστασιν.", "st": "15.8.4"}, {"sp": "N", "t": "Ἐξωχυρωμένης οὖν αὐτῷ τῆς πόλεως μὲν ὑπὸ τῆς αὐλῆς, ἐν ᾗ διῃτᾶτο, τοῦ δὲ ἱεροῦ τῇ περὶ τὸ φρούριον ὀχυρότητι τὸ καλούμενον Ἀντωνίαν κατασκευασθὲν δι’ αὐτοῦ, τρίτον παντὶ τῷ λαῷ τὴν Σαμάρειαν ἐνόησεν ἐπιτείχισμα, καλέσας μὲν αὐτὴν Σεβαστήν, οἰόμενος δὲ κατὰ τῆς χώρας οὐδὲν ἔλαττον ἰσχυροποιεῖν τὸν τόπον, ἀπέχοντα μὲν Ἱεροσολύμων μιᾶς ὁδὸν ἡμέρας, εὔχρηστον δ’ ὄντα καὶ κοινὸν ἐπί τε τοῖς ἐν τῇ πόλει καὶ τῇ χώρᾳ γενησόμενον. τῷ δὲ ἔθνει παντὶ φρούριον ἐνῳκοδόμησεν τὸ πάλαι μὲν καλούμενον Στράτωνος πύργον, Καισάρειαν δ’ ὑπ’ αὐτοῦ προσαγορευθέν. ἔν τε τῷ μεγάλῳ πεδίῳ τῶν ἐπιλέκτων ἱππέων περὶ αὐτὸν ἀποκληρώσας χωρίον συνέκτισεν ἐπί τε τῇ Γαλιλαίᾳ Γάβα καλούμενον καὶ τῇ Περαίᾳ τὴν Ἐσεβωνῖτιν. ταῦτα μὲν οὖν ἐν τοῖς κατὰ μέρος αἰεί τι πρὸς ἀσφάλειαν ἐπεξευρίσκων καὶ διαλαμβάνων φυλακαῖς τὸ πᾶν ἔθνος, ὡς ἥκιστα μὲν ἀπ’ ἐξουσίας εἰς ταραχὰς προπίπτειν, αἷς καὶ μικροῦ κινήματος ἐγγενομένου συνεχὲς ἐχρῶντο, λανθάνειν δὲ μηδ’ εἰ παρακινοῖεν ἐφεστηκότων αἰεί τινων πλησίον, οἳ καὶ γινώσκειν καὶ κωλύειν ἐδύναντο. τότε δὲ τὴν Σαμάρειαν ὡρμημένος τειχίζειν πολλοὺς μὲν τῶν συμμαχησάντων αὐτῷ κατὰ τοὺς πολέμους, πολλοὺς δὲ τῶν ὁμόρων συμπολίζειν ἐπετήδευεν, ὑπό τε φιλοτιμίας τοῦ νέον ἐγείρειν καὶ δι’ αὐτοῦ πρότερον οὐκ ἐν ταῖς ἐπισήμοις οὖσαν, καὶ μᾶλλον ὅτι πρὸς ἀσφάλειαν αὐτῷ τὸ φιλότιμον ἐπετηδεύετο, τήν τε προσηγορίαν ὑπήλλαττε Σεβαστὴν καλῶν καὶ τῆς χώρας ἀρίστην οὖσαν τὴν πλησίον κατεμέριζεν τοῖς οἰκήτορσιν, ὡς εὐθὺς ἐν εὐδαιμονίᾳ συνιόντας οἰκεῖν, καὶ τείχει καρτερῷ τὴν πόλιν περιέβαλεν τό τε τοῦ χωρίου πρόσαντες εἰς ἐρυμνότητα κατασκευαζόμενος καὶ μέγεθος οὐχ ὡς τὸ πρῶτον ἀλλ’ ὥστε μηδὲν ἀποδεῖν τῶν ἐλλογιμωτάτων πόλεων περιλαμβάνων· στάδιοι γὰρ ἦσαν εἴκοσιν. ἐντὸς δὲ καὶ κατὰ μέσην τριῶν ἡμισταδίων τέμενος ἀνῆκεν παντοίως κεκοσμημένον καὶ ναὸν ἐν αὐτῷ μεγέθει καὶ κάλλει τῶν ἐλλογιμωτάτων ἤγειρεν, ἔν τε τοῖς κατὰ μέρος διὰ πάντων ἐκόσμει τὴν πόλιν, τὸ μὲν ἀναγκαῖον τῆς ἀσφαλείας ὁρῶν καὶ τῇ τῶν περιβόλων ἐρυμνότητι φρούριον αὐτὴν ποιούμενος ἐπὶ τῇ μείζονι, τὸ δ’ εὐπρεπὲς ὡς ἂν ἐκ τοῦ φιλοκαλεῖν καὶ μνημεῖα φιλανθρωπίας ἀπολιπεῖν ἐν ὑστέρῳ.", "st": "15.8.5"}, {"sp": "N", "t": "Κατὰ τοῦτον μὲν οὖν τὸν ἐνιαυτὸν τρισκαιδέκατον ὄντα τῆς Ἡρώδου βασιλείας πάθη μέγιστα τὴν χώραν ἐπέλαβεν, εἴτε δὴ τοῦ θεοῦ μηνίσαντος ἢ καὶ κατὰ περιόδους οὕτως ἀπαντήσαντος τοῦ κακοῦ· πρῶτον μὲν γὰρ αὐχμοὶ διηνεκεῖς ἐγένοντο, καὶ διὰ τὸ τοιοῦτον ἄκαρπος ἡ γῆ μηδ’ ὅσα κατ’ αὐτὴν ἀναβλαστάνειν, ἔπειτα καὶ τῆς διαίτης κατὰ τὴν ἔνδειαν τῶν σιτίων ἐξαλλαττομένης νόσοι τῶν σωμάτων καὶ πάθος ἤδη λοιμικὸν ἐκράτει, διηνεκῶς ἀντεφοδιαζομένων αὐτοῖς τῶν κακῶν. τό τε γὰρ ἠπορῆσθαι θεραπείας καὶ τροφῆς ἐπέτεινεν εἰς πλέον ἀρξαμένην ἰσχυρῶς τὴν λοιμώδη νόσον ἥ τε φθορὰ τῶν οὕτως ἀπολλυμένων ἀφῃρεῖτο καὶ τοὺς περιόντας εὐθυμίας, ἐπεὶ προσαρκεῖν ταῖς ἀπορίαις ἐξ ἐπιμελείας [οὐκ] ἐδύναντο. φθαρέντων γε μὴν τῶν ἐπ’ ἔτος καρπῶν καὶ τῶν ὅσοι πρότερον ἀπέκειντο δεδαπανημένων, οὐδὲν εἰς ἐλπίδα χρηστὴν ὑπελείπετο μᾶλλον ἢ κατὰ προσδοκίαν ἐπιτείνοντος τοῦ κακοῦ καὶ οὐδὲ κατ’ ἐκεῖνον τὸν ἐνιαυτὸν μόνον, ὥστ’ αὐτοῖς εἶναι μὲν οὐδὲν ὑπόλοιπον, ἀπολωλέναι δὲ καὶ τῶν περιόντων τὰ σπέρματα μηδὲ τὸ δεύτερον ἀνείσης τῆς γῆς. ἥ τε ἀνάγκη πολλὰ διὰ τὰς χρείας ἐκαινούργει. καὶ τὰς ἀπορίας οὐκ ἐλάττους εἶναι συνέβαινεν αὐτῷ τῷ βασιλεῖ, τῶν τε φόρων, οὓς ἐλάμβανεν ἀπὸ τῆς γῆς, ἀφῃρημένῳ καὶ τὰ χρήματα δεδαπανηκότι πρὸς φιλοτιμίαν ὧν τὰς πόλεις ἐπεσκεύαζεν. ἦν δὲ οὐδὲν ὅ τι καὶ βοηθείας ἄξιον ἐδόκει προκατειληφότος τοῦ κακοῦ καὶ μῖσος εἰς αὐτὸν ἐκ τῶν ἀρχομένων· τὸ γὰρ οὐκ εὖ πράττειν φιλαίτιον αἰεὶ κατὰ τῶν προεστηκότων.", "st": "15.9.1"}, {"sp": "N", "t": "Ἐν τοιούτοις διενοεῖτο βοηθεῖν τῷ καιρῷ· χαλεπὸν δ’ ἦν οὔτε τῶν πλησίον ἐχόντων ἀποδόσθαι σιτία τῷ μηδ’ αὐτοὺς ἐλάττω πεπονθέναι, χρημάτων τε οὐκ ὄντων, εἰ καὶ δυνατὸν ὀλίγων ἐπὶ πολλοῖς εὐπορηθῆναι. καλῶς μέντοι νομίζων ἔχειν πάντως εἰς τὴν βοήθειαν [μὴ] ἀμελεῖν, τὸν ὄντα κόσμον ἐν τοῖς βασιλείοις αὐτοῦ συνέκοψεν ἀργύρου καὶ χρυσοῦ, μήτε τῆς ἐν ταῖς κατασκευαῖς ἐπιμελείας μήτ’ εἴ τι τέχνῃ τίμιον ἦν τούτου φεισάμενος. ἔπεμπε δ’ ἐπ’ Αἰγύπτου τὰ χρήματα Πετρωνίου τὴν ἐπαρχίαν ἀπὸ Καίσαρος εἰληφότος. οὗτος οὐκ ὀλίγων ἐπ’ αὐτὸν καταπεφευγότων διὰ τὰς αὐτὰς χρείας, ἰδίᾳ τε φίλος ὢν Ἡρώδῃ καὶ διασώσασθαι θέλων τοὺς ὑπ’ αὐτῷ, πρώτοις μὲν ἔδωκεν ἐξάγειν τὸν σῖτον, εἰς ἅπαντα δὲ κατὰ τὴν ὠνὴν καὶ τὸν ἔκπλουν συνήργησεν, ὡς μέγα μέρος ἢ τὸ πᾶν γενέσθαι ταύτης τῆς βοηθείας. ὁ γὰρ Ἡρώδης, τούτων ἀφικομένων ἐν ἀφορμῇ τὴν ἐπιμέλειαν τὴν αὐτοῦ προστιθεὶς οὐ μόνον ἀντιμετέστησεν τὰς γνώμας τῶν πρότερον χαλεπῶς ἐχόντων, ἀλλὰ καὶ μεγίστην ἐποιήσατο τὴν ἐπίδειξιν τῆς εὐνοίας καὶ τῆς προστασίας. πρῶτον μὲν γὰρ ὅσοις οἷόν τε δι’ αὐτῶν τὰ περὶ τὰς τροφὰς ἐκπονεῖν ἔνειμε τοῦ σίτου τὴν ἔκταξιν ἀκριβεστάτην ποιούμενος, ἔπειτα πολλῶν ὄντων, οἳ κατὰ γῆρας ἤ τινα προσοῦσαν ἄλλην ἀσθένειαν οὐχ ἱκανῶς εἶχον αὐτοῖς παρασκευάζειν τὰ σιτία, προυνόει καταστήσας ἀρτοποιοὺς καὶ παρέχων ἑτοίμας τὰς τροφάς. ἐπιμέλειαν δὲ καὶ τοῦ μὴ διαχειμάσαι μετὰ κινδύνων αὐτοὺς ἐποιήσατο συγκατειληφυίας καὶ τῆς περὶ τὰς ἐσθῆτας ἀπορίας, ἐφθαρμένων καὶ παντάπασιν ἐξαναλωθέντων τῶν βοσκημάτων, ὡς οὔτε ἐρίων εἶναι χρῆσιν οὔτε τῶν ἄλλων σκεπασμάτων. ἐκπορισθέντων δὲ αὐτῷ καὶ τούτων ταῖς πλησίον ἤδη πόλεσιν ἐπεβάλλετο τὰς ὠφελείας παρέχειν σπέρματα τοῖς ἐν Συρίᾳ διαδούς. καὶ τοῦτ’ ὤνησεν οὐχ ἧττον αὐτὸν εὐστοχηθείσης εἰς εὐφορίαν τῆς χάριτος, ὡς ἅπασιν ἱκανὰ τὰ περὶ τὰς τροφὰς γενέσθαι. τὸ δὲ σύμπαν ἀμήτου περὶ τὴν γῆν ὑποφανέντος οὐκ ἔλαττον ἢ πέντε μυριάδας ἀνθρώπων, οὓς αὐτὸς ἔθρεψεν καὶ περιεποίησεν, εἰς τὴν χώραν διέπεμψεν, καὶ τοῦτον τὸν τρόπον κακωθεῖσαν αὐτῷ τὴν βασιλείαν ὑπὸ πάσης φιλοτιμίας καὶ σπουδῆς ἀναλαβὼν οὐχ ἥκιστα καὶ τοὺς πέριξ ἐν ταῖς αὐταῖς κακοπαθείαις ὄντας ἐπεκούφισεν. οὐ γὰρ ἔσθ’ ὅστις ὑπὸ χρείας ἐντυχὼν ἀπελείφθη μὴ βοήθειαν εὕρασθαι κατὰ τὴν ἀξίαν. ἀλλὰ καὶ δῆμοι καὶ πόλεις καὶ τῶν ἰδιωτῶν ὅσοις ἀπορία διὰ τὸ πλειόνων προΐστασθαι συνετύγχανεν, ἐπ’ αὐτὸν καταφεύγοντες ἔσχον ὧν ἐδεήθησαν, ὥστε γενέσθαι λογιζομένων τοὺς μὲν ἔξω τῆς ἀρχῆς δοθέντας σίτου κόρους μυρίους, ὁ δὲ κόρος δύναται μεδίμνους Ἀττικοὺς δέκα, τοὺς δ’ εἰς αὐτὴν τὴν βασιλείαν περὶ ὀκτάκις μυρίους. ταύτην δ’ αὐτοῦ τὴν ἐπιμέλειαν καὶ τὴν τῆς χάριτος εὐκαιρίαν οὕτως ἐν αὐτοῖς τε τοῖς Ἰουδαίοις ἰσχῦσαι συνέβη καὶ διαβοηθῆναι παρὰ τοῖς ἄλλοις, ὥστε τὰ μὲν πάλαι μίση κινηθέντα διὰ τὸ παραχαράττειν ἔνια τῶν ἐθῶν καὶ τῆς βασιλείας ἐξαιρεθῆναι καὶ τοῦ παντὸς ἔθνους, ἀντικατάλλαγμα δὲ φαίνεσθαι τὴν ἐν τῇ βοηθείᾳ τῶν δεινοτάτων φιλοτιμίαν. εὔκλεια δὲ καὶ παρὰ τῶν ἔξωθεν ἦν, καὶ δοκεῖ τὰ δυσχερῆ συμβῆναι μὲν αὐτῷ μείζω λόγου, κακώσαντα δὲ τὴν βασιλείαν οὐχ ἥκιστα πρὸς εὐδοξίαν ὠφελῆσαι· τὸ γὰρ ἐν ταῖς ἀπορίαις μεγαλόψυχον παρὰ δόξαν ἐπιδειξάμενος ἀντιμετέστησε τοὺς πολλούς, ὡς ἐξ ὑπαρχῆς δοκεῖν οὐχ οἷον ἡ πεῖρα τῶν πάλαι γεγενημένων, ἀλλ’ οἷον ἡ μετὰ τῆς χρείας ἐπιμέλεια παρεστήσατο.", "st": "15.9.2"}, {"sp": "N", "t": "Περὶ δὲ τὸν χρόνον ἐκεῖνον καὶ συμμαχικὸν ἔπεμψεν Καίσαρι πεντακοσίους ἐπιλέκτους τῶν σωματοφυλάκων, οὓς Γάλλος Αἴλιος ἐπὶ τὴν Ἐρυθρὰν θάλασσαν ἦγεν εἰς πολλὰ χρησίμους αὐτῷ γενομένους. πάλιν οὖν αὐτῷ τῶν πραγμάτων πρὸς ἐπίδοσιν εὐθηνουμένων βασίλειον ἐξῳκοδόμει περὶ τὴν ἄνω πόλιν ὑπερμεγέθεις οἴκους ἐγείρων καὶ κόσμῳ κατασκευάζων πολυτελεστάτῳ χρυσοῦ καὶ λίθων καὶ περιαλειμμάτων ὡς ἕκαστον αὐτῶν κλισίας μὲν ἔχειν παμπόλλους ἄνδρας ὑποδέχεσθαι κατὰ μέτρα δὲ καὶ τὰς προσηγορίας· ὁ μὲν γὰρ Καίσαρος, ὁ δὲ Ἀγρίππα κέκλητο. προσέλαβεν δὲ καὶ γάμον αὐτῷ κινηθεὶς ἐξ ἐρωτικῆς ἐπιθυμίας μηδένα τοῦ κατὰ τὴν οἰκείαν ἡδονὴν ζῆν ὑπολογισμὸν ποιούμενος. ἀρχὴ δ’ αὐτῷ τῶν γάμων ἐγένετο τοιάδε· Σίμων ἦν Ἱεροσολυμίτης υἱὸς Βοηθοῦ τινος Ἀλεξανδρέως, ἱερεὺς ἐν τοῖς γνωρίμοις, εἶχεν δὲ θυγατέρα καλλίστην τῶν τότε νομιζομένην. ὄντος οὖν λόγου παρὰ τοῖς Ἱεροσολυμίταις αὐτῆς τὸ μὲν πρῶτον ὑπὸ τῆς ἀκοῆς τὸν Ἡρώδη κεκινῆσθαι συνέβαινεν, ὡς δὲ καὶ θεασάμενον ἡ τῆς παιδὸς ἐξέπληξεν ὥρα, τὸ μὲν ἀπ’ ἐξουσίας χρώμενον διατελεῖν ἅπαν ἀπεδοκίμαζεν ὑποπτεύων ὅπερ ἦν, εἰς βίαν καὶ τυραννίδα διαβληθήσεσθαι, βέλτιον δ’ ᾤετο γάμῳ τὴν κόρην λαβεῖν. καὶ τοῦ Σίμωνος ὄντος ἀδοξοτέρου μὲν ἢ πρὸς οἰκειότητα, μείζονος δὲ ἢ καταφρονεῖσθαι, τὸν ἐπιεικέστερον τρόπον μετῄει τὴν ἐπιθυμίαν αὔξων αὐτοὺς καὶ τιμιωτέρους ἀποφαίνων· αὐτίκα γοῦν Ἰησοῦν μὲν τὸν τοῦ Φοαβιτος ἀφαιρεῖται τὴν ἀρχιερωσύνην, Σίμωνα δὲ καθίστησιν ἐπὶ τῆς τιμῆς καὶ τὸ κῆδος πρὸς αὐτὸν συνάπτεται.", "st": "15.9.3"}, {"sp": "N", "t": "Τελεσθέντος δ’ αὐτῷ τοῦ γάμου προσκατεσκευάσατο φρούριον ἐπὶ τῶν τόπων, ἐν οἷς ἐνίκα Ἰουδαίους, ὅτε τῆς ἀρχῆς ἐκπεσόντος Ἀντίγονος ἐπὶ τῶν πραγμάτων ἦν. τοῦτο δὲ τὸ φρούριον ἀπέχει μὲν Ἱεροσολύμων περὶ ἑξήκοντα σταδίους, φύσει δὲ ἐχυρὸν καὶ πρὸς κατασκευὴν ἐπιτηδειότατόν ἐστιν ἐγγὺς ἐπιεικῶς κολωνὸς εἰς ὕψος ἀνιὼν χειροποίητον, ὡς εἶναι μαστοειδὴς τὴν περιφοράν, διείληπται δὲ κυκλοτερέσι πύργοις ὀρθίαν ἔχων ἄνοδον ξεσταῖς βαθμίσιν ἐξῳκοδομημένην εἰς διακοσίους. ἐντὸς δ’ αὐτοῦ καταγωγαὶ βασίλειοι πολυτελεῖς εἰς ἀσφάλειαν ὁμοῦ καὶ κόσμον πεποιημέναι· περὶ δὲ τὴν βάσιν τοῦ λόφου διατριβαὶ κατασκευῆς ἀξιοθεάτου τά τε ἄλλα καὶ τῆς εἰσαγωγῆς τῶν ὑδάτων, οὐ γὰρ οὗτος ὁ τόπος ἔσχηκεν, ἐκ μακροῦ καὶ διὰ πλειόνων ἀναλωμάτων πεποιημένης. τὰ δ’ ἐπίπεδα περιῳκοδόμηται πόλις οὐδεμιᾶς ἐλάσσων τὸν λόφον ἀκρόπολιν ἔχουσα τῆς ἄλλης οἰκήσεως.", "st": "15.9.4"}, {"sp": "N", "t": "Πάντων δ’ αὐτῷ προκεχωρηκότων εἰς δέον ὧν ἠλπίκει τὰς μὲν ἐν αὐτῇ τῇ βασιλείᾳ ταραχὰς οὐδ’ ὁπωσοῦν δι’ ὑποψίας εἶχεν ἑκατέρωθεν ὑπηκόους παραστησάμενος, φόβῳ μὲν ὧν ἀπαραίτητος εἰς τὰς τιμωρίας, τὴν ἐπιμέλειαν δὲ ὧν μεγαλόψυχος ἐν ταῖς περιπετείαις εὑρίσκετο. περιεβάλλετο δὲ τὴν ἔξωθεν ἀσφάλειαν ὥσπερ ἐπιτείχισμα καὶ τοῦτο τοῖς ἀρχομένοις ποιούμενος· πόλεσίν τε γὰρ ὡμίλει δεξιῶς καὶ φιλανθρώπως καὶ τοὺς δυνάστας ἐθεράπευεν εὐκαιρίαις ὧν ἑκάστους ἐδωρεῖτο μείζους τὰς χάριτας ἐμποιῶν καὶ τὸ μεγαλόψυχον φύσει πρὸς τὴν βασιλείαν εὐπρεπὲς ἔχων, ὥστ’ αὐτῷ πάντα διὰ πάντων αὔξεσθαι πρὸς τὸ πλεῖον ἀεὶ προχωρούντων. ὑπὸ δὲ τῆς εἰς τοῦτο φιλοτιμίας καὶ τῆς θεραπείας, ἣν ἐθεράπευεν Καίσαρα καὶ Ῥωμαίων τοὺς πλεῖστον δυναμένους, ἐκβαίνειν τῶν ἐθῶν ἠναγκάζετο καὶ πολλὰ τῶν νομίμων παραχαράττειν, πόλεις τε κτίζων ὑπὸ φιλοτιμίας καὶ ναοὺς ἐγείρων, οὐκ ἐν τῇ τῶν Ἰουδαίων, οὐδὲ γὰρ ἂν ἠνέσχοντο τῶν τοιούτων ἀπηγορευμένων ἡμῖν ὡς ἀγάλματα καὶ τύπους μεμορφωμένους τιμᾶν πρὸς τὸν Ἑλληνικὸν τρόπον, τὴν δ’ ἔξω χώραν καὶ τὰ πέριξ οὕτως κατεσκευάζετο, Ἰουδαίοις μὲν ἀπολογούμενος μὴ καθ’ αὑτὸν, ἀλλ’ ἐξ ἐντολῆς καὶ προσταγμάτων αὐτὰ ποιεῖν, Καίσαρι δὲ καὶ Ῥωμαίοις τὸ μηδὲ τῶν οἰκείων ἐθῶν ὅσον τῆς ἐκείνων τιμῆς ἐστοχάσθαι χαριζόμενος, αὐτὸς μέντοι τὸ σύμπαν αὐτοῦ στοχαζόμενος ἢ καὶ φιλοτιμούμενος μείζω τὰ μνημεῖα τῆς ἀρχῆς τοῖς αὖθις ὑπολιπέσθαι. ὅθεν καὶ περὶ τὰς ἐπισκευὰς τῶν πόλεων ἐκεκίνητο καὶ πλείστας εἰς τοῦτο τὰς δαπάνας ἐποιεῖτο.", "st": "15.9.5"}, {"sp": "N", "t": "Κατιδὼν δὲ καὶ πρὸς τῇ θαλάττῃ χωρίον ἐπιτηδειότατον δέξασθαι πόλιν, ὃ πάλαι Στράτωνος ἐκαλεῖτο πύργος, τῇ τε διαγραφῇ μεγαλοπρεπῶς ἐπεβάλλετο καὶ τοῖς οἰκοδομήμασιν ἀνιστὰς ἅπασαν οὐ παρέργως, ἀλλ’ ἐκ λευκῆς πέτρας, καὶ διακοσμῶν καὶ βασιλείοις πολυτελεστάτοις καὶ διαίταις πολιτικαῖς, τὸ δὲ μέγιστον καὶ πλείστην ἐργασίαν παρασχόν, ἀκλύστῳ λιμένι, μέγεθος μὲν κατὰ τὸν Πειραιᾶ, καταγωγὰς δ’ ἔνδον ἔχοντι καὶ δευτέρους ὑφόρμους, τῇ δὲ δομήσει περίβλεπτον, ὅτι μηδ’ ἐκ τοῦ τόπου τὴν ἐπιτηδειότητα τῆς μεγαλουργίας εἶχεν, ἀλλ’ ἐπεισάκτοις καὶ πολλαῖς ἐξετελειώθη ταῖς δαπάναις. κεῖται μὲν γὰρ ἡ πόλις ἐν τῇ Φοινίκῃ κατὰ τὸν εἰς Αἴγυπτον παράπλουν Ἰόππης μεταξὺ καὶ Δώρων, πολισμάτια ταῦτ’ ἐστὶν παράλια δύσορμα διὰ τὰς κατὰ λίβα προσβολάς, αἳ ἀεὶ τὰς ἐκ τοῦ πόντου θῖνας ἐπὶ τὴν ᾐόνα σύρουσαι καταγωγὴν οὐ διδόασιν, ἀλλ’ ἔστιν ἀναγκαῖον ἀποσαλεύειν τὰ πολλὰ τοὺς ἐμπόρους ἐπ’ ἀγκύρας. τοῦτο τὸ δυσδιάθετον τῆς χώρας διορθούμενος καὶ περιγράψας τὸν κύκλον τοῦ λιμένος ἐφ’ ὅσον ἦν αὔταρκες πρὸς τῇ χέρσῳ μεγάλοις στόλοις ἐνορμεῖσθαι λίθους ὑπερμεγέθεις καθίει εἰς τὸ βάθος εἰς ὀργυιὰς εἴκοσι. πεντήκοντα ποδῶν ἦσαν οἱ πλείους τὸ μῆκος καὶ πλάτος οὐκ ἔλαττον δεκαοκτώ, βάθος δὲ ἐννέα, τούτων δὲ οἱ μὲν μείζους οἱ δὲ ἐλάττους. ἡ δὲ ἐνδόμησις ὅσον ἦν † ἐβάλλετο κατὰ τῆς θαλάσσης διακοσίους πόδας. τούτων τὸ μὲν ἥμισυ προβέβλητο κυματωγαῖς, ὡς ἀπομάχεσθαι περικλώμενον ἐκεῖ τὸν κλύδωνα· προκυμία γοῦν ἐκαλεῖτο· τὸ δὲ λοιπὸν περιεῖχεν λίθινον τεῖχος πύργοις διειλημμένον, ὧν ὁ μέγιστος Δρούσιον ὀνομάζεται, πάνυ καλόν τι χρῆμα, τὴν προσηγορίαν εἰληφὼς ἀπὸ Δρούσου τοῦ Καίσαρος προγόνου τελευτήσαντος νέου. ψαλίδες δὲ ἐμπεποίηνται συνεχεῖς καταγωγαὶ τοῖς ναυτίλοις, τὸ δὲ πρὸ αὐτῶν ἀπόβασις πλατεῖα κύκλῳ περιεστεφάνωκεν τὸν πάντα λιμένα, περίπατος τοῖς ἐθέλουσιν ἥδιστος. ὁ δ’ εἴσπλους καὶ τὸ στόμα πεποίηται πρὸς βορέαν ἀνέμων αἰθριώτατον. βάσις δὲ τοῦ περιβόλου παντὸς ἐν ἀριστερᾷ μὲν εἰσπλεόντων πύργος νενασμένος ἐπὶ πολὺ στερρῶς ἀντέχειν, κατὰ δεξιὰν δὲ δύο λίθοι μεγάλοι καὶ τοῦ κατὰ θάτερα πύργου μείζους, ὀρθοὶ καὶ συνεζευγμένοι. περίκεινται δὲ ἐν κύκλῳ τὸν λιμένα λειοτάτου λίθου κατασκευὴ συνεχεῖς οἰκήσεις κἀν τῷ μέσῳ κολωνός τις, ἐφ’ οὗ νεὼς Καίσαρος ἄποπτος τοῖς εἰσπλέουσιν ἄγαλμά τε τὸ μὲν Ῥώμης, τὸ δὲ Καίσαρος· ἥ τε πόλις αὐτὴ Καισάρεια καλεῖται καλλίστης καὶ τῆς ὕλης καὶ τῆς κατασκευῆς τετυχηκυῖα. τὰ δ’ ὑπ’ αὐτὴν ὑπόνομοί τε καὶ λαῦραι πραγματείαν οὐκ ἐλάττω τῶν ὑπερῳκοδομημένων ἔχουσαι. τούτων αἱ μὲν κατὰ σύμμετρα διαστήματα φέρουσιν εἰς τὸν λιμένα καὶ τὴν θάλατταν, μία δ’ ἐγκαρσία πάσας ὑπέζωκεν, ὡς τούς τε ὄμβρους εὐμαρῶς καὶ τὰ λύματα τῶν οἰκητόρων συνεκδίδοσθαι τήν τε θάλατταν, ὅταν ἔξωθεν ἐπείγηται, διαρρεῖν καὶ τὴν σύμπασαν ὑποκλύζειν πόλιν. κατεσκεύαζεν δ’ ἐν αὐτῇ καὶ θέατρον καὶ πρὸς τῷ νοτίῳ τοῦ λιμένος ὄπισθεν ἀμφιθέατρον πολὺν ὄχλον ἀνθρώπων δέχεσθαι δυνάμενον καὶ κείμενον ἐπιτηδείως ἀποπτεύειν εἰς τὴν θάλασσαν. ἡ μὲν δὴ πόλις οὕτως ἐξετελέσθη δωδεκαετεῖ χρόνῳ καὶ ταῖς ἐργασίαις οὐκ ἐγκαμόντος καὶ ταῖς δαπάναις ἐπαρκέσαντος τοῦ βασιλέως.", "st": "15.9.6"}, {"sp": "N", "t": "Ἐπὶ τοιούτοις δὲ ὢν καὶ τῆς Σεβαστῆς ἤδη πεπολισμένης ἔγνω τοὺς παῖδας αὐτοῦ πέμπειν εἰς Ῥώμην Ἀλέξανδρον καὶ Ἀριστόβουλον, συντευξομένους Καίσαρι. τούτοις ἀνελθοῦσιν καταγωγὴ μὲν ἦν Πολλίωνος οἶκος ἀνδρὸς τῶν μάλιστα σπουδασάντων περὶ τὴν Ἡρώδου φιλίαν, ἐφεῖτο δὲ κἀν τοῖς Καίσαρος κατάγεσθαι· καὶ γὰρ ἐξεδέξατο μετὰ πάσης φιλανθρωπίας τοὺς παῖδας· καὶ δίδωσιν Ἡρώδῃ τὴν βασιλείαν ὅτῳ βούλεται βεβαιοῦν τῶν ἐξ αὐτοῦ γεγονότων, καὶ χώραν ἔτι τόν τε Τράχωνα καὶ Βαταναίαν καὶ Αὐρανῖτιν· ἔδωκεν δὲ διὰ τοιαύτην αἰτίαν παραλαβών. Ζηνόδωρός τις ἐμεμίσθωτο τὸν οἶκον τὸν Λυσανίου. τούτῳ τὰ μὲν κατὰ τὰς προσόδους οὐκ ἤρκει, τὰ λῃστήρια δὲ ἔχων ἐν τῷ Τράχωνι πλείω τὴν πρόσοδον ἔφερεν· οἰκοῦσι γὰρ ἄνδρες ἐξ ἀπονοίας ζῶντες τοὺς τόπους, οἳ τὰ Δαμασκηνῶν ἐλῄζοντο, καὶ Ζηνόδωρος οὔτ’ εἶργεν αὐτός τε τῶν ὠφελειῶν ἐκοινώνει. κακῶς δὲ πάσχοντες οἱ πλησιόχωροι Οὐάρρωνος κατεβόων τοῦ τότε ἡγεμονεύοντος καὶ γράφειν ἠξίουν Καίσαρι τοῦ Ζηνοδώρου τὴν ἀδικίαν. Καῖσαρ δὲ ἀνενεχθέντων τούτων ἀντέγραφεν ἐξελεῖν τὰ λῃστήρια τήν τε χώραν Ἡρώδῃ προσένειμεν, ὡς διὰ τῆς ἐπιμελείας τῆς ἐκείνου μηκέτ’ ἂν ὀχληρῶν τῶν περὶ τὸν Τράχωνα γενησομένων τοῖς πλησίον· οὐδὲ γὰρ ῥᾴδιον ἦν ἐπισχεῖν αὐτοὺς ἐν ἔθει τὸ λῃστεύειν πεποιημένους καὶ βίον οὐκ ἄλλοθεν ἔχοντας· οὔτε γὰρ πόλεις αὐτοῖς οὔτε κτήσεις ἀγρῶν, ὑποφυγαὶ δὲ κατὰ τῆς γῆς καὶ σπήλαια καὶ κοινὴ μετὰ τῶν βοσκημάτων δίαιτα. μεμηχάνηνται δὲ καὶ συναγωγὰς ὑδάτων καὶ προπαρασκευὰς σιτίων αἳ δύνανται πλεῖστον ἐξ ἀφανοῦς ἀντέχειν. αἵ γε μὴν εἴσοδοι στεναὶ καὶ καθ’ ἕνα παρερχομένων, τὰ δ’ ἔνδον ἀπίστως μεγάλα πρὸς εὐρυχωρίαν ἐξειργασμένων· τὸ δ’ ὑπὲρ τὰς οἰκήσεις ἔδαφος οὐχ ὑψηλόν, ἀλλ’ οἷον ἐξ ἐπιπέδου. πέτρα δὲ τὸ σύμπαν σκληρὰ καὶ δύσοδος, εἰ μὴ τρίβῳ χρῷτό τις ἐξ ὁδηγίας· οὐδὲ γὰρ αὗται κατ’ ὀρθὸν ἀλλὰ πολλὰς ἕλικας ἐξελίττονται. τούτοις ἐπειδὴ τῶν εἰς τοὺς πλησίον κακουργημάτων ἐκωλύοντο, καὶ κατ’ ἀλλήλων ἦν ὁ τῆς λῃστείας τρόπος, ὡς μηδὲν ἀνομίας ἐν τούτῳ λελεῖφθαι. λαβὼν δὲ τὴν χάριν Ἡρώδης παρὰ Καίσαρος καὶ παρελθὼν εἰς τὴν χώραν ὁδηγῶν ἐμπειρίᾳ τούς τε πονηρευομένους αὐτῶν κατέπαυσεν καὶ τοῖς πέριξ ἀδεῆ τὴν εἰρήνην παρέσχεν.", "st": "15.10.1"}, {"sp": "N", "t": "Ὁ δὲ Ζηνόδωρος ἀχθόμενος πρῶτον μὲν ἐπὶ τῇ τῆς ἐπαρχίας ἀφαιρέσει, μᾶλλον δὲ καὶ φθόνῳ τὴν ἀρχὴν Ἡρώδου μετειληφότος, ἀνῆλθεν εἰς Ῥώμην κατηγορήσων αὐτοῦ. κἀκεῖνος μὲν ἄπρακτος ἀναστρέφει. πέμπεται δ’ Ἀγρίππας τῶν πέραν Ἰονίου διάδοχος Καίσαρι· καὶ τούτῳ περὶ Μιτυλήνην χειμάζοντι συντυχὼν Ἡρώδης, ἦν γὰρ εἰς τὰ μάλιστα φίλος καὶ συνήθης, πάλιν εἰς τὴν Ἰουδαίαν ἀνέστρεφεν. Γαδαρέων δέ τινες ἐπ’ Ἀγρίππαν ἦλθον κατηγοροῦντες αὐτοῦ, καὶ τούτους ἐκεῖνος οὐδὲ λόγον αὐτοῖς δοὺς ἀναπέμπει τῷ βασιλεῖ δεσμίους. οἵ τε Ἄραβες καὶ πάλαι δυσμενῶς ἔχοντες πρὸς τὴν ἀρχὴν τὴν Ἡρώδου διεκεκίνηντο καὶ στασιάζειν ἐπεχείρουν αὐτῷ τὰ πράγματα τότε καὶ μετ’ αἰτίας, ὡς ἐδόκουν, εὐλογωτέρας· ὁ γὰρ Ζηνόδωρος ἀπογινώσκων ἤδη τῶν καθ’ αὑτὸν ἔφθη τῆς ἐπαρχίας μέρος τι τὴν Αὐρανῖτιν αὐτοῖς ἀποδόσθαι ταλάντων πεντήκοντα. ταύτης ἐμπεριεχομένης τῇ δωρεᾷ Καίσαρος ὡς μὴ δικαίως ἀφαιρούμενοι διημφισβήτουν, πολλάκις μὲν ταῖς καταδρομαῖς καὶ τῷ βιάζεσθαι θέλειν, ἄλλοτε δὲ καὶ πρὸς δικαιολογίαν ἰόντες. ἀνέπειθον δὲ καὶ τοὺς ἀπόρους τῶν στρατιωτῶν καὶ δυσμενεῖς, ἦσαν δ’ ἐπελπίζοντες ἀεὶ καὶ πρὸς τὸν νεωτερισμὸν ἐνδιδόντες, ᾧ μάλιστα χαίρουσιν οἱ κακῶς πράττοντες τῷ βίῳ. ταῦτα δὲ ἐκ μακροῦ πραττόμενα γινώσκων Ἡρώδης ὅμως οὐκ εἰς τὸ δυσμενές, ἀλλ’ ἐξ ἐπιλογισμοῦ παρηγόρει ταῖς ταραχαῖς οὐκ ἀξιῶν ἀφορμὰς ἐνδιδόναι.", "st": "15.10.2"}, {"sp": "N", "t": "Ἤδη δ’ αὐτοῦ τῆς βασιλείας ἑπτακαιδεκάτου προελθόντος ἔτους Καῖσαρ εἰς Συρίαν ἀφίκετο. καὶ τότε τῶν Γάδαρα κατοικούντων οἱ πλεῖστοι κατεβόων Ἡρώδου βαρὺν αὐτὸν ἐν τοῖς ἐπιτάγμασιν καὶ τυραννικὸν εἶναι. ταῦτα δὲ ἀπετόλμων μάλιστα μὲν ἐγκειμένου καὶ διαβάλλοντος αὐτὸν Ζηνοδώρου καὶ παρασχόντος ὅρκους, ὡς οὐκ ἐγκαταλείψει μὴ πάντα τρόπον ἀφελέσθαι μὲν τῆς Ἡρώδου βασιλείας, προσθήσειν δὲ τῇ διοικήσει τῇ Καίσαρος. τούτοις ἀναπεισθέντες οἱ Γαδαρεῖς οὐ μικρὰν καταβοὴν ἐποιήσαντο θράσει τοῦ μηδὲ τοὺς ὑπὸ Ἀγρίππα παραδοθέντας ἐν τιμωρίᾳ γενέσθαι διιέντος Ἡρώδου καὶ μηδὲν κακὸν εἰργασμένου· καὶ γὰρ εἴ τις καὶ ἄλλος ἐδόκει δυσπαραίτητος μὲν ἐπὶ τοῖς οἰκείοις, μεγαλόψυχος δὲ ἐπὶ τοῖς ἀλλοτρίοις ἁμαρτόντας ἀφιέναι. κατηγορούντων οὖν ὕβρεις καὶ ἁρπαγὰς καὶ κατασκαφὰς ἱερῶν ὁ μὲν Ἡρώδης ἀταρακτήσας ἕτοιμος ἦν εἰς τὴν ἀπολογίαν, ἐδεξιοῦτο δὲ Καῖσαρ αὐτὸν οὐδὲν ὑπὸ τῆς ταραχῆς τοῦ πλήθους μεταβαλὼν τῆς εὐνοίας. καὶ κατὰ μὲν τὴν πρώτην ἡμέραν οἱ περὶ τούτων ἐρρέθησαν λόγοι, ταῖς δ’ ἑξῆς οὐ προῆλθεν ἡ διάγνωσις· οἱ γὰρ Γαδαρεῖς ὁρῶντες τὴν ῥοπὴν αὐτοῦ τε Καίσαρος καὶ τοῦ συνεδρίου καὶ προσδοκήσαντες ὅπερ ἦν εἰκὸς ἐκδοθήσεσθαι τῷ βασιλεῖ, κατὰ φόβον αἰκίας οἱ μὲν ἀπέσφαττον αὑτοὺς ἐν τῇ νυκτί, τινὲς δὲ καθ’ ὕψους ἠφίεσαν, ἄλλοι δ’ εἰς τὸν ποταμὸν ἐμπίπτοντες ἑκοντὶ διεφθείροντο. ταῦτα δὲ ἐδόκει κατάγνωσις τῆς προπετείας καὶ ἁμαρτίας, ἔνθεν οὐδὲ μελλήσας ὁ Καῖσαρ ἀπέλυεν τῶν αἰτιῶν Ἡρώδην. ἐπισυμπίπτει δὲ οὐ μέτριον εὐτύχημα τοῖς ἤδη γεγονόσιν· ὁ γὰρ Ζηνόδωρος ῥαγέντος αὐτῷ τοῦ σπλάγχνου καὶ πολλοῦ κατὰ τὴν ἀσθένειαν ὑποχωροῦντος αἵματος ἐν Ἀντιοχείᾳ τῆς Συρίας ἐκλείπει τὸν βίον. Καῖσαρ δὲ καὶ τὴν τούτου μοῖραν οὐκ ὀλίγην οὖσαν Ἡρώδῃ δίδωσιν, ἣ μεταξὺ τοῦ Τράχωνος ἦν καὶ τῆς Γαλιλαίας, Οὐλάθαν καὶ Πανιάδα καὶ τὴν πέριξ χώραν. ἐγκαταμίγνυσιν δ’ αὐτὴν τοῖς ἐπιτροπεύουσιν τῆς Συρίας ἐντειλάμενος μετὰ τῆς ἐκείνου γνώμης τὰ πάντα ποιεῖν. τό τε σύνολον εἰς τοῦτο προῆλθεν εὐτυχίας, ὥστε δύο τούτων τὴν ἀρχὴν Ῥωμαίων διεπόντων τοσήνδε τὸ μέγεθος οὖσαν, Καίσαρος καὶ μετ’ αὐτὸν Ἀγρίππου, κατὰ τὴν πρὸς αὐτὸν εὔνοιαν Καῖσαρ μὲν οὐδένα μετὰ Ἀγρίππαν Ἡρώδου προετίμησεν, Ἀγρίππας δὲ μετὰ Καίσαρα πρῶτον ἀπεδίδου φιλίας τόπον Ἡρώδῃ. τοσαύτης δὲ ἐχόμενος παρρησίας τῷ μὲν ἀδελφῷ Φερώρᾳ παρὰ Καίσαρος ᾐτήσατο τετραρχίαν αὐτὸς ἀπονείμας ἐκ τῆς βασιλείας πρόσοδον ἑκατὸν ταλάντων, ὡς εἰ καί τι πάσχοι, τὰ κατ’ ἐκεῖνον ἀσφαλῶς ἔχειν καὶ μὴ τοὺς υἱεῖς αὐτῆς κρατεῖν. Καίσαρα δ’ ἐπὶ θάλατταν προπέμψας ὡς ἐπανῆκεν, ἐν τῇ Ζηνοδώρου περικαλλέστατον αὐτῷ ναὸν ἐγείρει πέτρας λευκῆς πλησίον τοῦ Πανίου καλουμένου. σπήλαιον ἐν ὄρει περικαλλές ἐστιν, ὑπ’ αὐτὸ δὲ γῆς ὀλίσθημα καὶ βάθος ἀπερρωγὸς ἄβατον ὕδατος ἀκινήτου πλέον, καθύπερθε δ’ ὄρος παμμέγεθες, ὑπὸ δὲ τὸ σπήλαιον ἀνατέλλουσιν αἱ πηγαὶ τοῦ Ἰορδάνου ποταμοῦ. τοῦτον ἐπισημότατον ὄντα τὸν τόπον καὶ τῷ ναῷ προσεκόσμησεν, ὃν ἀφιέρου Καίσαρι.", "st": "15.10.3"}, {"sp": "N", "t": "Τότε καὶ τὸ τρίτον μέρος ἀφῆκε τῶν φόρων τοῖς ἐν τῇ βασιλείᾳ, πρόφασιν μὲν ὡς ἀναλάβοιεν ἐκ τῆς ἀφορίας, τὸ δὲ πλέον ἀνακτώμενος ἔχοντας δυσμενῶς· κατὰ γὰρ τὴν ἐξεργασίαν τῶν τοιούτων ἐπιτηδευμάτων ὡς ἂν λυομένης αὐτοῖς τῆς εὐσεβείας καὶ μεταπιπτόντων τῶν ἐθῶν χαλεπῶς ἔφερον, καὶ λόγοι δὲ πόντων ἐγίνοντο παροξυνομένων ἀεὶ καὶ ταραττομένων. ὁ δὲ καὶ πρὸς τὸ τοιοῦτον πολλὴν τὴν ἐπιμέλειαν ἐπῆγεν, ἀφαιρούμενος μὲν τὰς εὐκαιρίας, ἐπιτάττων δ’ ἀεὶ γίνεσθαι πρὸς τοῖς πόνοις, ἦν δ’ οὔτε σύνοδος ἐφειμένη τοῖς περὶ τὴν πόλιν οὔτε κοινωνία περιπάτου καὶ διαίτης, ἀλλ’ ἐτετήρητο τὰ πάντα. καὶ χαλεπαὶ τῶν φωραθέντων ἦσαν αἱ κολάσεις, πολλοί τε καὶ φανερῶς καὶ λεληθότως εἰς τὸ φρούριον ἀναγόμενοι τὴν Ὑρκανίαν ἐκεῖ διεφθείροντο, κἀν τῇ πόλει κἀν ταῖς ὁδοιπορίαις ἦσαν οἱ τοὺς συνιόντας εἰς ταὐτὸν ἐπισκοποῦντες. ἤδη δέ φασιν οὐδ’ αὐτὸν ἀμελεῖν τοῦ τοιούτου μέρους, ἀλλὰ πολλάκις ἰδιώτου σχῆμα λαμβάνοντα καταμίγνυσθαι νύκτωρ εἰς τοὺς ὄχλους, καὶ πεῖραν αὐτῶν, ἣν ἔχουσιν ὑπὲρ τῆς ἀρχῆς, λαμβάνειν. τοὺς μὲν οὖν παντάπασιν ἐξαυθαδιζομένους πρὸς τὸ μὴ συμπεριφέρεσθαι τοῖς ἐπιτηδεύμασιν πάντας ἐπεξῄει τοὺς τρόπους, τὸ δ’ ἄλλο πλῆθος ὅρκοις ἠξίου πρὸς τὴν πίστιν ὑπάγεσθαι καὶ συνηνάγκαζεν ἐνώμοτον αὐτῷ τὴν εὔνοιαν ἦ μὴν διαφυλάξειν ἐπὶ τῆς ἀρχῆς ὁμολογεῖν. οἱ μὲν οὖν πολλοὶ κατὰ θεραπείαν καὶ δέος εἶκον οἷς ἠξίου, τοὺς δὲ φρονήματος μεταποιουμένους καὶ δυσχεραίνοντας ἐπὶ τῷ καταναγκάζεσθαι πάντα τρόπον ἐκποδὼν ἐποιεῖτο. συνέπειθεν δὲ καὶ τοὺς περὶ Πολλίωνα τὸν Φαρισαῖον καὶ Σαμαίαν καὶ τῶν ἐκείνοις συνδιατριβόντων τοὺς πλείστους ὀμνύειν· οἱ δ’ οὔτε συνεχώρησαν οὔθ’ ὁμοίως τοῖς ἀρνησαμένοις ἐκολάσθησαν ἐντροπῆς διὰ τὸν Πολλίωνα τυχόντες. ἀφείθησαν δὲ ταύτης τῆς ἀνάγκης καὶ οἱ παρ’ ἡμῖν Ἐσσαῖοι καλούμενοι· γένος δὲ τοῦτ’ ἔστιν διαίτῃ χρώμενον τῇ παρ’ Ἕλλησιν ὑπὸ Πυθαγόρου καταδεδειγμένῃ. περὶ τούτων μὲν οὖν ἐν ἄλλοις σαφέστερον διέξειμι. τοὺς δὲ Ἐσσηνοὺς ἀφ’ οἵας αἰτίας ἐτίμα μεῖζόν τι φρονῶν ἐπ’ αὐτοῖς ἢ κατὰ τὴν θνητὴν φύσιν, εἰπεῖν ἄξιον· οὐ γὰρ ἀπρεπὴς ὁ λόγος φανεῖται τῷ τῆς ἱστορίας γένει παραδηλῶν καὶ τὴν ὑπὲρ τούτων ὑπόληψιν.", "st": "15.10.4"}, {"sp": "N", "t": "Ἦν τις τῶν Ἐσσηνῶν Μανάημος ὄνομα καὶ τἆλλα κατὰ τὴν προαίρεσιν τοῦ βίου καλοκαγαθίαν μαρτυρούμενος καὶ πρόγνωσιν ἐκ θεοῦ τῶν μελλόντων ἔχων. οὗτος ἔτι παῖδα τὸν Ἡρώδην εἰς διδασκάλου φοιτῶντα κατιδὼν βασιλέα Ἰουδαίων προσηγόρευσεν. ὁ δ’ ἀγνοεῖν ἢ κατειρωνεύεσθαι νομίζων αὐτὸν ἀνεμίμνησκεν ἰδιώτης ὤν. Μανάημος δὲ μειδιάσας ἠρέμα καὶ τύπτων τῇ χειρὶ κατὰ τῶν γλουτῶν ἀλλά τοι καὶ βασιλεύσεις, ἔφη, καὶ τὴν ἀρχὴν εὐδαιμόνως ἀπάξεις· ἠξίωσαι γὰρ ἐκ θεοῦ. καὶ μέμνησο τῶν Μαναήμου πληγῶν, ὥστε σοι καὶ τοῦτο σύμβολον εἶναι τῶν κατὰ τὴν τύχην μεταπτώσεων. ἄριστος γὰρ ὁ τοιοῦτος λογισμός, εἰ καὶ δικαιοσύνην ἀγαπήσειας καὶ πρὸς τὸν θεὸν εὐσέβειαν ἐπιείκειαν δὲ πρὸς τοὺς πολίτας· ἀλλ’ οὐ γὰρ οἶδά σε τοιοῦτον ἔσεσθαι τὸ πᾶν ἐπιστάμενος. εὐτυχίᾳ μὲν γὰρ ὅσον οὐκ ἄλλος διοίσεις καὶ τεύξῃ δόξης αἰωνίου, λήθην δ’ εὐσεβείας ἕξεις καὶ τοῦ δικαίου. ταῦτα δ’ οὐκ ἂν λάθοι τὸν θεὸν ἐπὶ τῇ καταστροφῇ τοῦ βίου τῆς ἀντ’ αὐτῶν ὀργῆς ἀπομνημονευομένης. τούτοις αὐτίκα μὲν ἥκιστα τὸν νοῦν προσεῖχεν ἐλπίδι λειπόμενος αὐτῶν Ἡρώδης, κατὰ μικρὸν δὲ ἀρθεὶς ἕως καὶ τοῦ βασιλεύειν καὶ εὐτυχεῖν ἐν τῷ μεγέθει τῆς ἀρχῆς μεταπέμπεται τὸν Μανάημον καὶ περὶ τοῦ χρόνου πόσον ἄρξει διεπυνθάνετο. Μανάημος δὲ τὸ μὲν σύμπαν οὐκ εἶπεν· ὡς δὲ σιωπῶντος αὐτοῦ, μόνον εἰ δέκα γενήσονται βασιλείας ἐνιαυτοὶ προσεπύθετο καὶ εἴκοσι καὶ τριάκοντα εἰπὼν τὸν ὅρον οὐκ ἐπέθηκε τῷ τέλει τῆς προθεσμίας, Ἡρώδης δὲ καὶ τούτοις ἀρκεσθεὶς τόν τε Μανάημον ἀφῆκεν δεξιωσάμενος καὶ πάντας ἀπ’ ἐκείνου τοὺς Ἐσσηνοὺς τιμῶν διετέλει. ταῦτα μὲν οὖν εἰ καὶ παράδοξα δηλῶσαι τοῖς ἐντυγχάνουσιν ἠξιώσαμεν καὶ περὶ τῶν παρ’ ἡμῖν ἐμφῆναι, διότι πολλοὶ [διὰ] τοιούτων ὑπὸ καλοκαγαθίας καὶ τῆς τῶν θείων ἐμπειρίας ἀξιοῦνται.", "st": "15.10.5"}, {"sp": "N", "t": "Τότε δ’ οὖν ὀκτωκαιδεκάτου τῆς Ἡρώδου βασιλείας γεγονότος ἐνιαυτοῦ μετὰ τὰς προειρημένας πράξεις ἔργον οὐ τὸ τυχὸν ἐπεβάλετο, τὸν νεὼν τοῦ θεοῦ δι’ αὐτοῦ κατασκευάσασθαι μείζω τε τὸν περίβολον καὶ πρὸς ὕψος ἀξιοπρεπέστερον ἐγείρειν, ἡγούμενος ἁπάντων αὐτῷ τῶν πεπραγμένων περισημότερον, ὥσπερ ἦν, ἐκτελεσθήσεσθαι τοῦτο καὶ πρὸς αἰώνιον μνήμην ἀρκέσειν. οὐχ ἕτοιμον δὲ τὸ πλῆθος ἐπιστάμενος οὐδὲ ῥᾴδιον ἔσεσθαι πρὸς τὸ μέγεθος τῆς ἐπιχειρήσεως ἠξίου λόγῳ προκαταστησάμενος ἐγχειρῆσαι τῷ παντί, καὶ συγκαλέσας αὐτοὺς ἔλεγε τοιάδε· τὰ μὲν ἄλλα μοι τῶν κατὰ τὴν βασιλείαν πεπραγμένων, ἄνδρες ὁμόφυλοι, περισσὸν ὑπολαμβάνω λέγειν. καίτοι τοῦτον ἐγένετο τὸν τρόπον, ὡς ἐλάττω μὲν ἐμοὶ τὸν ἀπ’ αὐτῶν κόσμον, πλείω δὲ ὑμῖν τὴν ἀσφάλειαν φέρειν. οὔτε γὰρ ἐν τοῖς δυσχερεστάτοις ἀμελήσας τῶν εἰς τὰς ὑμετέρας χρείας διαφερόντων οὔτε ἐν τοῖς κατασκευάσμασιν ἐπιτηδεύσας ἐμαυτῷ μᾶλλον ἢ καὶ πᾶσιν ὑμῖν τὸ ἀνεπηρέαστον, οἶμαι σὺν τῇ τοῦ θεοῦ βουλήσει πρὸς εὐδαιμονίαν ὅσον οὐ πρότερον ἀγηοχέναι τὸ Ἰουδαίων ἔθνος. τὰ μὲν οὖν κατὰ μέρος ἐξεργασθέντα περὶ τὴν χώραν καὶ πόλεις ὅσας ἐν αὐτῇ καὶ τοῖς ἐπικτήτοις ἐγείραντες κόσμῳ τῷ καλλίστῳ τὸ γένος ἡμῶν ηὐξήσαμεν, περίεργά μοι δοκεῖ λέγειν εἰδόσιν. τὸ δὲ τῆς ἐπιχειρήσεως, ᾗ νῦν ἐπιχειρεῖν ἐπιβάλλομαι, παντὸς εὐσεβέστατον καὶ κάλλιστον ἐφ’ ἡμῶν γενέσθαι νῦν ἐκφανῶ· τὸν γὰρ ναὸν τοῦτον ᾠκοδόμησαν μὲν τῷ μεγίστῳ θεῷ πατέρες ἡμέτεροι μετὰ τὴν ἐκ Βαβυλῶνος ἐπάνοδον, ἐνδεῖ δ’ αὐτῷ πρὸς τὸ μέγεθος εἰς ὕψος ἑξήκοντα πήχεις· τοσοῦτον γὰρ ὑπερεῖχεν ὁ πρῶτος ἐκεῖνος, ὃν Σολομῶν ἀνῳκοδόμησεν. καὶ μηδεὶς ἀμέλειαν εὐσεβείας τῶν πατέρων καταγνώτω· γέγονεν γὰρ οὐ παρ’ ἐκείνους ἐλάττων ὁ ναός, ἀλλὰ ταῦτα καὶ Κῦρος καὶ Δαρεῖος ὁ Ὑστάσπου τὰ μέτρα τῆς δομήσεως ἔδοσαν, οἷς ἐκεῖνοι καὶ τοῖς ἀπογόνοις δουλεύσαντες καὶ μετ’ ἐκείνους Μακεδόσιν οὐκ ἔσχον εὐκαιρίαν τὸ πρῶτον τῆς εὐσεβείας ἀρχέτυπον εἰς ταὐτὸν ἀναγαγεῖν μέγεθος. ἐπειδὴ δὲ νῦν ἐγὼ μὲν ἄρχω θεοῦ βουλήσει, περίεστιν δὲ καὶ μῆκος εἰρήνης καὶ κτῆσις χρημάτων καὶ μέγεθος προσόδων, τὸ δὲ μέγιστον φίλοι καὶ δι’ εὐνοίας οἱ πάντων ὡς ἔπος εἰπεῖν κρατοῦντες Ῥωμαῖοι, πειράσομαι τὸ παρημελημένον ἀνάγκῃ καὶ δουλείᾳ τοῦ πρότερον χρόνου διορθούμενος τελείαν ἀποδοῦναι τῷ θεῷ τὴν ἀνθ’ ὧν ἔτυχον τῆσδε τῆς βασιλείας εὐσέβειαν.", "st": "15.11.1"}, {"sp": "N", "t": "Ὁ μὲν Ἡρώδης ταῦτ’ εἶπεν, ἐξέπληξε δὲ τοὺς πολλοὺς ὁ λόγος παρὰ δόξαν ἐμπεσών. καὶ τὸ μὲν τῆς ἐλπίδος ἄπιστον οὐκ ἐπήγειρεν αὐτούς, ἠδημόνουν δέ, μὴ φθάσας καταλῦσαι τὸ πᾶν ἔργον οὐκ ἐξαρκέσει πρὸς τέλος ἀγαγεῖν τὴν προαίρεσιν· ὅ τε κίνδυνος αὐτοῖς μείζων ἐφαίνετο καὶ δυσεγχείρητον ἐδόκει τὸ μέγεθος τῆς ἐπιβολῆς. οὕτως δ’ αὐτῶν διακειμένων παρεθάρρυνεν ὁ βασιλεύς, οὐ πρότερον καθαιρήσειν φάμενος τὸν ναὸν μὴ πάντων αὐτῷ τῶν εἰς συντέλειαν παρεσκευασμένων. καὶ ταῦτα προειπὼν οὐκ ἐψεύσατο· χιλίας γὰρ εὐτρεπίσας ἁμάξας, αἳ βαστάσουσι τοὺς λίθους, ἐργάτας δὲ μυρίους τοὺς ἐμπειροτάτους ἐπιλεξάμενος καὶ ἱερεῦσιν τὸν ἀριθμὸν χιλίοις ἱερατικὰς ὠνησάμενος στολάς, καὶ τοὺς μὲν διδάξας οἰκοδόμους, ἑτέρους δὲ τέκτονας, ἥπτετο τῆς κατασκευῆς ἁπάντων αὐτῷ προθύμως προευτρεπισμένων.", "st": "15.11.2"}, {"sp": "N", "t": "Ἀνελὼν δὲ τοὺς ἀρχαίους θεμελίους καὶ καταβαλόμενος ἑτέρους ἐπ’ αὐτῶν ναὸν ἤγειρεν μήκει μὲν ἑκατὸν ὄντα πηχῶν, τὸ δ’ ὕψος εἴκοσι περιττοῖς, οὓς τῷ χρόνῳ συνιζησάντων τῶν θεμελίων ὑπέβη. καὶ τοῦτο μὲν κατὰ τοὺς Νέρωνος καιροὺς ἐπεγείρειν ἐγνώκειμεν. ᾠκοδομήθη δὲ ὁ ναὸς ἐκ λίθων λευκῶν τε καὶ κραταιῶν τὸ μέγεθος ἑκάστων περὶ πέντε καὶ εἴκοσι πήχεις ἐπὶ μῆκος, ὀκτὼ δὲ ὕψος, εὖρος δὲ περὶ δώδεκα. καὶ παντὸς αὐτοῦ καθότι καὶ τῆς βασιλείου στοᾶς τὸ μὲν ἔνθεν καὶ ἔνθεν ταπεινότατον, ὑψηλότατον δὲ τὸ μεσαίτατον, ὡς περίοπτον ἐκ πολλῶν σταδίων εἶναι τοῖς τὴν χώραν νεμομένοις, μᾶλλον δ’ εἴ τινες κατ’ ἐναντίον οἰκοῦντες ἢ προσιόντες τύχοιεν. θύρας δὲ ἐπὶ τῆς εἰσόδου σὺν τοῖς ὑπερθυρίοις ἴσον ἐχούσας τῷ ναῷ ποικίλοις ἐμπετάσμασιν κεκόσμητο, τὰ μὲν ἄνθη ἁλουργέσιν, κίονας δὲ ἐνυφασμένους. καθύπερθε δ’ αὐτῶν ὑπὸ τοῖς τριχώμασιν ἄμπελος διετέτατο χρυσῆ τοὺς βότρυας ἀπαιωρουμένους ἔχουσα, θαῦμα καὶ τοῦ μεγέθους καὶ τῆς τέχνης τοῖς ἰδοῦσιν, οἷον ἐν πολυτελείᾳ τῆς ὕλης τὸ κατασκευασθὲν ἦν. περιελάμβανεν δὲ καὶ στοαῖς μεγίσταις τὸν ναὸν ἅπαντα πρὸς τὴν ἀναλογίαν ἐπιτηδεύων καὶ τὰς δαπάνας τῶν πρὶν ὑπερβαλλόμενος, ὡς οὐκ ἄλλος τις δοκεῖ ἐπικεκοσμηκέναι τὸν ναόν. ἄμφω δ’ ἦσαν μετὰ τοῦ τείχους, αὐτὸ δὲ τὸ τεῖχος ἔργον μέγιστον ἀνθρώποις ἀκουσθῆναι. λόφος ἦν πετρώδης ἀνάντης ἠρέμα πρὸς τοῖς ἑῴοις μέρεσιν τῆς πόλεως ὑπτιούμενος ἐπὶ τὴν κορυφὴν ἄκραν. τοῦτον ὁ πρῶτος ἡμῶν βασιλεὺς Σολομῶν κατ’ ἐπιφροσύνην μεγάλαις ἐργασίαις ἀπετείχιζεν τὰ περὶ τὴν ἄκραν ἄνωθεν, ἀπετείχιζεν δὲ κάτωθεν ἀπὸ τῆς ῥίζης ἀρχόμενος, ἣν βαθεῖα περιθεῖ φάραγξ ἠλιβάτοις πέτραις μολίβδῳ δεδεμέναις πρὸς ἀλλήλας, ἀπολαμβάνων αἰεί τι τῆς ἔσω χώρας καὶ προβαίνων εἰς βάθος, ὥστ’ ἄπειρον εἶναι τό τε μέγεθος τῆς δομῆς καὶ τὸ ὕψος τετραγώνου γεγενημένης, ὡς τὰ μὲν μεγέθη τῶν λίθων ἀπὸ μετώπου κατὰ τὴν ἐπιφάνειαν ὁρᾶσθαι, τὰ δ’ ἐντὸς σιδήρῳ διησφαλισμένα συνέχειν τὰς ἁρμογὰς ἀκινήτους τῷ παντὶ χρόνῳ. τῆς δ’ ἐργασίας οὕτω συναπτούσης εἰς ἄκρον τὸν λόφον ἀπεργασάμενος αὐτοῦ τὴν κορυφὴν καὶ τὰ κοῖλα τῶν περὶ τὸ τεῖχος ἐμπλήσας ἰσόπεδον τοῖς κατὰ τὴν ἐπιφάνειαν τὴν ἄνω καὶ λεῖον ἐποίησεν. τοῦτ’ ἦν τὸ πᾶν περίβολος τεττάρων σταδίων τὸν κύκλον ἔχων, ἑκάστης γωνίας στάδιον μῆκος ἀπολαμβανούσης. ἐνδοτέρω δὲ τούτου καὶ παρ’ αὐτὴν τὴν ἄκραν ἄλλο τεῖχος ἄνω λίθινον περιθεῖ, κατὰ μὲν ἑῴαν ῥάχιν ἰσομήκη τῷ τείχει στοὰν ἔχον διπλῆν, ἐν μέσῳ τοῦ νεὼ τετυχηκότος ἀφορῶσαν εἰς τὰς θύρας αὐτοῦ. ταύτην πολλοὶ βασιλεῖς οἱ πρόσθεν κατεσκεύασαν. τοῦ δ’ ἱεροῦ παντὸς ἦν ἐν κύκλῳ πεπηγμένα σκῦλα βαρβαρικά, καὶ ταῦτα πάντα βασιλεὺς Ἡρώδης ἀνέθηκεν προσθεὶς ὅσα καὶ τῶν Ἀράβων ἔλαβεν.", "st": "15.11.3"}, {"sp": "N", "t": "Κατὰ δὲ τὴν βόρειον πλευρὰν ἀκρόπολις ἐγγώνιος εὐερκὴς ἐτετείχιστο διάφορος ἐχυρότητι. ταύτην οἱ πρὸ Ἡρώδου τοῦ Ἀσαμωναίων γένους βασιλεῖς καὶ ἀρχιερεῖς ᾠκοδόμησαν καὶ βᾶριν ἐκάλεσαν, ὡς ἐκεῖ τὴν ἱερατικὴν αὐτοῖς ἀποκεῖσθαι στολήν, ἣν ὅταν δέῃ θύειν τότε μόνον ὁ ἀρχιερεὺς ἀμφιέννυται. ταύτην Ἡρώδης ὁ βασιλεὺς ἐφύλαξεν ἐν τῷ τόπῳ καὶ μετὰ τὴν ἐκείνου τελευτὴν ὑπὸ Ῥωμαίοις ἦν μέχρι τῶν Τιβερίου Καίσαρος χρόνων. ἐπὶ τούτου δὲ Οὐιτέλλιος ὁ τῆς Συρίας ἡγεμὼν ἐπιδημήσας τοῖς Ἱεροσολύμοις, δεξαμένου τοῦ πλήθους αὐτὸν λαμπρότατα πάνυ θέλων αὐτοὺς τῆς εὐποιίας ἀμείψασθαι, ἐπεὶ παρεκάλεσαν τὴν ἱερὰν στολὴν ὑπὸ τὴν αὐτῶν ἐξουσίαν ἔχειν, ἔγραψεν περὶ τούτων Τιβερίῳ Καίσαρι κἀκεῖνος ἐπέτρεψεν, καὶ παρέμεινεν ἡ ἐξουσία τῆς στολῆς τοῖς Ἰουδαίοις μέχρις ἐτελεύτησεν ὁ βασιλεὺς Ἀγρίππας. μετὰ τοῦτον δὲ Κάσσιος Λογγῖνος ὁ τὴν Συρίαν τότε διοικῶν καὶ Κούσπιος Φᾶδος ὁ τῆς Ἰουδαίας ἐπίτροπος κελεύουσιν τοὺς Ἰουδαίους εἰς τὴν Ἀντωνίαν καταθέσθαι τὴν στολήν· Ῥωμαίους γὰρ αὐτῆς εἶναι δεῖν κυρίους, καθὼς καὶ πρότερον ἦσαν. πέμπουσιν οὖν Ἰουδαῖοι πρέσβεις πρὸς Κλαύδιον Καίσαρα περὶ τούτων παρακαλέσοντας. ὧν ἀναβάντων ὁ νεώτερος βασιλεὺς Ἀγρίππας ἐν Ῥώμῃ τυγχάνων αἰτησάμενος παρὰ τοῦ αὐτοκράτορος τὴν ἐξουσίαν ἔλαβεν ἐντειλαμένου Οὐιτελλίῳ τῷ τῆς Συρίας ἀντιστρατήγῳ. πρότερον δ’ ἦν ὑπὸ σφραγῖδα τοῦ ἀρχιερέως καὶ τῶν γαζοφυλάκων, καὶ πρὸ μιᾶς ἡμέρας τῆς ἑορτῆς ἐπὶ τὸν Ῥωμαίων φρούραρχον ἀναβαίνοντες οἱ γαζοφύλακες καὶ καταμανθάνοντες τὴν ἑαυτῶν σφραγῖδα τὴν στολὴν ἐλάμβανον. εἶτ’ αὖθις τῆς ἑορτῆς παρελθούσης εἰς τὸν αὐτὸν κομίσαντες τόπον καὶ τῷ φρουράρχῳ δείξαντες σύμφωνον τὴν σφραγῖδα κατετίθεντο. ταῦτα μὲν οὖν ὑπὸ τοῦ πάθους τῶν ἐπισυμβεβηκότων παρεδηλώθη. τότε δ’ οὖν ὁ τῶν Ἰουδαίων βασιλεὺς Ἡρώδης καὶ ταύτην τὴν βᾶριν ὀχυρωτέραν κατασκευάσας ἐπ’ ἀσφαλείᾳ καὶ φυλακῇ τοῦ ἱεροῦ, χαριζόμενος Ἀντωνίῳ φίλῳ μὲν αὐτοῦ Ῥωμαίων δὲ ἄρχοντι προσηγόρευσεν Ἀντωνίαν.", "st": "15.11.4"}, {"sp": "N", "t": "Ἐν δὲ τοῖς ἑσπερίοις μέρεσιν τοῦ περιβόλου πύλαι τέτταρες ἐφέστασαν, ἡ μὲν εἰς τὰ βασίλεια τείνουσα τῆς ἐν μέσῳ φάραγγος εἰς δίοδον ἀπειλημμένης, αἱ δύο δὲ εἰς τὸ προάστειον, ἡ λοιπὴ δ’ εἰς τὴν ἄλλην πόλιν βαθμίσιν πολλαῖς κάτω τε εἰς τὴν φάραγγα διειλημμένη καὶ ἀπὸ ταύτης ἄνω πάλιν ἐπὶ τὴν πρόσβασιν· ἄντικρυς γὰρ ἡ πόλις ἔκειτο τοῦ ἱεροῦ θεατροειδὴς οὖσα περιεχομένη βαθείᾳ φάραγγι κατὰ πᾶν τὸ νότιον κλίμα. τὸ δὲ τέταρτον αὐτοῦ μέτωπον τὸ πρὸς μεσημβρίαν εἶχε μὲν καὶ αὐτὸ πύλας κατὰ μέσον, ἐπ’ αὐτοῦ δὲ τὴν βασίλειον στοὰν τριπλῆν κατὰ μῆκος διιοῦσαν ἀπὸ τῆς ἑῴας φάραγγος ἐπὶ τὴν ἑσπέριον· οὐ γὰρ ἦν ἐκτεῖναι προσωτέρω δυνατόν. ἔργον δ’ ἦν ἀξιαφηγητότατον τῶν ὑφ’ ἡλίῳ· μεγάλου γὰρ ὄντος τοῦ τῆς φάραγγος ἀναλήμματος καὶ οὐδ’ ἀνεκτοῦ κατιδεῖν, εἴ τις ἄνωθεν εἰς τὸν βυθὸν εἰσκύπτοι, παμμέγεθες ὕψος ἐν αὐτῷ τὸ τῆς στοᾶς ἀνέστηκεν, ὡς εἴ τις ἀπ’ ἄκρου τοῦ ταύτης τέγους ἄμφω συντιθεὶς τὰ βάθη διοπτεύοι, σκοτοδινιᾶν οὐκ ἐξικνουμένης τῆς ὄψεως εἰς ἀμέτρητον τὸν βυθόν. κίονες δ’ ἐφέστασαν κατ’ ἀντίστοιχον ἀλλήλοις ἐπὶ μῆκος τέτραχα, συνεδέδετο γὰρ ὁ τέταρτος στοῖχος λιθοδομήτῳ τείχει, καὶ πάχος ἦν ἑκάστου κίονος εἰς τρεῖς ἐπισυναπτόντων ἀλλήλοις τὰς ὀργυιὰς περιλαβεῖν, μῆκος δὲ ποδῶν ἑπτὰ καὶ εἴκοσι διπλῆς σπείρας ὑπειλημένης. πλῆθος δὲ συμπάντων δύο καὶ ἑξήκοντα καὶ ἑκατὸν κιονοκράνων αὐτοῖς κατὰ τὸν Κορίνθιον τρόπον ἐπεξειργασμένων γλυφαῖς ἔκπληξιν ἐμποιούσαις διὰ τὴν τοῦ παντὸς μεγαλουργίαν. τεττάρων δὲ στίχων ὄντων τρεῖς ἀπολαμβάνουσι τὰς διὰ μέσου χώρας ταῖς στοαῖς. τῶν δὲ αἱ μὲν δύο παράλληλοι τὸν αὐτὸν γεγόνασι τρόπον, εὖρος ἑκατέρας πόδες τριάκοντα, μῆκος δὲ στάδιον, ὕψος δὲ πόδες ὑπὲρ πεντήκοντα· τῆς δὲ μέσης εὖρος μὲν ἡμιόλιον, ὕψος δὲ διπλάσιον· ἀνεῖχεν γὰρ πλεῖστον παρὰ τὰς ἑκατέρωθεν. αἱ δ’ ὀροφαὶ ξύλοις ἐξήσκηντο γλυφαῖς πολυτρόποις σχημάτων ἰδέαις, καὶ τὸ τῆς μέσης βάθος ἐπὶ μεῖζον ἠγείρετο περιδεδομημένου τοῖς ἐπιστυλίοις προμετωπιδίου τοίχου κίονας ἔχοντος ἐνδεδομημένους καὶ ξεστοῦ παντὸς ὄντος, ὡς ἄπιστα τοῖς οὐκ εἰδόσιν καὶ σὺν ἐκπλήξει θεατὰ τοῖς ἐντυγχάνουσιν εἶναι. τοιοῦτος μὲν ὁ πρῶτος περίβολος ἦν. ἐν μέσῳ δὲ ἀπέχων οὐ πολὺ δεύτερος, προσβατὸς βαθμίσιν ὀλίγαις, ὃν περιεῖχεν ἑρκίον λιθίνου δρυφάκτου γραφῇ κωλῦον εἰσιέναι τὸν ἀλλοεθνῆ θανατικῆς ἀπειλουμένης τῆς ζημίας. εἶχεν δ’ ὁ μὲν ἐντὸς περίβολος κατὰ μὲν τὸ νότιον καὶ βόρειον κλίμα τριστοίχους πυλῶνας ἀλλήλων διεστῶτας, κατὰ δὲ ἡλίου βολὰς ἕνα τὸν μέγαν, δι’ οὗ παρῄειμεν ἁγνοὶ μετὰ γυναικῶν. ἐσωτέρω δὲ κἀκείνου γυναιξὶν ἄβατον ἦν τὸ ἱερόν. ἐκείνου δ’ ἐνδοτέρω τρίτον, ὅπου τοῖς ἱερεῦσιν εἰσελθεῖν ἐξὸν ἦν μόνοις. [ὁ ναὸς ἐν τούτῳ] καὶ πρὸ αὐτοῦ βωμὸς ἦν, ἐφ’ οὗ τὰς θυσίας ὡλοκαυτοῦμεν τῷ θεῷ. τούτων εἰς οὐδένα τῶν τριῶν ὁ βασιλεὺς Ἡρώδης παρῆλθεν· ἐκεκώλυτο γὰρ οὐκ ὢν ἱερεύς. ἀλλὰ κἀν τοῖς ἔργοις τὰ περὶ τὰς στοὰς καὶ τοὺς ἔξω περιβόλους ἐπραγματεύετο καὶ ταῦτ’ ᾠκοδόμησεν ἔτεσιν ὀκτώ.", "st": "15.11.5"}, {"sp": "N", "t": "Τοῦ δὲ ναοῦ διὰ τῶν ἱερέων οἰκοδομηθέντος ἐνιαυτῷ καὶ μησὶν πέντε ἅπας ὁ λαὸς ἐπληρώθη χαρᾶς καὶ τοῦ τάχους πρῶτον μὲν τῷ θεῷ τὰς εὐχαριστηρίους ἐποιοῦντο, μετὰ δὲ καὶ τῆς προθυμίας τοῦ βασιλέως ἑορτάζοντες καὶ κατευφημοῦντες τὴν ἀνάκτισιν. ὁ δὲ βασιλεὺς τριακοσίους ἔθυσε τῷ θεῷ βοῦς καὶ τῶν ἄλλων οἱ κατὰ δύναμιν, ὧν οὐχ οἷόν τε τὸν ἀριθμὸν εἰπεῖν· ἐκφεύγει γὰρ τὸ δύνασθαι πρὸς ἀλήθειαν εἰπεῖν· συνεπεπτώκει γὰρ τῇ προθεσμίᾳ τοῦ περὶ τὸν ναὸν ἔργου καὶ τὴν ἡμέραν τῷ βασιλεῖ τῆς ἀρχῆς, ἣν ἐξ ἔθους ἑώρταζον, ἐς ταὐτὸν ἐλθεῖν, καὶ περισημοτάτην ἐξ ἀμφοῖν τὴν ἑορτὴν γενέσθαι.", "st": "15.11.6"}, {"sp": "N", "t": "Κατεσκευάσθη δὲ καὶ κρυπτὴ διώρυξ τῷ βασιλεῖ, φέρουσα μὲν ἀπὸ τῆς Ἀντωνίας μέχρι τοῦ ἔσωθεν ἱεροῦ πρὸς τὴν ἀνατολικὴν θύραν, ἐφ’ ἧς αὐτῷ καὶ πύργον κατεσκεύασεν, ἵν’ ἔχῃ διὰ τῶν ὑπογέων εἰς αὐτὸν ἀνιέναι, τὸν ἐκ τοῦ δήμου νεωτερισμὸν ἐπὶ τοῖς βασιλεῦσι φυλαττόμενος. λέγεται δὲ κατ’ ἐκεῖνον τὸν καιρὸν οἰκοδομουμένου τοῦ ναοῦ τὰς μὲν ἡμέρας οὐχ ὕειν, ἐν δὲ ταῖς νυξὶ γίνεσθαι τοὺς ὄμβρους, ὡς μὴ κωλυσιεργεῖν. καὶ τοῦτον τὸν λόγον οἱ πατέρες ἡμῖν παρέδωκαν, οὐδ’ ἐστὶν ἄπιστον, εἰ καὶ πρὸς τὰς ἄλλας ἀπίδοι τις ἐμφανείας τοῦ θεοῦ. τὰ μὲν οὖν περὶ τὸν ναὸν ἐξῳκοδομήθη τοῦτον τὸν τρόπον.", "st": "15.11.7"}, {"sp": "HDR", "t": "Βιβλίον ΙϚʹ", "st": "16"}, {"sp": "N", "t": "Ἐν δὲ τῇ διοικήσει τῶν ὅλων πραγμάτων ἐσπουδακὼς ὁ βασιλεὺς τὰς κατὰ μέρος ἀδικίας ἀναστεῖλαι τῶν περὶ τὴν πόλιν καὶ τὴν χώραν ἁμαρτανομένων τίθησι νόμον οὐδὲν ἐοικότα τοῖς πρώτοις, ὃν αὐτὸς ἐβεβαίου, τοὺς τοιχωρύχους ἀποδιδόμενος ἐπ’ ἐξαγωγῇ τῆς βασιλείας, ὅπερ ἦν οὐκ εἰς τὴν τιμωρίαν μόνον τῶν πασχόντων φορτικόν, ἀλλὰ καὶ κατάλυσιν περιεῖχεν τῶν πατρίων ἐθῶν. τὸ γὰρ ἀλλοφύλοις καὶ μὴ τὴν αὐτὴν δίαιταν ἔχουσιν τοῦ ζῆν δουλεύειν καὶ βιάζεσθαι πάνθ’ ὅσα προσέταττον ἐξ ἀνάγκης ἐκεῖνοι ποιεῖν ἁμαρτία πρὸς τὴν θρησκείαν ἦν, οὐ κόλασις τῶν ἁλισκομένων, πεφυλαγμένης ἐν τοῖς πρώτοις τῆς τοιαύτης τιμωρίας· ἐκέλευον γὰρ οἱ νόμοι τετραπλᾶ καταβάλλειν τὸν κλέπτην, οὐκ ἔχοντα δὲ πιπράσκεσθαι μέν, ἀλλ’ οὔτι γε τοῖς ἀλλοφύλοις οὐδ’ ὥστε διηνεκῆ τὴν δουλείαν ὑπομένειν· ἔδει γὰρ ἀφεῖσθαι μετὰ ἑξαετίαν. τὸ δ’ ὥσπερ ὡρίσθη τότε χαλεπὴν καὶ παράνομον γενέσθαι τὴν κόλασιν ὑπερηφανίας ἐδόκει μέρος, οὐ βασιλικῶς ἀλλὰ τυραννικῶς αὐτοῦ καὶ πρὸς τὰ κοινὰ τῶν ἀρχομένων ὀλιγώρως θεῖναι τὴν τιμωρίαν νενοηκότος. ταῦτα μὲν οὖν καθ’ ὁμοιότητα τοῦ λοιποῦ τρόπου γιγνόμενα μέρος ἦν τῶν διαβολῶν καὶ τῆς ἐπ’ αὐτῷ δυσνοίας.", "st": "16.1.1"}, {"sp": "N", "t": "Ἐν δὲ τούτῳ τῷ καιρῷ καὶ τὸν εἰς τὴν Ἰταλίαν πλοῦν ἐποιήσατο Καίσαρί τε συντυχεῖν ὁρμηθεὶς καὶ θεάσασθαι τοὺς παῖδας ἐν τῇ Ῥώμῃ διατρίβοντας. Καῖσαρ δὲ τά τε ἄλλα φιλοφρόνως αὐτὸν ἐξεδέξατο καὶ τοὺς παῖδας ὡς ἤδη τελειωθέντας ἐν τοῖς μαθήμασιν ἀπέδωκεν ἄγειν εἰς τὴν οἰκείαν. ὡς δ’ ἧκον ἀπὸ τῆς Ἰταλίας, σπουδὴ περὶ τὰ μειράκια τῶν ὄχλων ἦν, καὶ περίοπτοι πᾶσιν ἐγεγόνεισαν τῷ τε μεγέθει τῆς περὶ αὐτοὺς τύχης κοσμούμενοι καὶ βασιλικοῦ κατὰ τὰς μορφὰς ἀξιώματος οὐκ ἀποδέοντες. ἐπίφθονοί τε εὐθέως ἐδόκουν Σαλώμῃ τε τῇ τοῦ βασιλέως ἀδελφῇ καὶ τοῖς Μαριάμμην ταῖς διαβολαῖς κατηγωνισμένοις· οὗτοι γὰρ ᾤοντο δυναστευόντων αὐτῶν δίκην δώσειν τῶν εἰς τὴν μητέρα τὴν ἐκείνων παρανομηθέντων. τὴν αὐτὴν οὖν ταύτην ὑπόθεσιν τοῦ δέους εἰς τὴν κατ’ ἐκείνων διαβολὴν μετέφερον λογοποιοῦντες οὐ καθ’ ἡδονὰς συνεῖναι τῷ πατρὶ διὰ τὸν τῆς μητρὸς θάνατον, ὡς μηδὲ ὅσιον εἶναι δοκεῖν ἐπὶ ταὐτὸν συνιέναι τῷ τῆς τεκούσης φονεῖ· ταῦτα γὰρ ἀπὸ τῆς ἀληθείας ἐπὶ τὸ πιθανὸν τῆς αἰτίας φέροντες κακοῦν ἐδύναντο καὶ τῆς εὐνοίας ἧς εἶχεν εἰς τοὺς παῖδας ἀφαιρεῖν· οὐδὲ γὰρ πρὸς αὐτὸν ἄντικρυς ἔλεγον, ἀλλ’ εἰς τὸ λοιπὸν πλῆθος ἐσκόρπιζον τοὺς τοιούτους λόγους· ἐξ οὗ πρὸς τὸν Ἡρώδην ἀναφερομένων ὑποκατεσκευάζετο μῖσος οὐδ’ αὐτῇ τῇ φύσει χρόνῳ νικώμενον. ἐν μέντοι τῷ τότε πάσης ὑποψίας καὶ διαβολῆς μείζονι χρώμενος ὁ βασιλεὺς τῇ τοῦ γεγεννηκέναι φιλοστοργίᾳ καὶ τιμῆς ἧς ἔδει μετεδίδου καὶ γυναῖκας ἐν ἡλικίᾳ γεγονόσιν ἐζεύγνυεν, Ἀριστοβούλῳ μὲν τὴν Σαλώμης θυγατέρα Βερενίκην, Ἀλεξάνδρῳ δὲ τὴν Ἀρχελάου τοῦ Καππαδόκων βασιλέως Γλαφύραν.", "st": "16.1.2"}, {"sp": "N", "t": "Ταῦτα διοικήσας, ἐπειδὴ καὶ Μᾶρκον Ἀγρίππαν ἐπύθετο καταπεπλευκέναι πάλιν ἐκ τῆς Ἰταλίας εἰς τὴν Ἀσίαν, ἐπειχθεὶς πρὸς αὐτὸν ἠξίωσεν εἴς τε τὴν βασιλείαν αὐτοῦ παρελθεῖν καὶ τυχεῖν ὧν ἔδει παρὰ ἀνδρὸς ξένου καὶ φίλου. κἀκεῖνος μὲν εἴξας λιπαρῶς ἐγκειμένου ἧκεν εἰς τὴν Ἰουδαίαν, Ἡρώδης δὲ οὐδὲν ἀρεσκείας ἀπέλιπεν ἔν τε ταῖς νεοκτίστοις πόλεσιν ὑποδεχόμενος αὐτὸν καὶ μετὰ τοῦ τὰς κατασκευὰς ἐπιδεικνύναι πᾶσαν ἀπόλαυσιν διαίτης καὶ πολυτελείας ἐξαλλάττων αὐτῷ καὶ τοῖς φίλοις ἔν τε τῇ Σεβαστῇ καὶ Καισαρείᾳ περὶ τὸν λιμένα τὸν ὑπ’ αὐτοῦ κατεσκευασμένον κἀν τοῖς ἐρύμασιν, ἃ πολλαῖς δαπάναις ἐξῳκοδόμησεν, τό τε Ἀλεξάνδρειον καὶ Ἡρώδειον καὶ τὴν Ὑρκανίαν. ἦγεν δὲ καὶ εἰς τὴν πόλιν τῶν Ἱεροσολυμιτῶν ὑπαντῶντός τε τοῦ δήμου παντὸς ἐν ἑορτώδει στολῇ καὶ δεχομένου τὸν ἄνδρα σὺν εὐφημίαις. Ἀγρίππας δὲ τῷ θεῷ μὲν ἑκατόμβην κατέθυσεν, ἑστιᾷ δὲ τὸν δῆμον οὐδενὸς τῶν μεγίστων πλήθει λειπόμενον. αὐτὸς δὲ ὅσον ἐπὶ τῷ καθ’ ἡδονὴν κἂν ἔτι πλείους ἐπιμείνας ἡμέρας διὰ τὸν καιρὸν ἠπείγετο· τὸν γὰρ πλοῦν ἐπιβαίνοντος τοῦ χειμῶνος οὐκ ἐνόμιζεν ἀσφαλῆ κομιζομένῳ πάλιν ἐξ ἀνάγκης εἰς τὴν Ἰωνίαν.", "st": "16.2.1"}, {"sp": "N", "t": "Ἐκεῖνος μὲν οὖν ἀπέπλει πολλαῖς αὐτὸν δωρεαῖς τετιμηκότος Ἡρώδου καὶ τῶν σὺν αὐτῷ τοὺς ἐπισημοτάτους. ὁ δὲ βασιλεὺς χειμάσας ἐν τοῖς οἰκείοις ἔαρος ἠπείγετο συντυχεῖν αὐτῷ τὴν εἰς Βόσπορον εἰδὼς στρατείαν προηγούμενον. καὶ πλεύσας διὰ Ῥόδου καὶ Κῶ προσέσχεν, περὶ Λέσβον οἰόμενος ἐπικαταλήψεσθαι τὸν Ἀγρίππαν. ἐκεῖ δ’ αὐτὸν ἀπολαμβάνει πνεῦμα βόρειον εἶργον τὴν ἀναγωγὴν τῶν νεῶν. ὁ δ’ ἐπιδιέτριβεν ἡμέρας πλείους ἐν τῇ Χίῳ καὶ πολλοὺς μὲν τῶν προσιόντων αὐτῷ δεξιούμενος ἀνελάμβανεν βασιλικαῖς δωρεαῖς, αὐτῆς δὲ τῆς πόλεως ἰδὼν πεπτωκυῖαν στοάν, ἣν ἐν τῷ Μιθριδατικῷ πολέμῳ καθαιρεθεῖσαν οὐχ ὥσπερ τὰ ἄλλα διὰ μέγεθος καὶ κάλλος ἀναστῆναι ῥᾴδιον ἦν, χρήματα δοὺς ὅσα μὴ μόνον ἐπαρκεῖν, ἀλλὰ καὶ περιττεύειν ἐδύνατο πρὸς τὴν συντέλειαν τοῦ κατασκευάσματος, ἐνετέλλετο μὴ περιορᾶν, ἀλλὰ θᾶττον ἐγείρειν ἀποκαθιστάντας τῇ πόλει τὸν ἴδιον κόσμον. αὐτὸς δὲ λήξαντος τοῦ πνεύματος εἰς Μιτυλήνην κἀκεῖθεν εἰς Βυζάντιον παρακομισθείς, ὡς ἤκουσεν ἐντὸς Κυανέων ἤδη πεπλευκέναι τὸν Ἀγρίππαν, μετέσπευδεν ὡς ἐνῆν. καὶ περὶ Σινώπην τὴν ἐν Πόντῳ καταλαβὼν ἀπροσδόκητος μὲν ὤφθη ταῖς ναυσὶ προσπλέων, ἄσμενος δὲ ἐφάνη πολλαί τε φιλοφρονήσεις ἦσαν, ἅτε καὶ μεγίστην πίστιν εἰληφέναι δοκοῦντος εὐνοίας καὶ φιλοστοργίας τῆς εἰς αὐτὸν Ἀγρίππου, τοσοῦτον μὲν πλοῦν ἀνύσαντος τοῦ βασιλέως, οὐκ ἀπολειφθέντος δὲ τῆς ἐκείνου χρείας, ἣν μετὰ τοῦ καταλιπεῖν ἀρχὴν καὶ διοίκησιν οἰκείων πραγμάτων προυργιαιτέραν ἔθετο. πᾶν γοῦν ἦν αὐτῷ κατὰ τὴν στρατείαν Ἡρώδης, ἔν τε τοῖς πραγματικοῖς συναγωνιστὴς κἀν τοῖς κατὰ μέρος σύμβουλος, ἡδὺς δὲ κἀν ταῖς ἀνέσεσι καὶ μόνος ἁπάντων κοινωνὸς ὀχληρῶν μὲν διὰ τὴν εὔνοιαν, ἡδέων δὲ διὰ τὴν τιμήν. ὡς δ’ αὐτοῖς κατείργαστο καὶ τὰ περὶ τὸν Πόντον, ὧν ἕνεκεν Ἀγρίππας ἐστάλη, τὴν ἀνακομιδὴν οὐκέτ’ ἐδόκει ποιεῖσθαι πλέουσιν, ἀλλὰ διαμειψάμενοι τήν τε Παφλαγονίαν καὶ Καππαδοκίαν κἀκεῖθεν ἐπὶ τῆς μεγάλης Φρυγίας ὁδεύσαντες εἰς Ἔφεσον ἀφίκοντο, πάλιν δὲ ἐξ Ἐφέσου διέπλευσαν εἰς Σάμον. πολλαὶ μὲν οὖν καὶ κατὰ πόλιν ἑκάστην εὐεργεσίαι τῷ βασιλεῖ κατὰ τὰς χρείας τῶν ἐντυγχανόντων ἐγένοντο· καὶ γὰρ αὐτὸς ὅσα διὰ χρημάτων ἦν ηπίξεως οὐ παρέλειπεν ἐξ αὐτοῦ τὰς δαπάνας ποιούμενος καὶ τῶν παρὰ Ἀγρίππα τισὶν ἐπιζητουμένων μεσίτης ἦν καὶ διεπράττετο μηδενὸς ἀτυχῆσαι τοὺς δεομένους. ὄντος δὲ κἀκείνου χρηστοῦ καὶ μεγαλοψύχου πρὸς τὸ παρέχειν ὅσα τοῖς ἠξιωκόσιν ὠφέλιμα ὄντα μηδένα τῶν ἄλλων ἐλύπει, πλεῖστον ἡ τοῦ βασιλέως ἐποίει ῥοπὴ προτρέπουσα πρὸς τὰς εὐεργεσίας οὐ βραδύνοντα τὸν Ἀγρίππαν. Ἰλιεῦσι μέν γε αὐτὸν διήλλαξεν, διέλυσεν δὲ Χίοις τὰ πρὸς τοὺς Καίσαρος ἐπιτρόπους χρήματα καὶ τῶν εἰσφορῶν ἀπήλλαξεν, τοῖς δὲ ἄλλοις καθὸ δεηθεῖεν ἕκαστοι παρίστατο.", "st": "16.2.2"}, {"sp": "N", "t": "Τότε δὲ περὶ τὴν Ἰωνίαν αὐτῶν γενομένων πολὺ πλῆθος Ἰουδαίων, ὃ τὰς πόλεις ᾤκει, προσῄει καιροῦ καὶ παρρησίας ἐπειλημμένοι, καὶ τὰς ἐπηρείας ἔλεγον, ἃς ἐπηρεάζοντο μήτε νόμοις οἰκείοις ἐώμενοι χρῆσθαι δίκας τε ἀναγκαζόμενοι διδόναι κατ’ ἐπήρειαν τῶν εὐθυνόντων ἐν ἱεραῖς ἡμέραις, καὶ τῶν εἰς Ἱεροσόλυμα χρημάτων ἀνατιθεμένων ἀφαιροῖντο στρατειῶν καὶ λειτουργιῶν ἀναγκαζόμενοι κοινωνεῖν καὶ πρὸς ταῦτα δαπανᾶν τῶν ἱερῶν χρημάτων, ὧν ἀφείθησαν αἰεὶ Ῥωμαίων αὐτοῖς ἐπιτρεψάντων κατὰ τοὺς οἰκείους ζῆν νόμους. τοιαῦτα καταβοώντων παρεστήσατο μὲν ὁ βασιλεὺς ἀκοῦσαι τὸν Ἀγρίππαν αὐτῶν δικαιολογουμένων, Νικόλαον δέ τινα τῶν αὐτοῦ φίλων ἔδωκεν εἰπεῖν ὑπὲρ αὐτῶν τὰ δίκαια. τοῦ δὲ Ἀγρίππου Ῥωμαίων τε τοὺς ἐν τέλει καὶ βασιλέων καὶ δυναστῶν τοὺς παρόντας αὐτῷ συνέδρους ποιησαμένου καταστὰς ὁ Νικόλαος ὑπὲρ τῶν Ἰουδαίων ἔλεξεν·", "st": "16.2.3"}, {"sp": "N", "t": "Ἅπασι μὲν, ὦ μέγιστε Ἀγρίππα, τοῖς ἐν χρείᾳ γεγενημένοις ἀνάγκη καταφεύγειν ἐπὶ τοὺς ἀφελέσθαι τὰς ἐπηρείας αὐτῶν δυνησομένους, τοῖς δὲ νῦν ἐντυγχάνουσιν καὶ παρρησία· τυχόντες γὰρ πρότερον ὑμῶν οἵους ηὔξαντο πολλάκις, τὸ μὴ τὰς χάριτας ἀφαιρεῖσθαι δι’ ὑμῶν αἰτοῦνται τῶν δεδωκότων, καὶ ταῦτα εἰληφότες μὲν αὐτὰς παρὰ τούτων, οἷς μόνοις διδόναι δύναμις, ἀφαιρούμενοι δ’ ὑπ’ οὐδενὸς κρείττονος, ἀλλ’ οὓς ἴσον ἔχειν αὐτοῖς ἀρχομένους ὁμοίως ὑμῶν ἴσασιν. καίτοι γε εἴτε μεγάλων ἠξιώθησαν, ἔπαινός ἐστιν τῶν τετυχηκότων ὅτι τοσούτων παρέσχον αὑτοὺς ἀξίους, εἴτε μικρῶν, αἰσχρὸν μὴ καὶ ταῦτα βεβαιοῦν δεδωκότας. οἵ γε μὴν ἐμποδὼν ὄντες καὶ πρὸς ἐπήρειαν χρώμενοι Ἰουδαίοις εὔδηλον ὡς ἄμφω ἀδικοῦσιν, τοὺς εἰληφότας, εἰ μὴ νομίζοιεν ἀγαθοὺς οἷς οἱ κρατοῦντες ἐμαρτύρησαν ἐν τῷ καὶ τοιαῦτα δεδωκέναι, καὶ τοὺς δεδωκότας, εἰ τὰς χάριτας αὐτῶν ἀβεβαίους ἀξιοῦσιν γενέσθαι. εἰ δέ τις αὐτοὺς ἔροιτο δύο τούτων θάτερον ἐθέλοιεν ἂν ἀφαιρεθῆναι, τὸ ζῆν ἢ τὰ πάτρια ἔθη τὰς πομπὰς τὰς θυσίας τὰς ἑορτάς, ἃς τοῖς νομιζομένοις προσάγουσι θεοῖς, εὖ οἶδ’, ὅτι πάντα μᾶλλον αἱρήσονται παθεῖν ἢ καταλῦσαί τι τῶν πατρίων· καὶ γὰρ τοὺς πολέμους οἱ πολλοὶ διὰ ταῦτα αἱροῦνται φυλαττόμενοι μὴ παραβαίνειν αὐτά, καὶ τὴν εὐδαιμονίαν, ἣν νῦν τὸ σύμπαν τῶν ἀνθρώπων γένος δι’ ὑμᾶς ἔχει, τούτῳ μετροῦμεν τῷ ἐξεῖναι κατὰ χώραν ἑκάστοις τὰ οἰκεῖα τιμῶσιν αὔξειν καὶ διαζῆν. τοῦτο μὲν οὖν οὐκ ἂν αὐτοὶ παθεῖν ἑλόμενοι βιάζονται δρᾶν κατ’ ἄλλων ὥσπερ οὐχ ὁμοίως ἀσεβοῦντες, εἴτε τῶν οἰκείων εἰς θεοὺς ὁσίων ἀμελοῖεν, εἴτε τὰ οἰκεῖα τισὶν ἀνοσίως καταλύοιεν. τόδ’ ἕτερον δ’ ἤδη σκοπήσομεν· ἔστι τις δῆμος ἢ πόλις ἢ κοινὸν ἔθνος ἀνθρώπων, οἷς οὐ μέγιστον ἀγαθῶν πέφυκε προστασία τῆς ὑμετέρας ἀρχῆς καὶ τὸ Ῥωμαϊκὸν κράτος; ἐθέλοι δ’ ἄν τις ἀκύρους τὰς ἐντεῦθεν εἶναι χάριτας; οὐδεὶς οὐδὲ μαινόμενος· οὐδὲ γὰρ εἰσὶν οἱ μὴ μετέχοντες αὐτῶν ἰδίᾳ καὶ κοινῇ. καὶ μὴν οἱ τινὰς ὧν ὑμεῖς ἔδοτε παραιρούμενοι βέβαιον οὐδ’ αὐτοῖς οὐδὲν ὧν δι’ ὑμᾶς ἔχουσιν ὑπολείπονται. καίτοι τὰς μὲν τούτων χάριτας οὐδὲ μετρῆσαι δυνατόν ἐστιν· εἰ γὰρ ἐκλογίσαιντο τὴν πάλαι βασιλείαν καὶ τὴν νῦν ἀρχήν, πολλῶν ὄντων ὅσα πρὸς εὐδαιμονίαν αὐτοῖς ἐπέδωκεν, ἔτι κατὰ πάντων ἀρκεῖ τὸ μηκέτι δούλους ἀλλ’ ἐλευθέρους φαίνεσθαι. τὰ δ’ ἡμέτερα καὶ λαμπρῶς πραττόντων οὐκ ἔστιν ἐπίφθονα· δι’ ὑμᾶς γὰρ καὶ μετὰ πάντων εὐτυχοῦμεν καὶ τούτου μόνου μετέχειν ἠξιώσαμεν, ἀκωλύτως τὴν πάτριον εὐσέβειαν διαφυλάττειν, ὃ καὶ καθ’ αὑτὸ δόξειεν οὐκ ἐπίφθονον καὶ πρὸς τῶν συγχωρούντων εἶναι· τὸ γὰρ θεῖον, εἰ χαίρει τιμώμενον, χαίρει τοῖς ἐπιτρέπουσι τιμᾶν, ἐθῶν τε τῶν ἡμετέρων ἀπάνθρωπον μὲν οὐδέν ἐστιν, εὐσεβῆ δὲ πάντα καὶ τῇ συνήθει δικαιοσύνῃ συγκαθωσιωμένα. καὶ οὔτε ἀποκρυπτόμεθα τὰ παραγγέλματα, οἷς χρώμεθα πρὸς τὸν βίον ὑπομνήμασιν τῆς εὐσεβείας καὶ τῶν ἀνθρωπίνων ἐπιτηδευμάτων, τήν τε ἑβδόμην τῶν ἡμερῶν ἀνίεμεν τῇ μαθήσει τῶν ἡμετέρων ἐθῶν καὶ νόμου, μελέτην ὥσπερ ἄλλου τινὸς καὶ τούτων ἀξιοῦντες εἶναι δι’ ὧν οὐχ ἁμαρτησόμεθα. καλὰ μὲν οὖν, ἐὰν ἐξετάζῃ τις καὶ καθ’ αὑτὰ τὰ ἔθη, παλαιὰ δ’ ἡμῖν, κἂν μή τισιν δοκῇ, ὥστ’ αὐτῶν καὶ τὸ τοῦ χρόνου τιμητὸν δυσαποδίδακτον εἶναι τοῖς ὁσίως παρειληφόσιν καὶ διαφυλάττουσιν. τούτων ἡμᾶς ἀφαιροῦνται κατ’ ἐπήρειαν, χρήματα μὲν ἃ τῷ θεῷ συμφέρομεν ἐπώνυμα διαφθείροντες καὶ φανερῶς ἱεροσυλοῦντες, τέλη δ’ ἐπιτιθέντες κἀν ταῖς ἑορταῖς ἄγοντες ἐπὶ δικαστήρια καὶ πραγματείας ἄλλας, οὐ κατὰ χρείαν τῶν συναλλαγμάτων, ἀλλὰ κατ’ ἐπήρειαν τῆς θρησκείας, ἣν συνίσασιν ἡμῖν, μῖσος οὐ δίκαιον οὐδ’ αὐτεξούσιον αὐτοῖς πεπονθότες. ἡ γὰρ ὑμετέρα κατὰ πάντων ἀρχὴ γενομένη μία τὴν μὲν εὔνοιαν ἐνεργὸν τὴν δὲ δύσνοιαν ἄνεργον ποιεῖ τοῖς τὸ τοιοῦτον ἀντ’ ἐκείνου προαιρουμένοις. ταῦτ’ οὖν ἀξιοῦμεν, ὦ μέγιστε Ἀγρίππα, μὴ κακῶς πάσχειν μηδ’ ἐπηρεάζεσθαι μηδὲ κωλύεσθαι τοῖς ἔθεσι χρῆσθαι τοῖς ἡμετέροις μηδ’ ἀφαιρεῖσθαι τῶν ὄντων μηδ’ ἃ μὴ βιαζόμεθα τούτους ὑπὸ τούτων βιάζεσθαι· καὶ γὰρ οὐ δίκαια μόνον ἐστίν, ἀλλὰ καὶ ὑφ’ ὑμῶν δεδομένα πρότερον. ἔτι καὶ δυναίμεθ’ ἂν πολλὰ δόγματα τῆς συγκλήτου καὶ τὰς ἐν τῷ Καπετωλίῳ κειμένας δέλτους ὑπὲρ τούτων ἀναγινώσκειν, ἃ δῆλον μὲν ὡς μετὰ πεῖραν τῆς ἡμετέρας εἰς ὑμᾶς πίστεως ἐδόθη, κύρια δὲ κἂν εἰ μηδενὸς ὕπαρξιν ἐχαρίσασθε. σχεδὸν γὰρ οὐ μόνοις ἡμῖν ἀλλὰ πᾶσιν ἀνθρώποις τὰ μὲν ὄντα φυλάξαντες, μείζω δὲ τῶν ἐλπισθέντων προσθέντες εὐεργετεῖτε τῷ κρατεῖν, καὶ δύναιτ’ ἄν τις ἐπεξιὼν τὰς ἑκάστων εὐτυχίας, ἃς δι’ ὑμῶν ἔχουσιν, ἀπερίληπτον ποιῆσαι τὸν λόγον. ἵνα μέντοι καὶ δικαίως ἁπάντων αὐτῶν τυγχάνοντας ἑαυτοὺς ἐπιδείξωμεν, ἀρκεῖ πρὸς παρρησίαν ἡμῖν τὰ πρότερον σιωπήσασιν τὸν βασιλεύοντα νῦν ἡμῶν καὶ σοὶ παρακαθεζόμενον εἰπεῖν. ᾧ ποία μὲν εὔνοια πρὸς τὸν ὑμέτερον οἶκον παραλέλειπται; ποία δὲ πίστις ἐνδεής ἐστιν; τίς δὲ οὐ νενόηται τιμή; ποία δὲ χρεία μὴ εἰς πρῶτον ὁρᾷ; τί δὴ κωλύει καὶ τὰς ἡμετέρας χάριτας τῶν εἰς τοσούτων εὐεργεσιῶν ἀριθμὸν εἶναι; καλὸν δ’ ἴσως μηδὲ τὴν τοῦ πατρὸς Ἀντιπάτρου παραλιπεῖν ἀνδραγαθίαν ἀμνημόνευτον, ὃς εἰς Αἴγυπτον εἰσβεβληκότος Καίσαρος δισχιλίοις ὁπλίταις βοηθήσας οὔτ’ ἐν τοῖς κατὰ γῆν ἀγῶσιν οὔθ’ ὅτε νεῶν ἔδει δεύτερος ἐξητάζετο. καὶ τί δεῖ λέγειν, ὅσην ἐκεῖνοι παρέσχον ῥοπὴν τῷ τότε καιρῷ καὶ πόσων καὶ τίνων δωρεῶν ὑπὸ Καίσαρος ἠξιώθησαν καθ’ ἕνα, δέον ἀναμνῆσαι τῶν ἐπιστολῶν, ἃς ἔγραψεν τότε Καῖσαρ τῇ συγκλήτῳ, καὶ ὡς δημοσίᾳ τιμὰς καὶ πολιτείαν ἔλαβεν Ἀντίπατρος; ἀρκέσει γὰρ ταῦτα τὰ τεκμήρια τοῦ καὶ τὰς χάριτας ἡμᾶς κατ’ ἀξίαν ἔχειν καὶ παρὰ σοῦ τὸ βέβαιον αὐτῶν αἰτεῖν, παρ’ οὗ καὶ μὴ πρότερον δοθείσας ἦν ἐλπίσαι τὴν τοῦ βασιλέως πρὸς ὑμᾶς διάθεσιν καὶ τὴν ὑμετέραν πρὸς αὐτὸν ὁρῶσιν. ἀπαγγέλλεται δ’ ἡμῖν ὑπὸ τῶν ἐκεῖ Ἰουδαίων, ὡς μὲν ἐπέβης τῆς χώρας εὐμενής, ὡς δὲ ἀπέδωκας τῷ θεῷ τέλεια θύματα τιμῶν αὐτὸν ἐπὶ τελείαις εὐχαῖς, ὡς δὲ τὸν δῆμον εἱστίασας καὶ τὰ παρ’ ἐκείνου ξένια προσήκω. ταῦτα γὰρ πάντα καὶ ἔθνει καὶ πόλει πρὸς ἄνδρα τοσούτων ἐπιστατοῦντα πραγμάτων δεξιώματα καὶ σύμβολα φιλίας χρὴ δοκεῖν, ἣν ἀπέδωκας τῷ Ἰουδαίων ἔθνει τῆς Ἡρώδου προξενούσης αὐτὴν ἑστίας. τούτων ὑπομιμνήσκοντές σε καὶ αὐτοῦ τοῦ παρόντος καὶ συγκαθεζομένου βασιλέως ἠξιώκαμεν περιττὸν οὐδέν, ἃ δ’ αὐτοὶ δεδώκατε ταῦθ’ ὑπ’ ἄλλων μὴ περιιδεῖν ἀφαιρουμένους.", "st": "16.2.4"}, {"sp": "N", "t": "Τοιαῦτα μὲν τοῦ Νικολάου διελθόντος ἐγένετο οὐδεμία τῶν Ἑλλήνων ἀντικατάστασις· οὐδὲ γὰρ ὡς ἐν δικαστηρίῳ περὶ τῶν προκειμένων διελάμβανον, ἀλλ’ ἦν ἔντευξις ὧν ἐβιάζοντο. κἀκείνων ἀπολογία μὲν οὐδεμία τοῦ μὴ ταῦτα ποιεῖν, πρόφασις δέ, ὡς τὴν χώραν αὐτῶν νεμόμενοι πάντα νῦν ἀδικοῖεν. οἱ δὲ ἐγγενεῖς τε αὑτοὺς ἐδείκνυσαν κἀν τῷ τὰ οἰκεῖα τιμᾶν μηδὲν λυποῦντες οἰκεῖν. συνιδὼν οὖν Ἀγρίππας βιαζομένους ἀπεκρίνατο ταῦτα· διὰ μὲν τὴν Ἡρώδου πρὸς αὐτὸν εὔνοιάν τε καὶ φιλίαν ἕτοιμος εἶναι πᾶν ὁτιοῦν χαρίζεσθαι Ἰουδαίοις, ἃ δὲ ἀξιοῦσιν καὶ καθ’ αὑτὰ δίκαια δοκεῖν· ὥστ’, εἰ μὲν ἐδέοντο καὶ πλειόνων, οὐκ ἂν ὀκνῆσαι τά γε μὴ λυποῦντα τὴν Ῥωμαίων ἀρχὴν παρασχεῖν. ἐπεὶ δὲ ἃ καὶ πρότερον εἰλήφασιν ἄκυρα μὴ γενέσθαι, βεβαιοῦν αὐτοῖς ἀνεπηρεάστοις ἐν τοῖς οἰκείοις διατελεῖν ἔθεσιν. τοιαῦτα εἰπὼν διέλυε τὸν σύλλογον. Ἡρώδης δὲ προσεστὼς κατησπάζετο καὶ τῆς εἰς αὐτὸν διαθέσεως ὡμολόγει χάριν. ὁ δὲ καὶ εἰς ταῦτα φιλοφρονούμενος ἴσον αὑτὸν παρεῖχεν ἀντεμπλεκόμενος καὶ κατασπαζόμενος. καὶ τότε μὲν ἀνεχώρησεν· ἀπὸ δὲ Σάμου πλεῖν ὁ βασιλεὺς ἐπ’ οἴκου διέγνω καὶ τὸν Ἀγρίππαν παραιτησάμενος ἀνήχθη, κατάγεται δ’ εἰς Καισάρειαν οὐ πολλαῖς ὕστερον ἡμέραις πνευμάτων ἐπιτηδείων τυχών. κἀκεῖθεν ἐλθὼν εἰς Ἱεροσόλυμα συνήγαγεν ἐκκλησίαν πάνδημον· ἦν δὲ πολὺς κἀκ τῆς χώρας ὄχλος. ὁ δὲ παρελθὼν ἀπολογισμόν τε τῆς ὅλης ἐκδημίας ἐποιήσατο καὶ τὰ περὶ τοὺς Ἰουδαίους, ὅσοι κατὰ τὴν Ἀσίαν ἦσαν, ὡς δι’ αὐτὸν ἀνεπηρεάστως εἰς τὸ λοιπὸν ἕξουσιν διηγήσατο. τό τε σύμπαν ἐπὶ ταῖς εὐτυχίαις καὶ τῇ διοικήσει τῆς ἀρχῆς [ὡς] οὐδενὸς παραλείποιτο τῶν ἐκείνοις συμφερόντων, ἀγαλλόμενος τὸ τέταρτον τῶν φόρων ἀφίησιν αὐτοῖς τοῦ παρεληλυθότος ἔτους. οἱ δὲ καὶ τῷ λόγῳ καὶ τῇ χάριτι δεδημαγωγημένοι μετὰ πλείστης χαρᾶς ἀπῄεσαν πολλὰ ἀγαθὰ συνευχόμενοι τῷ βασιλεῖ.", "st": "16.2.5"}, {"sp": "N", "t": "Προύβαινε δ’ ἀεὶ τὰ κατὰ τὴν στάσιν τῆς οἰκίας καὶ χαλεπωτέραν ἐλάμβανε τὴν ἐπίδοσιν, ἀντιμεταλαβούσης μὲν ὥσπερ ἐκ κληρονομίας τὸ κατὰ τῶν νεανίσκων μῖσος τῆς Σαλώμης καὶ πᾶν ὅσον εὐδοκιμήκει κατὰ τῆς μητρὸς αὐτῶν εἰς ἀπόνοιαν καὶ θράσος λαμβανούσης μηδένα τῶν ἐξ ἐκείνης καταλιπεῖν, ὃς δυνήσεται τιμωρῆσαι τῷ θανάτῳ τῆς δι’ αὐτὴν ἀνῃρημένης, ἐχόντων δέ τι καὶ τῶν νεανίσκων θρασὺ καὶ δύσνουν εἰς τὸν γεγεννηκότα μνήμῃ τε τῆς μητρὸς οἷα πάθοι παρὰ τὴν ἀξίαν καὶ τῇ τοῦ κρατεῖν ἐπιθυμίᾳ. πάλιν τε τὸ κακὸν ὅμοιον ἐγεγόνει τοῖς πρώτοις, βλασφημίαι μὲν ἐξ ἐκείνων εἴς τε τὴν Σαλώμην καὶ τὸν Φερώραν, κακοήθειαι δὲ τούτων εἰς τὰ μειράκια καὶ μετὰ πραγματείας ἐπιβουλή· τὸ μὲν γὰρ μῖσος ἴσον ἦν ἐξ ἀλλήλων, ὁ δὲ τρόπος τοῦ μισεῖν οὐχ ὅμοιος· ἀλλ’ οἱ μὲν ἐν τῷ φανερῷ λοιδορηθῆναι καὶ προσονειδίσαι προπετεῖς εὐγενὲς ὑπὸ τῆς ἀπειρίας οἰόμενοι τὸ τῆς ὀργῆς ἀνυπόστολον, οἱ δ’ οὐ τὸν αὐτὸν τρόπον, ἀλλὰ πραγματικῶς καὶ κακοήθως ἐχρῶντο ταῖς διαβολαῖς, προέλκοντες ἀεὶ τὰ μειράκια καὶ τὸ θρασὺ καταλογιζόμενοι βίαιον ἔσεσθαι πρὸς τὸν γεγεννηκότα. τὸ γὰρ οὐκ αἰδεῖσθαι ταῖς τῆς μητρὸς ἁμαρτίαις οὐδ’ οἴεσθαι δίκαια παθεῖν ἐκείνην ἄσχετον εἶναι πρὸς τὸ μὴ τὸν αἴτιον δοκοῦντα τιμωρήσεσθαι καὶ δι’ αὐτοχειρίας. τέλος οὖν ἀνεπλήσθη πᾶσα ἡ πόλις τῶν τοιούτων λόγων καὶ καθάπερ ἐν τοῖς ἀγωνίσμασιν ἠλεεῖτο μὲν ἡ τῶν μειρακίων ἀπειρία, κατίσχυεν δὲ ἡ τῆς Σαλώμης ἐπιμέλεια καὶ παρ’ αὐτῶν ἐκείνων τὰς ἀφορμὰς τοῦ μὴ ψευδῆ λέγειν ἐλάμβανεν. οἱ γὰρ οὕτως ἀχθόμενοι τῷ θανάτῳ τῆς μητρός, ἐπειδὴ κἀκείνην καὶ σφᾶς αὐτοὺς κακῶς ἔλεγεν, ἐφιλονείκουν ἐλεεινὴν μέν, ὥσπερ ἦν, ἀποφαίνειν τὴν καταστροφὴν τῆς μητρός, ἐλεεινοὺς δὲ αὐτούς, οἳ τοῖς ἐκείνης φονεῦσιν ἀναγκάζονται συζῆν καὶ τῶν αὐτῶν μεταλαμβάνειν.", "st": "16.3.1"}, {"sp": "N", "t": "Ταῦτα προῄει μειζόνως καιρὸν ἐχούσης τῆς στάσεως ἐν ἀποδημίᾳ τοῦ βασιλέως. ὡς δ’ ἐπανῆλθεν Ἡρώδης καὶ τῷ πλήθει διελέξατο, καθὼς προειρήκαμεν, προσέπιπτον εὐθὺς οἱ λόγοι παρά τε τοῦ Φερώρα καὶ τῆς Σαλώμης μέγαν αὐτῷ τὸν κίνδυνον εἶναι τὸν παρὰ τῶν νεανίσκων ἀνάφανδα διαπειλουμένων, ὡς οὐκ ἀνέξονται μὴ τισάμενοι τῆς μητρὸς τὸν φόνον. προσετίθεσαν δ’ ἔτι καὶ ὡς ταῖς παρ’ Ἀρχελάου τοῦ Καππάδοκος ἐλπίσιν ἐπανέχοιεν, ὡς δι’ ἐκείνου πρός τε Καίσαρα ἀφιξόμενοι καὶ κατηγορήσοντες τοῦ πατρός. Ἡρώδης δὲ ἐτετάρακτο μὲν εὐθὺς ἀκούσας τοιούτων, ἐξεπέπληκτο δὲ μᾶλλον, ὅτι καὶ τῶν ἄλλων τινὲς ἀπήγγελλον, ἀνέκαμπτε τῇ συμφορᾷ τά τε πρῶτα καταλογιζόμενος ὡς οὔτε τῶν φιλτάτων οὔτε τῆς στεργομένης αὐτῷ γυναικὸς ὤνατο διὰ τὰς ἐγγινομένας ταραχὰς κατὰ τὴν οἰκίαν, τό τε μᾶλλον τοῦ προσπεπτωκότος ἤδη βαρὺ καὶ μεῖζον ἐκείνων ὑπολαμβάνων ἐν συγχύσει τῆς ψυχῆς ἦν. τῷ γὰρ ὄντι πλεῖστα μὲν καὶ παρ’ ἐλπίδας τῶν ἔξωθεν εἰς εὐτυχίαν αὐτῷ τὸ δαιμόνιον προσετίθει, μέγιστα δὲ τῶν οἴκοι καὶ μηδὲ προσδοκώμενα δυστυχεῖν αὐτῷ συνέβαινεν, ἑκατέρου προϊόντος ὡς οὐκ ἄν τις ᾠήθη καὶ παρέχοντος ἀμφήριστον τὴν ὑπερβολήν, εἰ δέον τὴν τοσαύτην εὐτυχίαν τῶν ἔξωθεν πραγμάτων ἀλλάξασθαι τῶν οἴκοι κακῶν, ἢ τοιοῦτο μέγεθος τῶν περὶ τοὺς οἰκείους συμφορῶν διαφυγεῖν ἐν τῷ μηδὲ τὰ τῆς βασιλείας θαυμαζόμενα κεκτῆσθαι.", "st": "16.3.2"}, {"sp": "N", "t": "Ταρασσόμενος δὲ καὶ διακείμενος τὸν τρόπον τοῦτον ἐπὶ καθαιρέσει τῶν μειρακίων ἕτερον αὐτῷ γενόμενον ἰδιωτεύοντι παῖδα προσήγετο καὶ τοῦτον ἐδόκει τιμᾶν, ἐκαλεῖτο δὲ Ἀντίπατρος, οὐχ ὥσπερ ἐν ὑστέρῳ καὶ τελέως ἡττηθεὶς αὐτοῦ καὶ πάντ’ εἰς ἐκεῖνον ἀναφέρων, οἰόμενος δὲ παραιρήσεσθαι τοῦ θράσους τοὺς ἐκ Μαριάμμης καὶ μᾶλλον εἰς νουθεσίαν τὴν ἐκείνων οἰκονομῶν αὐτό. τὸ γὰρ αὔθαδες οὐκ ἂν [εἴη] παρ’ αὐτοῖς, εἰ τοῦτο πεισθεῖεν, ὅτι μὴ μόνοις μηδ’ ἐξ ἀνάγκης ἡ διαδοχὴ τῆς βασιλείας ὀφείλεται. διὸ καὶ καθάπερ ἔφεδρόν τινα τὸν Ἀντίπατρον εἰσῆγεν οἰόμενος ὀρθῶς προνοεῖν καὶ κατασταλέντων τῶν μειρακίων ἐξεῖναι εὐκαίρως χρῆσθαι βελτίοσιν. τὸ δ’ οὐχ ὥσπερ ἐνόησεν ἀπέβη· τοῖς τε γὰρ παισὶν οὐ μετρίως ἐδόκει κεχρῆσθαι τῇ πρὸς αὐτοὺς ἐπηρείᾳ, καὶ δεινὸς ὢν τὸν τρόπον Ἀντίπατρος, ἐπειδὴ παρρησίας τινὸς τῆς οὐ πρότερον οὔσης ἐλπίδος ἀντεποιήσατο, μίαν ἔσχεν ὑπόθεσιν κακοῦ τοὺς ἀδελφοὺς μὴ παραχωρεῖν τῶν πρωτείων, ἀλλ’ ἔχεσθαι τοῦ πατρός, ἤδη μὲν ἠλλοτριωμένου ταῖς διαβολαῖς, εὐμεταχειρίστου δ’ ὄντος εἰς ὅπερ ἐσπουδάκει, πολὺ χαλεπώτερον ἀεὶ γενέσθαι τοῖς διαβεβλημένοις. ἦσαν οὖν οὐ παρ’ αὐτοῦ μόνου οἱ λόγοι φυλαττομένου δι’ αὑτοῦ δόξαι τὰ τοιαῦτα καταμηνύειν, ἀλλὰ μᾶλλον ἐχρῆτο συνεργοῖς τοῖς ἀνυπόπτοις καὶ διὰ τὴν εὔνοιαν τὴν πρὸς τὸν βασιλέα πιστευθησομένοις αὐτὸ ποιεῖν. ἤδη δὲ πλείους ἐγεγόνεισαν οἱ κἀκεῖνον ἐφ’ οἷς ἠλπίκει θεραπεύοντες καὶ τὸν Ἡρώδην ἐκ τοῦ δοκεῖν κατ’ εὔνοιαν τὰ τοιαῦτα λέγειν ὑπαγόμενοι. καὶ τούτων πολυπροσώπως καὶ πιστῶς ἀλλήλοις συναγωνιζομένων ἔτι καὶ μᾶλλον αἱ παρὰ τῶν μειρακίων ἀφορμαὶ προσεγίνοντο· καὶ γὰρ καὶ δάκρυα πολλάκις ἦν κατ’ ἐπήρειαν ὧν ἠτιμάζοντο καὶ τῆς μητρὸς ἀνάκλησις καὶ τὸν πατέρα φανερῶς ἤδη πρὸς τοὺς φίλους οὐ δίκαιον ἐλέγχειν ἐπετήδευον, ἅπερ ἅπαντα κακοήθως ὑπὸ τῶν περὶ τὸν Ἀντίπατρον καιροφυλακούμενα καὶ μειζόνως πρὸς τὸν Ἡρώδην ἐξαγγελλόμενα προύβαινεν οὐ μικρὰν ἀπεργαζόμενα τὴν τῆς οἰκίας στάσιν. ἀχθόμενος γὰρ ὁ βασιλεὺς ταῖς διαβολαῖς καὶ ταπεινῶσαι βουλόμενος τοὺς ἐκ τῆς Μαριάμμης μείζονα ἀεὶ πρὸς τιμὴν Ἀντιπάτρῳ παρεῖχεν, καὶ τέλος ἡττηθεὶς ἐπεισήγαγε μὲν τὴν ἐκείνου μητέρα, Καίσαρι δὲ πολλάκις γράφων ὑπὲρ αὐτοῦ καὶ ἰδίᾳ συνίστη σπουδαιότερον. Ἀγρίππου γε μὴν ἀνιόντος εἰς τὴν Ῥώμην μετὰ τὴν διοίκησιν τῶν ἐπὶ τῆς Ἀσίας δεκαετῆ γεγενημένην, πλεύσας ἀπὸ τῆς Ἰουδαίας καὶ συντυγχάνων μόνον τε τὸν Ἀντίπατρον ἐπήγετο καὶ παρέδωκεν εἰς Ῥώμην ἀνάγειν μετὰ πολλῶν δώρων Καίσαρι φίλον ἐσόμενον, ὥστε ἤδη πάντα δοκεῖν ἐπ’ ἐκείνῳ καὶ παρεῶσθαι παντάπασιν ἐκ τῆς ἀρχῆς τὰ μειράκια.", "st": "16.3.3"}, {"sp": "N", "t": "Πρὸς μὲν οὖν τιμὴν καὶ τὸ πρῶτον εἶναι δοκεῖν Ἀντιπάτρῳ προυχώρει τὰ κατὰ τὴν ἀποδημίαν· καὶ γὰρ ἐν τῇ Ῥώμῃ πᾶσιν ἐπεσταλκότος Ἡρώδου τοῖς φίλοις διάσημος ἦν· ἤχθετο δὲ τῷ μὴ παρεῖναι μηδὲ ἔχειν ἐξ εὐκαίρου διαβάλλειν ἀεὶ τοὺς ἀδελφούς, καὶ μᾶλλον ἐδεδοίκει μεταβολὴν τοῦ πατρός, εἴ τι καὶ καθ’ αὑτὸν ἀξιώσει ἐπιεικέστερον εἰς τοὺς ἐκ τῆς Μαριάμμης φρονεῖν. ταῦτα δὲ δι’ ἐννοίας ἔχων οὐκ ἀφίστατο τῆς ἑαυτοῦ προαιρέσεως, ἀλλὰ κἀκεῖθεν, ὅτε ἀνιάσειν τι καὶ παροξυνεῖν ἤλπιζεν τὸν πατέρα κατὰ τῶν ἀδελφῶν, συνεχῶς ἐπέστελλεν, πρόφασιν μὲν ὡς ὑπεραγωνιῶν αὐτοῦ, τὸ δὲ ἀληθὲς ἀφ’ ἧς εἶχεν [ἐν] φύσει κακοηθείας τὴν ἐλπίδα μεγάλην καὶ καθ’ ἑαυτὴν οὖσαν ἐμπορευόμενος, ἕως εἰς τοῦτο προήγαγεν τὸν Ἡρώδην ὀργῆς καὶ δυσφημίας, ὡς ἤδη μὲν ἔχων δυσμενῶς τοῖς μειρακίοις, ἐν δὲ κατοκνεῖν εἰς τοιοῦτον ἐμβῆναι πάθος, ὡς μήτ’ ἀμελῶν μήτ’ ἐκ προπετείας ἁμαρτάνοι, κρεῖττον ἡγήσατο πλεύσας εἰς Ῥώμην ἐκεῖ τῶν παίδων κατηγορεῖν παρὰ Καίσαρι, καὶ μηδὲν αὑτῷ τοιοῦτον ἐπιτρέπειν, ὃ καὶ διὰ μέγεθος τῆς ἀσεβείας ὕποπτον ἦν. ὡς δὲ ἀνῆλθεν εἰς τὴν Ῥώμην, ἐγένετο μὲν μέχρι τῆς Ἀκυληίας πόλεως Καίσαρι συντυχεῖν ἐπειγόμενος, ἐλθὼν δ’ εἰς λόγους καὶ καιρὸν αἰτησάμενος ἐπὶ μεγάλοις οἷς ἐδόκει δυστυχεῖν παρεστήσατο μὲν τοὺς παῖδας, ᾐτιᾶτο δὲ τῆς ἀπονοίας καὶ τῆς ἐπιχειρήσεως, ὡς ἐχθρῶς ἔχουσιν ἅπαντα τρόπον ἐσπουδακότες [μισεῖν] τὸν ἑαυτῶν πατέρα μεταχειρίσασθαι καὶ τὴν βασιλείαν ὠμοτάτῳ τρόπῳ παραλαβεῖν· ὁ δ’ οὐδὲ θνήσκων ἐξ ἀνάγκης μᾶλλον ἢ κρίσει παραδοῦναι τῷ διαμείναντι πρὸς αὐτὸν εὐσεβεστέρῳ παρὰ Καίσαρος ἐξουσίαν ἔχοι. τοῖς δ’ οὐχ ὑπὲρ τῆς ἀρχῆς τὸ πλέον, ἀλλ’ εἰ καὶ ταύτης στεροῖντο καὶ τοῦ ζῆν ἐλάττων λόγος, εἰ μόνον ἀποκτεῖναι τὸν πατέρα δυνηθεῖεν· οὕτως ἄγριόν τι καὶ μιαρὸν ἐντετηκέναι ταῖς ψυχαῖς αὐτῶν μῖσος. καὶ ταύτην τὴν ἀτυχίαν αὐτὸς ἐκ μακροῦ φέρων ἀναγκασθῆναι νῦν ἐξηγεῖσθαι Καίσαρι καὶ μιαίνειν αὐτοῦ τὰς ἀκοὰς τοιούτοις λόγοις. καίτοι τί μὲν εἴησαν παθόντες ἐξ αὐτοῦ δυσχερές; ἐπὶ τίνι δὲ μέμφονται βαρὺν ὄντα; πῶς δ’ οἷόν τε καὶ δίκαιον ἣν αὐτὸς ἐκτήσατο πολλοῖς πόνοις καὶ κινδύνοις ἀρχήν, ταύτης οὐκ ἐᾶν κύριον εἶναι κρατεῖν τε καὶ διδόναι τῷ κατ’ ἀξίαν; ὡς τοῦτό γε μετὰ τῶν ἄλλων ἆθλον εὐσεβείας ἐκτίθεται τῷ μέλλοντι πρὸς τὸν ποτὲ γενήσεσθαι τοιούτῳ τὴν ἐπιμέλειαν, ἅτε καὶ τῆς ἀμοιβῆς τοσῆσδε οὔσης ἐπιτυγχάνειν. ὅτι δὲ μηδὲ εὐσεβὲς αὐτοῖς ὑπὲρ τούτου πολυπραγμονεῖν, εὔδηλον· ὁ γὰρ ἀεί τι περὶ τῆς βασιλείας ἐνθυμούμενος συγκαταλογίζεται τὸν θάνατον τοῦ γεγεννηκότος, μεθ’ ὃν ἄλλως οὐκ ἔστιν τὴν ἀρχὴν παραλαβεῖν. αὐτὸς δ’ ὅσα βασιλευομένοις καὶ βασιλέως παισὶν οὐχ ὑστέρησεν μέχρι νῦν ἀποδιδούς, οὐ κόσμον, οὐχ ὑπηρεσίαν, οὐ τρυφήν, ἀλλὰ καὶ γάμους τοὺς ἐπισημοτάτους παρεσχῆσθαι, τῷ μὲν ἐκ τῆς ἀδελφῆς, Ἀλεξάνδρῳ δὲ τὴν Ἀρχελάου τοῦ βασιλέως θυγατέρα συνοικίσας, τὸ δὲ μέγιστον οὐδ’ ἐπὶ τοιούτοις ἣν εἶχεν ἐξουσίαν ταύτῃ κατ’ αὐτῶν χρησάμενος ἀγαγεῖν ἐπὶ τὸν κοινὸν εὐεργέτην Καίσαρα, καὶ παρελόμενον αὑτοῦ πᾶν, ὅσον ἢ πατὴρ ἀσεβούμενος ἢ βασιλεὺς ἐπιβουλευόμενος δύναται, κρίσεως ἰσοτιμίᾳ παρεστακέναι· δεήσει μέντοι μὴ παντάπασιν αὐτὸν ἀτιμώρητον γενέσθαι μηδ’ ἐν τοῖς μεγίστοις φόβοις καταζῆν, οὐδ’ ἐκείνοις λυσιτελοῦντος ἐφ’ οἷς ἐνεθυμήθησαν ὁρᾶν τὸν ἥλιον, εἰ νῦν διαφύγοιεν, ἔργῳ μέγιστα τῶν ἀνθρωπείων καὶ δράσαντας καὶ πεισομένους.", "st": "16.4.1"}, {"sp": "N", "t": "Ταῦτα μὲν Ἡρώδης ἐμπαθῶς ᾐτιάσατο παρὰ Καίσαρι τοὺς αὐτοῦ παῖδας. τῶν δὲ νεανίσκων ἤδη μὲν καὶ λέγοντος δάκρυα καὶ σύγχυσις ἦν· μᾶλλον δ’ ἐπεὶ κατέπαυσεν Ἡρώδης τὸν λόγον τῷ μὲν ἔξω τῆς τοιαύτης ἀσεβείας γενέσθαι τὸν λόγον πιστὸν εἶχον ἐν τῷ συνειδότι, τὸ δ’ ἐκ τοῦ πατρὸς ἐπιφέρεσθαι τὰς διαβολὰς δυσαπολόγητον ὥσπερ ἦν ᾔδεσαν, οὐκ εὐσχημονοῦντος οὐδὲ τοῦ κατὰ παρρησίαν λόγου πρὸς τὸν καιρόν, εἰ μέλλοιεν ἐκ βίας ἀεὶ καὶ κατὰ σπουδὴν ἐλέγχειν πεπλανημένον. ἦν οὖν ἀπορία τοῦ δύνασθαι λέγειν καὶ δάκρυα καὶ τέλος οἰμωγὴ συμπαθεστέρα, δεδοικότων μέν, εἰ δόξουσιν ἐκ τοῦ συνειδότος ἠπορῆσθαι, ῥᾳδίαν δ’ οὐχ εὑρισκομένων τὴν ἀπολογίαν ὑπό τε νεότητος καὶ ταραχῆς, ἣν ἐπεπόνθεισαν. οὐ μὴν ὅ γε Καῖσαρ ἐπιβλέπων αὐτοὺς ὡς εἶχον ἀσύνετον ἐποιεῖτο τὸ μὴ κατὰ συνείδησιν ἀτοπωτέραν, ἀλλ’ ἐξ ἀπειρίας καὶ μετριότητος ὀκνεῖν, ἐλεεινοί τ’ ἐγεγόνεισαν τοῖς παροῦσιν ἰδίᾳ καὶ τὸν πατέρα διεκίνησαν ἀληθινῷ τῷ πάθει συνεχόμενον.", "st": "16.4.2"}, {"sp": "N", "t": "Ἐπεὶ δὲ συνεῖδον εὐμένειάν τινα καὶ παρ’ ἐκείνου καὶ παρὰ τοῦ Καίσαρος, καὶ τῶν ἄλλων δὲ ἕκαστον τοὺς μὲν συνδακρύοντας, ἅπαντας δὲ συναλγοῦντας, ἅτερος αὐτῶν Ἀλέξανδρος ἐπικαλεσάμενος αὐτὸν ἐπεχείρει διαλύειν τὰς αἰτίας καί, πάτερ, εἶπεν, ἡ μὲν σὴ πρὸς ἡμᾶς εὔνοια δήλη καὶ παρ’ αὐτὴν τὴν κρίσιν· οὐκ ἂν γάρ, εἴ τι δυσχερὲς ἐνενόεις ἐφ’ ἡμῖν, ἐπὶ τὸν πάντας σώζοντα προήγαγες· καὶ γὰρ παρούσης μὲν ἐξουσίας ὡς βασιλεῖ, παρούσης δὲ ὡς πατρὶ τοὺς ἀδικοῦντας ἐπεξιέναι, τὸ εἰς Ῥώμην ἄγειν καὶ τοῦτον ποιεῖσθαι μάρτυρα σώζοντος ἦν· οὐδεὶς γὰρ ἀποκτεῖναί τινα προαιρούμενος εἰς ἱερὰ καὶ ναοὺς ἄγει. τὸ δ’ ἡμέτερον ἤδη χεῖρον· οὐ γὰρ ἂν ὑπομείναιμεν ἔτι ζῆν, εἰ τοιοῦτον ἠδικηκέναι πατέρα πεπιστεύμεθα. καὶ μήποτε τοῦτ’ ἐκείνου χεῖρον ἀντὶ τοῦ τεθνάναι μηδὲν ἀδικοῦντας τὸ ζῆν ἀδικεῖν ὑποπτευομένους. εἰ μὲν οὖν εὕροι λόγον τῆς ἀληθείας ἡ παρρησία, μακάριον καὶ σὲ πεῖσαι καὶ τὸν κίνδυνον διαφυγεῖν, εἰ δ’ οὕτως ἡ διαβολὴ κρατεῖ, περιττὸς ἡμῖν ὁ νῦν ἥλιος, ὃν τί δεῖ βλέπειν μετὰ τῆς ὑποψίας; τὸ μὲν οὖν φάναι βασιλείας ἐπιθυμεῖν, εὔκαιρος εἰς νέους αἰτία, καὶ τὸ προστιθέναι τὴν τῆς ἀθλίας μητρός, ἱκανὸν ἐκ τῆς πρώτης τὴν νῦν ἀτυχίαν ἐξεργάζεσθαι. βλέψον δέ, εἰ μὴ κοινὰ ταῦτα καὶ πᾶσιν ὁμοίως λέγεσθαι δυνησόμενα· κωλύσει γὰρ οὐδέν, τῷ βασιλεύοντι παῖδες εἰ εἰσὶν νέοι καὶ μήτηρ αὐτῶν ἀποθανοῦσα, πάντας ὑπόπτους εἶναι τοῦ πατρὸς ἐπιβούλους δοκεῖν. ἀλλ’ οὐ τὸ ὕποπτον πρὸς τοιαύτην ἀσέβειαν ἀρκετόν. εἰπάτω δέ τις, ἡμῖν εἰ τετόλμηται τοιοῦτον, ᾧ καὶ τὰ μὴ πιστὰ πίστιν εἴωθεν ὑπ’ ἐνεργείας λαμβάνειν. φαρμάκου παρασκευὴν ἐλέγχειν δύναταί τις ἢ συνωμοσίαν ἡλικιωτῶν ἢ διαφθορὰν οἰκετῶν ἢ γράμματα κατὰ σοῦ γεγραμμένα; καίτοι τούτων ἕκαστον ἔσθ’ ὅπη καὶ μὴ γενόμενον ἐκ διαβολῆς ἐπλάσθη· χαλεπὸν γὰρ οὐχ ὁμονοῶν οἶκος ἐν βασιλείᾳ· καὶ τὴν ἀρχήν, ἣν σὺ φῂς ἔπαθλον εὐσεβείας, συμβαίνει πολλάκις αἰτίαν γενέσθαι τοῖς πονηροτάτοις ἐλπίδων, δι’ ἃς οὐδεμίαν ὑποστολὴν ποιοῦνται κακοηθείας. ἀδίκημα μὲν οὖν οὐδεὶς ἐρεῖ καθ’ ἡμῶν· τὰς δὲ διαβολὰς πῶς ἂν λύσειεν ὁ ἀκοῦσαι μὴ θέλων; ἐλαλήσαμέν τι μετὰ παρρησίας. οὐκ εἰς σέ· τοῦτο γὰρ ἦν ἄδικον· ἀλλ’ εἰς τοὺς οὐδ’ ὅ τι λελάλητο μὴ σιωπῶντας. τὴν μητέρα τις ἡμῶν ἔκλαυσεν. οὐχ ὅτι τέθνηκεν, ἀλλ’ ὅτι καὶ νεκρὰ κακῶς ἤκουσεν ὑπὸ τῶν οὐκ ἀξίων. ἀρχῆς ἐπιθυμοῦμεν ἧς ἴσμεν ἔχοντα τὸν πατέρα; τί καὶ θέλοντες; εἰ μὲν εἰσὶν ἡμῖν τιμαὶ βασιλέων, ὥσπερ εἰσίν, οὐ κενοσπουδοῦμεν; εἰ δ’ οὐκ εἰσίν, οὐκ ἐλπίζομεν; ἢ σὲ διαχειρισάμενοι κρατήσειν τὴν βασιλείαν προσεδοκήσαμεν, οἷς οὔτε γῆ βάσιμος οὔτε πλωτὴ θάλαττα μετὰ τοιοῦτον ἔργον; ἡ δὲ τῶν ἀρχομένων εὐσέβεια καὶ θρησκεία τοῦ παντὸς ἔθνους ἠνέσχετο ἂν πατροκτόνους ἐπὶ τῶν πραγμάτων εἶναι καὶ εἰς τὸν ἁγιώτατον ὑπὸ σοῦ κατασκευασθέντα ναὸν εἰσιέναι. τί δ’ εἰ καὶ τῶν ἄλλων κατεφρονήσαμεν, ἐδύνατό τις φονεύσας ἀτιμώρητος μένειν ζῶντος Καίσαρος; οὔτ’ ἀσεβεῖς οὕτως ἐγέννησας οὔτ’ ἀλογίστους, ἀτυχεστέρους δ’ ἴσως ἢ σοὶ καλῶς εἶχεν. εἰ δὲ μήτ’ αἰτίας ἔχεις μήτ’ ἐπιβουλὰς εὑρίσκεις, τί σοι πρὸς πίστιν αὔταρκες τοιαύτης δυσσεβείας; ἡ μήτηρ τέθνηκεν· ἀλλά τοι τὰ κατ’ ἐκείνην οὐδὲ παροξύνειν ἡμᾶς ἀλλὰ νουθετεῖν ἠδύνατο. πλείω μὲν ἀπολογεῖσθαι δυνάμεθα, λόγον δ’ οὐκ ἐπιδέχεται τὰ μὴ γενόμενα. διόπερ ἐπὶ τῷ πάντων δεσπότῃ Καίσαρι μεσιτεύοντι τὸν παρόντα καιρὸν συντιθέμεθα ταύτην τὴν συνθήκην· εἰ μὲν ἀνύποπτον ἐξ αὐτῆς τῆς ἀληθείας τὴν πρὸς ἡμᾶς διάθεσιν ἀπολαμβάνεις, ὦ πάτερ, ζήσομεν, οὐδ’ οὕτως μὲν εὐτυχῶς· δεινὸν γὰρ τῶν μεγάλων κακῶν καὶ ψευδὴς αἰτία. παρούσης δέ τινος ὀρρωδίας σὺ μὲν ἐν τῇ κατὰ σαυτὸν εὐσεβείᾳ μένε, δώσομεν δὲ λόγον ἡμεῖς ἑαυτοῖς. οὐχ οὕτως ὁ βίος ἡμῖν τίμιος, ὡς ἔχειν αὐτὸν ἐπ’ ἀδικίᾳ τοῦ δεδωκότος.", "st": "16.4.3"}, {"sp": "N", "t": "Τοιαῦτα δὲ λέγοντος ὅ τε Καῖσαρ οὐδὲ πρότερον πιστεύων τῷ μεγέθει τῆς διαβολῆς ἔτι μᾶλλον ἐξηλλάττετο καὶ συνεχὲς εἰς τὸν Ἡρώδην ἀπέβλεπεν ὁρῶν κἀκεῖνον ὑποσυγχυνόμενον, ἀγωνία τε τοῖς παροῦσιν ἐνεπεπτώκει καὶ περὶ τὴν αὐλὴν ὁ λόγος διαδοθεὶς ἐπίφθονον ἐποίει τὸν βασιλέα. τὸ γὰρ ἄπιστον τῆς διαβολῆς καὶ τὸ περὶ τοὺς νεανίσκους ἐν ἀκμῇ καὶ κάλλει σωμάτων ἐλεεινὸν ἐπεσπᾶτο βοήθειαν· ἔτι δὲ μᾶλλον ἐπειδὴ καὶ τῷ λόγῳ δεξιῶς καὶ μετὰ φρονήσεως ὑπήντησεν Ἀλέξανδρος, ἦν οὐδ’ ἐκείνοις ἔτι ταὐτὸν σχῆμα, κλαίουσι μὲν ὅμως καὶ σὺν κατηφείᾳ πρὸς τὴν γῆν νενευκόσιν, ἡ δ’ ἐλπὶς ἀμείνων ὑπεφαίνετο, καὶ δόξας ὁ βασιλεὺς ἐξ ὧν αὐτὸν ἔπειθεν εὔλογα κατηγορηκέναι διὰ τὸ μηδὲν ἔχειν [ἐξελέγχειν] ἀπολογίας τινὸς ἐδεῖτο. Καῖσαρ δὲ μικρὸν ἐπισχὼν τοὺς μὲν νεανίσκους, εἰ καὶ πόρρω τῆς ἐπ’ αὐτοῖς διαβολῆς δοκοῦσιν, αὐτό γε τοῦτο ἁμαρτεῖν ἔφη τὸ μὴ τοιούτους αὐτοὺς παρασχεῖν τῷ πατρί, ὡς μηδὲ γενέσθαι τὸν ἐπ’ αὐτοῖς λόγον. Ἡρώδην δὲ παρεκάλει πᾶσαν ὑπόνοιαν ἐκβαλόντα διαλλάττεσθαι τοῖς παισίν· οὐ γὰρ εἶναι δίκαιον οὐδὲ πιστεύειν τὰ τοιαῦτα κατὰ τῶν ἐξ αὐτοῦ. δύνασθαι δὲ τὴν μετάνοιαν ἀμφοτέροις οὐ μόνον ἰάσασθαι τὰ συμβεβηκότα, παροξῦναι δὲ τὴν εὔνοιαν, ἐν ᾧ τὸ προπετὲς ἑκάτεροι τῆς ὑποψίας ἀπολογούμενοι σπουδῇ πλείονι περὶ ἀλλήλους ἀξιώσουσι κεχρῆσθαι. τοιαῦτα νουθετῶν ἔνευσε τοῖς νεανίσκοις. ἐκείνων δὲ βουλομένων ὑποπεσεῖν ἐπὶ δεήσει προαναλαβὼν αὐτοὺς ὁ πατὴρ δακρύοντας ἠσπάζετο παρ’ ἕκαστον ἐν μέρει περιπτύσσων, ὡς μηδένα τῶν παρατυγχανόντων ἐλεύθερον ἢ δοῦλον ἀπαθῆ γενέσθαι.", "st": "16.4.4"}, {"sp": "N", "t": "Τότε μὲν οὖν εὐχαριστήσαντες Καίσαρι μετ’ ἀλλήλων ἀπῄεσαν καὶ σὺν αὐτοῖς Ἀντίπατρος ὑποκρινόμενος ἐφήδεσθαι ταῖς διαλλαγαῖς. ἐν δὲ ταῖς ὑστέραις ἡμέραις Ἡρώδης μὲν ἐδωρεῖτο Καίσαρα τριακοσίοις ταλάντοις θέας τε καὶ διανομὰς ποιούμενον τῷ Ῥωμαίων δήμῳ, Καῖσαρ δὲ αὐτῷ τοῦ μετάλλου τοῦ Κυπρίων χαλκοῦ τὴν ἡμίσειαν πρόσοδον καὶ τῆς ἡμισείας τὴν ἐπιμέλειαν ἔδωκεν καὶ τἆλλα ξενίαις καὶ καταγωγαῖς ἐτίμησεν, καὶ περὶ τῆς βασιλείας αὐτῷ τὴν ἐξουσίαν ἐφῆκεν ὃν ἂν αἱρῆται τῶν παίδων διάδοχον καθιστάνειν ἢ καὶ διανέμειν μέρος ἑκάστῳ τῆς τιμῆς εἰς πάντας ἐλευσομένης. ἐκείνου δὲ ἤδη θέλοντος αὐτὸ ποιεῖν οὐκ ἐπιτρέψειν ἔφη ζῶντι μὴ καὶ τῆς βασιλείας καὶ τῶν παίδων κρατεῖν.", "st": "16.4.5"}, {"sp": "N", "t": "Ἐπὶ τούτοις ἐπανῄει πάλιν εἰς τὴν Ἰουδαίαν. ἀποδημοῦντος δὲ οὐ μικρὸν μέρος ἀπέστη τῆς ἀρχῆς τὸ περὶ τὸν Τράχωνα, καὶ τούτους οἱ καταλειφθέντες στρατηγοὶ χειρωσάμενοι πάλιν ὑπακούειν ἠνάγκασαν. Ἡρώδης δὲ πλέων σὺν τοῖς παισὶν ὡς ἐγένετο κατὰ Κιλικίαν ἐν Ἐλαιούσῃ τῇ μετωνομασμένῃ νῦν Σεβαστῇ καταλαμβάνει τὸν βασιλέα τῆς Καππαδοκίας Ἀρχέλαον, ὃς αὐτὸν ἐκδέχεται φιλοφρόνως ἡδόμενος ἐπὶ ταῖς τῶν παίδων διαλλαγαῖς καὶ τῷ τὸν Ἀλέξανδρον, ὃς εἶχεν αὐτοῦ τὴν θυγατέρα, τῆς αἰτίας ἀπολελύσθαι, δωρεάς τε ἀντέδοσαν ἀλλήλοις ἃς εἰκὸς βασιλεῖς. ἐντεῦθεν Ἡρώδης ἐπὶ Ἰουδαίας ἐλθὼν καὶ γενόμενος ἐν τῷ ἱερῷ περὶ τῶν πεπραγμένων κατὰ τὴν ἀποδημίαν διελέγετο, τὴν Καίσαρος εἰς αὐτὸν φιλοφροσύνην καὶ τἆλλα διεξιὼν ὅσα κατὰ μέρος αὐτῷ πραχθέντα συμφέρειν ἡγεῖτο καὶ τοὺς ἄλλους εἰδέναι. τέλος ἐπὶ νουθεσίᾳ τῶν παίδων κατέστρεφε τὸν λόγον τοὺς περὶ τὴν αὐλὴν καὶ τὸ λοιπὸν πλῆθος εἰς ὁμόνοιαν παρακαλῶν καὶ τοὺς υἱοὺς μετ’ αὐτὸν ἀποδεικνύων βασιλέας γενέσθαι, πρῶτον μὲν Ἀντίπατρον, εἶτα καὶ τοὺς ἐκ Μαριάμμης Ἀλέξανδρον καὶ Ἀριστόβουλον. ἐν δὲ τῷ τότε πάντας ἀποβλέπειν εἰς αὐτὸν ἀξιῶν καὶ βασιλέα καὶ δεσπότην ἁπάντων δοκεῖν μήτε γήρᾳ παραποδιζόμενον, ἐν ᾧ τοῦ χρόνου τὸ πρὸς ἀρχὴν ἐμπειρότατον ἔχειν, οὔτε τοῖς ἄλλοις ἐπιτηδεύμασιν ἐλαττούμενον, ἃ δύναται καὶ βασιλείας κρατεῖν καὶ παίδων ἄρχειν, τούς τε ἡγεμόνας καὶ τὸ στρατιωτικὸν εἰ πρὸς ἕνα βλέποιεν αὐτὸν ἀτάραχον ἔφη τὸν βίον ἕξειν καὶ πᾶσαν ἀφορμὴν εὐδαιμονίας ἐξ ἀλλήλων ἔσεσθαι. ταῦτ’ εἰπὼν ἀφίησιν τὴν ἐκκλησίαν, τοῖς πλείστοις μὲν ἀρεστὰ διειλεγμένος, ἐνίοις δ’ οὐχ ὁμοίως· ἤδη γὰρ ὑπὸ τῆς ἁμίλλης καὶ τῶν ἐλπίδων ἃς ἐδεδώκει τοῖς παισὶ νενεωτέριστο πολλὰ καὶ νεωτέρων ἐφιέμενοι", "st": "16.4.6"}, {"sp": "N", "t": "Περὶ δὲ τὸν χρόνον τοῦτον συντέλειαν ἔλαβεν ἡ Καισάρεια Σεβαστή, ἣν ᾠκοδόμει δεκάτῳ μὲν ἔτει πρὸς τέλος ἐλθούσης αὐτῷ τῆς ὅλης κατασκευῆς, ἐκπεσούσης δὲ τῆς προθεσμίας εἰς ὄγδοον καὶ εἰκοστὸν ἔτος τῆς ἀρχῆς ἐπ’ ὀλυμπιάδος δευτέρας καὶ ἐνενηκοστῆς πρὸς ταῖς ἑκατόν. ἦν οὖν εὐθὺς ἐν καθιερώσει μείζονες ἑορταὶ καὶ παρασκευαὶ πολυτελέσταται· κατηγγέλκει μὲν γὰρ ἀγῶνα μουσικῆς καὶ γυμνικῶν ἀθλημάτων, παρεσκευάκει δὲ πολὺ πλῆθος μονομάχων καὶ θηρίων ἵππων τε δρόμον καὶ τὰ πολυτελέστερα τῶν ἔν τε τῇ Ῥώμῃ καὶ παρ’ ἄλλοις τισὶν ἐπιτηδευμάτων. ἀνετίθει δὲ καὶ τοῦτον τὸν ἀγῶνα Καίσαρι κατὰ πενταετηρίδα παρεσκευασμένος ἄγειν αὐτόν· ὁ δ’ αὐτῷ πᾶσαν τὴν εἰς τὰ τοιαῦτα παρασκευὴν ἀπὸ τῶν οἰκείων διεπέμπετο τὴν φιλοτιμίαν ἐπικοσμῶν. ἰδίᾳ δὲ καὶ ἡ γυνὴ Καίσαρος Ἰουλία πολλὰ τῶν ἐκεῖ πολυτελεστάτων ἀπέστειλεν, ὡς μηδὲν ὑστερεῖν τὰ πάντα συντιμώμενα ταλάντων πεντακοσίων. συνελθόντος δ’ εἰς τὴν πόλιν ὄχλου πλείονος κατὰ θεωρίαν καὶ πρεσβείας, ἃς ἔπεμπον οἱ δῆμοι δι’ ἃς ἐπεπόνθεισαν εὐεργεσίας, ἅπαντας ἐξεδέξατο καὶ καταγωγαῖς καὶ τραπέζαις καὶ διηνεκέσιν ἑορταῖς, τῆς πανηγύρεως ἐν μὲν ταῖς ἡμέραις ἐχούσης τὰς ἀπὸ τῶν θεαμάτων ψυχαγωγίας, ἐν δὲ ταῖς νυξὶ τὰς εὐφροσύνας καὶ τὴν εἰς τοῦτο πολυτέλειαν, ὡς ἐπίσημον γενέσθαι τὴν μεγαλοψυχίαν αὐτοῦ· εἰς πάντα γὰρ ἅπερ [ἂν] ἐπιτηδεύσειεν ἐφιλονείκει τὴν τῶν ἤδη γεγενημένων ἐπίδειξιν ὑπερβαλέσθαι, καί φασιν αὐτόν τε Καίσαρα καὶ Ἀγρίππαν πολλάκις εἰπεῖν, ὡς ἀποδέοι τὰ τῆς ἀρχῆς Ἡρώδῃ τῆς οὔσης ἐν αὐτῷ μεγαλοψυχίας· ἄξιον γὰρ εἶναι καὶ Συρίας ἁπάσης καὶ Αἰγύπτου τὴν βασιλείαν ἔχειν.", "st": "16.5.1"}, {"sp": "N", "t": "Μετὰ δὲ τὴν πανήγυριν ταύτην καὶ τὰς ἑορτὰς πόλιν ἄλλην ἀνήγειρεν ἐν τῷ πεδίῳ τῷ λεγομένῳ Καφαρσαβᾶ τόπον ἔνυδρον καὶ χώραν ἀρίστην φυτοῖς ἐκλέξας, ποταμοῦ τε περιρρέοντος τὴν πόλιν αὐτὴν καὶ καλλίστου κατὰ μέγεθος τῶν φυτῶν περιειληφότος ἄλσους. ταύτην ἀπὸ Ἀντιπάτρου τοῦ πατρὸς Ἀντιπατρίδα προσηγόρευσεν. ἐπώνυμον δὲ καὶ τῇ μητρὶ χωρίον ὑπὲρ Ἱεριχοῦν οἰκοδομήσας ἀσφαλείᾳ τε διάφορον καὶ καταγωγαῖς ἥδιστον ἐκάλεσεν Κύπρον. Φασαήλῳ τε τῷ ἀδελφῷ μνημεῖα διὰ τὴν γεγενημένην εἰς αὐτὸν φιλοστοργίαν ἀνετίθει τὰ κάλλιστα, πύργον ἐπ’ αὐτῆς τῆς πόλεως ἀναστήσας οὐδὲν ἐλάττω τοῦ κατὰ τὴν Φάρον, ὃν προσηγόρευσεν Φασάηλον, ἀσφαλείας τε τῇ πόλει μέρος ὄντα καὶ μνήμης τῷ τετελευτηκότι διὰ τὴν προσηγορίαν. ὁμώνυμον δὲ αὐτῷ καὶ πόλιν περὶ τὸν αὐλῶνα τῆς Ἱεριχοῦντος ἔκτισεν ἀπιόντων κατὰ βορρᾶν ἄνεμον, δι’ ἧς καὶ τὴν πέριξ χώραν ἔρημον οὖσαν ἐνεργοτέραν ἐποίησεν ταῖς ἐπιμελείαις τῶν οἰκητόρων. Φασαηλίδα καὶ ταύτην ἐκάλει.", "st": "16.5.2"}, {"sp": "N", "t": "Τὰς δὲ ἄλλας εὐεργεσίας ἄπορον εἰπεῖν ὅσας ἀπέδωκεν ταῖς πόλεσιν ἔν τε Συρίᾳ καὶ κατὰ τὴν Ἑλλάδα καὶ παρ’ οἷς ποτ’ ἂν ἀποδημήσας τύχοι· καὶ γὰρ πλείους λειτουργίας καὶ δημοσίων ἔργων κατασκευὰς καὶ χρήματα τοῖς δεομένοις [ἔργοις] εἰς ἐπιμέλειαν τῶν προτέρων ἔργων ἐκλελοιπότων ἄφθονα χαρίσασθαι δοκεῖ. τὰ δὲ μέγιστα καὶ διασημότατα τῶν πεπραγμένων αὐτῷ Ῥοδίοις μὲν τό τε Πύθιον ἀνέστησεν οἰκείοις ἀναλώμασιν καὶ παρέσχεν ἀργυρίου πολλὰ τάλαντα πρὸς ναυπηγίαν. Νικοπολίταις δὲ τοῖς ἐπ’ Ἀκτίῳ κτισθεῖσιν ὑπὸ Καίσαρος τὰ πλεῖστα τῶν δημοσίων συγκατεσκεύασεν. Ἀντιοχεῦσι δὲ τοῖς ἐν Συρίᾳ μεγίστην πόλιν οἰκοῦσιν, ἣν κατὰ μῆκος τέμνει πλατεῖα, ταύτην αὐτὴν στοαῖς παρ’ ἑκάτερα καὶ λίθῳ τὴν ὕπαιθρον ὁδὸν ξεστῷ καταστορέσας πλεῖστον εἰς κόσμον καὶ τὴν τῶν οἰκούντων εὐχρηστίαν ὠφέλησεν. τόν γε μὴν Ὀλυμπίασιν ἀγῶνα πολὺ τῆς προσηγορίας ἀδοξότερον ὑπ’ ἀχρηματίας διατεθειμένον τιμιώτερον ἐποίει χρημάτων προσόδους καταστήσας καὶ πρὸς θυσίας καὶ τὸν ἄλλον κόσμον ἐσεμνοποίησεν τὴν πανήγυριν. διὰ δὴ ταύτην τὴν φιλοτιμίαν διηνεκὴς ἀγωνοθέτης παρὰ τοῖς Ἠλείοις ἀνεγράφη.", "st": "16.5.3"}, {"sp": "N", "t": "Τοῖς μὲν οὖν ἄλλοις ἐπέρχεται θαυμάζειν τὸ διεστὸς τῆς ἐν τῇ φύσει προαιρέσεως· ὅταν μὲν γὰρ εἰς τὰς φιλοτιμίας καὶ τὰς εὐεργεσίας ἀπίδωμεν, αἷς ἐκέχρητο πρὸς ἅπαντας ἀνθρώπους, οὐκ ἔστιν ὅπως οὐκ ἄν τις αὐτὸν καὶ τῶν ἔλαττον τετιμημένων ἠρνήθη μὴ συνομολογεῖν εὐεργετικωτάτῃ κεχρῆσθαι τῇ φύσει. ὅταν δὲ εἰς τὰς τιμωρίας καὶ ἀδικίας, ἃς εἰς τοὺς ἀρχομένους καὶ τοὺς οἰκειοτάτους ἐπεδείξατο βλέψῃ καὶ καταμάθῃ τὸ σκληρὸν καὶ τὸ δυσπαράκλητον τοῦ τρόπου, νικηθήσεται θηριώδη δοκεῖν καὶ πάσης μετριότητος ἀλλότριον. ἔνθεν καὶ διάφορόν τινα καὶ μαχομένην ἐπ’ αὐτῷ νομίζουσιν γενέσθαι τὴν προαίρεσιν. ἐγὼ δ’ οὐχ οὕτως ἔχων μίαν αἰτίαν ἀμφοτέρων τούτων ὑπολαμβάνω· φιλότιμος γὰρ ὢν καὶ τούτου τοῦ πάθους ἡττημένος ἰσχυρῶς, προήγετο μὲν εἰς μεγαλοψυχίαν, εἴ που μνήμης εἰς αὖθις ἢ κατὰ τὸ παρὸν εὐφημίας ἐλπὶς ἐμπέσοι. ταῖς δὲ δαπάναις ὑπὲρ δύναμιν χρώμενος ἠναγκάζετο χαλεπὸς εἶναι τοῖς ὑποτεταγμένοις· τὰ γὰρ εἰς οὓς ἐδαπάνα πολλὰ γενόμενα κακῶν ποριστὴν ἐξ ὧν ἐλάμβανεν ἐποίει. καὶ συνειδὼς ἐφ’ οἷς ἠδίκει τοὺς ὑποτεταγμένους μισούμενον ἑαυτὸν τὸ μὲν ἐπανορθοῦσθαι τὰς ἁμαρτίας οὐ ῥᾴδιον ἐνόμιζεν· οὐδὲ γὰρ εἰς τὰς προσόδους λυσιτελὲς ἦν. ἀντεφιλονείκει δὲ τὴν δύσνοιαν αὐτὴν εὐπορίας ἀφορμὴν ποιούμενος. περί γε μὴν τοὺς οἰκείους, εἴ τις ἢ λόγῳ μὴ θεραπεύοι τὸ δοῦλον ἐξομολογούμενος ἢ δόξειεν εἰς τὴν ἀρχήν τι παρακινεῖν, οὐχ ἱκανὸς ἑαυτοῦ κρατεῖν ἐγίνετο καὶ διεξῆλθεν ὁμοῦ συγγενεῖς καὶ φίλους ἴσα πολεμίοις τιμωρούμενος ἐκ τοῦ μόνος ἐθέλειν τετιμῆσθαι τὰς τοιαύτας ἁμαρτίας ἀναλαμβάνων. μαρτύριον δέ μοι τούτου τοῦ πάθους, ὅτι μέγιστον περὶ αὐτὸν ἦν, καὶ τὰ γινόμενα κατὰ τὰς Καίσαρος καὶ Ἀγρίππα καὶ τῶν ἄλλων φίλων τιμάς· οἷς γὰρ ἐθεράπευεν τοὺς κρείττονας, τούτοις καὶ αὐτὸς ἠξίου θεραπεύεσθαι καὶ τὸ κάλλιστον ὧν ᾤετο παρέχων ἐν τῷ διδόναι τὴν τοῦ τυχεῖν τῶν ὁμοίων ἐπιθυμίαν ἐδήλου. τό γε μὴν Ἰουδαίων ἔθνος ἠλλοτρίωται νόμῳ πρὸς πάντα τὰ τοιαῦτα καὶ συνείθισται τὸ δίκαιον ἀντὶ τοῦ πρὸς δόξαν ἠγαπηκέναι. διόπερ οὐκ ἦν αὐτῷ κεχαρισμένον, ὅτι μὴ δυνατὸν εἰκόσιν ἢ ναοῖς ἢ τοιούτοις ἐπιτηδεύμασιν κολακεύειν τοῦ βασιλέως τὸ φιλότιμον. αἰτία μὲν αὕτη μοι δοκεῖ τῆς Ἡρώδου περὶ μὲν τοὺς οἰκείους καὶ συμβούλους ἁμαρτίας, περὶ δὲ τοὺς ἔξω καὶ μὴ προσήκοντας εὐεργεσίας.", "st": "16.5.4"}, {"sp": "N", "t": "Τοὺς δὲ κατὰ τὴν Ἀσίαν Ἰουδαίους καὶ ὅσους ἡ πρὸς Κυρήνῃ Λιβύη κατέσχεν ἐκάκουν αἱ πόλεις, τῶν μὲν πρότερον βασιλέων ἰσονομίαν αὐτοῖς παρεσχημένων, ἐν δὲ τῷ τότε δι’ ἐπηρείας ἐχόντων τῶν Ἑλλήνων αὐτούς, ὡς καὶ χρημάτων ἱερῶν ἀφαίρεσιν ποιεῖσθαι καὶ καταβλάπτειν ἐν τοῖς ἐπὶ μέρους. πάσχοντες δὲ κακῶς καὶ πέρας οὐδὲν εὑρίσκοντες τῆς τῶν Ἑλλήνων ἀπανθρωπίας ἐπρεσβεύσαντο παρὰ Καίσαρα καὶ περὶ τούτων. ὁ δ’ αὐτοῖς τὴν αὐτὴν ἰσοτέλειαν ἔδωκεν γράψας τοῖς κατὰ τὰς ἐπαρχίας, ὧν ὑπετάξαμεν τὰ ἀντίγραφα μαρτύρια τῆς διαθέσεως, ἣν ἔσχον ὑπὲρ ἡμῶν ἄνωθεν οἱ κρατοῦντες.", "st": "16.6.1"}, {"sp": "N", "t": "Καῖσαρ Σεβαστὸς ἀρχιερεὺς δημαρχικῆς ἐξουσίας λέγει. ἐπειδὴ τὸ ἔθνος τὸ τῶν Ἰουδαίων εὐχάριστον εὑρέθη οὐ μόνον ἐν τῷ ἐνεστῶτι καιρῷ ἀλλὰ καὶ ἐν τῷ προγεγενημένῳ καὶ μάλιστα ἐπὶ τοῦ ἐμοῦ πατρὸς αὐτοκράτορος Καίσαρος πρὸς τὸν δῆμον τὸν Ῥωμαίων ὅ τε ἀρχιερεὺς αὐτῶν Ὑρκανός, ἔδοξέ μοι καὶ τῷ ἐμῷ συμβουλίῳ μετὰ ὁρκωμοσίας γνώμῃ δήμου Ῥωμαίων τοὺς Ἰουδαίους χρῆσθαι τοῖς ἰδίοις θεσμοῖς κατὰ τὸν πάτριον αὐτῶν νόμον, καθὼς ἐχρῶντο ἐπὶ Ὑρκανοῦ ἀρχιερέως θεοῦ ὑψίστου, τά τε ἱερὰ εἶναι ἐν ἀσυλίᾳ καὶ ἀναπέμπεσθαι εἰς Ἱεροσόλυμα καὶ ἀποδίδοσθαι τοῖς ἀποδοχεῦσιν Ἱεροσολύμων, ἐγγύας τε μὴ ὁμολογεῖν αὐτοὺς ἐν σάββασιν ἢ τῇ πρὸ αὐτῆς παρασκευῇ ἀπὸ ὥρας ἐνάτης. ἐὰν δέ τις φωραθῇ κλέπτων τὰς ἱερὰς βίβλους αὐτῶν ἢ τὰ ἱερὰ χρήματα ἔκ τε σαββατείου ἔκ τε ἀνδρῶνος, εἶναι αὐτὸν ἱερόσυλον καὶ τὸν βίον αὐτοῦ ἐνεχθῆναι εἰς τὸ δημόσιον τῶν Ῥωμαίων. τό τε ψήφισμα τὸ δοθέν μοι ὑπ’ αὐτῶν ὑπὲρ τῆς ἐμῆς εὐσεβείας ἧς ἔχω πρὸς πάντας ἀνθρώπους καὶ ὑπὲρ Γαΐου Μαρκίου Κηνσωρίνου καὶ τοῦτο τὸ διάταγμα κελεύω ἀνατεθῆναι ἐν ἐπισημοτάτῳ τόπῳ τῷ γενηθέντι μοι ὑπὸ τοῦ κοινοῦ τῆς Ἀσίας ἐν Ἀγκύρῃ. ἐὰν δέ τις παραβῇ τι τῶν προειρημένων, δώσει δίκην οὐ μετρίαν. ἐστηλογραφήθη ἐν τῷ Καίσαρος ναῷ.", "st": "16.6.2"}, {"sp": "N", "t": "Καῖσαρ Νωρβανῷ Φλάκκῳ χαίρειν. Ἰουδαῖοι ὅσοι ποτ’ οὖν εἰσίν, [οἳ] δι’ ἀρχαίαν συνήθειαν εἰώθασιν χρήματά τε ἱερὰ φέροντες ἀναπέμπειν ἀκωλύτως τοῦτο ποιείτωσαν εἰς Ἱεροσόλυμα. καὶ ταῦτα μὲν Καῖσαρ.", "st": "16.6.3"}, {"sp": "N", "t": "Ἀγρίππας δὲ καὶ αὐτὸς ἔγραψεν ὑπὲρ τῶν Ἰουδαίων τὸν τρόπον τοῦτον· Ἀγρίππας Ἐφεσίων ἄρχουσι βουλῇ δήμῳ χαίρειν. τῶν εἰς τὸ ἱερὸν τὸ ἐν Ἱεροσολύμοις ἀναφερομένων ἱερῶν χρημάτων τὴν ἐπιμέλειαν καὶ φυλακὴν βούλομαι τοὺς ἐν Ἀσίᾳ Ἰουδαίους ποιεῖσθαι κατὰ τὰ πάτρια. τούς τε κλέπτοντας ἱερὰ γράμματα τῶν Ἰουδαίων καταφεύγοντάς τε εἰς τὰς ἀσυλίας βούλομαι ἀποσπᾶσθαι καὶ παραδίδοσθαι τοῖς Ἰουδαίοις, ᾧ δικαίῳ ἀποσπῶνται οἱ ἱερόσυλοι. ἔγραψα δὲ καὶ Σιλανῷ τῷ στρατηγῷ, ἵνα σάββασιν μηδεὶς ἀναγκάζῃ Ἰουδαῖον ἐγγύας ὁμολογεῖν.", "st": "16.6.4"}, {"sp": "N", "t": "Μᾶρκος Ἀγρίππας Κυρηναίων ἄρχουσιν βουλῇ δήμῳ χαίρειν. οἱ ἐν Κυρήνῃ Ἰουδαῖοι, ὑπὲρ ὧν ἤδη ὁ Σεβαστὸς ἔπεμψεν πρὸς τὸν ἐν Λιβύῃ στρατηγὸν τόντε ὄντα Φλάβιον καὶ πρὸς τοὺς ἄλλους τοὺς τῆς ἐπαρχίας ἐπιμελουμένους, ἵνα ἀνεπικωλύτως ἀναπέμπηται τὰ ἱερὰ χρήματα εἰς Ἱεροσόλυμα, ὡς ἔστιν αὐτοῖς πάτριον, ἐνέτυχόν μοι νῦν, ὡς ὑπό τινων συκοφαντῶν ἐπηρεαζόμενοι καὶ ὡς ἐν προφάσει τελῶν μὴ ὀφειλομένων κωλύοιντο· οἷς ἀποκαθιστάνειν κατὰ μηδένα τρόπον ἐνοχλουμένοις, καὶ εἴ τινων ἱερὰ χρήματα ἀφῄρηνται τῶν πόλεων τοὺς εἰς ταῦτα ἀποκεκριμένους καὶ ταῦτα διορθώσασθαι τοῖς ἐκεῖ Ἰουδαίοις κελεύω.", "st": "16.6.5"}, {"sp": "N", "t": "Γάιος Νωρβανὸς Φλάκκος ἀνθύπατος Σαρδιανῶν ἄρχουσι χαίρειν. Καῖσάρ μοι ἔγραψεν κελεύων μὴ κωλύεσθαι τοὺς Ἰουδαίους ὅσα ἂν ὦσιν κατὰ τὸ πάτριον αὐτοῖς ἔθος συναγαγόντες χρήματα ἀναπέμπειν εἰς Ἱεροσόλυμα. ἔγραψα οὖν ὑμῖν, ἵν’ εἰδῆτε, ὅτι Καῖσαρ κἀγὼ οὕτως θέλομεν γίνεσθαι.", "st": "16.6.6"}, {"sp": "N", "t": "Οὐδὲν ἧττον καὶ Ἰούλιος Ἀντώνιος ἀνθύπατος ἔγραψεν Ἐφεσίων ἄρχουσιν βουλῇ δήμῳ χαίρειν. οἱ ἐν τῇ Ἀσίᾳ κατοικοῦντες Ἰουδαῖοι εἰδοῖς Φεβρουαρίοις δικαιοδοτοῦντί μοι ἐν Ἐφέσῳ ὑπέδειξαν Καίσαρα τὸν Σεβαστὸν καὶ Ἀγρίππαν συγκεχωρηκέναι αὐτοῖς χρῆσθαι τοῖς ἰδίοις νόμοις καὶ ἔθεσιν, ἀπαρχάς τε, ἃς ἕκαστος αὐτῶν ἐκ τῆς ἰδίας προαιρέσεως εὐσεβείας ἕνεκα τῆς πρὸς τὸ θεῖον ἀνακομιδῆς συμπορευομένους ποιεῖν ἀνεμποδίστως. ᾔτουν τε, ὅπως κἀγὼ ὁμοίως τοῖς ὑπὸ τοῦ Σεβαστοῦ καὶ Ἀγρίππα δοθεῖσιν τὴν ἐμὴν γνώμην βεβαιώσω. ὑμᾶς οὖν βούλομαι εἰδέναι ἐν τοῖς τοῦ Σεβαστοῦ καὶ Ἀγρίππα βουλήμασιν συνεπιτρέπειν αὐτοῖς χρῆσθαι καὶ ποιεῖν κατὰ τὰ πάτρια χωρὶς ἐμποδισμοῦ.", "st": "16.6.7"}, {"sp": "N", "t": "Ταῦτα μὲν οὖν παρεθέμην ἐξ ἀνάγκης, ἐπειδὴ μέλλουσιν αἱ τῶν ἡμετέρων πράξεων ἀναγραφαὶ τὸ πλέον εἰς τοὺς Ἕλληνας ἰέναι, δεικνὺς αὐτοῖς ὅτι πάσης τιμῆς ἄνωθεν ἐπιτυγχάνοντες οὐδὲν τῶν πατρίων ἐκωλύθημεν ὑπὸ τῶν ἀρχόντων πράττειν, ἀλλὰ καὶ συνεργούμεθα τὰ τῆς θρησκείας ἔχοντες καὶ τῶν εἰς τὸν θεὸν τιμῶν. ποιοῦμαι δὲ πολλάκις αὐτῶν τὴν μνήμην ἐπιδιαλλάττων τὰ γένη καὶ τὰς ἐμπεφυκυίας τοῖς ἀλογίστοις ἡμῶν τε κἀκείνων μίσους αἰτίας ὑπεξαιρούμενος. ἔθεσιν μὲν γὰρ οὐδέν ἐστιν γένος ὃ τοῖς αὐτοῖς ἀεὶ χρῆται καὶ κατὰ πόλεις ἔσθ’ ὅπη πολλῆς ἐγγιγνομένης τῆς διαφορᾶς· τὸ δίκαιον δὲ πᾶσιν ἀνθρώποις ὁμοίως ἐπιτηδεύοντες λυσιτελέστατον ὂν Ἕλλησίν τε καὶ βαρβάροις, οὗ πλεῖστον οἱ παρ’ ἡμῖν νόμοι λόγον ἔχοντες ἅπασιν ἡμᾶς, εἰ καθαρῶς ἐμμένοιμεν αὐτοῖς, εὔνους καὶ φίλους ἀπεργάζονται. διὸ καὶ ταῦτα παρ’ ἐκείνων ἡμῖν ἀπαιτητέον καὶ δέον οὐκ ἐν τῇ διαφορᾷ τῶν ἐπιτηδευμάτων οἴεσθαι τὸ ἀλλότριον, ἀλλ’ ἐν τῷ πρὸς καλοκαγαθίαν ἐπιτηδείως ἔχειν· τοῦτο γὰρ κοινὸν ἅπασιν καὶ μόνον ἱκανὸν διασώζειν τὸν τῶν ἀνθρώπων βίον. ἐπάνειμι δὲ πάλιν ἐπὶ τὰ συνεχῆ τῆς ἱστορίας.", "st": "16.6.8"}, {"sp": "N", "t": "Ὁ γὰρ Ἡρώδης πολλοῖς τοῖς ἀναλώμασιν εἴς τε τὰς ἔξω καὶ τὰς ἐν τῇ βασιλείᾳ χρώμενος, ἀκηκοὼς ἔτι τάχιον ὡς Ὑρκανὸς ὁ πρὸ αὐτοῦ βασιλεὺς ἀνοίξας τὸν Δαυίδου τάφον ἀργυρίου λάβοι τρισχίλια τάλαντα κειμένων πολὺ πλειόνων ἔτι καὶ δυναμένων εἰς ἅπαν ἐπαρκέσαι ταῖς χορηγίαις, ἐκ πλείονος μὲν δι’ ἐννοίας εἶχεν τὴν ἐπιχείρησιν, ἐν δὲ τῷ τότε νυκτὸς ἀνοίξας τὸν τάφον εἰσέρχεται πραγματευσάμενος ἥκιστα μὲν τῇ πόλει φανερὸς εἶναι, παρειληφὼς δὲ τοὺς πιστοτάτους τῶν φίλων. ἀποθέσιμα μὲν οὖν χρήματα καθάπερ Ὑρκανὸς οὐχ εὗρεν, κόσμον δὲ χρυσοῦν καὶ κειμηλίων πολύν, ὃν ἀνείλετο πάντα. σπουδὴν δ’ εἶχεν ἐπιμελεστέραν ποιούμενος τὴν ἔρευναν ἐνδοτέρω τε χωρεῖν καὶ κατὰ τὰς θήκας, ἐν αἷς ἦν τοῦ Δαυΐδου καὶ τοῦ Σολομῶνος τὰ σώματα. καὶ δύο μὲν αὐτῷ τῶν δορυφόρων διεφθάρησαν φλογὸς ἔνδοθεν εἰσιοῦσιν ἀπαντώσης, ὡς ἐλέγετο, περίφοβος δ’ αὐτὸς ἐξῄει, καὶ τοῦ δέους ἱλαστήριον μνῆμα λευκῆς πέτρας ἐπὶ τῷ στομίῳ κατεσκευάσατο πολυτελὲς τῇ δαπάνῃ. τούτου καὶ Νικόλαος ὁ κατ’ αὐτὸν ἱστοριογράφος μέμνηται τοῦ κατασκευάσματος, οὐ μὴν ὅτι καὶ κατῆλθεν, οὐκ εὐπρεπῆ τὴν πρᾶξιν ἐπιστάμενος. διατελεῖ δὲ καὶ τἆλλα τοῦτον τὸν τρόπον χρώμενος τῇ γραφῇ· ζῶντι γὰρ ἐν τῇ βασιλείᾳ καὶ σὺν αὐτῷ κεχαρισμένως ἐκείνῳ καὶ καθ’ ὑπηρεσίαν ἀνέγραφεν, μόνων ἁπτόμενος τῶν εὔκλειαν αὐτῷ φερόντων, πολλὰ δὲ καὶ τῶν ἐμφανῶς ἀδίκων ἀντικατασκευάζων καὶ μετὰ πάσης σπουδῆς ἐπικρυπτόμενος, ὅς γε καὶ τὸν Μαριάμμης θάνατον καὶ τῶν παίδων αὐτῆς οὕτως ὠμῶς τῷ βασιλεῖ πεπραγμένον εἰς εὐπρέπειαν ἀνάγειν βουλόμενος ἐκείνης τε ἀσέλγειαν καὶ τῶν νεανίσκων ἐπιβουλὰς καταψεύδεται, καὶ διατετέλεκεν τῇ γραφῇ τὰ μὲν πεπραγμένα δικαίως τῷ βασιλεῖ περιττότερον ἐγκωμιάζων, ὑπὲρ δὲ τῶν παρανομηθέντων ἐσπουδασμένως ἀπολογούμενος. ἐκείνῳ μὲν οὖν πολλὴν ἄν τις, ὡς ἔφην, ἔχοι τὴν συγγνώμην· οὐ γὰρ ἱστορίαν τοῖς ἄλλοις, ἀλλὰ ὑπουργίαν τῷ βασιλεῖ ταύτην ἐποιεῖτο. ἡμεῖς δὲ καὶ γένους ὄντες ἀγχοῦ τῶν ἐξ Ἀσαμωναίου βασιλέων καὶ διὰ τοῦτο σὺν τιμῇ τὴν ἱερωσύνην ἔχοντες τὸ ψεύσασθαί τι περὶ αὐτῶν οὐκ εὐπρεπὲς ὑπειληφότες καθαρῶς καὶ δικαίως ἐκτίθεμεν τὰς πράξεις, πολλοὺς μὲν τῶν ἐγγόνων τῶν ἐκείνου καὶ βασιλεύοντας ἔτι δι’ ἐντροπῆς ἔχοντες, τὴν δ’ ἀλήθειαν πρὸ ἐκείνων τετιμηκότες, ἣν ὅτε δικαίως ἐγίνετο συνέβη τε παρ’ αὐτοῖς ἐκείνοις ὀργῆ τυγχάνειν.", "st": "16.7.1"}, {"sp": "N", "t": "Ἡρώδης δὲ διὰ τὴν ἐπιχείρησιν, ἣν ἐποιήσατο τῷ τάφῳ, χεῖρον ἐδόκει πράττειν ἐν τοῖς κατὰ τὴν οἰκίαν, εἴτε δὴ τοῦ μηνίματος ἐπιδόντος εἰς ἃ μάλιστα καὶ πρότερον ἐνόσει πλείω γενέσθαι πρὸς ἀνηκέστους ἐξελθεῖν συμφοράς, εἴτε καὶ τῆς τύχης ἐν ἐκείνῳ τὴν ἐπίθεσιν ποιουμένης ἐν οἷς τὸ κατὰ τὴν αἰτίαν εὔκαιρον οὐ μικρὰν πίστιν παρεῖχεν τοῦ διὰ τὴν ἀσέβειαν αὐτῷ τὰς συμφορὰς ἀπηντηκέναι. στάσις γὰρ ἦν ὥσπερ ἐμφυλίου πολέμου κατὰ τὴν αὐλὴν καὶ μίση πρὸς ἀλλήλους ἀνθυπερβαλλομένων ταῖς διαβολαῖς. ἐστρατήγει δ’ ἀεὶ κατὰ τῶν ἀδελφῶν Ἀντίπατρος δεινὸς ὢν ἔξωθεν μὲν περιβάλλειν αὐτοὺς ταῖς αἰτίαις, αὐτὸς δὲ πολλάκις ἀπολογουμένου τόπον λαμβάνων, ἵν’ ᾖ τὸ δοκοῦν εὔνουν πιστὸν αὐτῷ πρὸς τὰς ἐπιχειρήσεις ὧν ἐδόκει. καὶ τούτῳ τῷ τρόπῳ ποικίλως ἐκπεριεληλύθει τὸν πατέρα μόνος ὑπὲρ τῆς ἐκείνου σωτηρίας ἅπαντα πράττειν αὐτὸς πεπιστευκώς. ὁ δὲ καὶ Πτολεμαῖον, ὃς ἦν αὐτῷ διοικητὴς τῶν τῆς βασιλείας πραγμάτων, Ἀντιπάτρῳ συνίστη καὶ μετὰ τῆς ἐκείνου μητρὸς ὑπὲρ τῶν ἐπειγόντων ἐβουλεύετο. καὶ καθόλου τὰ πάντα ἦσαν οὗτοι καὶ πράττειν ὅσα θέλοιεν καὶ πρὸς δύσνοιαν ἄγειν τὸν βασιλέα τῶν ἔξωθεν οἷς ἐδόκει συμφέρειν. οἱ δ’ ἐκ τῆς Μαριάμμης χαλεπώτερον ἀεὶ διετίθεντο, καὶ τὴν αἰτίαν ὑπ’ εὐγενείας οὐκ ἔφερον παρεωσμένοι καὶ τάξιν ἀτιμοτέραν ἔχοντες. αἵ γε μὴν γυναῖκες, ἡ μὲν Ἀλεξάνδρῳ συνοικοῦσα θυγάτηρ Ἀρχελάου Γλαφύρα μῖσος εἶχεν εἰς τὴν Σαλώμην κατά τε τὴν πρὸς τὸν ἄνδρα διάθεσιν κἀκ τοῦ πρὸς τὴν ἐκείνης θυγατέρα δοκεῖν ὑπερηφανώτερον διακεῖσθαι· συνῴκει μὲν γὰρ Ἀριστοβούλῳ, τὴν δὲ ἰσοτιμίαν αὐτῆς ἀναξιοπάθει Γλαφύρα.", "st": "16.7.2"}, {"sp": "N", "t": "Δευτέρας οὖν ταύτης ἔριδος ἐμπεπτωκυίας οὐδ’ ὁ τοῦ βασιλέως ἀδελφὸς Φερώρας ἔξω ταραχῆς ἦν, ἰδίαν δὲ ὑπόθεσιν ὑποψίας καὶ μίσους εἶχεν· ἐμπεπτώκει μὲν γὰρ εἰς ἔρωτα δουλευούσης αὐτῷ γυναικός, ἥττητο δὲ τῆς ἀνθρώπου μεμηνότως ἐπὶ τοσοῦτον κρατούμενος, ὥστ’ αὐτῷ καὶ τῆς τοῦ βασιλέως ἐγγυηθείσης θυγατρὸς τὴν μὲν ὑπερηφανῆσαι, πρὸς δὲ τῇ δούλῃ τὸν νοῦν εἶχεν. ἤχθετο δὲ ἀτιμασθεὶς Ἡρώδης τῷ πολλὰ μὲν εὐεργετῆσαι τὸν ἀδελφόν, δυνάμει δὲ καὶ κοινωνὸν ἔχειν τῆς βασιλείας, οὐχ ὅμοιον εἰς τὰς ἀμοιβὰς ὁρῶν, κἀν τῷ προσώπῳ δυστυχεῖν ᾤετο. καὶ τὴν μὲν κόρην μὴ τυχὼν Φερώρα δικαίου παιδὶ Φασαήλου δίδωσιν, αὐτὸς δὲ χρόνου διελθόντος οἰόμενος ἤδη παρηκμακέναι τὴν ἐπιθυμίαν τἀδελφῷ περί τε τῶν πρώτων ᾐτιᾶτο καὶ τὴν δευτέραν ἠξίου λαμβάνειν, Κύπρος ἐκαλεῖτο. Φερώρᾳ δὲ συμβουλεύει Πτολεμαῖος ἤδη ποτὲ παυσαμένῳ τῆς εἰς τὸν ἀδελφὸν ἀτιμίας καταβαλεῖν τὸν ἔρωτα· καὶ γὰρ αἰσχρὸν εἶναι δούλης ἡττώμενον ἀποστερεῖν μὲν αὑτὸν τῆς εὐνοίας τῆς παρὰ βασιλέως, αἴτιον δὲ κἀκείνῳ ταραχῆς καὶ μίσους πρὸς αὐτὸν καθίστασθαι. ταῦτ’ ἐκεῖνος ἰδὼν λυσιτελήσοντα τῷ καὶ πρότερον ἐν διαβολαῖς γενόμενος συνεγνῶσθαι, τὴν μὲν ἄνθρωπον ἤδη καὶ παῖδα ἐξ αὐτῆς ἔχων ἀποπέμπεται, βασιλεῖ δ’ ὡμολόγει λήψεσθαι τὴν δευτέραν αὐτοῦ θυγατέρα καὶ τριακοστὴν ἡμέραν συνέθετο τοῦ γάμου, συνεπομνύμενος ὡς οὐδὲν ἔτι κοινώνημα πρὸς τὴν ἀποπεμφθεῖσαν ἔσται. διελθουσῶν δὲ τῶν τριάκοντα ἡμερῶν τοσοῦτον ἦν ἥττων τοῦ ἔρωτος, ὥστε μηδὲν μὲν ἔτι ποιῆσαι τῶν ὡμολογημένων, πάλιν δὲ διατελεῖν ἐπὶ τῇ πρώτῃ. ταῦτα φανερῶς ἤδη τὸν Ἡρώδην ἐλύπει καὶ πρὸς ὀργὴν ἦγεν. ἦσαν οὖν λόγοι τινὲς ἀεὶ παραπίπτοντες παρ’ αὐτοῦ, καὶ πολλοὶ τὴν ὀργὴν τοῦ βασιλέως ἀφορμὴν τῶν κατὰ Φερώρου διαβολῶν ἐποιοῦντο. διέλειπεν δὲ οὐκ ἔσθ’ ἥτις ἡμέρα οὐδ’ ὥρα, καθ’ ἣν ἀτρεμεῖν αὐτῷ συνέβαινεν, ἀλλ’ ἀεί τι προσέπιπτεν καινῶν ἀγωνισμάτων συγγενῶν καὶ φιλτάτων εἰς ἀλλήλους πεποιημένων. τοῦτο μὲν γὰρ ἡ Σαλώμη χαλεπὴ καὶ δύσνους οὖσα τοῖς ἐκ Μαριάμμης οὐδὲ τὴν ἑαυτῆς θυγατέρα συνοικοῦσαν Ἀριστοβούλῳ θατέρῳ τῶν νεανίσκων εἴα τῇ τοῦ γάμου πρὸς ἐκεῖνον εὐνοίᾳ χρῆσθαι, λέγειν τε εἴ τι λαλήσειεν κατ’ ἰδίαν ἀναπείθουσα καὶ μηνύειν ἑαυτῇ κἀν τοῖς προσκρούμασιν, οἷα συμβαίνει, πολλὰς ὑποψίας εἰσάγουσα. δι’ ὧν αὐτὴ μὲν ἅπαντα τὰ κατ’ ἐκείνους ἐμάνθανεν, δύσνουν δὲ τὴν παῖδα τῷ νεανίσκῳ πεποιήκει. χαριζομένη δ’ ἐκείνη τῇ μητρὶ πολλάκις ἔλεγεν, ὡς μέμνηνται μὲν ἰδιάζοντες ἐκεῖνοι τῆς Μαριάμμης, ἐστυγήκασι δὲ τὸν πατέρα, συνεχὲς δὲ διαπειλοῦσιν, εἰ τύχοιεν αὐτοί ποτε τῆς ἀρχῆς, τοὺς μὲν ἐκ τῶν ἄλλων γυναικῶν παῖδας Ἡρώδῃ γεγενημένους κωμογραμματεῖς καταστήσειν· ἁρμόσειν γὰρ εἰς τοιαύτην χρείαν τὸ νῦν ἐπιμελὲς αὐτῶν καὶ πρὸς παιδείαν ἐσπουδασμένον. τὰς δὲ γυναῖκας, εἴ ποτε καὶ ταύτας ἴδοιεν τοῦ μητρῴου κόσμου μετειληφυίας, ἀντὶ τῆς παρούσης ἁβρότητος ἀπειλεῖν, ὡς τρύχεσιν ἠμφιεσμέναι καθειργοῦνται μηδὲ τὸν ἥλιον βλέπουσαι. ταῦτ’ εὐθὺς ἀπηγγέλλετο διὰ τῆς Σαλώμης τῷ βασιλεῖ· κἀκεῖνος ἤκουεν μὲν ἀλγεινῶς, ἐπειρᾶτο δὲ διορθοῦν, ἐκακοῦτο δὲ ταῖς ὑποψίαις καὶ χείρων ἀεὶ γινόμενος ἅπασιν κατὰ πάντων ἐπίστευεν. οὐ μὴν ἀλλὰ τότε μὲν ἐπιπλήξας τοῖς παισὶν ἀπολογησαμένων ῥᾴων εἰς τὸν καιρὸν ἐγίνετο, ταῖς δ’ ἑξῆς πολὺ χείρω προσέπεσεν.", "st": "16.7.3"}, {"sp": "N", "t": "Ὁ γὰρ Φερώρας ἐλθὼν παρὰ τὸν Ἀλέξανδρον ἔχοντα τὴν Ἀρχελάου θυγατέρα Γλαφύραν, ὡς ἐδηλώσαμεν, Σαλώμης ἔφη λεγούσης ἀκηκοέναι τὸν Ἡρώδην ἡττῆσθαι τοῦ τῆς Γλαφύρας ἔρωτος καὶ δυσπαρηγόρητον αὐτῷ τὴν ἐπιθυμίαν εἶναι. τοῦτο οὖν ἐκεῖνος ἀκούσας ὑπό τε νεότητος καὶ ζηλοτυπίας ἐξεκαίετο καὶ τὰ κατὰ τιμὴν εἰς τὴν παῖδα γινόμενα παρ’ Ἡρώδου, πολλάκις δ’ ἦσαν αἱ τοιαῦται φιλοφρονήσεις, ἐπὶ τὸ χεῖρον ἐλάμβανεν ἐξ ὑπονοιῶν διὰ τὸν ἐκπεσόντα λόγον. οὐκ ἐκαρτέρησέν τε τὴν ὀδύνην τοῦ πράγματος, ἀλλὰ ἐλθὼν πρὸς τὸν πατέρα καταμηνύει τὰ ὑπὸ τοῦ Φερώρα ῥηθέντα μετὰ δακρύων. Ἡρώδης δὲ πολὺ μᾶλλον ἐκπαθὴς γενόμενος καὶ τὸ σὺν αἰσχύνῃ τῆς διαβολῆς ἐψευσμένον οὐ φέρων ἐτετάρακτο. καὶ πολλάκις μὲν ὠδύρετο τὴν πονηρίαν τῶν οἰκείων οἷος εἰς αὐτοὺς γενόμενος οἵων τυγχάνοι, μεταπέμπεται δὲ τὸν Φερώραν καὶ προσονειδίσας κάκιστε πάντων, εἶπεν, εἰς τοῦτο τῆς ἀμέτρου καὶ περιττῆς ἦλθες ἀχαριστίας, ὡς τοιαῦτα μὲν περὶ ἡμῶν νοῆσαι, τοιαῦτα δὲ λαλεῖν; ἆρ’ οὐχ ὁρῶ τὴν σὴν προαίρεσιν, ὡς οὐ βλασφημίας ἐστοχασμένος τοὺς τοιούτους λόγους τῷ παιδὶ προσήνεγκας, ἐπιβουλὴν δὲ καὶ φάρμακον αὐτοὺς ποιούμενος τῆς ἐμῆς ἀπωλείας; τίς γὰρ ἄν, εἰ μὴ δαιμόνων ἀγαθῶν ἔτυχεν, ὥσπερ οὗτος ὁ παῖς, ἠνέσχετο τὸν πατέρα μὴ τίσασθαι διὰ τοιαύτην ὑποψίαν; πότερον δὲ λόγον εἰς τὴν ψυχὴν ἢ ξίφος εἰς τὴν δεξιὰν ἐμβαλεῖν αὐτῷ δοκεῖς κατὰ τοῦ γεγεννηκότος; τί δέ σοι βούλεται τὸ μισοῦντά τε αὐτὸν καὶ τὸν ἀδελφὸν αὐτοῦ πρὸς μόνην τὴν κατ’ ἐμοῦ βλασφημίαν εὔνοιαν ὑποκρίνασθαι καὶ περὶ τούτων λέγειν, ἃ τῆς σῆς ἀσεβείας ἦν καὶ νοῆσαι καὶ διαβαλεῖν; ἔρρε κάκιστος εἰς εὐεργέτην καὶ ἀδελφὸν γενόμενος. καὶ σοὶ μὲν ἡ συνείδησις αὕτη συζήσειεν, ἐγὼ δὲ νικῴην ἀεὶ τοὺς ἐμοὺς μήτε ἀμυνόμενος κατ’ ἀξίαν καὶ μειζόνως εὐεργετῶν ἢ τυχεῖν εἰσι δίκαιοι.", "st": "16.7.4"}, {"sp": "N", "t": "Τοιαῦτα μὲν οὖν ὁ βασιλεύς. Φερώρας δ’ ἐπ’ αὐτοφώρῳ τῇ μοχθηρίᾳ Σαλώμην ἔφη ταῦτα συμπείσειν καὶ παρ’ ἐκείνης εἶναι τοὺς λόγους. ἡ δὲ ὡς μόνον ἤκουσεν, ἐτύγχανεν δὲ παροῦσα, πιθανῶς ἀνεβόησεν, ὡς οὐδὲν εἴη παρ’ αὐτῆς τοιοῦτον, καὶ ὅτι διὰ σπουδῆς ἐστιν ἅπασιν εἰς μῖσος ἀγαγεῖν αὐτὴν τοῦ βασιλέως καὶ πάντα τρόπον ἐνέχειν διὰ τὴν εὔνοιαν, ἣν ἔχοι περὶ τὸν Ἡρώδην ἀεὶ προγινώσκουσα τοὺς κινδύνους. ἐν δὲ τῷ παρόντι καὶ μᾶλλον ἐπιβουλεύεσθαι· μόνη γὰρ ἀναπείθουσα τὸν ἀδελφὸν ἐκβάλλειν ἣν εἶχε γυναῖκα, λαμβάνειν δὲ θυγατέρα τὴν βασιλέως εἰκότως ὑπ’ ἐκείνου μεμισῆσθαι. τοιαῦτα λεγούσης καὶ πολλάκις μὲν ἐπιδραττομένης τῶν τριχῶν, πολλάκις δὲ τυπτούσης τὰ στέρνα, ἡ μὲν ὄψις εἶχέ τι πρὸς τὴν ἄρνησιν πιθανόν, ἡ δὲ κακοήθεια τοῦ τρόπου τὴν ἐν τοῖς γινομένοις ὑπόκρισιν ἀπεσήμαινεν. ὁ δὲ Φερώρας εἰς μέσον ἀπείληπτο μηδὲν εὔσχημον εἰς ἀπολογίαν ἔχων, εἰπεῖν μὲν ὡμολογηκώς, ἀκοῦσαι δ’ οὐ πιστευόμενος. ἐγένετο δ’ ἐπὶ πλεῖον ἥ τε σύγχυσις καὶ ἡ τῶν λόγων εἰς ἀλλήλους ἅμιλλα. τέλος δὲ ὁ βασιλεὺς τόν τε ἀδελφὸν καὶ τὴν ἀδελφὴν μεμισηκὼς ἀπεπέμπετο καὶ τὸν υἱὸν ἐπαινέσας τῆς ἐγκρατείας καὶ τοῦ πρὸς αὐτὸν ἀνενεγκεῖν τοὺς λόγους ὀψὲ τῆς ὥρας περὶ θεραπείαν τοῦ σώματος ἐγένετο. τοιαύτης δὲ τῆς μάχης ἐμπεσούσης κακῶς ἤκουσεν ἡ Σαλώμη· παρ’ αὐτῆς γὰρ ἐδόκει κεκινῆσθαι τὰ περὶ τὴν διαβολήν· αἵ τε τοῦ βασιλέως γυναῖκες ἤχθοντο φύσει δυσχερεστάτην εἰδυῖαι καὶ γινομένην ἄλλοτ’ ἄλλην κατὰ καιροὺς ἐχθρὰν καὶ φίλην. ἔλεγον οὖν ἀεί τι πρὸς τὸν Ἡρώδην κατ’ αὐτῆς καί τι συμπεσὸν ἐπὶ μεῖζον ἤγαγεν τὴν εἰς τοῦτο παρρησίαν.", "st": "16.7.5"}, {"sp": "N", "t": "Ἦν μὲν γὰρ ὁ τῆς Ἀραβίας βασιλεὺς Ὀβόδας ἀπράγμων καὶ νωθὴς τὴν φύσιν, Σύλλαιος δ’ αὐτῷ διῴκει τὰ πολλὰ δεινὸς ἀνὴρ καὶ τὴν ἡλικίαν νέος ἔτι καὶ καλός. ὑπὸ χρείας οὖν τινος ἐλθὼν ὡς τὸν Ἡρώδην συνδειπνῶν εἶδεν τὴν Σαλώμην, καὶ τὸν νοῦν ἔσχεν πρὸς αὐτήν, γινώσκων δ’ ὅτι καὶ χήρα τυγχάνοι διελέγετο. Σαλώμη δὲ καὶ χεῖρον ἢ πάλαι φερομένη παρὰ τἀδελφῷ καὶ τὸν νεανίσκον οὐκ ἀπαθῶς ὁρῶσα πρὸς τὸν γάμον ὥρμητο, ταῖς τε μεταξὺ φοιτώντων ἐπὶ τὸ δεῖπνον ἐνεφαίνετο πλείω τε καὶ μὴ μέτρια τῆς ἐκείνων πρὸς ἀλλήλους ὁμολογίας. ταῦτα δὲ αἱ γυναῖκες ἀνέφερον τῷ βασιλεῖ διαγελῶσαι τὴν ἀσχημοσύνην, Ἡρώδης δὲ καὶ παρὰ τοῦ Φερώρα προσεπυνθάνετο καὶ τηρεῖν ἠξίου παρὰ τὸ δεῖπνον, πῶς τὰ πρὸς ἀλλήλους ἐσχήκασιν. ἐκεῖνος δὲ ἀπήγγελλεν, ὅτι καὶ νεύμασιν καὶ βλέμμασιν οὐκ ἄδηλοι τῆς ὁρμῆς εἰσιν ἀμφότεροι. μετὰ τοῦτο ὁ μὲν Ἄραψ ὕποπτος ὢν ἀπῄει· διαλιπὼν δὲ δύο μῆνας ἢ τρεῖς ἔρχεται πάλιν ὡς ἐπ’ αὐτῷ τούτῳ καὶ λόγους Ἡρώδῃ προσέφερεν, ἀξιῶν αὐτῷ τὴν Σαλώμην δοθῆναι πρὸς γάμον· ἔσεσθαι γὰρ οὐκ ἀλυσιτελὲς τὸ κῆδος ἐπιμιξίᾳ τῆς τῶν Ἀράβων ἀρχῆς, ἣν αὐτῷ καὶ νῦν ἤδη παρεῖναι δυνάμει καὶ μᾶλλον ὀφείλεσθαι. τοῦ δὲ Ἡρώδου τὸν λόγον ἀναφέροντος καὶ πυνθανομένου τῆς ἀδελφῆς, εἰ πρὸς τὸν γάμον ἑτοίμως ἔχει, ταχέως μὲν ἐκείνη προσήκατο, Σύλλαιος δὲ ἀξιούντων αὐτὸν ἐγγραφῆναι τοῖς τῶν Ἰουδαίων ἔθεσι καὶ τότε γαμεῖν, ἄλλως γὰρ οὐκ εἶναι δυνατόν, οὐχ ὑπομείνας, ἀλλὰ καὶ καταλευσθήσεσθαι πρὸς τῶν Ἀράβων εἰπών, εἰ τοῦτο πράξειεν, ἀπαλλάττεται. Σαλώμην οὖν ὅ τε Φερώρας ἤδη διέβαλλεν εἰς ἀκρασίαν καὶ μᾶλλον αἱ γυναῖκες, λέγουσαι κοινωνίαν αὐτῇ γενέσθαι πρὸς τὸν Ἄραβα. τήν τε κόρην, ἣν τἀδελφῷ κατενεγύησεν ὁ βασιλεύς, ἣν ὁ μὲν Φερώρας οὐκ ἔλαβεν, ὡς προεῖπον, ἡττημένος τῆς γυναικός, αἰτούσης Σαλώμης εἰς τὸν υἱὸν τὸν ἐκ Κοστοβάρου γενόμενον ὥρμητο μὲν ἐκείνῳ συνοικίσαι, μεταπείθεται δὲ ὑπὸ τοῦ Φερώρα τόν τε νεανίσκον οὐκ εὔνουν ἔσεσθαι λέγοντος διὰ τὴν ἀπώλειαν τοῦ πατρὸς καὶ δικαιότερον εἶναι λαβεῖν τὸν αὐτοῦ παῖδα τῆς τετραρχίας ὄντα διάδοχον. οὕτω δὲ συγγνώμην ᾐτεῖτο καὶ μὴ πείσας οὕτως. ἐκείνη μὲν οὖν ἀντιμετατεθείσης τῆς ἐγγύης ἐγαμεῖτο τῷ Φερώρα μειρακίῳ φερνὴν ἐπιδόντος ἑκατὸν τάλαντα τοῦ βασιλέως.", "st": "16.7.6"}, {"sp": "N", "t": "Οὐκ ἀνεῖτο δὲ τὰ κατὰ τὴν οἰκίαν ἀεὶ καὶ μείζους τὰς ταραχὰς λαμβάνοντα, καὶ συμπίπτει τι τοιοῦτον ἐξ αἰτίας μὲν οὐκ εὐπρεποῦς, χωρῆσαν δὲ πρόσω κατὰ δυσχέρειαν· ἦσαν εὐνοῦχοι τῷ βασιλεῖ διὰ κάλλος οὐ μετρίως ἐσπουδασμένοι. τούτων ὁ μὲν οἰνοχοεῖν, ὁ δὲ δεῖπνον προσφέρειν, ὁ δὲ κατακοιμίζειν βασιλέα πεπίστευτο καὶ τὰ μέγιστα τῶν ἐν ταῖς ἀρχαῖς. καί τις ἀγγέλλει τῷ βασιλεῖ διαφθαρῆναι τούτους ὑπὸ Ἀλεξάνδρου τοῦ παιδὸς ἐπὶ πολλοῖς χρήμασιν. ἀνακρίναντι δὲ περὶ μὲν τῆς γεγενημένης πρὸς αὐτὸν κοινωνίας καὶ μίξεως ὡμολόγουν, ἄλλο δὲ οὐδὲν δυσχερὲς εἰς τὸν πατέρα συνειδέναι. βασανιζόμενοι δὲ μᾶλλον κἀν ταῖς ἀνάγκαις ὄντες ἐπιτεινόντων ἀεὶ τῶν ὑπηρετῶν καὶ χαριζομένων τῷ Ἀντιπάτρῳ τὸ τοιοῦτον, ἔλεγον ὡς εἴη δυσμένεια πρὸς τὸν πατέρα καὶ μῖσος ἔμφυτον Ἀλεξάνδρῳ. παραινοίη δ’ αὐτοῖς Ἡρώδην μὲν ἀπεγνωκέναι περιττὸν ἤδη τετυχηκότα καὶ τῷ γήρᾳ παρακάλυμμα τοῦ χρόνου ποιούμενον, μελαίνοντα τὰς τρίχας καὶ κλέπτοντα τὸν ἔλεγχον τῆς ἡλικίας· εἰ δ’ αὐτῷ προσέχοιεν τὸν νοῦν, περιγενομένης τῆς βασιλείας, ἣν καὶ μὴ βουλομένου τοῦ πατρὸς οὐκ ἄλλου τινὸς εἶναι, ταχὺ τὸν πρῶτον ἕξειν ἐν αὐτῇ τόπον· οὐ γὰρ μόνον διὰ τὸ γένος, ἀλλ’ ἤδη καὶ ταῖς παρασκευαῖς ἕτοιμον αὐτῷ τὸ κρατεῖν εἶναι· πολλοὶ μὲν γὰρ τῶν ἡγεμόνων, πολλοὶ δὲ τῶν φίλων συνεστᾶσιν οὐχὶ πονηροὶ πᾶν ὁτιοῦν καὶ δρᾶν καὶ πάσχειν.", "st": "16.8.1"}, {"sp": "N", "t": "Τούτων τῶν λόγων ἀκούσας Ἡρώδης ὅλος ἐγένετο τῆς ἐπηρείας καὶ τοῦ δέους, τὰ μὲν εἰς ὕβριν ῥηθέντα χαλεπῶς, τὰ δ’ εἰς ὑπόνοιαν οὐκ ἀκινδύνως ἐκλαβών, ὥστε καὶ μᾶλλον ἐξ ἀμφοτέρων ἠρεθίζετο καὶ πικρὸς ὢν ἐδεδοίκει, μὴ καί τι ταῖς ἀληθείαις συνέστηκεν ἐπ’ αὐτὸν ἰσχυρότερον ἢ φυλάξασθαι πρὸς ἐκεῖνον τὸν καιρόν. ἔνθεν οὐδ’ ἐκ φανεροῦ τὴν ἔρευναν ἐποιεῖτο, κατασκόπους δὲ τῶν ὑπονοουμένων διέπεμψεν. ὑποψία τε καὶ μίση πρὸς ἅπαντας ἦν, καὶ τὴν ὑπόνοιαν ἐπ’ ἀσφαλείᾳ λαμβάνων πολλὴν καὶ κατὰ τῶν οὐκ ἀξίων αὐτῇ χρώμενος διετέλει. πέρας τε οὐδὲν ἦν, ἀλλὰ μένειν οἱ νομιζόμενοι μᾶλλον ὡς ἂν καὶ μᾶλλον ἰσχύοντες ἐδόκουν αὐτῷ φοβεροί· τοῖς δ’ οἷς οὐκ ἦν συνήθεια πλείων ὀνομάσαι μόνον ἐδόκει, καὶ μέρος εὐθὺς ἀσφαλείας ἐδόκουν ἀπολλύμενοι. τέλος τε οἱ περὶ αὐτὸν ἐν τῷ μηδὲν ἔχειν βέβαιον εἰς ἐλπίδα σωτηρίας ἐπ’ ἀλλήλους ἐτράπησαν, νομίζοντες μέν, εἰ φθάσας ἕτερος τὸν ἕτερον διαβάλοι, τοῦτ’ αὐτῷ πρὸς σωτηρίαν φέρειν, ἐπίφθονοι δ’ εἴ ποτε τύχοιεν ὧν ἠξίουν γενόμενοι καὶ τὸ δικαίως αὐτοὶ παθεῖν ἐφ’ οἷς ἄλλους ἠδίκησαν προσλαμβάνοντες μόνον. ἤδη γοῦν οἰκείας τινὲς ἔχθρας ἐπεξῄεσαν τῷ τοιούτῳ τρόπῳ καὶ καταφωραθέντες ἐν τοῖς ὁμοίοις ἐγένοντο, τὸν καιρὸν ὥσπερ ὄργανον καὶ πάγην ἐπὶ τοὺς ἐχθροὺς νοοῦντες καὶ συναλισκόμενοι τῇ πείρᾳ, καθ’ ἣν ἑτέροις ἐπεβούλευον. ἥ τε γὰρ μετάνοια τῷ βασιλεῖ ταχὺ διὰ τὸ μὴ προφανῶς ἁμαρτάνοντας ἀναιρεῖν ἐπεγίνετο καὶ ταύτης τὸ χαλεπὸν οὐκ εἰς τὸ παύσασθαι τὰ ὅμοια δρᾶν, ἀλλ’ εἰς τὸ τιμωρήσασθαι τοῖς ἴσοις τοὺς ἐνδειξαμένους ἀπηρτίζετο.", "st": "16.8.2"}, {"sp": "N", "t": "Τοιαύτη μὲν ἦν τῶν περὶ τὴν αὐλὴν ταραχή. πολλοῖς δὲ τῶν φίλων ἤδη καὶ τοῦτ’ αὐτὸ προεῖπεν, ὡς οὔτ’ ἐμφανίζεσθαι δέον αὐτῷ λοιπὸν οὔτ’ εἰς τὸ βασίλειον εἰσιέναι. ταύτην δὲ τὴν παραγγελίαν ἐποιεῖτο καθ’ ὧν ἡ παρρησία ἐλάττονος ἢ πλείονος ἐντροπῆς μετειλήφει· καὶ γὰρ Ἀνδρόμαχον καὶ Γέμελλον ἄνδρας ἄνωθεν φίλους αὐτῷ, καὶ πολλὰ μὲν περὶ τὰς βασιλικὰς χρείας ἔν τε πρεσβείαις καὶ συμβουλίαις ὀνήσαντας αὐτοῦ τὸν οἶκον, συμπαιδεύσαντας δὲ τοὺς υἱοὺς καὶ τί γὰρ ἢ πρῶτον παρρησίας τόπον ἐσχηκότας παρῃτήσατο τότε, τὸν μὲν, ὅτι Δημήτριος ὁ παῖς αὐτοῦ συνήθης ἦν Ἀλεξάνδρῳ, Γέμελλον δὲ εὔνουν ἐπιστάμενος ἐκείνῳ· καὶ γὰρ ἐν ταῖς τροφαῖς κἀν τῇ παιδείᾳ παραγεγόνει καὶ τὴν ἐν τῇ Ῥώμῃ συνδιέτριβεν ἀποδημίαν. παρῃτήσατο δὲ καὶ τούτους ἡδέως μὲν ἂν καὶ χεῖρον, ὑπὸ δὲ τοῦ μὴ κατ’ ἀνδρῶν οὐκ ἀσήμων ἔχειν τὴν ἄχρι τοσούτων παρρησίαν τήν τε τιμὴν καὶ τὸ δύνασθαι κωλύειν ἁμαρτάνοντας παραιρούμενος", "st": "16.8.3"}, {"sp": "N", "t": "Ἦν δὲ τούτων ἁπάντων αἴτιος Ἀντίπατρος, ὃς ἐπειδὴ τὸ νενοσηκὸς τῆς τοῦ πατρὸς παρρησίας κατέμαθεν, ἔκπαλαι μὲν συνεδρεύων αὐτῷ προσέκειτο καὶ μᾶλλον ἐδόκει τι περαίνειν, τῶν ἀντέχειν δυναμένων ἕκαστος εἰ ὑπεξαιρεθείη. τότε γοῦν τῶν περὶ τὸν Ἀνδρόμαχον ἀπελαθέντων λόγου καὶ παρρησίας πρῶτον μὲν ὁ βασιλεὺς ὅσους ᾤετο πιστοὺς Ἀλεξάνδρῳ βασάνοις ἀνέκρινεν, εἴ τι κατ’ αὐτοῦ τολμηθὲν εἰδείησαν· οἱ δὲ ἀπέθνησκον οὐδὲν ἔχοντες λέγειν. τῷ δ’ ἦν φιλονεικίας αἴτιον, εἰ μή τι τοιοῦτον οἷον ἐδόκει κακῶς εὑρίσκοιτο, καὶ δεινὸς Ἀντίπατρος τὸν μὲν ὑπ’ αὐτῆς τῆς ἀληθείας ἀναίτιον εἰς ἐγκράτειαν καὶ πίστιν διαβαλεῖν, ἐπιπαροξῦναι δὲ ζητεῖν ἐκ πλειόνων τὸ λανθάνον τῆς ἐπιχειρήσεως. καί τις ἐν πολλοῖς τοῖς βασανιζομένοις εἶπεν, ὡς εἰδείη τὸν νεανίσκον λέγοντα πολλάκις, ὅταν ἐπαινούμενος αὐτὸς τύχῃ τό τε σῶμα ὡς εἴη μέγας καὶ τὴν τοξικὴν εὔστοχος καὶ τἆλλα τὰ πρὸς ἀρετὴν ὑπὲρ ἅπαντας, ὅτι ταῦτ’ αὐτῷ κακὰ μᾶλλον ἤπερ ἀγαθὰ παρὰ τῆς φύσεώς ἐστιν· ἄχθεσθαι γὰρ ἐπ’ αὐτοῖς τὸν πατέρα καὶ φθονεῖν, αὐτός τε ὅταν μὲν ἅμα περιπατῶν συστέλλειν αὑτὸν καὶ καθαιρεῖν ὡς μὴ μείζων ὁρᾶσθαι, τοξεύων δὲ ἐν τοῖς κυνηγεσίοις ἐκείνου παρόντος ἀπὸ σκοποῦ ῥίπτειν· τὴν γὰρ φιλοτιμίαν εἰδέναι τοῦ γεγεννηκότος τούτων εὐδοκιμούντων. βασανιζομένῳ τῷ τε λόγῳ καὶ προσγινομένης ἀνέσεως τῷ σώματι προσετίθει δ’ ὅτι καὶ συνεργὸν ἔχων τὸν ἀδελφὸν Ἀριστόβουλον ἐν κυνηγεσίῳ λοχήσας φεύγειν εἰς Ῥώμην, ἐπειδὰν τοῦτ’ αὐτῷ πραχθῇ, τὴν βασιλείαν αἰτησόμενος. εὑρέθη δὲ καὶ γράμματα τοῦ νεανίσκου πρὸς τὸν ἀδελφόν, ἐν οἷς ἐμέμφετο τὸν πατέρα μὴ δίκαια ποιεῖν, Ἀντιπάτρῳ χώραν ἀπονέμοντα πρόσοδον διακοσίων ταλάντων φέρουσαν. ἐπὶ τούτοις εὐθὺς μὲν ἔδοξέν τι πιστὸν ἔχειν Ἡρώδης, ὡς ᾤετο, κατὰ τῆς τῶν παίδων ὑποψίας καὶ συλλαβὼν ἔδησεν τὸν Ἀλέξανδρον. αὖθις δὲ οὐκ ἀνίει χαλεπὸς ὤν, τὰ μὲν οὐδ’ οἷς ἤκουσεν ἄγαν πεπιστευκώς· ἀναλογιζομένῳ γὰρ ἄξιον μὲν ἐπιβουλῆς ἐξ αὐτῶν οὐδὲν ἐφαίνετο, μέμψεις δὲ καὶ νεανικαὶ φιλοτιμίαι, καὶ τὸ κτείναντα φανερῶς εἰς τὴν Ῥώμην ὁρμᾶν ἀπίθανον. ἠξίου δὲ καὶ μεῖζόν τι λαβεῖν τῆς περὶ τὸν υἱὸν παρανομίας τεκμήριον καὶ φιλόνεικος ἦν μὴ δόξαι προπετῶς τὰ δεσμὰ κατεγνωκέναι. τῶν τε φίλων τῶν Ἀλεξάνδρου βασανίζων τοὺς ἐν τέλει διέφθειρεν αὐτῶν οὐκ ὀλίγους οὐδὲν εἰπόντας ὧν ἐκεῖνος ᾤετο. πολλῆς δὲ τῆς εἰς τὸ τοιοῦτον ἑτοιμότητος οὔσης καὶ φόβου καὶ ταραχῆς περὶ τὸ βασίλειον, εἷς τις τῶν νεωτέρων ὡς ἐν ταῖς ἀνάγκαις ἐγένετο, διαπέμπειν ἔφη τοῖς ἐν Ῥώμῃ φίλοις τὸν Ἀλέξανδρον ἀξιοῦντα κληθῆναι θᾶττον ὑπὸ Καίσαρος· ἔχειν γὰρ αὐτῷ πρᾶξιν ἐπ’ αὐτὸν συνισταμένην μηνῦσαι Μιθριδάτην τὸν βασιλέα Πάρθων τοῦ πατρὸς ᾑρημένου κατὰ Ῥωμαίων φίλον· εἶναι δ’ αὐτῷ καὶ φάρμακον ἐν Ἀσκάλωνι παρεσκευασμένον.", "st": "16.8.4"}, {"sp": "N", "t": "Τούτοις ἐπίστευσεν Ἡρώδης καί τινα παραμυθίαν τῆς προπετείας εἴληφεν ἐν τοῖς κακοῖς ὑπὸ τῶν χειρόνων κολακευόμενος. καὶ τὸ μὲν φάρμακον εὐθὺς ἐσπουδακότι ζητεῖν οὐχ εὑρέθη. τὴν δ’ ὑπερβολὴν τῶν κακῶν Ἀλέξανδρος ἐκ φιλονεικίας ἐπιρρῶσαι θέλων εἰς μὲν ἄρνησιν οὐκ ἐτράπετο, μετῄει δὲ τὴν προπέτειαν τοῦ πατρὸς ἁμαρτίᾳ μείζονι, τάχα δὲ καὶ διὰ τούτου βουλόμενος δυσωπῆσαι τὸ πρὸς τὰς διαβολὰς ἕτοιμον, οὐχ ἥκιστα δὲ εἰ καὶ ἔτυχεν πιστευθεὶς κακοῦν αὐτόν τε καὶ πᾶσαν τὴν βασιλείαν προῃρημένος. γράμματα γὰρ γράψας ἐν βιβλίοις τέσσαρσιν ἀπέστειλεν, ὡς οὐδὲν δεῖ βασανίζειν οὐδὲ περαιτέρω χωρεῖν· γενέσθαι γὰρ τὴν ἐπιβουλὴν καὶ ταύτης συλλαμβάνειν τόν τε Φερώραν καὶ τοὺς πιστοτάτους αὐτῷ τῶν φίλων, Σαλώμην δὲ καὶ νύκτωρ ἐπεισελθοῦσαν ἄκοντι μιγῆναι· καὶ πάντας ἐπὶ ταὐτὸν ἥκειν τοὺς θᾶττον ἐκεῖνον ἐκποδὼν ποιησαμένους ἄδειαν τῆς ἀεὶ προσδοκίας ἔχειν. ἐν τούτοις καὶ Πτολεμαῖος διεβέβλητο καὶ Σαπίννιος οἱ πιστότατοι τῷ βασιλεῖ. καὶ τί γὰρ ἢ καθάπερ λύττης τινὸς ἐμπεσούσης κατ’ ἀλλήλων οἱ πάλαι φίλτατοι τεθηρίωντο, μήτ’ ἀπολογίας μήτ’ ἐλέγχου τόπον ἕως ἀληθείας ἐχόντων, ἀλλ’ ἀεὶ γινομένης ἀκρίτου τινὸς εἰς ἅπαντας ἀπωλείας, καὶ τῶν μὲν δεσμά, τῶν δὲ θανάτους, τῶν δὲ τὸ ταῦτα μέλλειν ἐπ’ αὐτοῖς ὀδυρομένων, ἡσυχία τε καὶ κατήφεια τὸ βασίλειον ἀπεκόσμει τῆς πρώτης εὐδαιμονίας. καὶ χαλεπὸς ἦν Ἡρώδῃ πᾶς ὁ βίος ἐκτεταραγμένῳ καὶ τὸ μηδενὶ πιστεύειν μέγα τῆς προσδοκίας κολαστήριον ἔχοντι· πολλάκις γοῦν ὡς ἐπανιστάμενον αὐτῷ τὸν υἱὸν ἢ καὶ ξιφήρη παρεστῶτα διὰ φαντασίας ἐλάμβανεν. οὕτως ἡ ψυχὴ καὶ νύκτα καὶ ἡμέραν πρὸς τούτῳ γινομένη πάθος ἀνεμάξατο μανίας οὐχ ἧττον δὲ καὶ ἀνοίας. καὶ τὰ περὶ ἐκεῖνον εἶχεν οὕτως.", "st": "16.8.5"}, {"sp": "N", "t": "Ἀρχέλαος δὲ ὁ τῶν Καππαδόκων βασιλεύς, ὡς ἐπύθετο τὰ κατὰ τὸν Ἡρώδην, ἀγωνιῶν τε ὑπὲρ τῆς θυγατρὸς καὶ τοῦ νεανίσκου καὶ συναλγῶν ἀνδρὶ φίλῳ τῆς ἐπὶ τοσόνδε ταραχῆς, ἧκεν οὐκ ἐν παρέργῳ θέμενος τὰ πράγματα. καὶ καταλαβὼν οὕτως ἔχοντα τὸ μὲν ἐπιτιμᾶν ἢ φάναι γενέσθαι τι προπετὲς αὐτῷ τελέως ἀνοίκειον εἰς τὸν καιρὸν ἡγήσατο· φιλονεικήσειν γὰρ κεκακωμένον καὶ μᾶλλον ἀπολογεῖσθαι σπεύδοντα πλείονος ὀργῆς ἀναπλησθήσεσθαι· μετῄει δὲ τάξιν ἑτέραν τὴν ἐπανόρθωσιν τῶν ἠτυχημένων, ὀργιζόμενος τῷ νεανίσκῳ κἀκεῖνον ἐπιεικῆ λέγων τῷ μηδὲν ἐκ προπετείας ἐργάσασθαι, τόν τε γάμον διαλύσειν ἔφη πρὸς τὸν Ἀλέξανδρον, καὶ μηδ’ ἂν τῆς θυγατρὸς φείσασθαι, εἴ τι συνειδυῖα τούτῳ οὐ κατεμήνυσεν. τοιούτου δ’ ὄντος οὐ κατὰ προσδοκίαν ὧν Ἡρώδης ᾤετο, τὸ δὲ πλέον ὑπὲρ αὐτοῦ τὴν ὀργὴν ἐπιδεικνυμένου, μετέπιπτεν ὁ βασιλεὺς τῆς χαλεπότητος καὶ λαβὼν ἐκ τοῦ δικαίου δοκεῖν τὰ πεπραγμένα πεποιηκέναι κατὰ μικρὸν εἰς τὸ τοῦ πατρὸς ἀντιμεθίστατο πάθος. οἰκτρὸς δ’ ἦν ἐν ἀμφοτέροις, ὅτε μὲν ἀπελύοντό τινες τὰς τοῦ νεανίσκου διαβολὰς εἰς ὀργὴν ἐκταραττόμενος, ἐπειδὴ δὲ Ἀρχέλαος συγκατηγόρει, πρὸς δάκρυα καὶ λύπην οὐκ ἀπαθῆ μεθιστάμενος· ἐδεῖτο γοῦν ἐκείνου μήτε διαλύειν τὸν γάμον ὀργῆς τε ἔλαττον ἔχειν ἐφ’ οἷς ὁ νεανίσκος ἠδίκησεν. Ἀρχέλαος δὲ παραλαβὼν ἐπιεικέστερον εἴς τε τοὺς φίλους μετέφερεν τὰς διαβολάς, ἐκείνων εἶναι λέγων νέον ὄντα καὶ κακοηθείας ἀναίσθητον διαφθεῖραι, τόν τε ἀδελφὸν αὐτῷ μᾶλλον εἰς ὑποψίαν καθίστη· τοῦ γὰρ Ἡρώδου χαλεπῶς καὶ πρὸς τὸν Φερώραν ἔχοντος ὁ μὲν ἀπορίᾳ τοῦ διαλλάξοντος Ἀρχέλαον ὁρῶν μάλιστα δυνάμενον αὐτὸς τυχὼν πρὸς ἐκεῖνον ἐτράπετο μελανείμων καὶ πάντα τὰ σημεῖα τῆς μετὰ μικρὸν ἀπωλείας ἔχων, Ἀρχέλαος δὲ οὔτε ὑπερεῖδεν τὴν ἔντευξιν οὔτ’ ἔφη δυνατὸς εἶναι ταχὺ μεταπείθειν οὕτως ἔχοντα τὸν βασιλέα· βέλτιον δὲ εἶναι αὐτῷ προσιέναι καὶ δεῖσθαι, τῶν πάντων αἴτιον αὑτὸν ὁμολογοῦντα· ὠφελήσειν γὰρ οὕτως τοῦ θυμοῦ τὸ περιττόν, αὐτὸς δὲ συλλήψεσθαι παρών. ταῦτα δὲ πεισθέντος αὐτοῦ συναμφότερον ἦν διαπεπραγμένον, αἵ τε διαβολαὶ παρὰ δόξαν ἀφῄρηντο τοῦ νεανίσκου καὶ Φερώραν Ἀρχέλαος διαλλάξας οὕτως εἰς Καππαδοκίαν ἀπῄει, κεχαρισμένος ὡς οὐκ ἄλλος ἐν τῇ τότε περιστάσει τῶν καιρῶν Ἡρώδῃ γενόμενος. ὅθεν καὶ δώροις αὐτὸν ἐτίμησεν πολυτελεστάτοις κἀν τοῖς ἄλλοις μεγαλοπρεπῶς ἐν τοῖς μάλιστα φίλτατον ἡγησάμενος. ἐποιήσατο δὲ καὶ συνθήκας εἰς Ῥώμην ἐλθεῖν, ἐπειδὴ περὶ τούτων ἐγέγραπτο Καίσαρι, καὶ μέχρις Ἀντιοχείας ἐπὶ τὸ αὐτὸ παρῆλθον. ἐκεῖ καὶ τὸν ἡγεμόνα Συρίας Τίτιον ἐκ διαφορᾶς Ἀρχελάῳ κακῶς ἔχοντα διήλλαξεν Ἡρώδης καὶ πάλιν εἰς Ἰουδαίαν ὑποστρέφει.", "st": "16.8.6"}, {"sp": "N", "t": "Γενομένῳ δὲ ἐν τῇ Ῥώμῃ κἀκεῖθεν ἐπανήκοντι συνέστη πόλεμος πρὸς τοὺς Ἄραβας ἐξ αἰτίας τοιαύτης· οἱ κατοικοῦντες τὸν Τράχωνα Καίσαρος ἀφελομένου Ζηνόδωρον καὶ προσθέντος Ἡρώδῃ τὴν χώραν λῃστεύειν μὲν οὐκ εἶχον ἐξουσίαν ἔτι, γεωργεῖν δὲ καὶ ζῆν ἡμέρως ἠναγκάζοντο. τόδ’ ἦν ἐκείνοις οὐχ αἱρετὸν οὐδὲ λυσιτέλειαν ἔφερεν ἡ γῆ πονούντων. ὅμως δὲ κατ’ ἀρχὰς μὲν οὐκ ἐπιτρέποντος τοῦ βασιλέως ἀπείχοντο τῶν εἰς τοὺς περιοίκους ἀδικημάτων, καὶ πολλὴ διὰ τοῦτο ἦν εὐδοξία τῆς ἐπιμελείας Ἡρώδῃ. πλεύσαντος δ’ εἰς τὴν Ῥώμην, ὅτε καὶ τοῦ παιδὸς Ἀλεξάνδρου κατηγόρει καὶ παραθησόμενος Ἀντίπατρον τὸν υἱὸν παρεληλύθει Καίσαρι, λόγον ὡς ἀπολωλὼς εἴη διασπείροντες οἱ τὸν Τράχωνα νεμόμενοι τῆς τε ἀρχῆς ἀπέστησαν καὶ πάλιν ἐπὶ τὰ συνήθη τοὺς πλησιοχώρους ἀδικεῖν ἐτρέποντο. τότε μὲν οὖν αὐτοὺς οἱ στρατηγοὶ τοῦ βασιλέως ἀπόντος ἐχειρώσαντο. περὶ τετταράκοντα δέ τινες ἀρχιλῃσταὶ κατὰ δέος τῶν ἡλωκότων ἐξέλιπον μὲν τὴν χώραν, εἰς δὲ τὴν Ἀραβίαν ἀφορμήσαντες Συλλαίου δεξαμένου μετὰ τὴν ἀποτυχίαν τοῦ Σαλώμης γάμου, τόπον τε ἐρυμνὸν ἐκείνου δόντος ᾤκησαν καὶ κατατρέχοντες οὐ μόνον τὴν Ἰουδαίαν ἀλλὰ καὶ τὴν κοίλην Συρίαν ἅπασαν ἐλῄζοντο, παρέχοντος ὀρμητήρια τοῦ Συλλαίου καὶ κακῶς ποιοῦσιν ἄδειαν. Ἡρώδης δὲ ἐπανελθὼν ἀπὸ τῆς Ῥώμης ἔγνω πολλὰ τῶν οἰκείων αὐτῷ κεκακωμένα, καὶ τῶν μὲν λῃστῶν ἐγκρατὴς γενέσθαι οὐκ ἠδυνήθη διὰ τὴν ἀσφάλειαν, ἣν ἐκ τῆς τῶν Ἀράβων προστασίας ἐπορίσαντο, χαλεπῶς δὲ ἔχων αὐτὸς τῶν ἀδικημάτων περιελθὼν τὸν Τράχωνα τοὺς οἰκείους αὐτῶν ἀπέσφαξεν. ἐντεῦθεν ἐκεῖνοι καὶ μᾶλλον πρὸς ὀργὰς ὧν ἐπεπόνθεισαν ὄντος αὐτοῖς καὶ νόμου πάντα τρόπον ἐπεξιέναι τοὺς τῶν οἰκείων φονεῖς ἀνυποτιμήτως τὴν Ἡρώδου πᾶσαν ἄγοντες καὶ φέροντες διετέλουν. ἐκεῖνος δὲ διελέγετο περὶ τούτων τοῖς Καίσαρος ἡγεμόσιν Σατορνίνῳ τε καὶ Οὐολομνίῳ ἐπὶ κολάσει τοὺς λῃστὰς ἐξαιτούμενος. ὅθεν ἔτι καὶ μᾶλλον ἰσχυρῶς ἐχόντων πλείους μὲν ἐγίνοντο, πάντα δὲ ἐτάραττον ἐπ’ ἀναστάσει τῆς Ἡρώδου βασιλείας χωρία καὶ κώμας πορθοῦντες καὶ τοὺς λαμβανομένους τῶν ἀνθρώπων ἀπέσφαττον, ὡς εἶναι πολέμῳ τὴν ἀδικίαν ἐοικυῖαν· ἐγεγόνεισαν γὰρ ἤδη περὶ χιλίους. ἐφ’ οἷς ἀχθόμενος Ἡρώδης τούς τε λῃστὰς ἐξῄτει καὶ χρέος ὃ διὰ Συλλαίου δανείσας ἔτυχεν Ὀβάδᾳ τάλαντα ἑξήκοντα, παρηκούσης αὐτῷ τῆς προθεσμίας ἀπολαβεῖν ἠξίου. Σύλλαιος δὲ τὸν μὲν Ὀβάδαν παρεωσμένος αὐτὸς δὲ ἅπαντα διοικῶν τούς τε λῃστὰς ἔξαρνος ἦν μὴ κατὰ τὴν Ἀραβίαν εἶναι καὶ περὶ τῶν χρημάτων ἀνεβάλλετο, περὶ ὧν ἐπί τε Σατορνίνου καὶ Οὐολομνίου τῶν Συρίας ἐπιστατούντων ἐγίνοντο λόγοι. τέλος δὲ συνέθεντο δι’ ἐκείνων ἐντὸς ἡμερῶν τριάκοντα τά τε χρήματα τὸν Ἡρώδην ἀπολαβεῖν καὶ τοὺς ἀλλήλων ἐν ἑκατέρᾳ τῇ βασιλείᾳ καὶ παρὰ μὲν Ἡρώδῃ τῶν Ἀράβων οὐδεὶς εὑρέθη τὸ σύνολον οὔτε ἐπ’ ἀδικίας οὔτε κατ’ ἄλλον τρόπον, οἱ δ’ Ἄραβες ἠλέγχοντο τοὺς λῃστὰς παρ’ αὐτοῖς ἔχειν.", "st": "16.9.1"}, {"sp": "N", "t": "Διελθούσης δὲ τῆς προθεσμίας Σύλλαιος οὐδὲν τῶν δικαίων πεποιηκὼς εἰς Ῥώμην ἀνέρχεται. ῥύσια δὲ τῶν χρημάτων καὶ τῶν παρ’ ἐκείνοις λῃστῶν Ἡρώδης ἐποιεῖτο, καὶ τῶν περὶ τὸν Σατορνῖνον καὶ Οὐολόμνιον ἐπιτρεπόντων ἀγνωμονοῦντας ἐπεξιέναι στρατιάν τε ἔχων προήγαγεν εἰς τὴν Ἀραβίαν τρισὶν ἡμέραις ἑπτὰ σταθμοὺς διανύσας, καὶ γενόμενος ἐπὶ τοῦ φρουρίου τοῦ τοὺς λῃστὰς ἔχοντος αἱρεῖ μὲν ἐξ ἐφόδου πάντας αὐτούς, κατασκάπτει δὲ τὸ χωρίον Ῥάεπτα καλούμενον· τῶν δὲ ἄλλων οὐδὲν ἐλύπησεν. ἐκβοηθησάντων δὲ τῶν Ἀράβων ἡγουμένου Νακέβου μάχη γίνεται, καθ’ ἣν ὀλίγοι μὲν τῶν Ἡρώδου, Νάκεβος δὲ ὁ τῶν Ἀράβων στρατηγὸς καὶ περὶ εἰκοσιπέντε τῶν σὺν αὐτῷ πίπτουσιν, οἱ δὲ ἄλλοι πρὸς φυγὴν ἐτράποντο. τισάμενος δὲ τούτους τρισχιλίους Ἰδουμαίων ἐπὶ τῇ Τραχωνίτιδι κατοικίσας ἦγεν λῃστὰς τοὺς ἐκεῖ, καὶ περὶ τούτων τοῖς ἡγεμόσιν ἔπεμπεν περὶ Φοινίκην οὖσιν, ἀποδεικνὺς ὅτι μηδὲν πλέον ὧν ἀγνωμονοῦντας ἐπεξελθεῖν ἔδει τοὺς Ἄραβας αὐτῷ πέπρακται. ταῦτα μὲν οὖν ἐκεῖνοι πολυπραγμονοῦντες εὕρισκον οὐ ψευδόμενον.", "st": "16.9.2"}, {"sp": "N", "t": "Ἄγγελοι δὲ Συλλαίῳ καταταχήσαντες εἰς Ῥώμην τὰ πεπραγμένα διεσάφουν εἰς μεῖζον, ὡς εἰκός, ἕκαστον τῶν γεγονότων αἴροντες. ὁ δὲ ἤδη μὲν ἐπεπραγμάτευτο γνώριμος εἶναι Καίσαρι, τότε δὲ περὶ τὴν αὐλὴν ἀναστρεφόμενος ὡς ἤκουσεν εὐθὺς μεταμφιέννυται μέλαιναν ἐσθῆτα καὶ παρελθὼν ἔλεγεν ὡς αὐτόν, ὅτι πολέμῳ τὰ περὶ τὴν Ἀραβίαν εἴη κεκακωμένα καὶ πᾶσα ἀνάστατος ἡ βασιλεία στρατιᾷ πορθήσαντος αὐτὴν Ἡρώδου. δακρύων δὲ πεντακοσίους μὲν ἐπὶ δισχιλίοις Ἀράβων ἀπολωλέναι τοὺς πρώτους ἔλεγεν, ἀνῃρῆσθαι δὲ καὶ τὸν στρατηγὸν αὐτῶν Νάκεβον οἰκεῖον αὐτῷ καὶ συγγενῆ, πλοῦτον δὲ διηρπάσθαι τὸν ἐν Ῥαέπτοις, καταπεφρονῆσθαι δὲ τὸν Ὀβόδαν ὑπὸ ἀσθενείας οὐκ ἀρκέσαντα τῷ πολέμῳ διὰ τὸ μήτ’ αὐτὸν μήτε τὴν Ἀραβικὴν δύναμιν παρεῖναι. τοιαῦτα τοῦ Συλλαίου λέγοντος καὶ προστιθέντος ἐπιφθόνως, ὡς οὐδ’ ἂν αὐτὸς ἀπέλθοι τῆς χώρας μὴ πεπιστευκὼς ὅτι Καίσαρι μέλοι τὴν εἰρήνην ἅπασιν εἶναι πρὸς ἀλλήλους, μηδ’ εἰ παρὼν ἐτύγχανεν ἐκεῖ λυσιτελῆ ποιῆσαι τὸν πόλεμον Ἡρώδῃ, παροξυνθεὶς ἐπὶ τοῖς λεγομένοις ὁ Καῖσαρ ἀνέκρινε τῶν Ἡρώδου τοὺς παρόντας καὶ τῶν ἰδίων τοὺς ἀπὸ Συρίας ἥκοντας αὐτὸ μόνον, εἰ τὴν στρατιὰν Ἡρώδης ἐξαγάγοι. τῶν δὲ τοῦτο μὲν αὐτὸ λέγειν ἀνάγκην ἐχόντων, τὸ δὲ ἐφ’ ὅτῳ καὶ πῶς οὐκ ἀκούοντος, ὀργή τε μείζων ἐγίνετο τῷ Καίσαρι καὶ γράφει πρὸς τὸν Ἡρώδην τά τε ἄλλα χαλεπῶς καὶ τοῦτο τῆς ἐπιστολῆς τὸ κεφάλαιον, ὅτι πάλαι χρώμενος αὐτῷ φίλῳ νῦν ὑπηκόῳ χρήσεται. γράφει δὲ καὶ Σύλλαιος ὑπὲρ τούτων τοῖς Ἄραψιν. οἱ δ’ ἐπαρθέντες οὔτε τῶν λῃστῶν ὅσοι διέφυγον ἐξεδίδοσαν οὔτε τὰ χρήματα διευλύτουν, νομάς τε ἃς ἐκείνου μισθωσάμενοι διακατεῖχον ἀμισθὶ ταύταις ἐχρῶντο, τεταπεινωμένου τοῦ τῶν Ἰουδαίων βασιλέως διὰ τὴν ὀργὴν τοῦ Καίσαρος. ἐπιτίθενται δὲ τῷ καιρῷ καὶ οἱ τὴν Τραχωνῖτιν ἔχοντες τῆς τῶν Ἰδουμαίων φρουρᾶς κατεξαναστάντες καὶ λῃστηρίοις χρώμενοι μετὰ τῶν Ἀράβων, οἳ ἐλεηλάτουν τὴν ἐκείνων χώραν οὐκ ἀπὸ ὠφελείας μόνον, ἀλλὰ καὶ μνησικακίας χαλεπώτεροι τὰς ἀδικίας ὄντες.", "st": "16.9.3"}, {"sp": "N", "t": "Ἡρώδης δὲ ταῦτα πάντα φέρων ἠνείχετο μεταβεβληκυίας αὐτῷ τῆς παρρησίας, ἣν εἶχε διὰ Καίσαρα, καὶ τὸ μεῖζον ἀφῄρητο τοῦ φρονήματος· οὐδὲ γὰρ πέμψαντος αὐτοῦ πρεσβείαν ἀπολογησομένην ὁ Καῖσαρ ἠνέσχετο, πάλιν δὲ τοὺς συνελθόντας ἀπράκτους ἀνέπεμψεν. ἦν δ’ οὖν ἐπὶ τούτοις ἀθυμία καὶ δέος, ὅ τε Σύλλαιος οὐ μετρίως ἐλύπει πιστευθείς τε καὶ παρὼν ἐν τῇ Ῥώμῃ, τότε δὲ καὶ μειζόνων ἁπτόμενος· ὁ μὲν γὰρ Ὀβόδας ἐτεθνήκει, παραλαμβάνει δὲ τὴν τῶν Ἀράβων ἀρχὴν Αἰνείας ὁ μετονομασθεὶς αὖθις Ἀρέτας. τοῦτον γὰρ ἐπεχείρει διαβολαῖς παρωσάμενος αὐτὸς ἀναλαμβάνειν τὴν ἀρχήν, χρήματα μὲν πολλὰ διδοὺς τοῖς περὶ τὴν αὐλήν, πολλὰ δὲ Καίσαρι δώσειν ὑπισχνούμενος. ὁ δὲ τῷ μὴ τὸν Ἀρέταν ἐπιστείλαντα πρότερον αὐτῷ βασιλεύειν ὠργίζετο. πέμπει δὲ κἀκεῖνος ἐπιστολὴν καὶ δῶρα τῷ Καίσαρι στέφανόν τε χρυσοῦν ἀπὸ πολλῶν ταλάντων· ἡ δὲ ἐπιστολὴ κατηγόρει Σύλλαιον ὄντα πονηρὸν δοῦλον Ὀβόδαν τε φαρμάκοις διαφθεῖραι καὶ ζῶντος ἔτι κρατεῖν αὐτὸν τάς τε τῶν Ἀράβων μοιχεύοντα καὶ χρήματα δανειζόμενον, ὥστ’ ἐξιδιώσασθαι τὴν ἀρχήν. προσέσχεν δὲ οὐδὲ τούτοις ὁ Καῖσαρ, ἀλλ’ ἀποπέμπει μηδὲν τῶν δώρων λαβών. τὰ δὲ περὶ τὴν Ἰουδαίαν καὶ Ἀραβίαν ἀεὶ καὶ μᾶλλον ἐπεδίδου τὰ μὲν εἰς ἀταξίαν τὰ δ’ ὡς καταφθειρομένων μηδένα προεστάναι· τῶν γὰρ βασιλέων ὁ μὲν οὐδέπω τὴν ἀρχὴν βεβαίαν ἔχων οὐχ ἱκανὸς ἦν κωλύειν τοὺς ἀδικοῦντας, Ἡρώδης δὲ ἐφ’ οἷς ἠμύνατο τάχιον ὀργισθέντος αὐτῷ Καίσαρος ἁπάσας τὰς εἰς αὐτὸν παρανομίας φέρειν ἠναγκάζετο. πέρας δ’ οὐδὲν ὁρῶν τῶν περιεστώτων κακῶν ἔγνω πάλιν εἰς Ῥώμην ἀποστέλλειν, εἴ τι δύναιτο μετριώτερον εὑρεῖν διά τε τῶν φίλων καὶ πρὸς αὐτὸν Καίσαρα τὴν ἐντυχίαν ποιησάμενος. κἀκεῖ μὲν ὁ Δαμασκηνὸς ἀπῄει Νικόλαος.", "st": "16.9.4"}, {"sp": "N", "t": "Ἐξετετάρακτο δὲ τὰ περὶ τὴν οἰκίαν καὶ τοὺς παῖδας αὐτῷ πολὺ χεῖρον ἐσχηκότα περὶ τὸν καιρὸν ἐκεῖνον. ὅλως μὲν γὰρ οὐδὲ τὸν ἔμπροσθε χρόνον ἀσύνοπτον ἦν, ὡς τὸ μέγιστον καὶ δυσχερέστατον τῶν ἀνθρωπίνων παθῶν ἀπειλεῖται τῇ βασιλείᾳ διὰ τῆς τύχης, ἐπέβαινεν δὲ καὶ μᾶλλον ηὐξήθη τότε παρὰ τοιαύτην αἰτίαν. Εὐρυκλῆς ἀπὸ Λακεδαίμονος οὐκ ἄσημος τῶν ἐκεῖ κακὸς δὲ τὴν ψυχὴν ἄνθρωπος καὶ περὶ τρυφὴν καὶ κολακείαν δεινὸς ἑκάτερον αὐτῶν ἔχειν τε καὶ μὴ δοκεῖν, ἐπιδημήσας ὡς τὸν Ἡρώδην δῶρά τε δίδωσιν αὐτῷ καὶ πλείω παρ’ ἐκείνου λαβὼν ταῖς εὐκαιρίαις τῶν ἐντεύξεων ἐπραγματεύσατο φίλος ἐν τοῖς μάλιστα γενέσθαι βασιλέως. ἦν δ’ αὐτῷ καταγωγὴ μὲν ἐν τοῖς Ἀντιπάτρου, πρόσοδος δὲ καὶ συνήθεια πρὸς τὸν Ἀλέξανδρον· Ἀρχελάῳ γὰρ ἔλεγεν εἶναι τῷ Καππάδοκι διὰ σπουδῆς. ὅθεν καὶ τὴν Γλαφύραν ὑπεκρίνατο τιμᾶν, καὶ πολὺς ἦν ἀφανῶς μὲν ἐκθεραπεύων ἅπαντας ἀεὶ δὲ τοῖς λαλουμένοις ἢ γινομένοις προσέχων, ὡς ἐξ αὐτῶν ἀντιχαρίζεσθαι τὰς διαβολάς. τέλος δὲ τοιοῦτος ἑκάστῳ κατὰ τὰς συντυχίας ἀπέβαινεν, ὡς ἐκείνῳ μὲν εἶναι φίλος τοῖς δὲ ἄλλοις δοκεῖν κατὰ τὸ συμφέρον ἐκείνῳ προσεῖναι. οὗτος Ἀλέξανδρον παράγει νέον ὄντα καὶ περὶ ὧν ἐπεπόνθει μηδενὶ μὲν πρὸς ἐκεῖνον δὲ μόνον ἀδεῶς πεπεισμένον ἐξεῖναι λέγειν· ἐνέφαινεν οὖν ἀχθόμενος, ὡς ὁ πατὴρ ἠλλοτρίωτο, καὶ τὰ περὶ τὴν μητέρα διηγεῖτο καὶ τὸν Ἀντίπατρον, ὅτι παρωθούμενος αὐτοὺς τῆς τιμῆς τὰ πάντα ἤδη δύναται. τούτων δὲ ἀνεκτὸν οὐδὲν ἔφη κατεσκευασμένου πρὸς μῖσος ἤδη τοῦ πατρός, ὡς μηδὲ συμποσίοις ἢ συλλόγοις ἀνέχεσθαι λέγων. τοιαῦτα μὲν ἐκεῖνος, ὡς εἰκός, ἐφ’ οἷς ἤλγει· τοὺς δὲ λόγους Εὐρυκλῆς Ἀντιπάτρῳ τούτους ἀνέφερεν, λέγων μὲν ὡς οὐχ ἕνεκα σοῦ τοῦτ’ αὐτὸν ποιεῖν, νικᾶσθαι δὲ ὑπὸ σοῦ τιμώμενος τῷ μεγέθει τοῦ πράγματος καὶ φυλάττεσθαι παρακελευόμενος τὸν Ἀλέξανδρον· οὐ γὰρ ἀπαθῶς τούτων ἕκαστον λέγειν, ἀλλὰ τοῖς ῥήμασιν αὐτοῖς εἶναι τὴν αὐτοχειρίαν. Ἀντίπατρος μὲν οὖν εὔνουν ὑπολαμβάνων ἐκ τούτων μεγάλας αὐτῷ παρ’ ἕκαστα δωρεὰς ἐδίδου καὶ τέλος ἤδη πείθει πρὸς τὸν Ἡρώδην ἀναφέρειν τὸν λόγον. ὁ δ’ οὐκ ἦν τὴν Ἀλεξάνδρου δύσνοιαν ἐξ ὧν ἔλεγεν ἀκηκοέναι διηγούμενος ἀπίθανος, ἀλλ’ οὕτω διέθηκε τὸν βασιλέα περιάγων ἀεὶ τοῖς ῥήμασι καὶ παροξύνων, ὡς ἀμετάγνωστον ποιῆσαι τὸ μῖσος. ἐδήλωσεν δὲ καὶ πρὸς αὐτὸν τὸν καιρόν· εὐθὺς γὰρ Εὐρυκλεῖ δίδωσιν πεντήκοντα τάλαντα δωρεάν. ὁ δὲ ταῦτα λαβὼν καὶ πρὸς Ἀρχέλαον ἀναβὰς τὸν βασιλέα τῶν Καππαδόκων τὸν Ἀλέξανδρον ἐπῄνει καὶ χρήσιμος ἔλεγεν αὐτῷ πολλὰ πρὸς τὰς διαλλαγὰς τὰς πρὸς τὸν πατέρα γεγενῆσθαι. χρηματισάμενος δὲ καὶ παρ’ ἐκείνου πρὶν καταφωραθῆναι τῆς κακοηθείας ἀπῄει. Εὐρυκλῆς μὲν οὖν οὐδὲ ἐν τῇ Λακεδαίμονι παυσάμενος εἶναι μοχθηρὸς ἐπὶ πολλοῖς ἀδικήμασιν ἀπεστερήθη τῆς πατρίδος.", "st": "16.10.1"}, {"sp": "N", "t": "Ὁ δὲ τῶν Ἰουδαίων βασιλεὺς οὐχ ὥσπερ πρότερον εἶχεν πρός τε τὸν Ἀλέξανδρον καὶ τὸν Ἀριστόβουλον ἀκούειν μόνον τὰς κατ’ αὐτῶν διαβολάς, ἀλλ’ ἤδη διὰ μίσους οἰκείου γεγενημένος αὐτὸς εἰ καὶ μὴ λέγοι τις ἐξειργάζετο, παρατηρῶν ἕκαστα καὶ πυνθανόμενος καὶ πᾶσιν ἐνδιδοὺς τοῖς βουλομένοις, εἴ τις ἔχοι τι κατ’ ἐκείνων εἰπεῖν, Εὐάρατόν τε Κῷον Ἀλεξάνδρῳ συνειδέναι. καὶ τοῦτο μὲν οὖν καθ’ ἡδονὴν τὸ πάντων ἥδιστον Ἡρώδης ἐλάμβανεν.", "st": "16.10.2"}, {"sp": "N", "t": "Ἐπιγίνεται δὲ κατὰ τῶν νεανίσκων μεῖζόν τι σκευωρουμένης ἀεὶ τῆς κατ’ αὐτῶν διαβολῆς καὶ πᾶσιν, ὡς εἰπεῖν, ἄθλου τούτου προκειμένου λέγειν τι περὶ ἐκείνων δυσχερὲς πρὸς τῆς τοῦ βασιλεύοντος ἐδόκει σωτηρίας. σωματοφύλακες ἦσαν Ἡρώδῃ δύο κατ’ ἰσχὺν καὶ μέγεθος τιμώμενοι Ἰούκουνδος καὶ Τύραννος. οὗτοι προσκρούσαντος αὐτοῖς τοῦ βασιλέως ἀπεωσμένοι περὶ Ἀλέξανδρον ἦσαν συνιππαζόμενοι καὶ κατὰ τὰ γυμνάσια τιμώμενοι καί τι χρυσίον καὶ δωρεὰς ἄλλας ἔλαβον. εὐθὺς οὖν καὶ τούτους ὁ βασιλεὺς ἐν ὑποψίαις ἔχων ἐβασάνιζεν, οἱ δὲ διακαρτερήσαντες πολὺν χρόνον ὕστερον ἔλεγον, ὅτι πείθοι φονεύειν αὐτοὺς Ἡρώδην Ἀλέξανδρος, ἐπεὶ περὶ κυνηγέσιον θηρίων διώκων προλάβοι· δυνατὸν γὰρ εἶναι λέγειν ὡς ἀπὸ τοῦ ἵππου κατενεχθεὶς ἐμπαρείη ταῖς αὐτοῦ λόγχαις· καὶ γὰρ πρότερον αὐτῷ τοιοῦτον γενέσθαι πάθος. ἐπέδειξαν δὲ καὶ τὸ χρυσίον ἐν ἱππῶνι κατορωρυγμένον καὶ τὸν ἀρχικύνηγον ἐξήλεγχον, ὅτι καὶ λόγχας αὐτοῖς δοίη βασιλικὰς καὶ τοῖς Ἀλέξανδρον θεραπεύουσιν ὅπλα κελεύοντος ἐκείνου.", "st": "16.10.3"}, {"sp": "N", "t": "Μετὰ τούτους ὁ φρούραρχος Ἀλεξανδρείου συλληφθεὶς ἐβασανίζετο· καὶ γὰρ ἐκεῖνος αἰτίαν εἶχεν δέξεσθαι τῇ φρουρᾷ καὶ παρέξειν χρήματα τοῖς νεανίσκοις ὑπεσχῆσθαι τὰ κείμενα τῶν βασιλικῶν κατ’ ἐκεῖνο τὸ φρούριον. αὐτὸς μὲν οὖν οὐδὲν ὡμολόγησεν, υἱὸς δὲ αὐτοῦ παρελθὼν ταῦτ’ ἔφη γενέσθαι, καὶ γράμματα ἐπέδωκεν ὡς εἰκάσαι τῆς Ἀλεξάνδρου χειρός· τελέσαντες σὺν θεῷ εἰπεῖν ἃ προεθέμεθα πάντα ἥξομεν πρὸς ὑμᾶς· ἀλλὰ πειράθητε, καθὼς ὑπέσχησθε, δέξασθαι ἡμᾶς τῷ φρουρίῳ. μετὰ τοῦτο τὸ γραμματεῖον ὁ μὲν Ἡρώδης οὐκ ἐνδοιασίμως εἶχεν περὶ τῆς τῶν παίδων εἰς αὐτὸν ἐπιβουλῆς, Ἀλέξανδρος δὲ Διόφαντον ἔφη τὸν γραμματέα μιμήσασθαι τὸν τύπον καὶ δι’ Ἀντιπάτρου κακουργηθῆναι τὸ γραμματίδιον· ὁ γάρ τοι Διόφαντος ἐδόκει τὰ τοιαῦτα δεινὸς ἐν ὑστέρῳ τε διελεγχθεὶς ἐπ’ ἄλλοις οὕτως ἀπέθανεν.", "st": "16.10.4"}, {"sp": "N", "t": "Τοὺς δὲ βασανισθέντας ὁ βασιλεὺς καὶ εἰς τὸ πλῆθος προήγαγεν ἐν Ἱεριχοῦντι κατηγοροῦντας τῶν παίδων· καὶ τούτους μὲν ἐκ χειρὸς οἱ πολλοὶ βάλλοντες ἀπέκτειναν. ὡρμημένων δὲ καὶ τοὺς περὶ τὸν Ἀλέξανδρον ὁμοίως κτεῖναι, τοῦτο μὲν ὁ βασιλεὺς παρῃτήσατο διὰ Πτολεμαίου καὶ Φερώρα τὸ πλῆθος ἀναστείλας, ἦν δὲ φυλακὴ καὶ τήρησις αὐτῶν καὶ προσῄει μὲν οὐδείς, πάντα δ’ ἐπεσκοπεῖτο τὰ γινόμενα καὶ λαλούμενα, καὶ τί γὰρ ἢ καταδίκων εἶχον ἀδοξίαν καὶ δέος. ἕτερος δ’ αὐτῶν Ἀριστόβουλος ἐκ βαρυθυμίας ὑπαγόμενος καὶ τὴν ἑαυτοῦ τηθίδα καὶ πενθερὰν συναλγεῖν αὐτῷ ταῖς συμφοραῖς καὶ μισεῖν τὸν τοιαῦτα πειθόμενον οὐ γάρ, ἔφη, καὶ σοὶ κίνδυνος ἀπωλείας διαβεβλημένῃ Συλλαίῳ κατ’ ἐλπίδα γάμων ἅπαντα τἀνθάδε προμηνύειν; τούτους ἐκείνη ταχὺ μάλα τἀδελφῷ προσφέρει τοὺς λόγους. ὁ δ’ οὐκέτι κατασχὼν αὑτὸν δῆσαί τε κελεύει καὶ διαστήσαντας ἀπ’ ἀλλήλων ὅσα κακῶς ἐποίησαν ἐπὶ τῷ πατρὶ ταῦτα γραψαμένους ἀποφέρειν. οἱ δ’ ἐπεὶ τοῦτο προσετέτακτο αὐτοῖς, ἐγγράφουσιν ἐπιβουλὴν μὲν οὔτε νοῆσαι κατὰ τοῦ γεγεννηκότος οὔτε συσκευάσασθαι, δρασμῷ δὲ ἐπιβαλέσθαι καὶ τοῦτο δι’ ἀνάγκην ὑπόπτου καὶ δυσχεροῦς ὄντος αὐτοῖς τοῦ βίου.", "st": "16.10.5"}, {"sp": "N", "t": "Κατὰ δὲ τὸν χρόνον ἥκοντος ἐκ Καππαδοκίας πρεσβευτοῦ παρὰ Ἀρχελάου Μήλα τινός, ὃς ἦν δυνάστης τῶν ἐκείνου, βουλόμενος Ἡρώδης ἐνδείξασθαι τὴν δύσνοιαν Ἀρχελάου πρὸς αὐτὸν ἐκάλει τὸν Ἀλέξανδρον ὡς ἦν ἐν τοῖς δεσμοῖς καὶ πάλιν ἠρώτα περὶ τῆς φυγῆς, ὅπου καὶ πῶς ἐγνώκασιν ἀποχωρεῖν. ὁ δὲ Ἀλέξανδρος πρὸς Ἀρχέλαον ἔφη κἀκεῖθεν εἰς Ῥώμην ὁμολογήσαντα διαπέμψειν· ἄλλο δ’ οὐδὲν οὔτ’ ἄτοπον οὔτε δυσχερὲς ἐντεθυμῆσθαι κατὰ τοῦ πατρὸς οὐδ’ ὅσα συνεσκεύασται κακοηθείᾳ τῶν ἐναντίων ἀληθὲς εἶναί τι τούτων. βούλεσθαι δ’ ἂν ἔτι ζῆν καὶ τοὺς περὶ Τύραννον εἰς ἐξέτασιν ἀσφαλεστέραν, ἀλλὰ καὶ τούτους ἀπολέσθαι θᾶττον Ἀντιπάτρου τῷ πλήθει τοὺς ἰδίους ἐγκαθιστάντος φίλους.", "st": "16.10.6"}, {"sp": "N", "t": "Τοιαῦτα λέγοντος ἐκέλευσεν ἅμα τόν τε Μήλαν καὶ τὸν Ἀλέξανδρον ἄγειν ὡς Γλαφύραν τὴν Ἀρχελάου καὶ πυνθάνεσθαι παρ’ αὐτῆς, εἰ μηδὲν ἠγνόει τῶν εἰς ἐπιβουλὴν Ἡρώδου γιγνομένων. ὡς δὲ ἧκον, εὐθὺς μὲν Γλαφύρα δεσμώτην ἰδοῦσα τὸν Ἀλέξανδρον ἔπληξε τὴν κεφαλὴν καὶ καταπληξαμένη μέγα καὶ συμπαθὲς ἀνῴμωξεν. ἦν δὲ καὶ τοῦ νεανίσκου δάκρυα καὶ τῶν παρόντων ὀδυνηρά τις θέα, μέχρι πλείονος οὐδὲ ἐφ’ οἷς ἧκον εἰπεῖν ἢ πράττειν δυναμένων. ὀψὲ δὲ τοῦ Πτολεμαίου, τούτῳ γὰρ ἄγειν αὐτὸν ἐπετέτακτο, φράζειν κελεύοντος εἴ τι τῶν πραττομένων ἡ γυνὴ σύνοιδεν αὐτῷ, τί δ’ οὐκ ἄν, ἔφη, συνέγνω τῆς ψυχῆς ἐμοὶ στεργομένη πλέον καὶ κοινωνοῦσα τέκνων; ἡ δὲ πρὸς ταῦτα μὲν ἀνεβόησεν, ὡς συνειδείη μὲν οὐδὲν ἄτοπον, εἰ δὲ φέροι πρὸς τὴν σωτηρίαν τὴν ἐκείνου τὸ καὶ καθ’ αὑτῆς τι ψεύσασθαι, πάνθ’ ὁμολογεῖν. ὁ δὲ Ἀλέξανδρος ἀσεβὲς μὲν οὐδέν, εἶπεν, οὐδ’ ὧν ὑπονοοῦσιν οὓς ἥκιστα ἐχρῆν οὔτ’ αὐτὸς ἐνόησα σύ τε οὐδὲν οἶσθα, ἀλλ’ ὅτι παρ’ Ἀρχέλαον ἀποχωρεῖν ἐγνώκειμεν κἀκεῖθεν εἰς Ῥώμην. ταῦτ’ ἐκείνης ὁμολογούσης ὁ μὲν Ἡρώδης Ἀρχέλαον ἐξεληλέγχθαι τῆς πρὸς αὐτὸν δυσνοίας ὑπολαβὼν δίδωσιν Ὀλύμπῳ καὶ Οὐολομνίῳ γράμματα κελεύσας ἐν παράπλῳ μὲν Ἐλαιούσῃ τῆς Κιλικίας προσσχόντας Ἀρχελάῳ τε περὶ τούτων ἀποδοῦναι καὶ μεμψαμένους ὅτι τῆς ἐπιβουλῆς ἐφάψαιτο τοῖς παισὶν ἐκεῖθεν εἰς Ῥώμην πλεῖν. κἂν εὕρωσιν ἀνύσαντά τι Νικόλαον, ὡς μηκέτ’ αὐτῷ δυσχεραίνειν Καίσαρα, διδόναι τὰς ἐπιστολὰς καὶ τοὺς ἐλέγχους τοὺς κατὰ τῶν νεανίσκων συνεσκευασμένως ἐπέστειλεν. Ἀρχέλαος μὲν οὖν ἀπελογεῖτο δέξασθαι μὲν τοὺς νεανίσκους ὁμολογήσας διὰ τὸ συμφέρειν αὐτοῖς τε ἐκείνοις καὶ τῷ πατρὶ μὴ χαλεπώτερόν τι προστεθῆναι κατ’ ὀργὴν ὧν ὑπόπτως ἔχοντες ἐστασίαζον· οὐ μὴν καὶ πρὸς Καίσαρα πέμψειν οὐδ’ ἄλλο τι κατὰ δύσνοιαν τὴν πρὸς ἐκεῖνον ὁμολογῆσαι τοῖς νεανίσκοις.", "st": "16.10.7"}, {"sp": "N", "t": "Εἰς δὲ τὴν Ῥώμην ἀποκομισθέντες ἔσχον καιρὸν ἐπιδοῦναι τὰ γράμματα τῷ Καίσαρα διηλλαγμένον εὑρεῖν Ἡρώδῃ· τὰ γὰρ περὶ τὴν Νικολάου πρεσβείαν ἀπέβη τοῦτον τὸν τρόπον· ὡς ἀνῆλθεν εἰς τὴν Ῥώμην καὶ περὶ τὴν αὐλὴν ἐγένετο, πρῶτον μὲν οὐκ ἐφ’ οἷς ἐληλύθει μόνον ἀλλὰ καὶ Συλλαίου κατηγορεῖν ἠξίου, καὶ δῆλοι πρὸ τῆς ἐντυχίας ἦσαν ἀλλήλους πολεμοῦντες. οἱ δὲ Ἄραβες ὑπονοήσαντες ἐξ αὐτοῦ καὶ τῷ Νικολάῳ προσελθόντες τὰς ἀδικίας ἁπάσας ἐμήνυον καὶ τῶν Ὀβόδου ὡς διαφθαρέντων πάντων ἐμφανῆ τεκμήρια παρέχοντες, ἦν γὰρ καὶ τῶν γραμμάτων αὐτοῦ ὃ κατὰ τὴν ἀπόστασιν ὑφῃρημένοι διὰ τούτων ἤλεγχον. ὁ δὲ Νικόλαος εὐτυχίαν τινὰ ταύτην ὁρῶν αὐτῷ προσγεγενημένην δι’ αὐτῆς ἐπραγματεύετο τὸ μέλλον, ἐπείγων εἰς διαλλαγὰς ἐλθεῖν Ἡρώδῃ Καίσαρα· σαφῶς γὰρ ἠπίστατο βουλομένῳ μὲν ἀπολογεῖσθαι περὶ ὧν ἔπραξεν οὐκ ἔσεσθαι παρρησίαν, ἐθέλοντι δὲ κατηγορεῖν Συλλαίου γενήσεσθαι καιρὸν ὑπὲρ Ἡρώδου λέγειν. συνεστώτων οὖν ἐπ’ ἀλλήλους καὶ δοθείσης ἡμέρας ὁ Νικόλαος παρόντων αὐτῷ τῶν Ἀρέτα πρέσβεων τά τε ἄλλα κατηγόρει τοῦ Συλλαίου, τήν τε τοῦ βασιλέως ἀπώλειαν λέγων καὶ πολλῶν Ἀράβων, χρήματά τε ὡς εἴη δεδανεισμένος ἐπ’ οὐδὲν ὑγιές, καὶ μοιχείας ἐξελέγχων οὐ τῶν ἐν Ἀραβίᾳ μόνον ἀλλὰ καὶ τῶν ἐν Ῥώμῃ γυναικῶν· προσετίθει δὲ τὸ μέγιστον, ὡς ἐξαπατήσειεν Καίσαρα μηδὲν ἀληθὲς διδάξας ὑπὲρ τῶν Ἡρώδῃ πεπραγμένων. ὡς δ’ ἧκεν ἐπὶ τοῦτον τὸν τόπον, ὁ μὲν Καῖσαρ ἐξεῖργεν αὐτὸν τοῦτο μόνον ἀξιῶν ὑπὲρ Ἡρώδου λέγειν, εἰ μὴ στρατιὰν ἤγαγεν εἰς Ἀραβίαν μηδὲ δισχιλίους πεντακοσίους ἀποκτείνειεν τῶν ἐκεῖ μηδ’ αἰχμαλώτους λάβοι τὴν χώραν διαρπάσας. πρὸς ταῦτα ὁ Νικόλαος ὑπὲρ τούτων ἔφη καὶ μάλιστα διδάξειν, ὅτι μηδὲν ἢ τὰ πλεῖστά γε αὐτῶν οὐ γέγονεν, ὡς σὺ ἀκήκοας καὶ δίκαιον ἦν ἐπ’ αὐτοῖς χαλεπώτερον φέρειν. πρὸς δὲ τὸ παράδοξον Καίσαρος ἐνδόντος αὑτὸν ἀκροατήν, τὸ δάνειον εἰπὼν τῶν πεντακοσίων ταλάντων καὶ τὴν συγγραφήν, ἐν ᾗ καὶ τοῦτο ἦν προσγεγραμμένον ἐξεῖναι τῆς προθεσμίας παρελθούσης ῥύσια λαμβάνειν ἐξ ἁπάσης τῆς χώρας, τὴν μὲν στρατείαν οὐ στρατείαν ἔλεγεν, ἀλλ’ ἐπὶ δικαίαν τῶν ἰδίων ἀπαίτησιν χρημάτων· καὶ μηδὲ ταύτην ταχὺ μηδ’ ὡς ἐπέτρεπον αἱ συγγραφαί, πολλάκις μὲν ἐπὶ Σατορνῖνον ἐλθόντα καὶ Οὐολόμνιον τοὺς τῆς Συρίας ἡγεμόνας, τελευταῖον δὲ ἐν Βηρυτῷ τούτων ἐναντίον Συλλαίου τὴν σὴν τύχην ἐπομόσαντος, ἦ μὴν ἐντὸς ἡμερῶν τριάκοντα παρέξειν τὰ χρήματα καὶ τοὺς ἐκ τῆς ἀρχῆς τῆς Ἡρώδου πεφευγότας. ὧν οὐδὲν ποιήσαντος Συλλαίου πάλιν ἐπὶ τοὺς ἡγεμόνας ἐλθεῖν Ἡρώδην κἀκείνων ἐφέντων αὐτῷ λαμβάνειν τὰ ῥύσια μόγις οὕτως ἐξελθεῖν σὺν τοῖς περὶ αὐτόν. ὁ μὲν δὴ πόλεμος, ὡς οὗτοι τραγῳδοῦντες ἔλεγον, καὶ τὰ τῆς ἐπιστρατείας τοιαῦτα. καίτοι πῶς ἂν εἴη πόλεμος, ἐπιτρεψάντων μὲν τῶν σῶν ἡγεμόνων, δεδωκυίας δὲ τῆς συνθήκης, ἠσεβημένου δὲ μετὰ τῶν ἄλλων θεῶν καὶ τοῦ σοῦ, Καῖσαρ, ὀνόματος; τὰ δὲ περὶ τοὺς αἰχμαλώτους ἑξῆς ἤδη λεκτέον. λῃσταὶ τῶν τὸν Τράχωνα κατοικούντων τετταράκοντα τὸ πρῶτον εἶτ’ αὖθις πλείονες τὰς Ἡρώδου κολάσεις διαφεύγοντες ὁρμητήριον ἐποιήσαντο τὴν Ἀραβίαν. τούτους ὑπεδέξατο Σύλλαιος ἐπὶ πάντας ἀνθρώπους τρέφων καὶ χώραν ἔδωκε νέμεσθαι καὶ τὰ κέρδη τῶν λῃστῶν αὐτὸς ἐλάμβανεν. ὡμολόγησε δὲ καὶ τούτους ἐπὶ τοῖς αὐτοῖς ὅρκοις ἀποδώσειν κατὰ τὴν αὐτὴν τοῦ δανείου προθεσμίαν. καὶ δύναιτ’ ἂν οὐκ ἐπιδεῖξαι κατὰ τὸ παρὸν οὔτ’ ἄλλον τινὰ τῆς Ἀράβων χώρας ἢ τούτους ἐξῃρημένους οὔτε πάντας, ἀλλ’ ὅσοι μὴ λαθεῖν ἴσχυσαν. οὕτως οὖν καὶ τοῦ τῆς αἰχμαλωσίας ἐπιφθόνου συκοφαντήματος πεφηνότος μέγιστον, ὦ Καῖσαρ, κατάμαθε πλάσμα καὶ ψεῦσμα πρὸς τὴν σὴν ὀργὴν αὐτῷ ποιηθέν. φημὶ γὰρ ἐπελθούσης ἡμῖν τῆς τῶν Ἀράβων δυνάμεως καὶ τῶν περὶ Ἡρώδην πεσόντος ἑνὸς καὶ δευτέρου, τότε μόλις ἀμυνομένου Νάκεβον τὸν στρατηγὸν αὐτῶν καὶ περὶ πέντε καὶ εἴκοσι τοὺς πάντας ὧν ἕκαστον αὐτὸς εἰς ἑκατὸν ἀναφέρων δισχιλίους καὶ πεντακοσίους τοὺς ἀπολωλότας ἔλεγεν.", "st": "16.10.8"}, {"sp": "N", "t": "Ταῦτα μᾶλλον ἐκίνει τὸν Καίσαρα καὶ πρὸς τὸν Σύλλαιον ἐπιστραφεὶς ὀργῆς μεστὸς ἀνέκρινεν, ὁπόσοι τεθνήκασιν Ἀράβων. ἀπορουμένου δ’ αὐτοῦ καὶ πεπλανῆσθαι λέγοντος αἵ τε συνθῆκαι τῶν δανείων ἀνεγινώσκοντο καὶ τὰ τῶν ἡγεμόνων γράμματα πόλεις τε ὅσαι τὰ λῃστήρια κατῃτιῶντο, καὶ πέρας εἰς τοῦτο μετέστη Καῖσαρ, ὡς τοῦ μὲν Συλλαίου καταγνῶναι θάνατον, Ἡρώδῃ δὲ διαλλάττεσθαι μετάνοιαν ἐφ’ οἷς ἐκ διαβολῆς πικρότερον ἔγραψεν αὐτῷ πεπονθώς, καί τι τοιοῦτον εἰπεῖν εἰς τὸν Σύλλαιον, ὡς ἀναγκάσειεν αὐτὸν ψευδεῖ λόγῳ πρὸς ἄνδρα φίλον ἀγνωμονῆσαι. τὸ δὲ σύμπαν ὁ μὲν Σύλλαιος ἀνεπέμπετο τὰς δίκας καὶ τὰ χρέα τοῖς δεδανεικόσιν ἀποδώσων εἶθ’ οὕτω κολασθησόμενος. Ἀρέτᾳ δ’ οὐκ εὐμενὴς ἦν Καῖσαρ, ὅτι τὴν ἀρχὴν μὴ δι’ ἐκείνου καθ’ αὑτὸν δὲ ἔλαβεν. ἐγνώκει δὲ καὶ τὴν Ἀραβίαν Ἡρώδῃ διδόναι, διεκώλυσεν δὲ τὰ παρ’ ἐκείνου πεμφθέντα γράμματα. τοῖς γὰρ περὶ τὸν Ὄλυμπον καὶ Οὐολόμνιον εὐμενῆ Καίσαρα πυνθανομένοις εὐθὺς ἔδοξεν ἐξ ἐντολῆς Ἡρώδου τὰ περὶ τῶν παίδων γράμματα καὶ τοὺς ἐλέγχους ἀναδιδόναι. Καῖσαρ δὲ ἀναγνοὺς τὸ μὲν ἀρχὴν ἄλλην προσθεῖναι γέροντι καὶ κακῶς πράττοντι τὰ περὶ τοὺς παῖδας οὐκ ᾠήθη καλῶς ἔχειν, δεξάμενος δὲ τοὺς παρὰ Ἀρέτα καὶ τοῦτο μόνον ἐπιτιμήσας, ὡς προπετείᾳ χρήσαιτο τῷ μὴ παρ’ αὐτοῦ τὴν βασιλείαν ἀναμεῖναι λαβεῖν, τά τε δῶρα προσήκατο καὶ τὴν ἀρχὴν ἐβεβαίωσεν.", "st": "16.10.9"}, {"sp": "N", "t": "Ἡρώδῃ δὲ γράφει διηλλαγμένος ἐπί τε τοῖς παισὶν ἄχθεσθαι λέγων καὶ δέον, εἰ μὲν ἀνοσιώτερόν τι τετολμήκασιν, ἐπεξιέναι πατραλόας ὄντας· αὐτῷ γὰρ ἐφεῖναι ταύτην τὴν ἐξουσίαν· εἰ δὲ δρασμὸν ἐνόησαν, ἄλλως νουθετήσαντα μηδὲν ἀνήκεστον διαπράττεσθαι. συμβουλεύειν δὲ ἔχειν αὐτῷ συνέδριον ἀποδείξαντα περὶ Βηρυτόν, ἐν ᾗ κατοικοῦσιν Ῥωμαῖοι, καὶ παραλαβόντα τούς τε ἡγεμόνας καὶ τὸν βασιλέα τῶν Καππαδόκων Ἀρχέλαον ὅσους τε τῶν ἄλλων οἴεται φιλίᾳ τε καὶ ἀξιώματι ἐπιφανεῖς μετὰ τῆς ἐκείνων γνώμης ὅ τι χρὴ διαλαμβάνειν. Καῖσαρ μὲν τοιαῦτα ἐπέστελλεν. ὁ δὲ Ἡρώδης τῶν γραμμάτων ὡς αὐτὸν ἀπενεχθέντων περιχαρὴς μὲν εὐθὺς ἐπὶ ταῖς διαλλαγαῖς ἐγεγόνει, περιχαρὴς δὲ καὶ τῷ πάντ’ ἐξεῖναι κατὰ τῶν παίδων αὐτῷ. καί πως τὸ μὲν οὐκ εὖ πράττειν ἐν τῷ προτέρῳ χαλεπὸν μὲν ἀλλ’ οὔτε θρασὺν οὔτε προπετῆ πρὸς τὴν ἀπώλειαν τῶν τέκνων παρεῖχεν αὐτόν, ἐν δὲ τῷ τότε μεταβολῆς ἀμείνονος καὶ παρρησίας ἐπιλαβόμενος τὸ μῖσος ἐκενοδόξει τὴν ἐξουσίαν. διέπεμπεν οὖν ὅσους ἐδόκει καλεῖν εἰς τὸ συνέδριον Ἀρχελάου χωρίς· ἐκεῖνον δὲ δι’ ἔχθος οὐκ ἠξίου παρατυγχάνειν ἢ καὶ τῇ προαιρέσει νομίζων ἐμποδὼν ἔσεσθαι.", "st": "16.11.1"}, {"sp": "N", "t": "Γενομένων δὲ ἐν Βηρυτῷ τῶν ἡγεμόνων καὶ τῶν ἄλλων ὅσους τῶν πόλεων ἐκάλεσεν, τοὺς μὲν παῖδας, οὐ γὰρ ἠξίου παράγειν εἰς τὸ συνέδριον, ἐν κώμῃ τινὶ Σιδωνίων εἶχεν Παλαεστῶ καλουμένῃ πλησίον τῆς πόλεως, ὡς ἔχειν εἰ κληθεῖεν παραστῆσαι. μόνος δὲ καὶ κατ’ αὐτὸν εἰσελθὼν ἑκατὸν καὶ πεντήκοντα συγκαθημένων ἀνδρῶν κατηγόρει κατηγορίαν οὐκ ὀδυνηρὰν ὡς πρὸς ἀνάγκην ὧν ἠτύχει, πλεῖστον δὲ ἀπεοικυῖαν ᾗ πατὴρ ἐπὶ παισὶν εἴποι· βίαιος γὰρ ἦν καὶ περὶ τὴν ἀπόδειξιν τῆς αἰτίας ἐτετάρακτο καὶ μέγιστα θυμοῦ καὶ ἀγριότητος ἐνεδίδου σημεῖα, τούς τε ἐλέγχους οὐκ ἐκείνοις ἐπιτρέπων καταμαθεῖν, ἀλλὰ συνηγορίαν αὐτοῖς προτιθεὶς πατρὶ κατὰ παίδων ἀσχήμονα, καὶ τὰ γραφέντα δι’ αὐτῶν ἐκείνων ἀναγινώσκων, ἐν οἷς ἐπιβουλὴ μὲν ἤ τις ἐπίνοια δυσσεβείας οὐκ ἐγέγραπτο, μόνον δὲ ὡς φυγεῖν βουλεύοιντο καὶ λοιδορίαι τινὲς εἰς αὐτὸν ὀνείδη περιέχουσαι διὰ τὴν δύσνοιαν. ἐφ’ αἷς ἐκεῖνος ὡς ἐγένετο μᾶλλόν τε ἐξεβόα καὶ τὸ περιὸν εἰς ὁμολογίαν τῆς ἐπιβουλῆς δι’ ἐκείνων ηὔξανεν ἐπομνύμενος, ὡς ἥδιον ἂν στέροιτο τοῦ ζῆν ἢ τοιούτων ἀκούειν λόγων. τὸ δὲ τελευταῖον εἰπών, ὅτι καὶ τῇ φύσει καὶ τῇ Καίσαρος δόσει τὴν ἐξουσίαν αὐτὸς ἔχοι, προσέθηκεν αὐτῷ καὶ πάτριον νόμον κελεύειν, εἴ του κατηγορήσαντες οἱ γονεῖς ἐπιθοῖεν τῇ κεφαλῇ τὰς χεῖρας, ἐπάναγκες εἶναι τοῖς περιεστῶσιν βάλλειν καὶ τοῦτον ἀποκτείνειν τὸν τρόπον. ὅπερ ἕτοιμος ὢν αὐτὸς ἐν τῇ πατρίδι καὶ τῇ βασιλείᾳ ποιεῖν ὅμως ἀναμεῖναι τὴν ἐκείνων κρίσιν, ἥκειν μέντοι δικαστὰς μὲν οὐχ οὕτως ἐπὶ φανεροῖς οἷς ἐκ τῶν παίδων ὀλίγου πάθοι, συνοργισθῆναι δὲ καιρὸν ἔχοντας, ὡς οὐδενὶ καὶ τῶν πόρρω γεγονότων ἀμελῆσαι τοιαύτης ἐπιβουλῆς ἄξιον.", "st": "16.11.2"}, {"sp": "N", "t": "Ταῦτα τοῦ βασιλέως εἰπόντος καὶ τῶν νεανίσκων οὐδὲ ἕως ἀπολογίας παρηγμένων συμφρονήσαντες οἱ κατὰ τὸ συνέδριον, ὡς ἐπιεικείας καὶ διαλλαγῶν χεῖρον ἔχοι, τὴν ἐξουσίαν ἐβεβαίουν αὐτῷ. καὶ πρῶτον μὲν Σατορνῖνος ἀνὴρ ὑπατικὸς καὶ τῶν ἐπ’ ἀξιώματος ἀπεφήνατο γνώμην ἀηδεστάτῃ περιστάσει χρώμενος· ἔφη γὰρ καταδικάζειν μὲν τῶν Ἡρώδου παίδων, κτείνειν δ’ οὐκ οἴεσθαι δικαιοῦν αὐτὸς παῖδας ἔχων καὶ τοῦ πάθους μείζονος ὄντος, εἰ καὶ πάντα δι’ αὐτοὺς δεδυστύχηκεν. μετ’ ἐκεῖνον οἱ Σατορνίνου παῖδες, εἵποντο γὰρ αὐτῷ πρεσβευταὶ τρεῖς ὄντες, τὴν αὐτὴν γνώμην ἀπεφήναντο, Οὐολόμνιος δὲ ἄντικρυς ἔφη κολάζειν θανάτῳ τοὺς οὕτως ἀσεβήσαντας εἰς τὸν πατέρα. τὰ δ’ αὐτὰ καὶ τῶν ἑξῆς οἱ πλείους, ὥστε καὶ μηκέτι ἄλλο τι δοκεῖν ἢ καταδεδικάσθαι τὴν ἐπὶ θανάτῳ τοὺς νεανίσκους. κἀκεῖθεν μὲν εὐθὺς Ἡρώδης ἧκεν ἄγων αὐτοὺς εἰς Τύρον, καὶ τοῦ τε Νικολάου πλεύσαντος ὡς αὐτὸν ἐκ τῆς Ῥώμης ἐπυνθάνετο προδιηγησάμενος τὰ ἐν Βηρυτῷ, ἥντιν’ ἔχοιεν γνώμην περὶ τῶν παίδων αὐτοῦ καὶ οἱ ἐν Ῥώμῃ αὐτοῦ φίλοι, κἀκεῖνος εἶπεν, ὅτι δοκεῖ μὲν ἀσεβῆ εἶναι τὰ ἐκείνοις περὶ σὲ ἐγνωσμένα, χρῆναι μέντοι αὐτοὺς καθείρξαντα δεσμώτας φυλάττειν, καὶ εἰ μὲν ἑτέρως σοι δοκοίη κολάζειν αὐτούς, μὴ φαίνοιο ὀργῇ τὸ πλεῖον ἢ γνώμῃ κεχρῆσθαι, εἰ δὲ τἀναντία ἀπολύειν, μὴ ἀνεπανόρθωτον εἴη σοι τὸ ἀτύχημα. ταῦτα δοκεῖ καὶ ἐν Ῥώμη τοῖς πλείστοις τῶν σῶν φίλων. καὶ ὃς σιωπήσας ἐν πολλῇ ἐγένετο συννοίᾳ κἀκεῖνον ἐκέλευσεν συμπλεῖν αὐτῷ.", "st": "16.11.3"}, {"sp": "N", "t": "Ὡς δ’ ἦλθεν εἰς Καισάρειαν γίνεται λόγος οὖν ἦν εὐθὺς ἅπασιν τῶν παίδων καὶ μετέωρος ἡ βασιλεία, ποῖ ποτε χωρήσειεν τὰ κατ’ αὐτοὺς ἐκδεχομένων· δεινὸν γὰρ ὑπῄει πάντας δέος ἐκ παλαιοῦ καταστασιαζομένους εἰς αὐτὸ τὸ πέρας ἐλθεῖν, καὶ τοῖς μὲν πάθεσιν ἐδυσχέραινον, οὐκ ἦν δ’ οὔτε εἰπεῖν τι προπετὲς οὔτ’ ἄλλου λέγοντος ἀκούειν ἀκίνδυνον, ἀλλ’ ἐγκεκλεισμένοι τὸν ἔλεον ὀδυνηρῶς μὲν ἀναύδως δὲ τὴν ὑπερβολὴν τοῦ πάθους ἔφερον. εἷς δὲ αὐτῶν πάλαι στρατιώτης ὄνομα Τίρων, υἱοῦ αὐτῷ καθ’ ἡλικίαν ὄντος Ἀλεξάνδρῳ φίλου, πάνθ’ ὅσα καὶ τοῖς ἄλλοις ὑποδυόμενα δι’ ἡσυχίας ἦν, αὐτὸς ὑπ’ ἐλευθεριότητος ἐξελάλει καὶ βοᾶν ἠναγκάζετο πολλάκις ἐν τοῖς πλήθεσιν ἀπαρακαλύπτως λέγων, ὡς ἀπόλοιτο μὲν ἡ ἀλήθεια, τὸ δὲ δίκαιον ἐκ τῶν ἀνθρώπων ἀνῃρημένον εἴη, κρατοίη δὲ τὰ ψεύσματα καὶ ἡ κακοήθεια καὶ τοσοῦτο νέφος ἐπάγοι τοῖς πράγμασιν, ὡς μηδὲ τὰ μέγιστα τῶν ἀνθρωπίνων παθῶν ὁρᾶσθαι τοῖς ἁμαρτάνουσιν. τοιοῦτος ὢν ἐδόκει μὲν οὐκ ἀκινδύνως παρρησιάζεσθαι, τὸ δ’ εὔλογον ἐκίνει πάντας οὐκ ἀνάνδρως αὐτοῦ πρὸς τὸν καιρὸν ἱσταμένου. διὸ καὶ πάνθ’ ἅπερ αὐτὸς ἕκαστος εἴποιεν ἡδέως ἤκουον ὑπ’ ἐκείνου λεγόμενα καὶ τὸ καθ’ αὑτοὺς ἀσφαλὲς ἐν τῷ σιγᾶν προορώμενοι τὴν ἐκείνου παρρησίαν ὅμως ἀπεδέχοντο· τὸ γὰρ προσδοκώμενον πάθος ἐβιάζετο πάνθ’ ὁντινοῦν ὑπὲρ αὐτοῦ λαλεῖν.", "st": "16.11.4"}, {"sp": "N", "t": "Ὁ δὲ καὶ πρὸς τὸν βασιλέα μετὰ πάσης παρρησίας ὠσάμενος μόνος μόνῳ λέγειν ἠξίου, καὶ συγχωρήσαντος οὐ δυνάμενος, εἶπεν, ὦ βασιλεῦ, διακαρτερεῖν ἐπὶ τοιούτῳ πάθει τὴν τολμηρὰν ταύτην παρρησίαν, ἀναγκαίαν δὲ σοὶ καὶ συμφέρουσαν, εἰ λάβοις τι χρήσιμον ἐξ αὐτῆς, προύκρινα τῆς ἐμῆς ἀσφαλείας. ποῖ ποτε οἴχονταί σου καὶ πεπτώκασιν ἐκ τῆς ψυχῆς αἱ φρένες; ποῖ δὲ καὶ ὁ περιττὸς ἐκεῖνος νοῦς, ᾧ πολλὰ καὶ μεγάλα κατώρθους; τίς δὲ ἡ τῶν φίλων καὶ συγγενῶν ἐρημία; κρίνω δὲ οὐδὲ παρόντας αὐτοὺς συγγενεῖς εἶναι ἢ φίλους, οἳ περιορῶσι τοιοῦτο μῦσος ἐπὶ τῇ μακαριζομένῃ ποτὲ βασιλείᾳ. σὺ δ’ οὐ σκέψει τί τὸ πραττόμενόν ἐστιν; δύο νεανίσκους ἐκ βασιλίδος γυναικὸς γενομένους εἰς πᾶσαν ἀρετὴν ἄκρους ἀναιρήσεις σεαυτὸν ἐν γήρᾳ καταλιπὼν ἐφ’ ἑνὶ παιδὶ κακῶς οἰκονομήσαντι τὴν εἰς αὐτὸν ἐλπίδα καὶ συγγενέσιν, ὧν αὐτὸς τοσαυτάκις ἤδη κατέγνωκας θάνατον; οὐκ ἐννοεῖς, ὅτι καὶ τῶν ὄχλων ἡ σιωπὴ τὴν αμογίαν ὅμως ὁρᾷ καὶ μισεῖ τὸ πάθος, ἥ τε στρατιὰ πᾶσα καὶ ταύτης οἱ πρωτεύοντες ἔλεον μὲν τῶν ἀτυχούντων, μῖσος δὲ τῶν ταῦτα διαπραττομένων ἐσχήκασιν; ἤκουεν τούτων ὁ βασιλεὺς ἐν ἀρχῇ μὲν οὐ παντάπασιν ἀγνωμόνως, ἀλλὰ τί δεῖ καὶ λέγειν, διεκίνησεν αὐτὸν ἁψαμένου τοῦ Τίρωνος ἐναργῶς τοῦ τε πάθους καὶ τῆς περὶ τοὺς οἰκείους ἀπιστίας. αὖθις δὲ ὁ μὲν ἐπεδίδου κατὰ μικρὸν ἀμέτρῳ καὶ στρατιωτικῇ χρώμενος παρρησίᾳ· τὸ γὰρ ἀπαίδευτον ὑπεξέπιπτε τοῦ καιροῦ, ταραχῆς δὲ Ἡρώδης ἐνεπίμπλατο, καὶ μᾶλλον ὀνειδίζεσθαι δοκῶν ἢ πρὸς τὸ συμφέρον ἀκούειν τῶν λόγων, ἐπειδὴ καὶ τοὺς διακειμένους στρατιώτας καὶ τοὺς ἀγανακτοῦντας ἡγεμόνας ἐπύθετο, προστάττει τῷ τε ὀνόματι δηλωθέντων ἁπάντων καὶ τὸν Τίρωνα δήσαντας ἔχειν ἐν φυλακῇ.", "st": "16.11.5"}, {"sp": "N", "t": "Τούτου γενηθέντος ἐπιτίθεται τῷ καιρῷ καὶ Τρύφων τις κουρεὺς τοῦ βασιλέως, ὃς ἔφη προσελθὼν ὡς πείθοι πολλάκις αὐτὸν ὁ Τίρων, ὁπόταν θεραπεύῃ βασιλέως ξυρῷ τὸν λαιμὸν ἀποτέμνειν· ἔσεσθαι γὰρ ἐν πρώτοις περὶ Ἀλέξανδρον καὶ μεγάλας λήψεσθαι δωρεάς. ταῦτ’ εἰπόντα συλλαμβάνειν κελεύει, καὶ μετὰ ταῦτα βάσανος ἦν τοῦ τε Τίρωνος καὶ τοῦ παιδὸς αὐτοῦ καὶ τοῦ κουρέως. διακαρτεροῦντός τε τοῦ Τίρωνος ὁρῶν ὁ νεανίσκος τὸν πατέρα χαλεπῶς μὲν ἤδη διακείμενον, ἔχοντα δὲ οὐδεμίαν ἐλπίδα σωτηρίας αὑτῷ τε τὸ μέλλον ἐκ τῆς περὶ τὸν πάσχοντα δυσχερείας προῦπτον, ἔφη μηνύσειν τῷ βασιλεῖ τὴν ἀλήθειαν, εἰ παραιτήσεται διὰ τοῦ φράσαι τῆς βασάνου καὶ τῆς αἰκίας αὐτόν τε καὶ τὸν πατέρα. δόντος δὲ πίστιν ἐπὶ τούτοις ἔλεγεν ὡς εἴη τις συνθήκη ἐπιθέσθαι δι’ αὐτοχειρίας βασιλεῖ τὸν Τίρωνα, προσελθεῖν γὰρ εὔπορον εἶναι μόνον μόνῳ καὶ δράσαντα παθεῖν τι τῶν εἰκότων οὐκ ἀγεννὲς Ἀλεξάνδρῳ χαριζόμενον. ταῦτα μὲν οὖν ἐκεῖνος εἰπὼν ἐξαιρεῖται τὸν πατέρα τῆς ἀνάγκης, ἄδηλον εἴτε τὴν ἀλήθειαν ἐκβιασθεὶς φράζειν, εἴτε κἂν παραγραφὴν νοήσας τινὰ ταύτην τῶν κακῶν αὐτῷ καὶ τῷ γεγεννηκότι.", "st": "16.11.6"}, {"sp": "N", "t": "Ὁ δὲ Ἡρώδης οὐδ’ εἴ τι πρότερον ἦν αὐτῷ ἐνδοιάσιμον περὶ τὴν τεκνοκτονίαν τούτῳ τόπον ἢ χώραν ἐν τῇ ψυχῇ καταλελοιπώς, ἀλλὰ πᾶν ἐξῃρημένος τὸ δυνησόμενον αὐτῷ μετάνοιαν ἀμείνονος λογισμοῦ παρασχεῖν ἔσπευσεν ἤδη τέλος ἐπιθεῖναι τῇ προαιρέσει. καὶ προαγαγὼν εἰς ἐκκλησίαν τριακοσίους τε τῶν ἡγεμόνων τοὺς ἐν αἰτίᾳ γενομένους καὶ τὸν Τίρωνα σὺν τῷ παιδὶ καὶ τῷ πρὸ ἐκείνου διελέγχοντι κουρεῖ κατηγορίαν ἁπάντων αὐτῶν ἐποιήσατο. κἀκείνους μὲν τὸ πλῆθος ἀεὶ τοῖς παρατυχοῦσιν βάλλοντες ἀπέκτειναν. Ἀλέξανδρος δὲ καὶ Ἀριστόβουλος ἀχθέντες εἰς Σεβαστὴν ἐπιτάξαντος τοῦ πατρὸς στραγγάλῃ κτείνονται. τὰ δὲ σώματα νύκτωρ εἰς Ἀλεξάνδρειον ἀπέθεντο τοῦ τε μητροπάτορος ἐκεῖ καὶ τῶν πλείστων αὐτοῖς προγόνων κειμένων.", "st": "16.11.7"}, {"sp": "N", "t": "Ἴσως μὲν οὖν οὐκ ἄλογον ἐνίοις καταφαίνεται τρεφόμενον ἐκ πολλοῦ τὸ μῖσος οὕτως αὐξηθῆναι καὶ περαιτέρω προελθὸν ἀπονικῆσαι τὴν φύσιν. ἐπίστασις δὲ γένοιτ’ ἂν εἰκότως, εἴτε εἰς τοὺς νεανίσκους ἀνοιστέον τὴν τοιαύτην αἰτίαν πρὸς αἰτίαν ἐνάγοντας τὸν πατέρα καὶ χρόνῳ παρασκευάσαντας ὑπὸ χαλεπότητος ἀνήκεστον αὐτοῖς, εἴτε καὶ πρὸς αὐτὸν ἐκεῖνον, ἀπαθῆ καὶ περιττὸν ὄντα περὶ τὴν ἐπιθυμίαν τῆς ἀρχῆς καὶ τῆς ἄλλης εὐδοξίας, ὡς μηδένα οἴεσθαι παραλειπτέον ἐφ’ ᾧ πᾶν τὸ βουλόμενον ἀνίκητον ἔχειν, ἢ καὶ τὴν τύχην παντὸς εὐγνώμονος λογισμοῦ μείζω τὴν δύναμιν ἐσχηκυῖαν, ὅθεν καὶ πειθόμεθα τὰς ἀνθρωπίνας πράξεις ὑπ’ ἐκείνης προκαθωσιῶσθαι τῇ τοῦ γενέσθαι πάντως ἀνάγκῃ καὶ καλοῦμεν αὐτὴν εἱμαρμένην, ὡς οὐδενὸς ὄντος, ὃ μὴ δι’ αὐτὴν γίνεται. τοῦτον μὲν οὖν τὸν λόγον ὡς μείζω πρὸς ἐκεῖνον ἀρκέσει κινεῖν ἡμῖν τε αὐτοῖς ἀποδιδόντας τι καὶ τὰς διαφορὰς τῶν ἐπιτηδευμάτων οὐκ ἀνυπευθύνους ποιοῦντας, ἃ πρὸ ἡμῶν ἤδη πεφιλοσόφηται καὶ τῷ νόμῳ. τῶν δὲ ἄλλων δύο τὸν μὲν ἀπὸ τῶν παίδων μέμψαιτ’ ἄν τις αἰτίαν ὑπό τε αὐθαδείας νεωτερικῆς καὶ βασιλικῆς οἰήσεως, ὅτι καὶ διαβολῶν ἠνείχοντο κατὰ τοῦ πατρὸς καὶ τῶν πραττομένων αὐτῷ περὶ τὸν βίον οὐκ εὐμενεῖς ἦσαν ἐξετασταί, καὶ κακοήθεις μὲν ὑπονοεῖν, ἀκρατεῖς δὲ λέγειν, εὐάλωται δὲ δι’ ἀμφότερα τοῖς ἐπιτηροῦσιν αὐτοὺς καὶ πρὸς χάριν καταμηνύουσιν. ὁ μέντοι πατὴρ οὐδ’ ἐντροπῆς ἄξιος ἔοικεν φαίνεσθαι τοῦ περὶ ἐκείνους ἀσεβήματος, ὃς οὔτε πίστιν ἐπιβουλῆς ἐναργῆ λαβὼν οὔτε παρασκευὴν ἐπιχειρήσεως ἐλέγχειν ἔχων ἐτόλμησεν ἀποκτεῖναι τοὺς ἐξ αὐτοῦ φύντας, ἀρίστους μὲν τὰ σώματα καὶ περιποθήτους πᾶσιν τοῖς ἀλλοτρίοις, οὐκ ἀποδέοντας δὲ ἐν τοῖς ἐπιτηδεύμασιν, εἴ που θηρᾶν ἢ γυμνάζεσθαι τὰ πολέμων ἢ λέγειν ὑπὲρ τῶν ἐμπεσόντων ἔδει. τούτων γὰρ ἁπάντων μετεῖχον, Ἀλέξανδρος δὲ καὶ μᾶλλον ὁ πρεσβύτερος· ἤρκει γάρ, εἰ καὶ κατέγνω, καὶ ζῶντας ὅμως ἐν δεσμοῖς ἢ ξενιτεύοντας ἀπὸ τῆς ἀρχῆς ἔχειν μεγάλην ἀσφάλειαν αὐτῷ περιβεβλημένῳ τὴν Ῥωμαίων δύναμιν, δι’ ἣν οὐδὲν οὐδ’ ἐξ ἐφόδου καὶ βίας παθεῖν ἐδύνατο. τὸ δ’ ἀποκτεῖναι ταχὺ καὶ πρὸς ἡδονὴν τοῦ νικῶντος αὐτὸν πάθους ἀσεβείας τεκμήριον ἀνυποτιμήτου καὶ τῆς ἡλικίας οὔσης ἐν γήρᾳ τοσοῦτον ἐξήμαρτεν. ἥ γε μὴν παρολκὴ καὶ τὸ χρονίζον οὐκ ἂν αὐτῷ συγγνώμην τινὰ φέροι· ταχὺ μὲν γὰρ ἐκπλαγέντα καὶ κεκινημένον χωρῆσαι πρός τι τῶν ἀτόπων, εἰ καὶ δυσχερές, ἀλλ’ ἀεὶ συμβαῖνον, ἐν ἐπιστάσει δὲ καὶ μήκει πολλάκις μὲν ὁρμηθέντα πολλάκις δὲ μελλήσαντα τὸ τελευταῖον ὑποστῆναι καὶ διαπράξασθαι, φονώσης καὶ δυσμετακινήτου ψυχῆς ἀπὸ τῶν χειρόνων. ἐδήλωσεν δὲ καὶ τοῖς αὖθις οὐκ ἀποσχόμενος οὐδὲ τῶν περιλοίπων ὅσους ἐδόκει φιλτάτους, ἐφ’ οἷς τὸ μὲν δίκαιον ἔλαττον ἐποίει συμπαθεῖσθαι τοὺς ἀπολλυμένους, τὸ δ’ ὠμὸν ὅμοιον ἦν τὸ μηδὲ ἐκείνων φεισάμενον. διέξιμεν δὲ ὑπὲρ αὐτῶν ἑξῆς ἀφηγούμενοι.", "st": "16.11.8"}, {"sp": "HDR", "t": "Βιβλίον ΙΖʹ", "st": "17"}, {"sp": "N", "t": "Ἀντιπάτρῳ δὲ ἀραμένῳ τοὺς ἀδελφοὺς ἀσεβείᾳ τε τῇ ὑστάτῃ καὶ ἀλαστορίᾳ τῇ ἐπ’ αὐτοῖς τὸν πατέρα περιβεβληκότι οὔτι κατὰ γνώμας ἡ ἐλπὶς τοῦ αὖθις βίου ἦν· ἀπαλλαγεὶς γὰρ φόβου τοῦ ἐπὶ τῇ ἀρχῇ διὰ τὸ τῶν ἀδελφῶν μὴ ἐπικοινωνῆσον, ἐργωδέστερον καὶ ἄπορον αὐτῷ εὕρισκεν τὸ τῆς βασιλείας περιγενέσθαι· τοσόνδ’ ἐφύη τῷ ἔθνει μῖσος πρὸς αὐτόν. ὄντος δὲ αὐτῷ καὶ τοῦδε χαλεποῦ πλειόνως παρελύπει τὸ στρατιωτικὸν ἀλλοτρίως ἔχον τῇ γνώμῃ πρὸς αὐτόν, εἰς οὓς τὰ πάντα ἦν τοῖς βασιλεῦσιν ἀνακείμενα τοῦ οἰκείου ἀσφαλοῦς, ὁπότε τύχοι τὸ ἔθνος νεωτέρων ὀριγνώμενον πραγμάτων· τοσόνδε κίνδυνον ἐμνήστευσεν αὐτῷ ὁ ὄλεθρος τῶν ἀδελφῶν. οὐ μὴν ἀλλὰ καὶ συνῆρχέν γε τῷ πατρὶ οὐδὲν ἄλλο ἢ ὡς βασιλεὺς ὢν καὶ ἐπιστεύετο παρ’ αὐτῷ μειζόνως, ἐξ ὧν ἀπολωλέναι καλῶς εἶχεν εὐνοίας βεβαιώματα εὑρημένος, ὡς ἐπ’ ἀσφαλείᾳ σωτηρίας τῆς Ἡρώδου τοὺς ἀδελφοὺς ἐνδεδειχώς, ἀλλ’ οὐκ ἔχθρᾳ τῇ πρὸς ἐκείνους καὶ πρὸ αὐτῶν πρὸς τὸν πατέρα τοιαίδε αὐτὸν περιεσπένδον ἀραί. ἅπερ δὴ πάντα μηχαναὶ τῆς ἐπὶ τὸν Ἡρώδην ὁδοῦ ἵσταντο Ἀντιπάτρῳ, ἐρημοῦντι αὐτὸν μὲν κατηγόρων ἐφ’ οἷς πράττειν διενοεῖτο, Ἡρώδην δὲ καταφυγῆς οἳ βοηθοῖεν αὐτῷ τοῦ Ἀντιπάτρου φανερῶς πολεμίου καταστάντος· ὥστε μίσει μὲν τῷ πρὸς τὸν πατέρα ἔπρασσεν τὴν ἐπιβουλὴν τῶν ἀδελφῶν, τὸ δὲ ἥπτετο μειζόνως τοῦ ἐγχειρῶν μὴ ἀφίεσθαι τῆς πράξεως· ἀποθνήσκοντος μὲν γὰρ Ἡρώδου, βεβαίως αὐτῷ περιγενομένης τῆς ἀρχῆς, ἐξικνουμένου δὲ εἰς τὸ πλέον ἔτι ζῆν, κινδύνων ἀντιπεριστάντων ἐξαγγέλτου γενομένης τῆς πράξεως, ἧς συνθέτης γεγονὼς πολέμιον ἠνάγκαζε τὸν πατέρα καταστῆναι. καὶ διὰ τοῦ χαρίζεσθαι πολυτελὴς ἦν τοὺς περὶ τὸν πατέρα, κέρδεσι μεγάλοις ἐκπλήσσων τὸ τῶν ἀνθρώπων μῖσος πρὸς αὐτὸν καὶ μάλιστα τοὺς ἐπὶ Ῥώμης φίλους πομπαῖς μεγάλων δωρεῶν εὔνους καθιστάμενος, πρὸ πάντων δὲ Σατορνῖνον τὸν τῆς Συρίας ἐπιμελητήν. ὑπάξεσθαί τε ἦν ἐλπὶς αὐτῷ καὶ τὸν Σατορνίνου ἀδελφὸν μεγέθει δώρων, ἃ ἐδίδου, καὶ τὴν ἀδελφὴν τοῦ βασιλέως ἀνδρὶ πρώτῳ τῶν περὶ τὸν Ἡρώδην συνοικοῦσαν τῷ αὐτῷ τρόπῳ χρώμενος. ψευσάμενός τε φιλίαν πρὸς τοὺς ὁμιλοῦντας δεινότατός τις ἦν πεπιστεῦσθαι καὶ μῖσος ἀράμενος ἐφ’ οὕστινας ἐπικρύψασθαι συνετώτατος. οὐ μὴν ἠπάτα γε τὴν τηθίδα προκατανενοηκυῖαν ἐκ πλείονος αὐτὸν καὶ μηκέθ’ οἷαν οὖσαν παραλογισθῆναι καὶ διὰ τὸ ἤδη παρασκευῇ τῇ πάσῃ ἀντιτετάχθαι αὐτοῦ πρὸς τὸ κακότροπον. καίτοι θυγατρὶ αὐτῆς συνῴκει θεῖος πρὸς μητρὸς Ἀντιπάτρου προνοίᾳ τῇ ἐκείνου καὶ διαπράξει παραλαβὼν τὴν κόρην πρότερον Ἀριστοβούλῳ γεγαμημένην· τὴν δὲ ἑτέραν ὁ ἐκ τοῦ ἀνδρὸς αὐτῆς Καλλέα παῖς γυναῖκα εἶχεν. ἀλλ’ οὐδὲν ἐπὶ τῷ μὴ κατανοεῖσθαι πονηρὸν ὄντα ἦν ἡ ἐπιγαμία τεῖχος, ὥσπερ οὐδ’ ἡ πρότερον συγγένεια πρὸς τὸ οὐ μεμισῆσθαι. τὴν δὲ Σαλώμην Ἡρώδης ἐσπουδακυῖαν Συλλαίῳ τῷ Ἄραβι γαμηθῆναι κατ’ ἐρωτικὴν ἐπιθυμίαν βιάζεται τῷ Ἀλεξᾷ συνοικεῖν συμπρασσούσης αὐτῷ Ἰουλίας καὶ πειθούσης τὴν Σαλώμην μὴ ἀνήνασθαι τὸν γάμον, μὴ καὶ ἔχθρα καθίσταιτο αὐτοῖς προύπτως ὀμωμοκότος Ἡρώδου μὴ ἂν εὐνοήσειν Σαλώμῃ μὴ ὑποδεξαμένῃ τὸν Ἀλεξᾶ γάμον. καὶ ἐπείθετο Καίσαρός τε οὔσῃ γυναικὶ τῇ Ἰουλίᾳ καὶ ἄλλως συμβουλευούσῃ πάνυ συμφέροντα. ἐν τούτῳ δὲ καὶ τὴν Ἀρχελάου θυγατέρα τοῦ βασιλέως Ἡρώδης ὡς τὸν αὐτῆς πατέρα ἐξέπεμψεν Ἀλεξάνδρῳ συνῳκηκυῖαν ἐκ τῶν αὐτοῦ τὴν προῖκα ἀποδούς, ὥστε ἀμφισβήτημα αὐτοῖς μηδὲν εἶναι.", "st": "17.1.1"}, {"sp": "N", "t": "Ἀνέτρεφεν δὲ αὐτὸς τῶν παίδων τὰ τέκνα πάνυ ἐπιμελῶς· ἦσαν γὰρ τῷ μὲν Ἀλεξάνδρῳ ἐκ Γλαφύρας ἄρσενες δύο, Ἀριστοβούλῳ δὲ ἐκ Βερενίκης τῆς Σαλώμης θυγατρὸς ἄρσενές τε τρεῖς καὶ θήλειαι δύο. καί ποτε παρόντων αὐτῷ τῶν φίλων παραστησάμενος τὰ παιδάρια καὶ τῶν υἱέων ἀνακλαύσας τὴν τύχην ηὔχετο μηδὲν τοιόνδε παισὶν τοῖς ἐκείνων συνελθεῖν, αὐξηθέντας δὲ ἀρετῇ καὶ συμφορᾷ τοῦ δικαίου τὰς τροφὰς ἀμείψασθαι, ἃς ποιοῖτο. ἐγγεγύητό τε εἰς γάμον, ὁπότε ἀφικοίατο εἰς ὥραν τὴν ἐπ’ αὐτῷ, τῷ μὲν πρεσβυτέρῳ τῶν Ἀλεξάνδρου παίδων Φερώρου θυγατέρα, τῷ δὲ Ἀριστοβούλου τὴν Ἀντιπάτρου, καὶ θυγατέρα τὴν Ἀριστοβούλου ἐπωνόμαζε παιδὶ τῷ Ἀντιπάτρου, τὴν δὲ ἑτέραν τῶν Ἀριστοβούλου θυγατέρων Ἡρώδῃ παιδὶ τῷ αὑτοῦ· γίνεται δὲ τῷ βασιλεῖ οὗτος ἐκ τῆς τοῦ ἀρχιερέως θυγατρός· πάτριον γὰρ πλείοσιν ἐν ταὐτῷ ἡμῖν συνοικεῖν. ἔπρασσε δὲ τὰς μνηστείας τῶν παίδων ὁ βασιλεὺς ἐλέῳ τῶν ὀρφανῶν εἰς εὔνοιαν αὐτῶν διὰ τὴν ἐπιγαμίαν τὸν Ἀντίπατρον προκαλούμενος. Ἀντίπατρος δὲ γνώμῃ τῇ πρὸς τοὺς ἀδελφοὺς πολιτεύειν οὐκ ἐνέλιπεν καὶ πρὸς τοὺς παῖδας αὐτοῖς γεγονότας, ἥ τε τοῦ πατρὸς σπουδὴ περὶ αὐτοὺς ἠρέθιζεν αὐτὸν μείζονας ἔσεσθαι τῶν ἀδελφῶν προσδεχόμενον, καὶ μάλιστα ὁπότε ἀνδρωθεῖεν, Ἀρχελάου προσληψομένου τοῖς θυγατριδοῖς βασιλέως ἀνδρὸς καὶ Φερώρου τῷ ληψομένῳ τὴν θυγατέρα· τετράρχης δὲ καὶ οὗτος ἦν. ἐπήγειρε δ’ αὐτὸν καὶ τὸ πᾶν πλῆθος ἐλέῳ μὲν τὰ πρὸς τοὺς ὀρφανοὺς χρώμενον, μίσει δὲ πρὸς αὐτὸν τὰ πάντα ἐξαγαγεῖν οὐκ ἀπηλλαγμένον κακοτροπίᾳ τῇ ἐπὶ τοῖς ἀδελφοῖς. ἐμηχανᾶτο οὖν διάλυσιν τῶν τῷ πατρὶ ἐγνωσμένων, ἐν δεινῷ τιθέμενος προσλήψει τοσῆσδε αὐτοὺς ὁμιλῆσαι δυνάμεως. καὶ μετέπιπτεν Ἡρώδης εἴκων δεήσει τῇ Ἀντιπάτρου, ὥστε αὐτὸν μὲν τὴν Ἀριστοβούλου θυγατέρα γαμεῖν καὶ τὴν Φερώρου τὸν υἱὸν αὐτοῦ. καὶ τὰ μὲν τῶν ὁμολογιῶν τοῦ γάμου τοῦτον κινεῖται τὸν τρόπον ἄκοντος τοῦ βασιλέως.", "st": "17.1.2"}, {"sp": "N", "t": "Ἡρώδῃ δὲ τῷ βασιλεῖ κατὰ τοῦτον τὸν χρόνον συνῴκουν ἐννέα γυναῖκες, ἥ τε Ἀντιπάτρου μήτηρ καὶ ἡ θυγάτηρ τοῦ ἀρχιερέως, ἐξ ἧς δὴ καὶ ὁμώνυμος αὐτῷ παῖς γεγόνει· ἦν δὲ καὶ ἀδελφοῦ παῖς αὐτῷ μία γεγαμημένη καὶ ἀνεψιὰ σὺν αὐτῇ. καὶ ταῖσδε μὲν τέκνον οὐδὲν ἐφύη. ἦν δ’ ἐν ταῖς γυναιξὶν κἀκ τοῦ Σαμαρέων ἔθνους μία καὶ παῖδες αὐτῆς Ἀντίπας καὶ Ἀρχέλαος καὶ θυγάτηρ Ὀλυμπιάς. καὶ ταύτην μὲν ὕστερον Ἰώσηπος γαμεῖ βασιλέως ἀδελφιδοῦς ὤν, Ἀρχέλαος δὲ καὶ Ἀντίπας ἐπὶ Ῥώμης παρά τινι ἰδίῳ τροφὰς εἶχον. Κλεοπάτρα δὲ Ἱεροσολυμῖτις γεγάμητο αὐτῷ καὶ παῖδες ἐξ αὐτῆς Ἡρώδης τε ἐγεγόνεισαν καὶ Φίλιππος, ὃς καὶ αὐτὸς ἐν Ῥώμῃ τροφὰς εἶχεν. καὶ Παλλὰς δὲ ἐν ταῖς γαμεταῖς Φασάηλον πεποιημένη παῖδα αὐτῷ, πρός γε μὴν ταύταις Φαῖδρα καὶ Ἐλπίς, ἐξ ὧν θυγατέρες δύο ἦσαν Ῥωξάνη καὶ Σαλώμη. τὰς δὲ πρεσβυτέρας αὐτοῦ θυγατέρας ὁμομητρίας τῶν περὶ Ἀλέξανδρον, ὧν περιεώρα Φερώρας τὸν γάμον, συνῴκουν ἡ μὲν Ἀντιπάτρῳ τοῦ βασιλέως ἀδελφῆς παιδὶ ὄντι, Φασαήλῳ δὲ ἡ ἑτέρα· καὶ οὗτος Ἡρώδου ἀδελφοῦ παῖς ἐγεγόνει. καὶ τοῦτο μὲν Ἡρώδου τὸ γένος ἦν.", "st": "17.1.3"}, {"sp": "N", "t": "Τότε δὲ βουλόμενος πρὸς Τραχωνίτας ἀσφαλὴς εἶναι, κώμην πόλεως μέγεθος οὐκ ἀποδέουσαν ἔγνω Ἰουδαίων κτίσαι ἐν μέσῳ, δυσέμβολόν τε ποιεῖν τὴν αὐτοῦ καὶ τοῖς πολεμίοις ἐξ ἐγγίονος ὁρμώμενος ἐκ τοῦ ὀξέος κακουργεῖν. καὶ ἐπιστάμενος ἄνδρα Ἰουδαῖον ἐκ τῆς Βαβυλωνίας σὺν πεντακοσίοις ἱπποτοξόταις πᾶσι καὶ συγγενῶν πλήθει εἰς ἑκατὸν ἀνδρῶν τὸν Εὐφράτην διαβεβηκότα κατὰ τύχας ἐν Ἀντιοχείᾳ τῇ ἐπὶ Δάφνῃ τῆς Συρίας διαιτᾶσθαι Σατορνίνου τοῦ τότε στρατηγοῦντος εἰς ἐνοίκησιν αὐτῷ δεδωκότος χωρίον, Οὐλαθὰ ὄνομα αὐτῷ, μετεπέμπετο τοῦτον σὺν τῷ πλήθει τῶν ἑπομένων, παρέξειν ὑπισχνούμενος γῆν ἐν τοπαρχίᾳ τῇ λεγομένῃ Βαταναίᾳ, ὡρίζετο δὲ αὕτη τῇ Τραχωνίτιδι, βουλόμενος πρόβλημα τὴν κατοίκησιν αὐτοῦ κτᾶσθαι, ἀτελῆ τε τὴν χώραν ἐπηγγέλλετο καὶ αὐτοὺς εἰσφορῶν ἀπηλλαγμένους ἁπασῶν, αἳ εἰωθυῖαι ἐγκατοικεῖν τὴν γῆν ἄπρακτον παρασχόμενος.", "st": "17.2.1"}, {"sp": "N", "t": "Τούτοις πεισθεὶς ὁ Βαβυλώνιος ἀφικνεῖται καὶ λαβὼν τὴν γῆν φρούρια ᾠκοδομήσατο καὶ κώμην, Βαρθύραν ὄνομα αὐτῇ θέμενος. πρόβλημά τε ἦν οὗτος ὁ ἀνὴρ καὶ τοῖς ἐγχωρίοις τὰ πρὸς τοὺς Τραχωνίτας καὶ Ἰουδαίων τοῖς ἐκ Βαβυλῶνος ἀφικνουμένοις κατὰ θυσίαν ἐπὶ Ἱεροσολύμων τοῦ μὴ λῃστείαις ὑπὸ τῶν Τραχωνιτῶν κακουργεῖσθαι, πολλοί τε ὡς αὐτὸν ἀφίκοντο καὶ ἁπανταχόθεν, οἷς τὰ Ἰουδαίων θεραπεύεται πάτρια. καὶ ἐγένετο ἡ χώρα σφόδρα πολυάνθρωπος ἀδείᾳ τοῦ ἐπὶ πᾶσιν ἀτελοῦς, ἃ παρέμεινεν αὐτοῖς Ἡρώδου ζῶντος. Φίλιππος δὲ υἱὸς ἐκείνου παραλαβὼν τὴν ἀρχὴν ὀλίγα τε καὶ ἐπ’ ὀλίγοις αὐτοὺς ἐπράξατο, Ἀγρίππας μέντοι γε ὁ μέγας καὶ ὁ παῖς αὐτοῦ καὶ ὁμώνυμος καὶ πάνυ ἐξετρύχωσαν αὐτούς, οὐ μέντοι τὰ τῆς ἐλευθερίας κινεῖν ἠθέλησαν. παρ’ ὧν Ῥωμαῖοι δεξάμενοι τὴν ἀρχὴν τοῦ μὲν ἐλευθέρου καὶ αὐτοὶ τηροῦσιν τὴν ἀξίωσιν, ἐπιβολαῖς δὲ τῶν φόρων εἰς τὸ πάμπαν ἐπίεσαν αὐτούς. καὶ τάδε μὲν ᾗ καιρὸς ἀκριβώσομαι προϊόντος τοῦ λόγου.", "st": "17.2.2"}, {"sp": "N", "t": "Τελευτᾷ δὲ Ζάμαρις ὁ Βαβυλώνιος, ὃς ἐπὶ κτήσει τῆσδε τῆς χώρας Ἡρώδῃ προσποιεῖται, ζήσας τε μετὰ ἀρετῆς καὶ παῖδας λειπόμενος ἀγαθούς, Ἰάκειμον μέν, ὃς ἀνδρείᾳ γενόμενος ἐπιφανὴς ἱππεύειν συνεκρότησε τὸ ὑφ’ αὑτῷ Βαβυλώνιον, καὶ ἴλη τῶνδε τῶν ἀνδρῶν ἐδορυφόρει τούσδε τοὺς βασιλέας. καὶ Ἰάκειμος δὲ ἐν γήρᾳ τελευτῶν Φίλιππον τὸν υἱὸν κατέλιπεν ἄνδρα κατὰ χεῖρας ἀγαθὸν καὶ τὰ ἄλλα ἀρετῇ χρῆσθαι παρ’ ὁντινοῦν ἀξιόλογον. διόπερ φιλία τε πιστὴ καὶ εὔνοια ἀσφαλὴς αὐτῷ πρὸς Ἀγρίππαν γίνεται τὸν βασιλέα, στρατιάν τε ὁπόσην ὁ βασιλεὺς ἔτρεφεν οὗτος ἀσκῶν διετέλει καὶ ὅπη ἐξοδεύειν δεήσειεν ἡγούμενος.", "st": "17.2.3"}, {"sp": "N", "t": "Ἡρώδου δ’ ἐν οἷς εἶπον ὄντος ἀφεώρα τὰ πάντα πράγματα εἰς Ἀντίπατρον, κἀφ’ οἷς ὠφελήσειεν κυροῦν οὐκ ἀπήλλακτο ἐξουσίας ἐπικεχωρηκότος τε τοῦ πατρὸς ἐλπίδι εὐνοίας καὶ πίστεως, καὶ περαιτέρω κτᾶσθαι τὴν ἐπ’ αὐτοῖς ἐξουσίαν τολμηρὸς καθιστάμενος διὰ τὸ ἄδηλος τῷ πατρὶ εἶναι κακουργῶν κἀφ’ οἷς εἴπειεν πιστότατος. ἦν τε πᾶσιν φοβερὸς οὐχ οὕτως ἰσχύι τῆς ἐξουσίας, ὡς τοῦ κακοτρόπου τῷ προμηθεῖ· μάλιστα δ’ αὐτὸν Φερώρας ἐθεράπευεν καὶ ἀντεθεραπεύετο δεινῶς, πάνυ τοῦ Ἀντιπάτρου περιστοιχίσαντος αὐτὸν καὶ τὴν γυναικωνῖτιν συνισταμένου τὰ πρὸς αὐτόν· ἐδεδούλωτο γὰρ Φερώρας γαμετῇ τε καὶ μητρὶ ταύτης καὶ ἀδελφῇ καὶ ταῦτα μισῶν τὰς ἀνθρώπους ὕβρει θυγατέρων αὐτοῦ παρθένων· ἀλλ’ ὅμως ἠνείχετο, πράσσειν τε οὐδὲν ἦν δίχα τῶν γυναικῶν ἐκπεριωδευκυιῶν τὸν ἄνθρωπον καὶ ἀλλήλαις εὐνοίᾳ συμπράσσειν τὰ πάντα μὴ ἀπηλλαγμένων, ὥστε παντοίως ὁ Ἀντίπατρος ὑπῆκτο αὐτὰς καὶ δι’ αὐτοῦ καὶ διὰ τῆς μητρός· ταὐτὸν γὰρ αἵδε αἱ τέσσαρες γυναῖκες ἔλεγον. καὶ Φερώρᾳ δὲ πρὸς Ἀντίπατρον ἐπ’ οὐδαμινοῖς τισιν αἱ γνῶμαι διήλλασσον. ἀντίσπασμα δ’ ἦν αὐτοῖς βασιλέως ἡ ἀδελφὴ περισκοποῦσά τε ἐκ πλείονος τὰ πάντα καὶ τὴν εὔνοιαν αὐτῶν ἐπὶ κακοῖς τοῖς Ἡρώδου πρασσομένην εἰδυῖά τε καὶ μηνύειν οὐκ ἀποτετραμμένη. καὶ γνόντες ἐν ἀπεχθείᾳ βασιλεῖ τὴν εὔνοιαν αὐτῶν οὖσαν ἐπινοοῦσιν ὥστε φανερὰν μὲν μὴ εἶναι τὴν πρὸς ἀλλήλους αὐτῶν σύνοδον, μίσους δὲ καὶ λοιδοριῶν ᾗ καιρὸς προσποίησιν, καὶ μάλιστα Ἡρώδου παρατυγχάνοντος ἢ οἳ πρὸς αὐτὸν ἀπαγγέλλειν ἔμελλον, κρυπτῶς δὲ τὰ τῆς εὐνοίας ὀχυρώτερα καθίστασθαι. καὶ ἔπρασσον οὕτως. ἐλάνθανεν δὲ τὴν Σαλώμην οὔτε πρῶτον ἡ διάνοια αὐτῶν ἐπὶ τοιοῖσδε ὡρμημένων οὔτε ἐπειδὴ χρῆσθαι οὐκ ἀπήλλακτο αὐτή· πάντα δὲ ἀνίχνευέν τε καὶ πρὸς τὸν ἀδελφὸν μειζόνως ἐκδεινοῦσα ἀπεσήμαινεν συνόδους τε κρυπτὰς καὶ πότους βουλευτήριά τε ἀφανῶς κατεσκευασμένα, ὧν μὴ ἐπ’ ὀλέθρῳ τῷ ἐκείνου συντιθεμένων κἂν πεφανερῶσθαι μὴ κεκωλῦσθαι. νῦν δὲ τοὺς μὲν ἐκ τοῦ προὔπτου διαφόρους καὶ τὰ πάντα ἐπὶ βλάβῃ τῇ ἀλλήλων λέγοντας, εἰς δὲ τὸ ἀφανὲς τοῖς πολλοῖς τὴν εὔνοιαν ἀνατιθεμένους καὶ ὁπότε ἀλλήλοις συμμονωθεῖεν φίλια πράσσειν μὴ ἀπηλλαγμένους, ὁμολογεῖν πολεμεῖν πρὸς οὓς λανθάνειν χρώμενοι εὐνοίᾳ τῇ ἀλλήλων ἐσπουδάκοιεν. καὶ ἡ μὲν ταῦτ’ ἀνίχνευέν τε καὶ ἀκριβῶν τυγχάνουσα τῷ ἀδελφῷ ἀνέφερεν συνιέντι μὲν ἤδη τὰ πολλὰ καὶ δι’ ἑαυτοῦ, εἰς δὲ τὸ θαρσεῖν οὐ διακενῆς ὑπονοῶν καθισταμένῳ διαβολαῖς τῆς ἀδελφῆς. καὶ ἦν γὰρ μόριόν τι Ἰουδαϊκὸν ἀνθρώπων ἐπ’ ἐξακριβώσει μέγα φρονοῦν τοῦ πατρίου καὶ νόμων οἷς χαίρει τὸ θεῖον προσποιουμένων, οἷς ὑπῆκτο ἡ γυναικωνῖτις, Φαρισαῖοι καλοῦνται, βασιλεῖ δυναμένῳ μάλιστα πράσσειν προμηθεῖς κἀκ τοῦ προὔπτου εἰς τὸ πολεμεῖν τε καὶ βλάπτειν ἐπηρμένοι. παντὸς γοῦν τοῦ Ἰουδαϊκοῦ βεβαιώσαντος δι’ ὅρκων ἦ μὴν εὐνοήσειν Καίσαρι καὶ τοῖς βασιλέως πράγμασιν, οἵδε οἱ ἄνδρες οὐκ ὤμοσαν ὄντες ὑπὲρ ἑξακισχίλιοι, καὶ αὐτοὺς βασιλέως ζημιώσαντος χρήμασιν ἡ Φερώρου γυνὴ τὴν ζημίαν ὑπὲρ αὐτῶν εἰσφέρει. οἱ δὲ ἀμειβόμενοι τὴν εὔνοιαν αὐτῆς, πρόγνωσιν δὲ ἐπεπίστευντο ἐπιφοιτήσει τοῦ θεοῦ, προύλεγον, ὡς Ἡρώδῃ μὲν καταπαύσεως ἀρχῆς ὑπὸ θεοῦ ἐψηφισμένης αὐτῷ τε καὶ γένει τῷ ἀπ’ αὐτοῦ, τῆς δὲ βασιλείας εἴς τε ἐκείνην περιηξούσης καὶ Φερώραν παῖδάς τε οἳ εἶεν αὐτοῖς. καὶ τάδε, οὐ γὰρ ἐλάνθανεν τὴν Σαλώμην, ἐξάγγελτα βασιλεῖ ἦν, καὶ ὅτι τῶν περὶ τὴν αὐλὴν διαφθείροιέν τινας. καὶ βασιλεὺς τῶν τε Φαρισαίων τοὺς αἰτιωτάτους ἀναιρεῖ καὶ Βαγώαν τὸν εὐνοῦχον Κᾶρόν τέ τινα τῶν τότε προύχοντα ἀρετῇ τοῦ εὐπρεποῦς καὶ παιδικὰ ὄντα αὐτοῦ. κτείνει δὲ καὶ πᾶν ὅ τι τοῦ οἰκείου συνειστήκει οἷς ὁ Φαρισαῖος ἔλεγεν. ἦρτο δὲ ὁ Βαγώας ὑπ’ αὐτῶν ὡς πατήρ τε καὶ εὐεργέτης ὀνομασθησόμενος τοῦ ἐπικατασταθησομένου προρρήσει βασιλέως· κατὰ χεῖρα γὰρ ἐκείνῳ τὰ πάντ’ εἶναι, παρέξοντος αὐτῷ γάμου τε ἰσχὺν καὶ παιδώσεως τέκνων γνησίων.", "st": "17.2.4"}, {"sp": "N", "t": "Ἡρώδης δὲ κολάσας τῶν Φαρισαίων τοὺς ἐπὶ τοῖσδε ἐληλεγμένους συνέδριόν τε ποιεῖται τῶν φίλων καὶ κατηγορίαν τῆς Φερώρου γυναικός, τήν τε ὕβριν τῶν παρθένων τῇ τόλμῃ τῆς γυναικὸς ἀνατιθεὶς καὶ ἔγκλημα ταύτην ἀτιμίαν αὐτῷ ποιούμενος, ὥστε ἀγωνοθετῶν στάσιν αὐτῷ πρὸς τὸν ἀδελφὸν πόλεμον ἐκ φύσεως αὐτοῖς καὶ λόγῳ καὶ δι’ ἔργων ὁπόσα δύναιτο, τήν τε διάλυσιν τῆς ζημίας τῆς ὑπ’ αὐτοῦ ἐπιβληθείσης τέλεσι διαφευχθείσης τοῖς ἐκείνης, τῶν τε νῦν πεπραγμένων οὐδὲν ὅ τι οὐ μετ’ αὐτῆς. ἀνθ’ ὧν, ὦ Φερώρα, καλῶς εἶχεν οὐ δεήσει οὐδὲ γνωμῶν εἰσηγήσεως τῶν ἐμῶν αὐτοκέλευστον ἀποπέμπεσθαι γυναῖκα ταύτην ὡς πολέμου τοῦ πρός μέ σοι αἰτίαν ἐσομένην· καὶ νῦν, εἴπερ ἀντιποιῇ συγγενείας τῆς ἐμῆς, ἀπείπασθαι τήνδε τὴν γαμετήν· μενεῖς γὰρ οὕτως ἀδελφός τε καὶ στέργειν οὐκ ἀπηλλαγμένος. Φερώρας δὲ καίπερ λόγων ἀρετῇ περιωθούμενος οὔτε συγγενείας τῆς πρὸς τὸν ἀδελφὸν ἔλεγε κινήσειν δίκαιον οὐδὲν οὔτε τῶν πρὸς τὴν γαμετὴν εὐνοιῶν, αἱρεῖσθαί τε πρότερον θανεῖν ἢ ζῶν τολμᾶν ἀπεστερῆσθαι γυναικὸς αὐτῷ κεχαρισμένης. Ἡρώδης δὲ Φερώρᾳ μὲν ὑπερεβάλλετο τὴν ἐπὶ τούτοις ὀργὴν καίπερ ἀνήδονον τιμωρίαν εἰσπεπραγμένος, Ἀντιπάτρῳ δὲ ἀπεῖπε καὶ μητρὶ τῇ ἐκείνου Φερώρᾳ τε μὴ ὁμιλεῖν καὶ τῶν γυναικῶν φυλάσσεσθαι τὸ εἰς ταὐτὸν συνεσόμενον. οἱ δ’ ὡμολόγουν μέν, συνῄεσαν δὲ ᾗ καιρὸς καὶ συνεκώμαζον Φερώρας καὶ Ἀντίπατρος. ἐφοίτα δὲ λόγος ὁμιλεῖν καὶ Ἀντιπάτρῳ τὴν Φερώρου γυναῖκα συμπρασσούσης αὐτοῖς τὰ εἰς τὴν σύνοδον τῆς Ἀντιπάτρου μητρός.", "st": "17.3.1"}, {"sp": "N", "t": "Ὑφορώμενος δὲ τὸν πατέρα καὶ δεδιώς, μὴ εἰς πλεῖον προχωροίη τὰ τοῦ μίσους ἐπ’ αὐτῷ, γράφει πρὸς τοὺς ἐν Ῥώμῃ φίλους κελεύων ἐπιστέλλειν Ἡρώδῃ πέμπειν ᾗ τάχος Ἀντίπατρον ὡς Καίσαρα. οὗ γενομένου ἔπεμπεν Ἡρώδης Ἀντίπατρον δῶρα συμπέμψας ἀξιολογώτατα καὶ διαθήκην, ἐν ᾗ μετ’ αὐτὸν Ἀντίπατρον ἀπεδείκνυε βασιλέα, ἢ φθάντος τελευτῆσαι Ἡρώδην τὸν ἐκ τῆς τοῦ ἀρχιερέως θυγατρὸς υἱὸν αὐτῷ γεγενημένον. συνεξορμᾷ δ’ Ἀντιπάτρῳ καὶ Σύλλαιος ὁ Ἄραψ μηδὲν ὧν προσέταξε Καῖσαρ διαπεπραγμένος, καὶ Ἀντίπατρος αὐτοῦ κατηγορεῖ ἐπὶ Καίσαρος περὶ ὧν πρότερον Νικόλαος. κατηγορεῖτο δὲ καὶ ὑπὸ Ἀρέτα Σύλλαιος, ὡς πολλοὺς ἀπεκτονὼς τῶν ἐν Πέτρᾳ ἀξιολόγων παρὰ γνώμην τὴν αὐτοῦ καὶ μάλιστα Σόαιμον ἄνδρα τῇ ἐς πάντα ἀρετῇ τιμᾶσθαι δικαιότατον, ἀνῃρηκέναι δὲ καὶ Φάβατον Καίσαρος δοῦλον. καὶ Σύλλαιος αἰτίαν εἶχεν ἐκ τοιῶνδε ἐγκλημάτων· Κόρινθος ἦν Ἡρώδου σωματοφύλαξ τοῦ βασιλέως μάλιστα πιστευόμενος ὑπ’ αὐτοῦ. τοῦτον πείθει Σύλλαιος ἐπὶ χρήμασι μεγάλοις Ἡρώδην ἀποκτεῖναι, καὶ ὑπέσχετο. μαθὼν οὖν Φάβατος Συλλαίου πρὸς αὐτὸν εἰρηκότος διηγεῖται πρὸς τὸν βασιλέα. ὁ δὲ τόν τε Κόρινθον βασανίζει συλλαβὼν καὶ πάντα ἀνάπυστα ἦν αὐτῷ. συλλαμβάνει δὲ καὶ δευτέρους Ἄραβας καταγορεύσει τῇ Κορίνθου πειθόμενος τὸν μὲν φύλαρχον ὄντα τὸν δὲ Συλλαίου φίλον. οἳ καὐτοί, βασανίζει γὰρ αὐτοὺς ὁ βασιλεύς, ὡμολόγουν ὅτι παρεῖεν ἐξοτρύνοντες μὴ μαλακίζεσθαι Κόρινθον καὶ εἴ που δεήσειεν καὶ συγχειρουργήσοντες αὐτῷ τὸν φόνον. καὶ Σατορνῖνος δηλώσεως αὐτῷ πάντων ὑπὸ Ἡρώδου γενομένης εἰς Ῥώμην ἐξέπεμψεν αὐτούς.", "st": "17.3.2"}, {"sp": "N", "t": "Φερώραν δὲ ἰσχυρῶς ἐμμένοντα εὐνοίᾳ τῆς γυναικὸς ἀναχωρεῖν εἰς τὴν αὑτοῦ Ἡρώδης κελεύει. ὁ δὲ ἀσμένως ἐπὶ τὴν τετραρχίαν ἀπῆρεν, πολλὰ ὀμόσας οὐ πρότερον ἥξειν ἢ πύθοιτο Ἡρώδην τετελευτηκότα, ὥστε καὶ νοσήσαντος τοῦ βασιλέως ἀξιωθεὶς ἥκειν ἐπί τινων πίστεσιν ἐντολῶν, εἰ μέλλοι τελευτᾶν, οὐχ ὑπήκουσεν ἐπὶ τιμῇ τοῦ ὅρκου. οὐ μὴν Ἡρώδης γε μιμεῖται τὸ ἐπὶ τοιοῖσδε ἐκείνου γνώμην προαποφηνάμενον ἣν ἔχει, ἀλλ’ ἧκεν ὡς τὸν Φερώραν, ἐπειδὴ ὕστερον ἄρχεται νοσεῖν, καὶ μετακλήσεως αὐτῷ μὴ γενομένης, θανόντα δὲ περιστείλας ἐπὶ Ἱεροσολύμων ἀγόμενος ταφῆς ἠξίου καὶ πένθος μέγα ἐπ’ αὐτῷ προέθετο. τοῦτο Ἀντιπάτρῳ καίτοι γε ἐπὶ Ῥώμης πεπλευκότι κακῶν ἐγένετο ἀρχὴ τῆς ἀδελφοκτονίας αὐτὸν τινυμένου θεοῦ. διηγήσομαι δὲ τὸν πάντα περὶ αὐτοῦ λόγον παράδειγμα τῷ ἀνθρωπείῳ γενησόμενον τοῦ ἀρετῇ πολιτεύσοντος ἐπὶ πᾶσιν.", "st": "17.3.3"}, {"sp": "N", "t": "Ἐπειδὴ Φερώρας τελευτᾷ ταφνίται ἐγεγόνεισαν αὐτοῦ ἀπελεύθεροι δύο τῶν Φερώρᾳ τιμίων οὗτοι προσελθόντες Ἡρώδῃ ἠξίουν μὴ ἀνεκδίκητον καταλιπεῖν τοῦ ἀδελφοῦ τὸν νεκρόν, ἀλλὰ ζήτησιν ποιεῖσθαι τῆς ἀλόγου τε καὶ δυστυχοῦς μεταστάσεως. τοῦ δ’ ἐπιστραφέντος τοῖς λόγοις, πιστὰ γὰρ ἐδόκει, δειπνῆσαι μὲν αὐτὸν ἔλεγον παρὰ τῇ γυναικὶ τῇ προτέρᾳ τῆς νόσου, φάρμακον δὲ προσκομισθὲν ἐν βρώματι μὴ πρότερον εἰωθότι ἐμφαγόντα ὑπὸ τούτου τελευτῆσαι· κομιστὸν μέντοι γενέσθαι τὸ φάρμακον ὑπὸ γυναικὸς ἐκ τῆς Ἀραβίας λόγῳ μὲν ἐπὶ προσποιήσεσιν ἐρώτων, φίλτρον γὰρ δὴ ὄνομα αὐτῷ εἶναι, τὸ δ’ ἀληθὲς ἐπὶ τῇ Φερώρου τελευτῇ. φαρμακιστόταται δέ εἰσι γυναικῶν αἱ ἐκ τῆς Ἀραβίας· ᾗ δὲ ταῦτα ἐπεκάλουν καὶ τῆς Συλλαίου ἐρωμένης ἐν ταῖς μάλιστα ὡμολόγητο εἶναι φίλη, πείσουσαί τε αὐτὴν ἐπὶ πράσει τοῦ φαρμάκου εἰς τοὺς τόπους ἐληλύθεσαν ἥ τε μήτηρ τῆς τοῦ Φερώρου γυναικὸς καὶ ἡ ἀδελφὴ καὶ ἐπανῆκον αὐτὴν ἀγόμεναι τοῦ δείπνου πρότερον ἡμέρᾳ μιᾷ. ὑπὸ τούτων ὁ βασιλεὺς τῶν λόγων παροξυνθεὶς δούλας τε ἐβασάνιζε τῶν γυναικῶν καί τινας καὶ ἐλευθέρας, καὶ ὄντος ἀφανοῦς τοῦ πράγματος διὰ τὸ μηδεμίαν ἐξειπεῖν τελευταία τις περιουσῶν αὐτῆς τῶν ἀλγηδόνων ἄλλο μὲν ἔφη οὐδέν, θεὸν δ’ ἐπικαλεῖσθαι τοιαῖσδε αἰκίαις δώσειν περιβαλεῖν τὴν Ἀντιπάτρου μητέρα κακῶν τῶν ἐπεχόντων αἰτίαν πᾶσιν γενομένην. ταῦτα εἰς ἐπίστασιν Ἡρώδην ἄγει, καὶ τὰ πάντα βασάνοις τῶν γυναικῶν ἀνάπυστα ἦν, οἵ τε κῶμοι καὶ κρυπταὶ σύνοδοι καὶ δὴ καὶ λόγων πρὸς μόνον τὸν υἱὸν εἰρημένων ἐξοίσεις πρὸς τὰς Φερώρου γυναῖκας· ἦν δὲ ταλάντων ἑκατὸν δωρεὰς ἐπικρύπτεσθαι φράζειν πρὸς Φερώραν τῷ Ἀντιπάτρῳ κέλευσις ὑπὸ τοῦ πατρός· μῖσός τε πρὸς τὸν πατέρα καὶ ὀλοφυρμοὶ πρὸς τὴν μητέρα, ὡς ἐπὶ μήκιστον τοῦ πατρὸς βιοῦν ἐξηγμένου καὶ αὐτῷ μηδὲν ἐλάσσονος τοῦ γήρως ἐπικειμένου, ὡς μηδ’ ἂν ἐλθοῦσαν τὴν βασιλείαν ὁμοίως εὐφρᾶναί ποτ’ αὐτόν· παρατρέφεσθαί τε πολλοὺς ἐπὶ τῇ βασιλείᾳ καὶ ἀδελφοὺς καὶ ἀδελφῶν παῖδας οὐδαμῶς ἀδεῆ τὴν ἐλπίδα παρεχομένους τἀσφαλοῦς· καὶ γὰρ δὴ καὶ νῦν, εἴ τι πάσχειν, αὐτὸν ἀδελφῷ μᾶλλον ἢ παιδὶ τῷ αὐτοῦ κελεύειν τὴν ἀρχὴν δίδοσθαι. ὠμότητά τε πολλὴν κατηγόρει τοῦ βασιλέως καὶ τὰς σφαγὰς τῶν υἱέων, φόβῳ τε μὴ καὶ αὐτῶν ἅπτοιτο ἤδη τὸν μὲν ἐπὶ Ῥώμης ἄρασθαι τέχνην ἐπινοῆσαι, Φερώραν δὲ ἐπὶ τῆς αὐτοῦ τετραρχίας.", "st": "17.4.1"}, {"sp": "N", "t": "Ταῦτα συνῇδεν γὰρ τοῖς λόγοις τῆς ἀδελφῆς, καὶ πολὺ τοῦ μὴ ἀπιστίαν ἔτι ὑποπτεύεσθαι συνῆγεν αὐτοῖς, ὁ βασιλεὺς κρατυνάμενος ἐπὶ κακίᾳ τῇ Ἀντιπάτρου τὴν Δῶριν τὴν μητέρα αὐτοῦ πάντα τὸν περὶ αὐτὴν κόσμον ταλάντων πολλῶν ὄντα ἀφελόμενος ἔπειτα αὐτὴν ἀποπέμπεται καὶ ταῖς Φερώρου γυναιξὶν φιλίαν ἐσπείσατο. μάλιστα δ’ ἐξώτρυνεν εἰς ὀργὴν κατὰ τοῦ παιδὸς τὸν βασιλέα Σαμαρείτης ἀνὴρ Ἀντίπατρος ἐπιτροπεύων τὸν υἱὸν τοῦ βασιλέως Ἀντίπατρον, ἄλλα τε αὐτοῦ ἐν ταῖς βασάνοις κατειπὼν καὶ ὅτι παρασκευασάμενος φάρμακον θανάσιμον δοίη Φερώρᾳ κελεύσας παρὰ τὴν ἀποδημίαν αὐτοῦ, ἵν’ ὡς πλεῖστον ἀφεστήκοι τῶν ἐν τοιούτοις ὑποτοπασμῶν, τῷ πατρὶ δοῦναι. καὶ κομίσαι μὲν Ἀντίφιλον ἐξ Αἰγύπτου τὸ φάρμακον ἕνα τῶν Ἀντιπάτρου φίλων, σταλῆναι δὲ ὡς Φερώραν διὰ Θευδίωνος μητρὸς Ἀντιπάτρου ἀδελφοῦ τοῦ βασιλέως παιδός, καὶ οὕτως ἐλθεῖν τὸ φάρμακον εἰς τὴν γυναῖκα τὴν Φερώρου δόντος φυλάσσειν τοῦ ἀνδρὸς αὐτῆς. ἡ δὲ ὡμολόγει μὲν ἀνακρίναντος τοῦ βασιλέως, καὶ δραμοῦσα ὡς κομίσειεν ῥίπτει κατὰ τέγους ἑαυτήν, οὐ μὴν τελευτᾷ ἐπὶ πόδας τῆς πτώσεως γενομένης. καὶ οὕτως ἐπεὶ ἀνεκτήσατο αὐτὴν ἄδειάν τε αὐτῇ ὑπισχνούμενος καὶ τοῖς οἰκείοις μηδὲν ἐπ’ ἀφανισμῷ τἀληθοῦς τρεπομένῃ, τρίψειν γε μὴν κακοῖς τοῖς ὑστάτοις ἀγνωμονεῖν προθεμένην, ὑπισχνεῖται καὶ ὤμοσεν ἦ μὴν ἐρεῖν τὰ πάντα ὃν ἐπράχθη τρόπον, λέγουσα μὲν, ὡς ἔφασαν οἱ πολλοὶ τῶν ἀνθρώπων ἀληθῆ τὰ πάντα. κεκόμισται γὰρ ἐκ τῆς Αἰγύπτου τὸ φάρμακον ὑπ’ Ἀντιφίλου, ἀδελφὸς δ’ ἐκείνῳ ἰατρὸς ὢν ἐπόρισεν, καὶ Θευδίωνος ὡς ἡμᾶς κομίσαντος ἐφύλασσον αὐτὴ παρὰ Φερώρου λαβοῦσα ἐπὶ σὲ ἡτοιμασμένον ὑπὸ Ἀντιπάτρου. ἐπεὶ οὖν ἐνόσει Φερώρας καὶ ἐθεράπευες αὐτὸν ἀφικόμενος, ὁρῶν σου τὴν εὔνοιαν, ᾗ περὶ αὐτὸν ἐχρῶ, ἐπεκλάσθη τε τῇ διανοίᾳ καὶ μετακαλέσας με, ὦ γύναι, φησίν, περιώδευσέ με Ἀντίπατρος ἐπὶ πατρὶ μὲν τῷ αὐτοῦ, ἀδελφῷ δὲ τῷ ’μῷ, θανάσιμόν τε γνώμην συνθεὶς καὶ φάρμακον ᾧ διακονήσοιτο αὐτῇ πεπορισμένος. νῦν οὖν, ἐπειδὴ ὅ τε ἀδελφὸς οὐδὲν ἀρετῇ πρότερον ᾗ ἐχρῆτο περὶ ἐμοῦ ὑφαιρῶν ὦπται ἐμέ τε ἐλπὶς οὐκ εἰς μακρὰν ἀπέσεσθαι τοῦ βίου, φέρε μὴ γνώμῃ ἀδελφοκτόνῳ ἀποτισοίμην προπάτορας τοὺς ἐμαυτοῦ, τὸ φάρμακον καίειν τε ἐμοῦ βλέποντος, κομίσασά τε οὐδὲν εἰς ἀναβολὰς πράσσειν τοῦ ἀνδρὸς τὰς ἐπιστολάς. καὶ τὸ μὲν πλεῖστον καύσασαν τοῦ φαρμάκου τυχεῖν, ὑπολιπέσθαι δὲ ὀλίγον, ἵνα εἰ Φερώρου μεταστάντος περιέποι κακῶς αὐτὴν ὁ βασιλεύς, μεθίσταιτο αὐτῷ διάδρασιν ποιουμένη τῶν ἀναγκῶν. ταῦτα εἰποῦσα τό τε φάρμακον καὶ τὴν πυξίδα εἰς τὸ μέσον παρῆγεν. καὶ ἀδελφὸς δὲ Ἀντιφίλου ἕτερος καὶ μήτηρ αὐτοῦ ἀνάγκαις τε καὶ βασάνων σφοδρότητι ταὐτὰ ἔλεγον καὶ ἐγνώριζον τὴν πυξίδα. κατηγορεῖτο δὲ καὶ τοῦ ἀρχιερέως ἡ θυγάτηρ, γυνὴ δὲ τοῦ βασιλέως, ὡς πάντων ἵστωρ τούτων γενομένη κρύπτειν προθυμηθεῖσα αὐτά. καὶ διὰ τάδε Ἡρώδης ἐκείνην τε ἐξέβαλεν καὶ τὸν υἱὸν αὐτῆς ἐξήλειψε τῶν διαθηκῶν εἰς ὃ βασιλεύσοι μενουσῶν, καὶ τὸν πενθερὸν τὴν ἀρχιερωσύνην ἀφείλετο Σίμωνα τὸν τοῦ Βοηθοῦ, καθίσταται δὲ Ματθίαν τὸν Θεοφίλου Ἱεροσολυμίτην γένος.", "st": "17.4.2"}, {"sp": "N", "t": "Ἐν τούτῳ δὲ καὶ Βάθυλλος ἐκ Ῥώμης ἀπελεύθερος Ἀντιπάτρου παρῆν καὶ βασανισθεὶς εὑρίσκεται φάρμακον κομίζων δώσειν τε τῇ ἑαυτοῦ μητρὶ καὶ Φερώρᾳ, ὡς εἰ τὸ πρότερον μὴ ἅπτοιτο τοῦ βασιλέως, τούτῳ γοῦν μεταχειρίζοιντο αὐτόν. ἀφίκετο δὲ γράμματα παρὰ τῶν ἐν Ῥώμῃ φίλων τῷ Ἡρώδῃ γνώμῃ καὶ ὑπαγορεύσει Ἀντιπάτρου ἐπὶ κατηγορίᾳ Ἀρχελάου καὶ Φιλίππου συγκείμενα, ὡς δῆθεν διαβάλλοιέν τε τὸν πατέρα ἐπὶ σφαγῇ τῶν περὶ Ἀριστόβουλον καὶ Ἀλέξανδρον, δι’ οἴκτου δὲ καὶ αὑτοὺς λαμβάνοιεν· ἤδη γὰρ καὶ ἐκαλοῦντο ὑπὸ τοῦ πατρός, οὐχ ὡς ἐφ’ ἑτέροις, ἀλλ’ ἐπὶ τοῖς κἀκείνους προσαπολωλεκόσι κατακλήσεως αὐτῶν γινομένης. ταῦτα δὲ μεγάλων μισθῶν οἱ φίλοι τῷ Ἀντιπάτρῳ συνέπρασσον. γράφει δὲ καὐτὸς Ἀντίπατρος τῷ πατρὶ περὶ αὐτῶν ἐπὶ μεγίσταις τῶν αἰτιῶν καὶ παντελὲς ἀπαλλάσσειν φάσκων τὰ μειράκια, τῶν δὲ τῇ ἡλικίᾳ τὴν ἀνάθεσιν ποιούμενος. αὐτὸς δὲ τὰ περὶ Σύλλαιον ἠγωνίζετο καὶ θεραπεία τῶν πρώτων ἀνδρῶν ἐγεγόνει κόσμος τε ἀξιοπρεπὴς ταλάντων ἐώνητο διακοσίων. θαυμάσειε δ’ ἄν τις, ὅτι τοσούτων ἐν Ἰουδαίᾳ κατ’ αὐτοῦ κεκινημένων μησὶ πρότερον ἑπτὰ οὐδὲν αὐτῷ δῆλον γένοιτο· αἴτιον δ’ ἦν ἥ τε ἀκρίβεια καὶ φυλακὴ τῶν ὁδῶν καὶ μῖσος τῶν ἀνθρώπων τὰ πρὸς Ἀντίπατρον· οὐδεὶς γὰρ ἦν, ὃς προθύμως κινδύνῳ τῷ αὐτοῦ ποριστὴς τῶν ἐκείνου ἀσφαλειῶν καθίστατο.", "st": "17.4.3"}, {"sp": "N", "t": "Ἡρώδης δὲ Ἀντιπάτρου γεγραφότος πρὸς αὐτόν, ὡς τὰ πάντα ᾗ χρῆν διαπεπραγμένος ἥξοι ἐν τάχει, ἐπικρυψάμενος τὴν ὀργὴν ἀντεπετίθει, κελεύων μὴ ἀπιέναι τῆς εἰς τὴν ὁδὸν, μὴ καί τι πάσχοι παρὰ τὴν ἐκδημίαν αὐτοῦ, καὶ ἅμα τῆς μητρὸς αὐτοῦ κατηγορῶν ὡς ὀλίγον καταθήσεσθαι μέμψεις ἐπαγγελλόμενος τὰς πρὸς αὐτήν, ὁπότε ἐκεῖνος ἀφίκοιτο, παντί τε τρόπῳ φιλότητα τὴν πρὸς αὐτὸν ἐνεδείκνυτο, δεδιὼς μὴ καί τι ὑποτοπηθεὶς ὑπερβάλλοιτο μὲν ὁδοὺς τὰς πρὸς αὐτόν, τῇ δὲ Ῥώμῃ ἐνδιαιτώμενος κτήσεις ἐφεδρεύοι τῇ βασιλείᾳ καὶ δὴ καὶ διαπράσσοι τι αὐτῇ. τούτοις ἐν Κιλικίᾳ τοῖς γράμμασιν ἐπιτυγχάνει, τοῖς δὲ τὴν Φερώρου τελευτὴν διασαφοῦσιν ἐν Τάραντι πρότερον, δεινῶς τε ἤνεγκεν οὐκ εὐνοίᾳ τῇ Φερώρου, διότι δὲ τοῦ πατρὸς τὴν ἀναίρεσιν οὐ διαπραξάμενος ὥσπερ ὑπέσχετο ἀπέθανε. περὶ δὲ Κελένδεριν τῆς Κιλικίας γενόμενος ἐνεδοίαζεν ἤδη περὶ τοῦ οἴκαδε πλοῦ δεινῶς τῇ ἐκβολῇ τῆς μητρὸς λελυπημένος, καὶ τῶν φίλων οἱ μὲν ἐκέλευον αὐτὸν ταῦτά πῃ καραδοκοῦντα ἀνέχειν, οἱ δὲ μὴ διαμέλλειν τὸν οἴκαδε πλοῦν· λύσειν γὰρ παραγενόμενον αἰτίαν πᾶσαν, ὡς καὶ νῦν οὔτι ἑτέρωθεν, ἀλλὰ διὰ τὴν ἐκείνου ἀπουσίαν ἰσχὺν τοῖς κατηγόροις ὑπογενέσθαι. τούτοις πεισθεὶς ἔπλει τε καὶ προσέσχε τῷ Σεβαστῷ λιμένι λεγομένῳ, ὃν κατασκευάσας Ἡρώδης πολλῶν χρημάτων ἐπὶ τιμῇ τῇ Καίσαρος καλεῖ Σεβαστόν. ἐν προύπτοις δ’ ἦν Ἀντίπατρος ἤδη τοῖς κακοῖς μήτε προσιόντος αὐτῷ μηδενὸς μήτε προσαγορεύοντος ὥσπερ ὅτ’ ἐξῄει μετ’ εὐχῶν καὶ ἀγαθῶν ἐπιφημισμάτων ταῖς ἐναντιωτάταις ἀραῖς οὐκ ἐκωλύοντο αὐτὸν δέχεσθαι ποινὴν τοῖς ἀδελφοῖς ἀποτίνειν ὑπειληφότες.", "st": "17.5.1"}, {"sp": "N", "t": "Ἐτύγχανεν δ’ ἐν Ἱεροσολύμοις κατὰ τοῦτον τὸν καιρὸν Οὔαρος Κοϊντίλιος, διάδοχος μὲν Σατορνίνῳ τῆς ἐν Συρίᾳ ἀρχῆς ἀπεσταλμένος, ἥκων δὲ αὐτός τε σύμβουλος Ἡρώδῃ περὶ τῶν ἐνεστηκότων αὐτῷ δεηθέντι. καὶ αὐτῶν συνεδρευόντων παρῆν ὁ Ἀντίπατρος οὐδενὸς αὐτῷ ἐκπύστου γεγονότος. εἴσεισιν δὲ εἰς τὸ βασίλειον ἔτι πορφυρίδας ἀμπεχόμενος, καὶ αὐτὸν μὲν δέχονται οἱ ἐπὶ θύραις, ἀνείργουσι δὲ τοὺς φίλους. ἐθορυβεῖτο δὲ ἤδη σαφῶς οἷ ἐληλύθει κατανοῶν, ἐπειδὴ καὶ ὁ πατὴρ προσιόντα αὐτὸν ὡς ἀσπάσαιτο ἀπεώσατο, ἀδελφοκτονίαν τε ἐπικαλῶν καὶ βούλευσιν ὀλέθρου τοῦ ἐπ’ αὐτῷ, πάντων τε ἀκροατὴν καὶ δικαστὴν ἔσεσθαι Οὔαρον τῇ αὔριον. καὶ ὁ μὲν τοιούτου κακοῦ ἅμα τε ἀκροαθέντος καὶ παρόντος τῷ μεγέθει περιφερόμενος ᾤχετο, ὑπαντιάζουσιν δ’ αὐτὸν ἥ τε μήτηρ καὶ γυνή, αὕτη δὲ ἦν ήδη Ἀντιγόνῳ παῖς τῷ πρὸ Ἡρώδου Ἰουδαίων βεβασιλευκότι, παρ’ ὧν τὰ πάντα ἐκμαθὼν ἐν παρασκευαῖς τοῦ ἀγῶνος ἦν.", "st": "17.5.2"}, {"sp": "N", "t": "Τῇ δ’ ἑξῆς συνήδρευεν μὲν Οὔαρός τε καὶ ὁ βασιλεύς, εἰσεκλήθησαν δὲ καὶ οἱ ἀμφοῖν φίλοι καὶ οἱ συγγενεῖς βασιλέως Σαλώμη τε ἡ ἀδελφή, εἶτ’ εἴ τινες μηνύσειν ἔμελλον καὶ ὧν βάσανοι γεγόνασιν, δοῦλοί τε μητρῷοι τοῦ Ἀντιπάτρου μικρῷ πρότερον συνειλημμένοι ἢ ’κεῖνον ἥκειν, ἐπιστολὴν φέροντες, ἧς τὸ κεφάλαιον τῶν γεγραμμένων ἦν μὴ ἐπανιέναι ὡς πάντων τῷ πατρὶ ἡκόντων εἰς πύστιν, μόνην τε ἂν καταφυγὴν αὐτῷ λείπεσθαι Καίσαρα καὶ σὺν αὐτῇ τὸ μὴ πατρὶ ὑποχείριον γενέσθαι. Ἀντιπάτρου δὲ προσπεσόντος τῷ πατρὶ πρὸς τὰ γόνατα καὶ ἱκετεύοντος μὴ προδιεγνωσμένην καταστῆναι δίκην, ἀλλ’ ἀκροάσεως αὐτοῦ γενομένης παρὰ τῷ πατρὶ ἀκεραίως μένειν δυναμένῳ, τοῦτον κελεύσας Ἡρώδης ἀπάγειν εἰς μέσον αὐτὸς ὠλοφύρατο τῶν παίδων τῆς ποιήσεως, ἣν ἐπὶ τοιαύταις αὐτῷ τύχαις γενομένην πρότερον ἢ τῆς δυσμενείας ἀνασπάσασθαι τῶν πρότερον εἰς Ἀντίπατρον ἐμβαλεῖν αὐτοῦ τὸ γῆρας, τροφάς τε καὶ παιδεύσεις ἃς ποιήσαιτο αὐτῶν ἐξηγούμενος καὶ πλούτου εὐπορίαν ἐν καιροῖς ὡς θελήσειαν προτεθεῖσαν εἰς πάντα· ὧν οὐδὲν ἐπ’ ἐμποδίσματι γενέσθαι τοῦ μὴ οὐκ ἐπιβουλῇ τῇ ἐκείνων κινδυνεῦσαι τελευτᾶν ὑπὲρ τοῦ θᾶσσον δυσσεβῶς τὴν βασιλείαν παραλαβεῖν ἢ φύσεως νόμῳ μεταστάντος εὐχῇ τε τοῦ πατρὸς καὶ δίκῃ. τόν τε Ἀντίπατρον θαυμάζειν, τίνων ἐλπίδι ἐπαρθεὶς θαρσήσειεν ἐπὶ τοιαῦτα χωρεῖν μὴ ἀποτραπῆναι· διάδοχον μὲν γὰρ ἀποφήνασθαι διὰ γραμμάτων τῆς ἀρχῆς, ζῶντος δὲ ἐπ’ οὐδενὶ μειονεκτεῖν ἀξιώματός τε ἐπιφανείᾳ καὶ δυνάμει ἐξουσίας, πεντήκοντα μὲν τάλαντα ἐπέτειον πρόσοδον κομισάμενον, δωρεὰν δ’ εἰληφότα ὁδοῦ τῆς εἰς Ῥώμην τριακοσίων ταλάντων ἀριθμόν. ἐπεκάλει δὲ καὶ τῶν ἀδελφῶν εἰ μὲν πονηρῶν γεγονότων κατηγορίαν προθεμένῳ μιμητῇ γεγονότι, διακενῆς δὲ τοιῶνδε ἐπαγωγὰς ἐπάγοντι αὐτῇ τῶν συγγενῶν· τὰ γὰρ πάντα οὐδαμόθεν ἀλλὰ μηνύσει τῇ ἐκείνου μεμαθηκότα πρᾶξαι τὰ ἐπ’ αὐτοῖς πεπραγμένα γνώμῃ τῇ ἐκείνου, οὓς ἀπολύειν κακοῦ παντὸς κληρονόμον τῆς πατροκτονίας αὐτοῖς καθιστάμενον.", "st": "17.5.3"}, {"sp": "N", "t": "Ταῦθ’ ἅμα λέγων εἰς δάκρυα τρέπεται λέγειν τε ἄπορος ἦν. καὶ Νικόλαος ὁ Δαμασκηνός, φίλος τε ὢν τοῦ βασιλέως καὶ τὰ πάντα συνδιαιτώμενος ἐκείνῳ καὶ τοῖς πράγμασιν ὃν πραχθεῖεν τρόπον παρατετευχώς, δεηθέντι τῷ βασιλεῖ τὰ λοιπὰ εἰπεῖν ὁπόσα ἀποδείξεών τε καὶ ἐλέγχων ἐχόμενα ἦν. καὶ τοῦ Ἀντιπάτρου κατὰ δικαιολογίαν πρὸς τὸν πατέρα τετραμμένου καὶ ὁπόσα παραδείγματα τῆς εὐνοίας πρὸς αὐτὸν διεξιόντος, τὰς τιμὰς αἳ ὑπῆρχον αὐτῷ προφερόμενος, ἃς μὴ ἄν ποτε γενέσθαι μὴ οὐκ ἀρετῆς ἀξίῳ περὶ αὐτὸν γεγονότι· καὶ γὰρ ὁπόσα προϊδεῖν δεήσειε πάντων προβεβουλευκέναι σωφρόνως, εἴ τέ τινα ἐδεῖτο χειρῶν, πόνῳ τῷ αὐτοῦ ἐκπεπρᾶχθαι τὰ πάντα, εἰκός τε οὐκ εἶναι τῶν ἀλλαχόθεν ἐπιβουλῶν τὸν πατέρα ἐξελόμενον αὐτὸν ἐπιβουλευτὴν καταστῆναι ἀφανίζοντα ἀρετήν, ἣ ἐπ’ ἐκείνοις ἐμαρτυρεῖτο αὐτῷ, κακίᾳ τῇ ἐπὶ τοῖσδε μελλούσῃ συνεῖναι. καίτοι γε τοῦ μέλλοντος διάδοχον προαποδεδεῖχθαι καὶ τοῦ συναπολαυσομένου τιμῶν, αἳ εἰς τὸ παρὸν περιῆσαν, οὐκ ἐπικεκωλῦσθαι· εἰκός τε οὐκ εἶναι τὸν ἁπάντων ἀκινδύνως καὶ μετ’ ἀρετῆς ἔχοντα τὴν ἡμίσειαν μετὰ ψόγων καὶ κινδύνου ἐφίεσθαι τοῦ ὅλου ἄδηλον εἰ δυναμένου περιγενέσθαι, καὶ ταῦτα τεθεαμένον τὴν ζημίαν τῶν ἀδελφῶν καὶ μηνυτὴν μὲν καὶ κατηγορητὴν γενόμενον λανθάνειν δυναμένων, κολαστὴν δ’ ἐπεὶ φανεροὶ κατέστησαν πονηροὶ τὰ πρὸς τὸν πατέρα ὄντες. καὶ τάδε μὲν αὐτῷ τῶν ἐνταῦθα ἠγωνισμένων παραδείγματα εἶναι τῶν ἀκράτῳ εὐνοίᾳ πρὸς τὸν πατέρα πεπολιτευμένων· τῶν δ’ ἐπὶ Ῥώμης μάρτυρα εἶναι Καίσαρα ἐπίσης τῷ θεῷ ἀπατηθῆναι μὴ οἷόν τε ὄντα. ὧν πίστιν εἶναι τὰ ὑπ’ ἐκείνου γράμματα ἐπεσταλμένα, ὧν οὐ καλῶς ἔχειν ἰσχυροτέρας εἶναι τὰς διαβολὰς τῶν στασιάζειν αὐτοὺς προθεμένων τὰς πλείους ἀποδημίᾳ τῇ αὐτοῦ συντεθῆναι σχολῆς τοῖς ἐχθροῖς ἐγγενομένης, ἣν οὐκ ἂν αὐτοῖς ἐπιδημοῦντος παραγενέσθαι. διαβάλλοντος δὲ καὶ τὰς βασάνους εἰς ψευδολογίαν, ὡς τῆς ἀνάγκης φύσιν ἐχούσης διδάσκειν τοὺς ὑποπεσόντας τὰ πολλὰ ἡδονῇ τῶν ἐφεστηκότων λέγειν,", "st": "17.5.4"}, {"sp": "N", "t": "καὶ παρέχοντος αὑτὸν εἰς βάσανον, ἐπὶ τούτοις τροπῆς τοῦ συνεδρίου γενομένης, σφόδρα γὰρ ᾤκτειραν τὸν Ἀντίπατρον δάκρυσίν τε καὶ αἰκίαις τοῦ προσώπου χρώμενον, ὥστε καὶ τοῖς ἐχθροῖς δι’ οἴκτου καταστῆναι φανερὸν δὲ ἤδη καὶ Ἡρώδην εἶναι καμπτόμενόν τι τῇ γνώμῃ καίπερ μὴ βουλόμενον ἔκδηλον εἶναι, Νικόλαος ἀρξάμενος οἷς τε ὁ βασιλεὺς κατήρξατο λόγοις παλιλλογεῖ μειζόνως ἐκδεινῶν καὶ ὁπόσα ἐκ βασάνων ἢ μαρτυριῶν συνῆγεν τὴν ἀπόδειξιν τοῦ ἐγκλήματος. μάλιστα δὲ τὴν ἀρετὴν ἐπιπολὺ ἐξηγεῖτο τοῦ βασιλέως, ᾗ περί τε τροφὰς καὶ παιδεύματα χρησάμενος τῶν υἱέων οὐδαμόθεν εὕροιτο ὀνησιφόρον αὐτὴν περιπταίων ἑτέροις ἀφ’ ἑτέρων. καίτοι γε οὐχ οὕτως θαυμάζειν τῶν προτέρων τὴν ἀβουλίαν, νεωτέρους γὰρ καὶ κακίᾳ συμβούλων διεφθαρμένους ἀπαλεῖψαι τὰ τῆς φύσεως δικαιώματα ἀρχῆς θᾶσσον ἢ χρῆν μεταποιεῖσθαι σπουδάσαντας, Ἀντιπάτρου δ’ ἂν δικαίως τὴν μανίαν καταπλαγῆναι μὴ μόνον οἷς ὑπὸ τοῦ πατρὸς εὐεργετηθείη τὸν λογισμὸν ὥσπερ τὰ ἰοβολώτατα τῶν ἑρπετῶν μὴ μαλαχθέντος, καίτοι γε κἀκείνοις τινὸς ἐγγινομένης μαλακίας τοῦ ἀδικεῖν τοὺς εὐεργέτας, ἀλλὰ μηδὲ τὰς τύχας τῶν ἀδελφῶν πρὸς τὸ οὐ μιμητὴν αὐτῶν καταστῆναι τῆς ὠμότητος ἐμποδὼν στάντος. καίτοι γε, ὦ Ἀντίπατρε, τῶν ἀδελφῶν μηνυτής τε ὧν τολμήσειαν αὐτὸς ἦς καὶ ἐρευνητὴς τῶν ἐλέγχων καὶ κολαστὴς πεφωραμένων. καὶ οὐ τοῦ ἐπ’ ἐκείνοις ἐγκαλοῦμεν θυμῷ χρῆσθαι μὴ ἐλλιπόντος, ἀλλὰ τοῦ μιμεῖσθαι τὴν ἀσέλγειαν αὐτῶν σπουδάσαντος ἐκπεπλήγμεθα, εὑρίσκοντες κἀκεῖνά σοι οὐκ ἐπ’ ἀσφαλείᾳ τοῦ πατρός, ἀλλ’ ἐπ’ ὀλέθρῳ τῶν ἀδελφῶν πεπραγμένα, ὅπως μισοπονηρίᾳ τῇ κατ’ αὐτῶν φιλοπάτωρ εἶναι πεπιστευμένος ἀδεεστέραν ἐπ’ αὐτῷ κακουργεῖν παραλάβοις δύναμιν, ὃ δὴ καὶ τοῖς ἔργοις παρέστησας. ἅμα γὰρ καὶ τοὺς ἀδελφοὺς ἀνῄρεις ἐφ’ οἷς ἤλεγχες πονηροὺς γεγονότας καὶ τοὺς ὁμοπραγήσαντας αὐτοῖς οὐχ ὑπεδίδους, φανερὸν τοῖς πᾶσιν καθιστάς, ὡς καὶ συνθήκην πρὸς αὐτοὺς κατὰ τοῦ πατρὸς ποιησάμενος ἐπανείλω κατηγορεῖν, βουλόμενος σοὶ τὴν ἐπιβουλὴν τῆς πατροκτονίας κερδαίνεσθαι καταμόνας καὶ δυοῖν ἀγώνοιν εὐφροσύνην καρπούμενος τρόπου τοῦ σοῦ ἀξίαν, φανεροῦ μὲν τοῦ κατὰ τῶν ἀδελφῶν, ᾧ καὶ ἠγάλλου ὡς ἐπὶ τοῖς μεγίστοις, καὶ ἦν ἄξιον οὕτως φρονεῖν, εἰ δὲ μήγε σὺ χείρων ἦς, κρυπτοῦ δέ, ὃν κατὰ τοῦ πατρὸς συντιθεὶς ἐκείνους μὲν οὐχ ὡς τῷ πατρὶ ἐπιβεβουλευκότας μισῶν, οὐ γὰρ ἂν ἐξώκειλας αὐτοῖς ἐπὶ πρᾶξιν παραπλησίαν, ἀλλ’ ὡς διαδόχους τῆς ἡγεμονίας σου δικαιότερον ἂν γενομένους, τὸν δὲ πατέρα ἐπισφάζειν τοῖς ἀδελφοῖς, ἵνα θᾶσσον ὡς ἐκείνων τε ἐπικαταψεύσαιο μὴ ἐλεγχθῇς καὶ ὧν αὐτὸς δίκας παρασχεῖν ἄξιος γένοιο ταύτην παρὰ τοῦ δυστυχοῦς εἰσπράξαιο πατρός, ἐπινοῶν πατροκτονίαν οὐ κοινήν, ἀλλ’ οἵαν μέχρι νῦν οὐχ ἱστόρησεν ὁ βίος. οὐχ υἱὸς γὰρ μόνον πατρὶ ἐπεβούλευες, ἀλλὰ καὶ φιλοῦντι καὶ εὐεργετηκότι, κοινωνὸς τῆς βασιλείας ὢν τοῖς ἔργοις καὶ διάδοχος προφανθεὶς καὶ τὴν μὲν ἡδονὴν τῆς ἐξουσίας ἤδη προλαμβάνειν μὴ ἐπικεκωλυμένος, ἐλπίδα δὲ τὴν εἰσαῦθις γνώμῃ τοῦ πατρὸς καὶ γράμμασιν προησφαλισμένος. ἀλλ’ οὐκ ἄρα τῇ Ἡρώδου ἀρετῇ τὰ πράγματα, γνώμῃ δὲ καὶ πονηρίᾳ ἔκρινες τῇ σεαυτοῦ, βουλόμενος τοῦ πάντων σοι ὑπακούσαντος πατρὸς καὶ τὸ μέρος ἀφαιρεῖσθαι καὶ ὃν προσεποιοῦ τοῖς λόγοις σώζειν τοῖς ἔργοις τοῦτον ἀφανίσαι ζητῶν, καὶ μὴ μόνον αὐτὸς πονηρὸς καθιστάμενος, ἀλλὰ καὶ τὴν μητέρα ὧν ἐπενόεις πιμπλὰς καὶ στασιοποιῶν τὴν εὔνοιαν τοῖς ἀδελφοῖς καὶ τολμῶν θηρίον ἀποκαλεῖν τὸν πατέρα, παντὸς ἑρπετοῦ χαλεπωτέραν τὴν διάνοιαν κατεσκευασμένος, ᾗ τὸν ἐκείνων ἰὸν ἐπὶ τοὺς συγγενεστάτους καὶ τοὺς ἐπὶ τοσούτοις εὐεργέτας παρεκάλεις ἐπὶ συμμαχίαις φυλάκων καὶ τέχναις ἀνδρῶν καὶ γυναικῶν φρασσόμενος κατὰ τοῦ γέροντος, ὥσπερ οὐκ ἀρκούσης τῆς διανοίας μῖσος τὸ ὑποικουροῦν παραστῆσαι. καὶ νῦν ἐλήλυθας μετὰ βασάνους ἐλευθέρων οἰκετῶν ἀνδράσι γυναιξὶν διὰ σὲ γεγονυίας μηνύσεις τῶν συνωμοτῶν ἀντιλογεῖν τῇ ἀληθείᾳ σπεύδων, καὶ μονονουχὶ τὸν πατέρα ἀναιρεῖν μεμελετηκὼς ἐκ τοῦ ἀνθρωπείου, ἀλλ’ ἤδη καὶ νόμον τὸν κατὰ σοῦ γεγραμμένον καὶ τὴν ἀρετὴν τὴν Οὐάρου καὶ τοῦ δικαίου τὴν φύσιν, οὕτως ἄρα τῇ ἀναιδείᾳ πέποιθας, ὥστε καὶ βασανίζεσθαι ἀξιοῖς, καὶ ψευδεῖς λέγων τὰς βασάνους τῶν προβεβασανισμένων, ἵν’ οἱ μὲν ῥυόμενοί σου τὸν πατέρα ἐκκρουσθῶσιν τοῦ ἠληθευκέναι, αἱ δὲ σαὶ βάσανοι δοκῶσι πισταί; οὐ ῥύσῃ Οὔαρε τὸν βασιλέα τῆς ἐπηρείας τῶν συγγενῶν; οὐδὲ πονηρὸν θηρίον, ἐπ’ ὀλέθρῳ μὲν τῶν ἀδελφῶν εὔνοιαν προσποιούμενον τοῦ πατρός, ἔνθα δὲ μέλλοι καταμόνας ταχέως ἀποίσεσθαι τὴν βασιλείαν πάντων αὐτῷ θανασιμώτατον ἀναφαινόμενον; γνοὺς ὅτι πατροκτονία κοινόν ἐστιν ἀδίκημα καὶ τῆς φύσεως καὶ τοῦ βίου τὴν πεφηνυῖαν ὡς οὐδὲν ἡσσόνως τοῦ βεβουλευμένου καὶ ὁ μὴ κολάζων ἀδικεῖ τὴν φύσιν.", "st": "17.5.5"}, {"sp": "N", "t": "Προσετίθει δὲ ἤδη τὰ τῆς μητρὸς Ἀντιπάτρου ὁπόσα πρός τινας ἦν κουφολογίᾳ γυναικείῳ εἰρημένα, μαντείας τε καὶ θυσίας ἐπὶ τῷ βασιλεῖ γεγονυίας καὶ ὁπόσα μετὰ τῶν Φερώρου γυναικῶν Ἀντιπάτρῳ ἠσέλγητο μετὰ οἴνου καὶ λύμης ἐρωτικῆς, τῶν τε βασάνων ἀνακρίσεις καὶ ὁπόσα μαρτυριῶν ἐχόμενα· πολλὰ δὲ καὶ παντοῖα ἦν τὰ μὲν προητοιμασμένα, τὰ δὲ πρὸ τοῦ ὀξέως ἀπαγγέλλεσθαί τε καὶ βεβαιοῦσθαι ἐφευρημένα· οἱ γὰρ ἄνθρωποι κἂν εἴ τι κατὰ φόβον τοῦ Ἀντιπάτρου, μὴ διαδρὰς ἀμύνοιτο αὐτούς, σιγῇ παρεδίδοσαν, ὁρῶντες αὐτὸν ἐπιβατὸν ταῖς κατηγορίαις τῶν ἀρξάντων γεγονότα καὶ τὴν ποτὲ πολλὴν αὐτῷ συστᾶσαν τύχην προφανῶς αὐτὸν τοῖς ἐχθροῖς παραδεδωκυῖαν, οἳ καὶ ἀπλήστως μίσους τοῦ πρὸς αὐτὸν ἐνεφοροῦντο· κατέσπευδε δὲ τότε οὔτι τῇ ἔχθρᾳ τῶν ἐπικεχειρηκότων κατηγορεῖν, ὡς μεγέθει τόλμης ὧν ἐπενόησεν κακιῶν καὶ δυσμενείας τῆς πρὸς τὸν πατέρα καὶ τοὺς ἀδελφούς, στάσεως καὶ ἀλληλοφθοριῶν ἀναπεπληκὼς τὸν οἶκον καὶ μήτε μίσει κατὰ δίκην μήτε φιλίᾳ δι’ εὔνοιαν χρώμενος, ἀλλ’ ὡς μελλήσοι αὐτῷ συμφέρειν· ὧν ἁπάντων ἐκ πλέονος αὐτοῖς οἱ πολλοὶ προανεσκοπημένων, οἵπερ δὴ μάλιστα ἀρετῇ κρίνειν πεφύκασιν ἐπὶ τοῖς πράγμασιν διὰ τὸ καὶ ὀργῆς ἀπηλλαγμένως ἐπιψηφίζειν τοῖς γινομένοις, καταβοὰς ἐν τοῖς πρὶν εἱρχθέντες ποιεῖσθαι παραγενομένης ἀδείας ἐξέφερον εἰς μέσον ὁπόσα εἰδεῖεν. πολύτροποί τε κακιῶν ἀποδείξεις ἦσαν οὐδαμόθεν ψεύδους αἰτίαν ἐγκαλεῖσθαι δυνάμεναι διὰ τὸ μήτ’ εὐνοίᾳ τῇ πρὸς Ἡρώδην λέγειν τοὺς πολλοὺς μήτε ὑποψίᾳ κινδύνων σιγῆς ἐφ’ οἷς ἔχοιεν εἰπεῖν ἐγκαλουμένης, ἀλλὰ τῷ πονηρά τε ἡγεῖσθαι τὰ πράγματα, καὶ τὸν Ἀντίπατρον οὐκ ἀσφαλείᾳ τῇ Ἡρώδου, πονηρίᾳ δὲ τῇ αὐτοῦ πάσης ἄξιον τιμωρίας. πολλά τε ἦν καὶ παρὰ πολλῶν οἷς μὴ παρήγγελτο εἰπεῖν ἀγορευόμενα, ὥστε τὸν Ἀντίπατρον καίπερ ἐπὶ πλεῖστον πάντα δεινότατον ὄντα ψεύσασθαι καὶ ἀπερυθριάσαι μηδὲ ὅσον ἀπὸ φωνῆς ἐπ’ ἀντιλέξει τὴν ἰσχὺν εἰσφέρεσθαι. Νικολάου τε παυσαμένου τῶν τε λόγων καὶ τῶν ἐλέγχων Οὔαρος ἐκέλευσεν Ἀντίπατρον ἐπ’ ἀπολογίᾳ τῶν ἐγκλημάτων χωρεῖν, εἴ τινες αὐτῷ παρασκευαὶ τοῦ μὴ ἐνόχῳ τοῖς ἐπιφερομένοις εἶναι, καὶ γὰρ αὐτὸς εὔχεσθαι τὸν πατέρα εἰδέναι τῶν ὁμοίων εὐχόμενον μηδὲν αὐτὸν ἀδικοῦντα φωρᾶν. ὁ δ’ ἐπὶ στόμα ἔκειτο ἀνατετραμμένος τε τῷ θεῷ καὶ πᾶσι προτιθεὶς τὸ ἐπιμαρτυρῆσον αὐτῷ μηδὲν ἀδικεῖν, ἢ τεκμηρίοις ἐμφανέσι παραστῆσαι μὴ οὐκ ἐπίβουλον αὐτὸν τοῦ πατρὸς γεγονέναι, εἰωθότες μὲν καὶ πάντες οἷς ἐπιλείπει ἀρετῆς, ὁπότε μὲν ἐγχειρηταί τινα κακῶν εἶεν τοῦ θείου τὸ πᾶσιν παρατυγχάνειν ἀφορίσαντες γνώμῃ τῇ αὐτῶν ἐπὶ τὰ ἔργα χωρεῖν, ὁπότε δὲ φωρώμενοι κινδυνεύοιεν δίκην ὑποσχεῖν, κατ’ ἐπίκλησιν αὐτοῦ μαρτυρῶν τὰ πάντα ἐκτρέπειν. ὃ δὴ καὶ τῷ Ἀντιπάτρῳ συμβεβήκει· τὰ πάντα γὰρ ὡς ἐν ἐρημίᾳ τοῦ θείου διαπεπραγμένος, κατειργούσης αὐτὸν πανταχόθεν τῆς δίκης ἀπορίᾳ τῶν ἀλλαχόθεν δικαιωμάτων, οἷς ἀπολύσαιτο τὰ ἐγκεκλημένα, αὖθις ἐνεπαροίνει τῇ ἀρετῇ τοῦ θείου, μαρτυρίαν ἐπισκήπτων αὐτῷ περὶ ἰσχύι τῇ ἐκείνου περιτο ἕως εἰς μέσους παραγαγόντος ὁπόσα ἐπὶ τῷ πατρὶ πράσσειν τολμᾶν οὐκ ἐνέλιπεν.", "st": "17.5.6"}, {"sp": "N", "t": "Ὁ δὲ Οὔαρος ἐπειδὴ πολλάκις ἀνακρίνων τὸν Ἀντίπατρον οὐδὲν εὑρίσκετο πλέον τῆς ἀνακλήσεως τοῦ θεοῦ, ὁρῶν ἀπέραντον ὂν τὸ γινόμενον ἐκέλευσε τὸ φάρμακον εἰς μέσους ἐνεγκεῖν, ἵν’ εἰδῇ τὴν περιοῦσαν αὐτῷ δύναμιν. καὶ κομισθέντος τῶν ἐπὶ θανάτῳ τις ἑαλωκότων πίνει κελεύσαντος Οὐάρου καὶ παραχρῆμα ἔθανεν. τότε δὲ ἐξαναστὰς ἀπῄει τοῦ συνεδρίου καὶ τῇ ἑξῆς ἐπ’ Ἀντιοχείας, ᾗπερ δὴ καὶ τὸ πλεῖστον ἦσαν αὐτῷ διατριβαὶ διὰ τὸ Σύροις τοῦτο βασίλειον εἶναι. Ἡρώδης δὲ παραχρῆμα μὲν ἔδησε τὸν υἱόν. ἄδηλοι δὲ τοῖς πολλοῖς ἦσαν αἱ Οὐάρου πρὸς αὐτὸν ὁμιλίαι καὶ τί εἰπὼν ἀπεληλύθει. εἰκάζετο δὲ τοῖς πολλοῖς γνώμῃ τῇ ἐκείνου πράσσειν ὁπόσα περὶ τὸν Ἀντίπατρον ἔπραξεν. δήσας δὲ αὐτὸν εἰς Ῥώμην ὡς Καίσαρα ἐκπέμπει γράμματα περὶ αὐτοῦ καὶ τοὺς ἀπὸ γλώσσης διδάξοντας τὸν Καίσαρα τὴν κακίαν τοῦ Ἀντιπάτρου καὶ Κωπωνίου γνώμη τὴν Καίσαρος. ἁλίσκεται δὲ ὑπὸ τὰς αὐτὰς ἡμέρας καὶ ἐπιστολὴ ὑπὸ Ἀντιφίλου πρὸς Ἀντίπατρον γεγραμμένη, ἐν Αἰγύπτῳ δὲ αὐτὸς διέτριβεν, καὶ λυθεῖσα ὑπὸ τοῦ βασιλέως τάδε ἐδήλου· ἔπεμψά σοι τὴν παρ’ Ἀκμῆς ἐπιστολὴν μὴ φεισάμενος τῆς ἐμῆς ψυχῆς· οἶσθα γὰρ, ὅτι αὖθις κινδυνεύω ὑπὸ δύο οἰκιῶν, εἰ γνωσθείην. σὺ δ’ εὐτυχοίης περὶ τὸ πρᾶγμα. καὶ ἡ μὲν ἐπιστολὴ τάδε ἐδήλου. ἐζήτει δὲ ὁ βασιλεὺς καὶ τὴν ἑτέραν ἐπιστολήν, οὐ μὴν φανερά γε ἦν, καὶ τοῦ Ἀντιφίλου δοῦλος ὃς τὴν ἀναγνωσθεῖσαν ἔφερεν ἠρνεῖτο ἑτέραν παραλαβεῖν. ἀπορίας οὖν ἐχούσης τὸν βασιλέα τῶν φίλων τις τῶν τοῦ Ἡρώδου θεώμενος ὑπερραμμένον τοῦ δούλου τὸν ἐντὸς χιτῶνα, ἐνεδεδύκει γὰρ δύο, εἴκασεν ἐντὸς τῆς ἐπιπτυχῆς κρύπτεσθαι τὰ γράμματα· καὶ ἦν δὲ οὕτως. λαμβάνουσιν οὖν τὴν ἐπιστολὴν ἐγγεγραμμένα τε ἦν ἐν αὐτῇ τάδε· Ἀκμὴ Ἀντιπάτρῳ. ἔγραψα τῷ πατρί σου οἵαν ἤθελες ἐπιστολὴν καὶ ἀντίγραφον ποιήσασα τῇ πρὸς τὴν ἐμὴν κυρίαν ὡς παρὰ Σαλώμης ἔγραψα, ἣν ἀναγνοὺς οἶδ’ ὅτι τιμωρήσεται Σαλώμην ὡς ἐπίβουλον. ἦν δὲ ἡ παρὰ τῆς Σαλώμης δοκοῦσα εἶναι πρὸς τὴν δέσποιναν αὐτῆς ὑπ’ Ἀντιπάτρου ἐπ’ ὀνόματι τῷ Σαλώμης ὅσα γοῦν ἡ διάνοια θέλοι ὑπηγορευμένη, λέξει δὲ συνέκειτο αὐτῆς. τὰ δὲ γεγραμμένα ἦν τοιάδε· Ἀκμὴ βασιλεῖ Ἡρώδῃ. ἐγὼ ἔργον ποιουμένη μηδέν σε λανθάνειν τῶν κατὰ σοῦ γινομένων, εὑροῦσα ἐπιστολὴν Σαλώμης πρὸς τὴν ἐμὴν κυρίαν κατὰ σοῦ γεγραμμένην ἐπικινδύνως ἐμαυτῇ σοὶ δὲ ὠφελίμως ἐξεγραψάμην καὶ ἀπέστειλά σοι. ταύτην δὲ ἐκείνη ἔγραψεν γήμασθαι θέλουσα Συλλαίῳ. κατάσχισον οὖν τὴν ἐπιστολήν, ἵνα μὴ κἀγὼ τῷ ζῆν κινδυνεύσω. πρὸς δὲ αὐτὸν ἐγέγραπτο Ἀντίπατρον διασαφούσης, ὅτι διακονουμένη κελεύσματι τῷ ἐκείνου αὐτή τε γράψειε πρὸς Ἡρώδην, ὡς Σαλώμης ἐπιβούλως αὐτῷ πράσσειν ἐπειγομένης τὰ πάντα, καὶ ἀντίγραφον τῆς ὡς πρὸς δέσποιναν τὴν αὐτῆς πεμφθείσης ἐπιστολῆς ὑπὸ Σαλώμης ἀποπέμψειεν αὐτῷ. ἦν δὲ ἡ Ἀκμὴ Ἰουδαία μὲν τὸ γένος, ἐδούλευε δὲ Ἰουλίᾳ τῇ Καίσαρος γυναικὶ καὶ ἔπρασσε ταῦτα φιλίᾳ τῇ Ἀντιπάτρου ὠνηθεῖσα ὑπ’ αὐτοῦ μεγάλῃ δόσει χρημάτων συγκακουργεῖν κατά τε τοῦ πατρὸς καὶ κατὰ τῆς τηθίδος.", "st": "17.5.7"}, {"sp": "N", "t": "Ἡρώδης δὲ ἐκπλαγεὶς μεγέθει τῆς Ἀντιπάτρου κακίας ὥρμησεν μὲν καὶ παραχρῆμα αὐτὸν ἀνελεῖν ὡς κύκηθρον μεγάλων γεγονότα πραγμάτων καὶ μὴ μόνον αὐτῷ ἀλλὰ καὶ τῇ ἀδελφῇ ἐπιβεβουλευκότα καὶ τοῦ Καίσαρος διεφθαρκότα τὴν οἰκίαν, ἐξώτρυνεν δ’ αὐτὸν καὶ ἡ Σαλώμη στερνοτυπουμένη καὶ κτείνειν αὐτὴν κελεύουσα, εἴ τινος ἐπὶ τοιοῖσδε πίστεως αἰτίαν ἀξιόχρεων οἵα τε παρασχεῖν γένοιτο. Ἡρώδης δὲ μεταπέμψας ἀνέκρινεν τὸν υἱὸν κελεύων εἴ τι ἀντειπεῖν ἔχοι λέγειν μηδὲν ὑπιδόμενον, ἐπεὶ δὲ ἀχανὴς ἦν, ἤρετο αὐτόν, ἐπειδὴ τὰ πάντα πανταχοῦ πεφώραται πονηρὸς ὤν, τοὺς γοῦν συγκακουργήσαντας αὐτῷ τὰ πράγματα μὴ μελλῆσαι κατειπεῖν. ὁ δὲ Ἀντιφίλῳ τὴν πάντων αἰτίαν ἀνετίθει, ἕτερον δ’ οὐδένα προυτίθει. Ἡρώδης δὲ περιαλγῶν ὥρμησεν μὲν πέμπειν ἐπὶ Ῥώμης τὸν υἱὸν ὡς Καίσαρα λόγον ὑφέξοντα τῶν ἐπὶ τοῖσδε βουλευμάτων, ἔπειτα δείσας, μὴ καὶ βοηθείᾳ φίλων εὑρίσκοιτο τοῦ κινδύνου διαφυγάς, αὐτὸν μὲν δέσμιον ὡς καὶ πρότερον ἐφύλασσεν, αὖθις δὲ πρέσβεις ἐξέπεμπε καὶ γράμματα ἐπὶ κατηγορίᾳ τοῦ υἱέος ὁπόσα τε Ἀκμὴ συγκακουργήσειεν αὐτῷ καὶ ἀντίγραφα τῶν ἐπιστολῶν.", "st": "17.5.8"}, {"sp": "N", "t": "Καὶ οἱ μὲν πρέσβεις ἐπὶ τῆς Ῥώμης ἠπείγοντο ὁπόσα τε ἀνακρινομένους δεήσοι λέγειν προσεκδιδαχθέντες καὶ τὰ γράμματα φέροντες· εἰς νόσον δὲ ὁ βασιλεὺς ἐμπεσὼν διαθήκας γράφει τῷ νεωτάτῳ τῶν υἱῶν τὴν βασιλείαν διδοὺς μίσει τῷ τε πρὸς τὸν Ἀρχέλαον καὶ Φίλιππον ἐκ τῶν Ἀντιπάτρου διαβολῶν, Καίσαρί τε ταλάντων χιλίων καὶ γυναικὶ Ἰουλίᾳ τῇ Καίσαρος καὶ τέκνοις καὶ φίλοις καὶ ἀπελευθέροις Καίσαρος πεντακοσίων. ἔνεμε δὲ καὶ τοῖς υἱέσιν χρήματα καὶ προσόδους καὶ ἀγροὺς καὶ υἱέσι τοῖς ἐκείνων, Σαλώμην δὲ ἐπὶ μέγα ἐπλούτιζεν τὴν ἀδελφὴν εὔνουν τε αὐτῷ ἐπὶ πᾶσιν διαμεμενηκυῖαν καὶ μηδαμόθι θρασυνομένην κακουργεῖν. ἀπεγνωκὼς δὲ περιοίσειν, καὶ γὰρ περὶ ἔτος ἑβδομηκοστὸν ἦν, ἐξηγρίωσεν ἀκράτῳ τῇ ὀργῇ καὶ πικρίᾳ εἰς πάντα χρώμενος· αἴτιον δὲ ἦν δόξα τοῦ καταφρονεῖσθαι καὶ ἡδονῇ τὰς τύχας αὐτοῦ τὸ ἔθνος φέρειν· ἄλλως τ’ ἐπειδή τινες τῶν δημοτικωτέρων ἀνθρώπων καὶ ἐπανέστησαν αὐτῷ διὰ τοιαύτην αἰτίαν.", "st": "17.6.1"}, {"sp": "N", "t": "Ἦν Ἰούδας ὁ Σαριφαίου καὶ Ματθίας ὁ Μεργαλώθου Ἰουδαίων λογιώτατοι καὶ παρ’ οὕστινας ἐξηγηταὶ τῶν πατρίων νόμων, ἄνδρες καὶ δήμῳ προσφιλεῖς διὰ παιδείαν τοῦ νεωτέρου· ὁσημέραι γὰρ διημέρευον αὐτοῖς πάντες οἷς προσποίησις ἀρετῆς ἐπετετήδευτο. οἵ τε πυνθανόμενοι τοῦ βασιλέως τὴν νόσον θεραπεύειν ἄπορον οὖσαν ἐξῆραν τὸ νεώτερον, ὥστε ὁπόσα παρὰ νόμον τοῦ πατρίου κατεσκεύαστο ἔργα ὑπὸ τοῦ βασιλέως ταῦτα καθελόντες εὐσεβείας ἀγωνίσματα παρὰ τῶν νόμων φέρεσθαι· καὶ γὰρ δὴ διὰ τὴν τόλμαν αὐτῶν παρ’ ὃ διηγόρευεν ὁ νόμος τῆς ποιήσεως τά τε ἄλλα αὐτῷ συντυχεῖν, οἷς παρὰ τὸ εἰωθὸς τοῦ ἀνθρώπου διετρίβη, καὶ δὴ καὶ τὴν νόσον. ἦν γὰρ τῷ Ἡρώδῃ τινὰ πραγματευθέντα παρὰ τὸν νόμον, ἃ δὴ ἐπεκάλουν οἱ περὶ τὸν Ἰούδαν καὶ Ματθίαν. κατεσκευάκει δὲ ὁ βασιλεὺς ὑπὲρ τοῦ μεγάλου πυλῶνος τοῦ ναοῦ ἀνάθημα καὶ λίαν πολυτελές, ἀετὸν χρύσεον μέγαν· κωλύει δὲ ὁ νόμος εἰκόνων τε ἀναστάσεις ἐπινοεῖν καί τινων ζῴων ἀναθέσεις ἐπιτηδεύεσθαι τοῖς βιοῦν κατ’ αὐτὸν προῃρημένοις. ὥστε ἐκέλευον οἱ σοφισταὶ τὸν ἀετὸν κατασπᾶν· καὶ γὰρ εἴ τις γένοιτο κίνδυνος τῷ εἰς θάνατον ἀνακειμένῳ, πολὺ τῆς ἐν τῷ ζῆν ἡδονῆς λυσιτελεστέραν φαίνεσθαι τὴν προστιθεμένην ἀρετὴν ὑπ’ αὐτοῦ τοῖς ἐπὶ σωτηρίᾳ καὶ φυλακῇ τοῦ πατρίου μελλήσουσι τελευτᾶν διὰ τὸ ἀίδιον τοῦ ἐπαινεῖσθαι φήμην κατασκευασαμένους ἔν τε τοῖς νῦν ἐπαινεθήσεσθαι καὶ τοῖς ἐσομένοις ἀειμνημόνευτον καταλείπειν τὸν βίον. καίτοι γε καὶ τοῖς ἀκινδύνως διαιτωμένοις ἄφυκτον εἶναι τὴν συμφοράν, ὥστε καλῶς ἔχειν τοῖς ἀρετῆς ὀριγνωμένοις τὸ κατεψηφισμένον αὐτοῦ μετ’ ἐπαίνων καὶ τιμῶν δεχομένοις ἀπιέναι τοῦ βίου. φέρειν γὰρ κούφισιν πολλὴν τὸ ἐπὶ καλοῖς ἔργοις ὧν μνηστῆρα τὸν κίνδυνον εἶναι τελευτᾶν, καὶ ἅμα υἱέσι τῶν αὐτῶν καὶ ὁπόσοι τοῦ συγγενοῦς καταλείποιντο ἄνδρες γυναῖκες καὶ τοῖσδε περιποιῆσαι ὄφελος εὐκλείᾳ τῇ ἀπ’ αὐτῶν.", "st": "17.6.2"}, {"sp": "N", "t": "Καὶ οἱ μὲν τοιούτοις λόγοις ἐξῆραν τοὺς νέους. ἀφικνεῖται δὲ λόγος εἰς αὐτοὺς τεθνάναι φράζων τὸν βασιλέα καὶ συνέπραττε τοῖς σοφισταῖς. καὶ μέσης ἡμέρας ἀνελθόντες κατέσπων τε καὶ πελέκεσιν ἐξέκοψαν τὸν ἀετὸν πολλῶν ἐν τῷ ἱερῷ διατριβόντων. καὶ ὁ στρατηγὸς τοῦ βασιλέως, ἀγγέλλεται γὰρ ἡ ἐπιχείρησις πρὸς αὐτόν, ἀπὸ μείζονος διανοίας ἢ ἐπράσσετο ὑπολαβὼν ἄνεισι χεῖρα πολλὴν ἀγόμενος, ὁπόσοι ἀνθέξοιεν τῷ πλήθει τῶν πειρωμένων καθαιρεῖν τὸ ἀνάθημα, ἐπιπεσών τε μὴ προσδεχομένοις, ἀλλ’ ὁποῖα ὄχλος φιλεῖ δόξῃ μᾶλλον ἀμαθεῖ ἢ προνοίᾳ ἀσφαλεῖ τετολμηκότας, ἀσυντάκτοις τε καὶ μηδὲν τοῦ ὀνήσοντος προανεσκοπημένοις, τῶν τε νέων οὐκ ἐλάσσους τεσσαράκοντα ἀνδρῶν, οἳ θάρσει ἔμενον ἐπιόντα ἐς φυγὴν τοῦ λοιποῦ πλήθους καταστάντος, λαμβάνει καὶ τοὺς εἰσηγητὰς τοῦ τολμήματος Ἰούδαν καὶ Ματθίαν ἄδοξον ἡγουμένους ὑποχωρεῖν τὴν ἔφοδον αὐτοῦ, καὶ ἀνήγαγεν ἐπὶ τὸν βασιλέα. ἐρομένου δὲ ἐπεὶ ἀφίκοντο ἐπ’ αὐτὸν τοῦ βασιλέως, εἰ τολμήσειαν αὐτοῦ τὸ ἀνάθημα καθελεῖν, ἀλλὰ καὶ πεφρόνηταί γε ἡμῖν τὰ φρονηθέντα καὶ πέπρακται τὰ πεπραγμένα μετ’ ἀρετῆς ἀνδράσι πρεπωδεστάτης· τοῦ τε γὰρ θείου τῇ ἀξιώσει βεβοήθηται ὑφ’ ἡμῶν καὶ τοῦ νόμου ἠκρόατο τὸ σῶφρον, θαυμαστόν τε οὐδέν, εἰ τῶν σῶν δογμάτων ἀξιωτέρους τετηρῆσθαι ἡγησάμεθα νόμους, οὓς Μωσῆς ὑπαγορεύσει καὶ διδαχῇ τοῦ θεοῦ γραψάμενος κατέλιπεν. ἡδονῇ τε τὸν θάνατον οἴσομεν καὶ τιμωρίαν ἥντινα ἐπιβάλοις διὰ τὸ μὴ ἐπ’ ἀδίκοις ἔργοις, ἀλλὰ φιλίᾳ τοῦ εὐσεβοῦς μέλλειν συνείσεσθαι τὸ ἐφομιλῆσον αὐτοῦ. καὶ οἱ μὲν ταῦτα πάντες ἔλεγον οὐδὲν ἐλλιπεστέρᾳ τῇ τόλμῃ τοῦ λόγου χρώμενοι, ᾗ θαρσήσαντες τὸ ἔργον πράττειν οὐκ ἀπετράποντο. βασιλεὺς δὲ αὐτοὺς καταδήσας μετέπεμπεν εἰς Ἱεριχοῦντα Ἰουδαίων τοὺς ἐν τέλει, καὶ παραγενομένων ἐξεκλησίασεν εἰς τὸ αὐτὸ θέατρον ἐπὶ κλινιδίου κείμενος ἀδυναμίᾳ τοῦ στῆναι, γωνεῖστων τε ἐφόσον αἵτινες ἦσαν ἐπ’ αὐτοὺς γεγονυῖαι ἀνηριθμεῖτο, καὶ τοῦ ναοῦ τὴν κατασκευὴν ὡς μεγάλοις τέλεσι τοῖς αὐτοῦ γένοιτο μὴ δυνηθέντων ἔτεσιν ἑκατὸν εἰκοσιπέντε τῶν Ἀσαμωναίου ἐν οἷς ἐβασίλευον τοιόνδε τι ἐπὶ τιμῇ πρᾶξαι τοῦ θεοῦ, κοσμῆσαι δὲ καὶ ἀναθήμασιν ἀξιολόγοις. ἀνθ’ ὧν ἐλπίδα μὲν αὐτῷ γενέσθαι κἂν μεθὸ θάνοι καταλελείψεσθαι μνήμην τε αὐτοῦ καὶ εὔκλειαν. κατεβόα τε ἤδη, διότι μηδὲ ζῶντα ὑβρίζειν ἀπόσχοιντο εἰς αὐτόν, ἀλλ’ ἡμέρας τε καὶ ἐν ὄψει τῆς πληθύος ὕβρει χρωμένους ἅψασθαι τῶν ὑπ’ αὐτοῦ ἀνακειμένων καὶ καθαίρεσιν ὑβρίζοντάς τε ποιεῖσθαι, λόγῳ μὲν εἰς αὐτόν, ἀλήθειαν δὲ εἴ τις ἐξετάζοι τοῦ γεγονότος ἱεροσυλοῦντας.", "st": "17.6.3"}, {"sp": "N", "t": "Οἱ δὲ διὰ τὴν ὠμότητα αὐτοῦ, μὴ δὴ καὶ κατ’ αὐτῶν ἐξαγριώσας εἰσπράττοιτο τιμωρίαν, οὔτε γνώμῃ ἔφασαν αὐτὰ πεπρᾶχθαι τῇ αὐτῶν, φαίνεσθαί τε αὐτοῖς οὐκ ἀπηλλαγμένα κολάσεως αὐτὰ εἶναι. ὁ δὲ τοῖς μὲν ἄλλοις πραϋτέρως ἔσχεν, Ματθίαν δὲ τὸν ἀρχιερέα παύσας ἱερᾶσθαι ὡς αἴτιον τοῦ μέρους τούτων γεγονότα καθίστα Ἰωάζαρον ἀρχιερέα, ἀδελφὸν γυναικὸς τῆς αὐτοῦ. ἐπὶ δὲ τοῦ Μαθθίου τούτου ἱερωμένου συμβαίνει καὶ ἕτερον ἀρχιερέα καταστῆναι πρὸς μίαν ἡμέραν, ἣν Ἰουδαῖοι νηστείαν ἄγουσιν. αἰτία δ’ ἐστὶν ἥδε· ὁ Ματθίας ἱερώμενος ἐν νυκτὶ τῇ φερούσῃ εἰς ἡμέραν, ᾗ ἡ νηστεία ἐνίστατο, ἔδοξεν ἐν ὀνείρατι ὡμιληκέναι [γυναικί], καὶ διὰ τόδε οὐ δυναμένου ἱερουργεῖν Ἰώσηπος ὁ τοῦ Ἐλλήμου συνιεράσατο αὐτῷ συγγενὴς ὤν. Ἡρώδης δὲ τόν τε Ματθίαν ἐπεπαύκει τῆς ἀρχιερωσύνης καὶ τὸν ἕτερον Ματθίαν, ὃς ἐγηγέρκει τὴν στάσιν, καὶ ἄνδρας ἐκ τῶν ἑταίρων αὐτοῦ ἔκαυσεν ζώους. καὶ ἡ σελήνη δὲ τῇ αὐτῇ νυκτὶ ἐξέλιπεν.", "st": "17.6.4"}, {"sp": "N", "t": "Ἡρώδῃ δὲ μειζόνως ἡ νόσος ἐνεπικραίνετο δίκην ὧν παρανομήσειεν ἐκπρασσομένου τοῦ θεοῦ· πῦρ μὲν γὰρ μαλακὸν ἦν οὐχ ὧδε πολλὴν ἀποσημαῖνον τοῖς ἐπαφωμένοις τὴν φλόγωσιν ὁπόσην τοῖς ἐντὸς προσετίθει τὴν κάκωσιν. ἐπιθυμία δὲ δεινὴ τοῦ δέξασθαί τι ἀπ’ αὐτοῦ, οὐ γὰρ ἦν μὴ οὐχ ὑπουργεῖν, καὶ ἕλκωσις τῶν τε ἐντέρων καὶ μάλιστα τοῦ κόλου δειναὶ ἀλγηδόνες, καὶ φλέγμα ὑγρὸν περὶ τοὺς πόδας καὶ διαυγές· παραπλησία δὲ καὶ περὶ τὸ ἦτρον κάκωσις ἦν, ναὶ μὴν καὶ τοῦ αἰδοίου σῆψις σκώληκας ἐμποιοῦσα, πνεύματός τε ὀρθία ἔντασις καὶ αὐτὴ λίαν ἀηδὴς ἀχθηδόνι τε τῆς ἀποφορᾶς καὶ τῷ πυκνῷ τοῦ ἄσθματος, ἐσπασμένος τε περὶ πᾶν ἦν μέρος ἰσχὺν οὐχ ὑπομενητὴν προστιθέμενος. ἐλέγετο οὖν ὑπὸ τῶν θειαζόντων καὶ οἷς ταῦτα προαποφθέγγεσθαι σοφίᾳ πρόκειται, ποινὴν τοῦ πολλοῦ δυσσεβοῦς ταύτην ὁ θεὸς εἰσπράσσεσθαι παρὰ τοῦ βασιλέως. καίπερ δὲ μειζόνως ἢ ἀντίσχοι ἄν τις ταλαιπωρούμενος ἐν ἐλπίδι τοῦ ἀνασφαλοῦντος ἦν, ἰατρούς τε μεταπέμπων καὶ ὁπόσα ἀρωγὰ ὑπαγορεύσειαν χρῆσθαι μὴ ἀποτετραμμένος, ποταμόν τε περάσας Ἰορδάνην θερμοῖς τοῖς κατὰ Καλλιρρόην αὑτὸν παρεδίδου, ἅπερ σὺν τῇ ἐς πάντα ἀρετῇ καὶ πότιμά ἐστιν· ἔξεισιν δὲ τὸ ὕδωρ τοῦτο εἰς λίμνην τὴν ἀσφαλτοφόρον λεγομένην. κἀνταῦθα τοῖς ἰατροῖς δοκῆσαν ὥστε ἀναθάλπειν αὐτόν, καθεθεὶς εἰς πύελον πλέων ἐλαίου δόξαν μεταστάσεως ἐνεποίησεν αὐτοῖς. τῶν δὲ οἰκετῶν οἰμωγῇ χρωμένων περιενεγκὼν καὶ μηδ’ ἥντινα ἀμφὶ τοῦ σωθησομένου ἐλπίδα ἔχων τοῖς στρατιώταις ἀνὰ πεντήκοντα δραχμὰς ἑκάστῳ κελεύει νεμηθῆναι· πολλὰ δὲ καὶ τοῖς ἡγεμόσιν αὐτῶν καὶ φίλοις τοῖς αὐτοῦ ἐδωρεῖτο. καὶ παρῆν αὖθις ἐπὶ Ἱεριχοῦντος μέλαινά τε αὐτὸν ᾕρει χολὴ ἐπὶ πᾶσιν ἐξαγριαίνουσα, ὥστε δὴ τελευτῶν πρᾶξιν τοιάνδε ἐπινοεῖ· ἀφικομένων προστάγματι τῷ αὐτοῦ Ἰουδαίων ἀνδρῶν παντὸς τοῦ ἔθνους ὁποίποτε ἀξιολόγων· πολλοὶ δὲ ἐγένοντο ὡς τοῦ παντὸς ἔθνους κατακεκλημένου καὶ πάντων ἀκροασαμένων τοῦ διατάγματος, εἰς γὰρ θάνατον ἦν ἀνακείμενα τοῖς ἀλογήσασι τῶν ἐπιστολῶν ἐμμαινομένου πᾶσιν τοῦ βασιλέως ὁμοίως τοῖς τε ἀναιτίοις καὶ παρεσχηκόσιν αἰτίαν· συγκλείσας αὐτοὺς πάντας ἐν τῷ ἱπποδρόμῳ τήν τε ἀδελφὴν αὐτοῦ Σαλώμην καὶ τὸν ἄνδρα αὐτῆς Ἀλεξᾶν μεταπέμψας τεθνήξεσθαι μὲν οὐ πόρρω ἔλεγεν ἐπὶ τοσόνδε τῶν ἀλγηδόνων αὐτὸν περιεπουσῶν· καὶ τόδε μὲν οἰστόν τε καὶ πᾶσι φίλον παρατυγχάνειν, τὸ δὲ ὀλοφυρμῶν τε ἄπορον καὶ πένθους ἐνδεᾶ ὁποῖον ἐπὶ βασιλεῖ πράσσοιτο ἂν μάλιστα αὐτῷ λυπηρὸν εἶναι· οὐ γὰρ ἀποσκοποῦν τὴν Ἰουδαίων διάνοιαν, ὡς εὐκτὸς αὐτοῖς καὶ πάνυ κεχαρισμένος ὁ θάνατος αὐτοῦ διὰ τὸ καὶ ζῶντος ἐπὶ ἀποστάσει ἐπείγεσθαι καὶ ὕβρει τῶν ὑπ’ αὐτοῦ προτιθεμένων· ἔργον δ’ ἄρα ἐκείνων εἶναι κούφισίν τινα αὐτῷ ψηφίσασθαι τοῦ ἐπὶ τοιοῖσδε ἀλγεινοῦ· τὰ αὐτὰ γὰρ δὴ φρονῆσαι δόξῃ τῇ αὐτοῦ μὴ ἀπειπαμένων μέγαν τε αὐτοῦ τὸν ἐπιτάφιον γενέσθαι καὶ ὁποῖος οὐδ’ ἄλλοις βασιλέων καὶ πένθος διὰ τοῦ ἔθνους ἅπαντος ἐκ ψυχῆς ὀλοφυραμένων ἐπὶ παιδιᾷ καὶ γέλωτι αὐτοῦ. ἐπὰν οὖν θεάσωνται τὴν ψυχὴν ἀφέντα αὐτόν, περιστήσαντας τῷ ἱπποδρόμῳ τὸ στρατιωτικὸν ἀγνοοῦν ἔτι τὸν θάνατον αὐτοῦ, μὴ γὰρ πρότερον εἰς τοὺς πολλοὺς ἐξενεγκεῖν ἢ τάδε πρᾶξαι κελεύειν, ἀκοντίσαι τοὺς ἐγκαθειργμένους, καὶ πάντας τοῦτον ἀνελόντας τὸν τρόπον διχόθεν αὐτὸν οὐχ ἁμαρτήσαντας τοῦ εὐφρανοῦντος, κυρώσει τε ὧν ἐπιστείλειεν αὐτοῖς μέλλων τελευτᾶν καὶ τῷ πένθει ἀξιολόγῳ τετιμῆσθαι. καὶ ὁ μὲν μετὰ δακρύων ποτνιώμενος καὶ τοῦ συγγενοῦς τὴν εὔνοιαν καὶ πίστιν τοῦ θείου προσκαλῶν ἐπέσκηπτε μὴ ἠτιμῶσθαι ἀξιῶν, κἀκεῖνοι ὡμολόγουν οὐ παραβήσεσθαι.", "st": "17.6.5"}, {"sp": "N", "t": "Κατανοήσειεν δ’ ἄν τις τὴν διάνοιαν τοῦ ἀνθρώπου καὶ ὅτῳ τὰ πρότερα ἤρεσκεν ὡς ὑπὸ τοῦ φιλοζωεῖν πράξειε τὰ εἰς τοὺς συγγενεῖς πεπραγμένα, ἐκ γοῦν τῶν ἄρτι ἐπιστολῶν οὐδὲν ἀνθρώπειον εἰσφερομένην, εἴγε καὶ ἀπιὼν τοῦ βίου πρόνοιαν εἶχεν, ὡς ἐν πένθει καὶ ἐρημίᾳ τῶν φιλτάτων τὸ πᾶν καταστήσειεν ἔθνος, ἕνα ἀπὸ ἑκάστου οἴκου κελεύων μεταχειρίσαι μηδὲν ἄδικον μήτε εἰς αὐτὸν δεδρακότας μήτε ἐφ’ ἑτέροις ἐγκλήμασιν κατηγορίας αὐτῶν γενομένης, εἰωθότων οἷς προσποίησις ἀρετῆς καὶ πρὸς τοὺς δίκῃ ἐχθροὺς γεγονότας ἐν τοιοῖσδε καιροῖς τὰ μίση κατατίθεσθαι.", "st": "17.6.6"}, {"sp": "N", "t": "Ταῦτα δὲ ἐπιστέλλοντος αὐτοῦ πρὸς τοὺς συγγενεῖς γράμματα παρῆν ὑπὸ τῶν εἰς Ῥώμην πρέσβεων ἀπεσταλμένων πρὸς Καίσαρα. καὶ ἀναγνωσθέντων τὸ κεφάλαιον ἦν, ὡς τῆς τε Ἀκμῆς ὀργῇ τῇ Καίσαρος ἀνῃρημένης ἐφ’ οἷς Ἀντιπάτρῳ συγκακουργήσειεν, αὐτόν τε Ἀντίπατρον ὡς ἐπὶ γνώμῃ τῇ ἐκείνου ποιοῖτο ὡς πατρὸς καὶ βασιλέως, εἴτε φυγάδα ἐλαύνειν ἐθελήσειεν, εἴτε καὶ κτιννύειν. τούτων ἀκροώμενος Ἡρώδης βραχὺ μὲν ἀνήνεγκεν ἡδονῇ τῶν γεγραμμένων θανάτῳ τε τῆς Ἀκμῆς ἐπαιρόμενος καὶ ἐξουσίᾳ τῆς ἐπὶ τῷ παιδὶ τιμωρίας, περιουσῶν δὲ εἰς μέγα τῶν ἀλγηδόνων παρίετο τεταλαιπωρημένος σιτίων· καὶ ᾔτησε μῆλον καὶ μαχαίριον· ἦν γὰρ ἐν ἔθει καὶ πρότερον αὐτῷ περιλέψαντι αὐτὸ δι’ αὐτοῦ καὶ κατ’ ὀλίγον τεμόντι ἐσθίειν. λαβὼν δὲ καὶ περισκεψάμενος γνώμην εἶχεν παίσων ἑαυτόν, κἂν ἐπεπράχει μὴ φθάσαντος αὐτοῦ καταλαβεῖν τὴν δεξιὰν Ἀχιάβου· ἀνεψιὸς ἦν αὐτοῦ. καὶ μέγα ἀνακραγόντος οἰμωγή τε αὖθις ἀνὰ τὸ βασίλειον ἦν καὶ θόρυβος μέγας ὡς οἰχομένου τοῦ βασιλέως. καὶ ὁ Ἀντίπατρος, πιστεύει γὰρ τέλος ἀληθῶς τὸν πατέρα ἔχειν, θάρσει τε ἐχρῆτο ἐπὶ τοῖς λόγοις ὅλος ὡς ἤδη τῶν δεσμῶν ἀφησόμενος καὶ τὴν βασιλείαν ἀκονιτὶ δεξόμενος εἰς χεῖρας, καὶ τῷ εἱρκτοφύλακι περὶ ἀφέσεως ἦν αὐτοῦ διάλογος μεγάλα ὑπισχνουμένου εἰς τὸ παρὸν καὶ ταὖθις, ὡς ἂν περὶ τοιῶνδε τοῦ ἀγῶνος ἐνεστηκότος. ὁ δὲ οὐ μόνον ἀπειθὴς ἦν πράσσειν ἐφ’ οἷς ἠξίου Ἀντίπατρος, ἀλλὰ καὶ τῷ βασιλεῖ ἀποσημαίνει διάνοιαν τὴν ἐκείνου πολλῇ καὶ προσεισφορᾷ παρ’ αὑτοῦ χρώμενος. ὁ δὲ Ἡρώδης καὶ πρότερον οὐχ ἡσσώμενος οὐδ’ εὐνοίᾳ τοῦ υἱέος ἐπεὶ ἤκουσε τοῦ εἱρκτοφύλακος ταῦτα εἰρηκότος, ἀνεβόησέν τε ἀνατυψάμενος τὴν κεφαλὴν καίπερ ἐν τῷ ὑστάτῳ ὢν καὶ ἐπὶ τὸν ἀγκῶνα περιάρας ἑαυτὸν κελεύει πέμψας τινὰ τῶν δορυφόρων μηδὲν εἰς ἀναβολὰς ἀλλ’ ἐκ τοῦ ὀξέος κτείνασιν αὐτὸν ἐν Ὑρκανίᾳ ταφὰς ἀσήμους ποιεῖσθαι.", "st": "17.7.1"}, {"sp": "N", "t": "Τὰς δὲ διαθήκας αὖθις μετέγραφεν μεταβολῆς αὐτῷ περὶ τὴν διάνοιαν γενομένης, Ἀντίπαν μέν, ᾧ τὴν βασιλείαν καταλελοίπει, τετράρχην καθιστὰς Γαλιλαίας τε καὶ Περαίας, Ἀρχελάῳ δὲ τὴν βασιλείαν χαριζόμενος, τὴν δὲ Γαυλωνῖτιν καὶ Τραχωνῖτιν καὶ Βαταναίαν καὶ Πανιάδα Φιλίππῳ παιδὶ μὲν τῷ αὐτοῦ Ἀρχελάου δὲ ἀδελφῷ γνησίῳ τετραρχίαν εἶναι, Ἰάμνειαν δὲ καὶ Ἄζωτον καὶ Φασαηλίδα Σαλώμῃ τῇ ἀδελφῇ κατανέμει καὶ ἀργυρίου ἐπισήμου μυριάδας πεντήκοντα. προυνόησε δὲ καὶ τῶν λοιπῶν, ὁπόσοι συγγενεῖς ἦσαν αὐτῷ, χρημάτων τε δόσεσι καὶ προσόδων ἀναφοραῖς ἑκάστους ἐν εὐπορίᾳ καθιστάμενος. Καίσαρι δὲ ἀργυρίου μὲν ἐπισήμου μυριάδας χιλίας, χωρὶς δὲ σκεύη τὰ μὲν χρυσοῦ τὰ δ’ ἀργύρου καὶ ἐσθῆτα πάνυ πολλοῦ τέλους, Ἰουλίᾳ δὲ τῇ Καίσαρος γυναικὶ καί τισιν ἑτέροις πεντακοσίας μυριάδας. ταῦτα πράξας ἡμέρᾳ πέμπτῃ μεθ’ ὃ Ἀντίπατρον κτείνει τὸν υἱὸν τελευτᾷ, βασιλεύσας μεθ’ ὃ μὲν ἀνεῖλεν Ἀντίγονον ἔτη τέσσαρα καὶ τριάκοντα, μεθ’ ὃ δὲ ὑπὸ Ῥωμαίων ἀπεδέδεικτο ἑπτὰ καὶ τριάκοντα, ἀνὴρ ὠμὸς εἰς πάντας ὁμοίως καὶ ὀργῆς μὲν ἥσσων κρείσσων δὲ τοῦ δικαίου, τύχῃ δὲ εἰ καί τις ἕτερος κεχρημένος εὐμενεῖ. ἔκ τε γὰρ ἰδιώτου βασιλεὺς καταστὰς καὶ κινδύνοις περιστοιχιζόμενος μυρίοις πάντων ποιεῖται διάδρασιν καὶ τοῦ ζῆν ἐπὶ μήκιστον ἐξίκετο. ὁπόσα δὲ τὰ κατ’ οἶκον περὶ υἱεῖς τοὺς αὐτοῦ, ὅσα μὲν γνώμῃ τῇ ἐκείνου καὶ πάνυ δεξιᾷ κεχρημένος διὰ τὸ κρίνας ἐχθροὺς κρατεῖν οὐχ ὑστερῆσαι, δοκεῖν δ’ ἐμοὶ καὶ πάνυ δυστυχής.", "st": "17.8.1"}, {"sp": "N", "t": "Σαλώμη δὲ καὶ Ἀλεξᾶς πρὶν ἔκπυστον γενέσθαι τὸν θάνατον τοῦ βασιλέως τοὺς ἐπὶ τὸν ἱππόδρομον κατακεκλημένους ἐκπέμπονται ἐπὶ τὰ αὐτῶν, φάμενοι βασιλέα κελεύειν ἀπιοῦσιν αὐτοῖς ἐπὶ τοὺς ἀγροὺς νέμεσθαι τὰ οἰκεῖα, πράσσεταί τε αὐτοῖς ἥδε εὐεργεσία μεγίστη εἰς τὸ ἔθνος. ἐφανεροῦτο δ’ ἤδη ὁ θάνατος τοῦ βασιλέως, καὶ Σαλώμη καὶ Ἀλεξᾶς συναγαγόντες τὸ στρατιωτικὸν εἰς τὸ ἀμφιθέατρον τὸ ἐν Ἱεριχοῦντι πρῶτον μὲν ἐπιστολὴν ἀνέγνωσαν πρὸς τοὺς στρατιώτας γεγραμμένην ἐπὶ πίστεως εὐχαριστίᾳ καὶ εὐνοίας τῆς εἰς αὐτὸν καὶ παρακλήσει τῶν ὁμοίων παροκωχῆς Ἀρχελάῳ τῷ παιδὶ αὐτοῦ, ὃν βασιλέα καθίσταιτο. εἶτα μέντοι Πτολεμαῖος τὸν σημαντῆρα τοῦ βασιλέως πεπιστευμένος τὰς διαθήκας ἀνέλεγεν, αἳ λήψεσθαι κύρωσιν οὐκ ἄλλως ἔμελλον ἢ Καίσαρος ἐντυχόντος αὐταῖς. βοὴ οὖν εὐθὺς ἦν ἐκτιμώντων Ἀρχέλαον βασιλέα, καὶ οἱ στρατιῶται κατὰ στίφη τε αὐτοὶ καὶ οἱ ἡγεμόνες εὔνοιάν τε ὑπισχνοῦνται καὶ προθυμίαν τὴν αὐτῶν καὶ συλλήπτορα τὸν θεὸν παρεκάλουν.", "st": "17.8.2"}, {"sp": "N", "t": "Ἐντεῦθεν δὲ τάφον ἡτοίμαζον τῷ βασιλεῖ μελῆσαν Ἀρχελάῳ πολυτελεστάτην γενέσθαι τὴν ἐκκομιδὴν τοῦ πατρὸς καὶ πάντα τὸν κόσμον προκομίσαντος εἰς ὃ συμπομπεύσειε τῷ νεκρῷ. ἐφέρετο δὲ ἐπὶ κλίνης χρυσέας λίθοις πολυτελέσιν καὶ ποικίλοις διαπεπασμένης, στρωμνή τε ἦν ἁλουργὴς καὶ ἠμπέσχετο πορφυρίσιν ὁ νεκρὸς διαδήματι ἠσκημένος ὑπερκειμένου στεφάνου χρυσέου σκῆπτρόν τε τῇ δεξιᾷ παρακείμενον. περί τε τὴν κλίνην οἵ τε υἱεῖς καὶ τὸ πλῆθος ἦν τῶν συγγενῶν, ἐπὶ δὲ τούτοις τὸ στρατιωτικὸν κατὰ οἰκεῖα ἔθνη ἢ προσηγορίας διέκειντο αὐτοῖς νεμηθέντες, πρῶτοι μὲν οἱ δορυφόροι, μετὰ δὲ τὸ Θρᾴκιον, ἐπὶ δὲ τούτοις ὁπόσοι Γερμανῶν, καὶ τὸ Γαλατικὸν μετ’ αὐτούς, ἐν τῷ κόσμῳ πάντες τῷ πολεμιστηρίῳ. τούτων δὲ κατόπιν ἤδη πᾶς ὁ στρατὸς ὥσπερ ἐς πόλεμον ἐξοδεύοντες [ὥσπερ] ὑπὸ λοχαγῶν ἀγόμενοι καὶ τοῖς ταξιαρχοῦσιν αὐτῶν. τούτοις ἐπετετάχατο πεντακόσιοι τῶν οἰκετῶν ἀρωματοφόροι. ᾔεσαν δὲ ἐπὶ Ἡρωδίου στάδια ὀκτώ· τῇδε γὰρ αὐτῷ ἐγένοντο αἱ ταφαὶ κελεύσματι τῷ αὐτοῦ. Ἡρώδης μὲν δὴ τοῦτον ἐτελεύτα τὸν τρόπον.", "st": "17.8.3"}, {"sp": "N", "t": "Ἀρχέλαος δὲ ἐπὶ μὲν ἑβδόμην ἡμέραν πένθος τὸ ἐπὶ τῷ πατρὶ τιμῶν διετέλει· τόσας γὰρ διαγορεύει τὸ νόμιμον τοῦ πατρίου. ἑστιάσας δὲ τοὺς ὁμίλους καὶ καταλύσας τὸ πένθος ἄνεισιν εἰς τὸ ἱερόν. ἦσάν τε εὐφημίαι καὶ ἔπαινοι καθ’ οὕστινας ἴοι ἑκάστων τὰ πρὸς ἀλλήλους φιλοτιμουμένων εἰς τὸ δοκεῖν μείζοσι χρῆσθαι ταῖς εὐφημίαις. ὁ δὲ ἐπὶ ὑψηλὸν βῆμα πεποιημένον ἀνελθὼν καὶ ἱδρυθεὶς εἰς θρόνον χρυσοῦν [πεποιημένον] ἀντεδεξιοῦτο τοὺς ὁμίλους χάρματι τῶν εὐφημιῶν τὴν εὔνοιαν αὐτῶν ἡδονῇ φέρων, χάριν τε ὡμολόγει, διότι μηδὲν αὐτῷ μνησικακοῖεν ἀνθ’ ὧν ὁ πατὴρ εἰς αὐτοὺς ὑβρίσειεν καὶ πειράσεσθαι μὴ ἐλλείψειν ἀμειβόμενον τὸ πρόθυμον αὐτῶν. ἄρτι μέντοι φειδὼ ποιεῖσθαι τοῦ βασιλείου ὀνόματος, τετιμῆσθαι γὰρ αὐτὸν τῇ ἀξιώσει ὅπερ βεβαίως Καῖσαρ ἐπικυρώσειε τὰς διαθήκας, αἳ ὑπὸ τοῦ πατρὸς ἐγράφησαν αὐτοῦ· δι’ ἣν αἰτίαν οὐδὲ τοῦ στρατεύματος ἐν Ἱεριχοῦντι τὸ διάδημα αὐτῷ περιθέσθαι προθυμουμένου δέξασθαι τὸ περιμάχητον τῆς ἐνθένδε τιμῆς διὰ τὸ μηδέπω τὸν κυρίως ἀποδώσοντα φανερὸν εἶναι παρασχόμενον. περιιόντων μέν γε εἰς αὐτὸν τῶν πραγμάτων οὐ λείψειν ἀρετῆς τοῦ ἀμειψομένου τὴν εὔνοιαν αὐτῶν· σπουδάσειν γὰρ ἐν πᾶσιν τὰ πρὸς αὐτοὺς φανεῖσθαι τοῦ πατρὸς ἀμείνων τὰ πάντα. οἱ δὲ οἷον ὄχλος εἴωθεν, φιλεῖν οἰόμενοι τὰς πρώτας εἶναι τῶν ἡμερῶν τὰς διανοίας ἐμφανίζειν τῶν παριόντων ἐπὶ τοιάσδε ἀρχάς, ὅσῳ πρᾴως καὶ θεραπευτικῶς ὁ Ἀρχέλαος διελέγετο αὐτοῖς, τοσῷδε μειζόνως τε ἐχρῶντο τοῖς ἐπαίνοις καὶ κατὰ αἰτήσεις δωρεῶν ἐτετράφατο, οἱ μὲν εἰσφορὰς ἃς ἐνιαυσίους φέροιεν ἐπικουφίζειν βοῇ χρώμενοι, οἱ δὲ αὖ δεσμωτῶν, οἳ ὑφ’ Ἡρώδου ἐδέδεντο, πολλοὶ δὲ ἦσαν κἀκ πολλῶν χρόνων, ἀπόλυσιν. εἰσὶν δὲ οἳ ἄρσεις τῶν τελῶν ἃ ἐπὶ πράσεσιν ἢ ὠναῖς ἐπεβάλλετο πρασσόμενα πικρῶς ᾐτοῦντο. ἀντέλεγέν τε οὐδαμῶς Ἀρχέλαος ἐπειρᾶτο ὁμίλους σπουδαῖος ὢν ποιεῖν πάντα διὰ τὸ νομίζειν μέγα πρᾶγμα εἰς τήρησιν τῆς ἀρχῆς γενήσεσθαι τὴν εὔνοιαν αὐτῷ τῆς πληθύος. ἐντεῦθεν δὲ θύσας τῷ θεῷ κατ’ εὐωχίαν τρέπεται μετὰ τῶν φίλων.", "st": "17.8.4"}, {"sp": "N", "t": "Ἐν τούτῳ δέ τινες τῶν Ἰουδαίων συνελθόντες νεωτέρων ἐπιθυμίᾳ πραγμάτων Ματθίαν καὶ τοὺς σὺν αὐτῷ ὑφ’ Ἡρώδου ἀποθανόντας, οἳ παραχρῆμα τῆς εἰς τὸ πενθεῖσθαι τιμῆς φόβῳ τῷ ἐκείνου ἀπεστέρηντο, ἦσαν δὲ οἱ τῶν ἐπὶ καθαιρέσει τοῦ χρυσοῦ ἀετοῦ δεδικαιωμένων, ἐπὶ μέγα τε τῇ βοῇ καὶ οἰμωγῇ χρώμενοι καί τινα ὡς κούφισιν φέροντα τοῖς τεθνεῶσιν ἀπερρίπτουν εἰς τὸν βασιλέα. συνόδου τε αὐτοῖς γενομένης ἠξίουν τιμωρίαν αὐτοῖς ὑπ’ Ἀρχελάου γενέσθαι κολάσεσιν τῶν ὑπὸ Ἡρώδου τιμωμένων, καὶ πάντων γε καὶ πρῶτον καὶ ἐκδηλότατα τὸν ὑπ’ αὐτοῦ ἀρχιερέα καθεστῶτα παύσαντα νομιμώτερόν τε ἅμα καὶ καθαρὸν ἀρχιερᾶσθαι ἄνδρα αἱρεῖσθαι. τούτοις Ἀρχέλαος καίπερ δεινῶς φέρων ἐπένευεν τὴν ὁρμὴν αὐτῶν διὰ τὴν ἐπὶ Ῥώμης ὁδὸν ἀνύεσθαι προκείμενον αὐτῷ τάχος ἐπὶ περισκοπήσει τῶν δοξάντων Καίσαρι. πέμψας δὲ τὸν στρατηγὸν πειθοῖ χρῆσθαι, καὶ τῆς ἐπὶ τοιούτοις μωρίας ἀποστάντας σκοπεῖν, θάνατόν τε, ὃς τοῖς φίλοις αὐτῶν συνέλθοι, μετὰ νόμων γεγονότα, καὶ τὰς αἰτήσεις ὡς ἐπὶ μέγα τοῦ ὑβρίζειν προΐοιεν, τούς τε καιροὺς οὐκ ἐν τοιοῖσδε εἶναι, μᾶλλον δὲ τοῦ ὁμονοεῖν ἕως καταστησάμενος τὴν ἀρχὴν ἐπινεύσει τῇ Καίσαρος ἀφίκοιτο ὡς αὐτούς· τότε γὰρ κοινῇ βουλεύσειν περὶ ὧν ἀξιοῖεν σὺν αὐτοῖς· ἄρτι δὲ ἀνέχειν, μὴ καὶ στασιάζειν δοκοῖεν.", "st": "17.9.1"}, {"sp": "N", "t": "Καὶ ὁ μὲν ταῦτα ὑπειπὼν καὶ διδάξας τὸν στρατηγὸν ἐκπέμπει πρὸς αὐτούς. οἱ δὲ βοῶντες λέγειν τε οὐκ εἴων καὶ εἰς κίνδυνον τοῦ ἀπολουμένου ἐκεῖνόν τε καθίστασαν καὶ τῶν ἄλλων ὅστις γε ἐπὶ σωφρονισμῷ καὶ ἀποτροπῇ τοῦ μὴ τοιῶνδε ὀριγνᾶσθαι τολμήσειν φθέγξασθαι φανερὸς ἦν διὰ τὸ πάντα βουλήσει τῇ αὐτῶν μᾶλλον ἢ ἐξουσίᾳ τῶν ἐφεστηκότων συγχωρεῖν, δεινὸν ἡγούμενοι, εἰ ζῶντός τε Ἡρώδου στερηθεῖεν τῶν φιλτάτων καὶ τελευτῆς αὐτῷ γενομένης τιμωριῶν τῶν ἐπ’ αὐτοῖς, ὠργηκότες ταῖς γνώμαις καὶ νόμιμόν τε καὶ δίκαιον ἡγούμενοι ὅ τι μελλήσοι ἡδονὴν αὐτοῖς φέρειν, κίνδυνον δὲ τὸν ἀπ’ αὐτοῦ προϊδέσθαι τε ἀμαθεῖς καὶ εἴ τῳ ὑποπτευθείη, ὑπερβολῆς αὐτῷ γενομένης τῆς παραχρῆμα ἡδονῆς ἐκ τοῦ τιμωρήσασθαι τοὺς ἐχθίστους δοκοῦντας αὐτοῖς. πολλῶν δὲ ὑπὸ Ἀρχελάου πεμπομένων, οἳ διαλέξοιντο αὐτοῖς, τῶν τε ἐνεστώτων μὲν ὑπ’ ἐκείνου γνώμῃ δὲ τῇ αὐτῶν δοκεῖν παριόντων, ὅπως εἰς τὸ πραΰτερον καταστήσονται αὐτούς, οὐδενὸς ἠνείχοντο εἰπεῖν ἀνάστασίς τε ἦν δεύειν ὀργῇ χρωμένων, φανεροί τε ἦσαν ἐπὶ μέγα αὐξήσοντες τὴν στάσιν πλήθους ἐπισυρρυέντος αὐτοῖς.", "st": "17.9.2"}, {"sp": "N", "t": "Ἐνστάσης δὲ κατὰ τόνδε τὸν καιρὸν ἑορτῆς, ἐν ᾗ Ἰουδαίοις ἄζυμα προτίθεσθαι πάτριον· φάσκα δ’ ἡ ἑορτὴ καλεῖται ὑπόμνημα οὖσα τῆς ἐξ Αἰγύπτου ἀπάρσεως αὐτῶν γενομένης, καὶ θύουσιν αὐτὴν προθύμως πλῆθός τε ἱερείων ὡς οὐκ ἐν ἄλλῃ κατακόπτειν ἐστὶν αὐτοῖς νόμιμον· κάτεισιν δὲ πληθὺς ἀναρίθμητος ἐκ τῆς χώρας ἤδη δὲ καὶ ἐκ τῆς ὑπερορίας ἐπὶ θρησκείᾳ τοῦ θεοῦ, καὶ οἱ νεωτερισταὶ τοὺς περὶ τὸν Ἰούδαν τε καὶ Ματθίαν ἐξηγητὰς τῶν νόμων ὀδυρόμενοι συστάντες ἐν τῷ ἱερῷ τροφῆς ηὐποροῦντο τοῖς στασιασταῖς οὐκ ὂν ἐν αἰσχύνῃ μεταιτεῖν αὐτούς. καὶ δείσας Ἀρχέλαος, μὴ καί τι δεινὸν βλαστήσειεν αὐτῶν τῇ ἀπονοίᾳ, πέμπει σπεῖράν τε ὁπλιτῶν χιλίαρχόν τε τὴν ὁρμὴν τῶν ἐνεστηκότων πρότερον τὸν πάντα ὅμιλον τοῦ μανιώδους αὐτῶν πλέω καταστῆναι, καὶ εἴ τινες διάδηλοι πολὺ τῶν ἄλλων καθίσταιντο προθυμίᾳ τοῦ στασιάζειν ἐπ’ αὐτὸν ἀγαγεῖν. ἐπὶ τούτῳ οἱ στασιῶται τῶν ἐξηγητῶν καὶ τὸ πλῆθος ἐξηγρίωσε βοῇ καὶ διακελευσμῷ χρώμενοι ὥρμησάν τε ἐπὶ τοὺς στρατιώτας καὶ περιστάντες λεύουσιν τοὺς πλείστους αὐτῶν. ὀλίγοι δέ τινες καὶ ὁ χιλίαρχος τραυματίαι διέφυγον. καὶ τοῖς μὲν ταῦτα πράξασιν διὰ χειρῶν αὖθις ἡ θυσία ἦν· Ἀρχελάῳ δὲ ἄπορον ἐδόκει σώζεσθαι τὰ πάντα μὴ οὐκ ἀνακόψειν τὴν ἐπὶ τοιοῖσδε ὁρμὴν τῆς πληθύος, ἐκπέμπει δὲ πᾶν τὸ στρατόπεδον οἳ τούς τε αὐτόθι ἐσκηνωκότας κωλύοιεν τοῖς κατὰ τὸ ἱερὸν βοηθεῖν καὶ τοὺς ἐκπίπτοντας ὑπὸ τῶν πεζῶν δέχοιντο ἀντειλῆφθαι τἀσφαλοῦς ἤδη πεπιστευκότας. καὶ εἰς μὲν τρισχιλίους ἄνδρας ἔκτειναν οἱ ἱππεῖς· τὸ δὲ λοιπὸν ᾤχετο ἐπὶ ὄρη τὰ πλησίον ἰόντες. ἐκήρυσσε δ’ Ἀρχέλαος ἀναχωρεῖν ἐπὶ τὰ αὑτῶν πᾶσιν. οἱ δὲ ἀπῄεσαν τὴν ἑορτὴν καταλιπόντες φόβῳ κακοῦ μείζονος καίπερ θρασεῖς ὄντες διὰ τὸ ἀπαίδευτον. Ἀρχέλαος δ’ ἐπὶ θαλάσσης κατῄει μετὰ τῆς μητρὸς Νικόλαον καὶ Πτολεμαῖον καὶ Πτόλλαν τῶν φίλων ἐπαγόμενος, Φιλίππῳ τἀδελφῷ τὰ πάντα ἐφεὶς καθίστασθαι τοῦ οἴκου καὶ τῆς ἀρχῆς. συνεξῄει δ’ αὐτῷ καὶ Σαλώμη ἡ Ἡρώδου ἀδελφὴ γενεὰν ἀγομένη τὴν αὐτῆς, πολλοί τε τῶν συγγενῶν, λόγῳ μὲν ὡς συναγωνιούμενοι τῷ Ἀρχελάῳ ἐπὶ κτήσει τῆς βασιλείας, ἔργῳ δὲ ἀντιπράξοντες καὶ μάλιστα περὶ τῶν πεπραγμένων ἐν τῷ ἱερῷ ποιησόμενοι καταβοάς. ὑπαντιάζει δ’ ἐν Καισαρείᾳ τὸν Ἀρχέλαον Σαβῖνος Καίσαρος ἐπίτροπος τῶν ἐν Συρίᾳ πραγμάτων εἰς Ἰουδαίαν ὡρμημένος ἐπὶ φυλακῇ τῶν Ἡρώδου χρημάτων. καὶ αὐτὸν τῆς ἐπὶ τοῖσδε ὁρμῆς ἔσχεν ὁ Οὔαρος παρελθών· διὰ γὰρ Πτολεμαίου μετάπεμπτος ὑπ’ Ἀρχελάου παρῆν. καὶ Οὐάρῳ Σαβῖνος χαριζόμενος οὔτε τὰς ἄκρας, ὅσαι ἐν τοῖς Ἰουδαίοις ἦσαν, παρέλαβεν οὔτε τοὺς θησαυροὺς κατεσημήνατο, εἴα δ’ ἔχειν Ἀρχέλαον μέχρι Καίσαρι δόξειέν τι περὶ αὐτῶν, καὶ ἔμενεν ἐν τῇ Καισαρείᾳ τοῦθ’ ὑποσχόμενος. ἐπεὶ δ’ ἐκπλεῖ μὲν ἐπὶ τῆς Ῥώμης Ἀρχέλαος, Οὐάρῳ δ’ ἐπ’ Ἀντιοχείας ἐγένοντο κομιδαί, Σαβῖνος ἐπὶ Ἱεροσολύμων χωρήσας παραλαμβάνει τὰ βασίλεια. μεταπέμψας δὲ τοὺς φρουράρχους καὶ ὁπόσοι διοικηταὶ τῶν πραγμάτων ἦσαν λόγους τε ἀπαιτεῖν πρόδηλος ἦν καὶ τὰς ἄκρας καθίστατο ᾗ αὐτῷ δοκοῖ. οὐ μὴν οἱ φύλακες ἐν ὀλίγῳ τὰς Ἀρχελάου ἐπιστολὰς ἐποιοῦντο, ἀλλ’ ἔμενον σώζοντες τὰ πάντα ᾗ προσετέτακτο αὐτοῖς. Καίσαρι δὲ φυλάσσειν ἕκαστ’ ἦν προσποίησις αὐτοῖς.", "st": "17.9.3"}, {"sp": "N", "t": "Πλεῖ δὲ κατὰ τοῦτον τὸν καιρὸν ἐπὶ Ῥώμης καὶ Ἀντίπας Ἡρώδου μὲν παῖς, ἐπὶ δ’ ἀντιποιήσει τῆς ἀρχῆς ὑποσχέσεσι Σαλώμης ἠρμένος ἐπὶ τῷ ἄρχειν καὶ πολὺ δικαιότερον Ἀρχελάου παραλήψεσθαι τὰ πράγματα ἠξιωκὼς τῷ κατὰ τὰς προτέρας διαθήκας βασιλεὺς ἀποπεφάνθαι, ἃς ἀσφαλεστέρας εἶναι τῶν ἐπιγραφεισῶν. ἐπήγετο δὲ οὗτος τήν τε μητέρα καὶ τὸν ἀδελφὸν τὸν Νικολάου Πτολεμαῖον φίλον τε Ἡρώδῃ τιμιώτατον γεγενημένον καὶ αὐτῷ προσκείμενον. μάλιστα δὲ αὐτὸν ἐνῆγεν ἐπ’ ἀντιποιήσει τῆς βασιλείας φρονεῖν Εἰρηναῖος ῥήτωρ ἀνὴρ καὶ δόξῃ δεινότητος τῆς περὶ αὐτῷ τὴν βασιλείαν πεπιστευμένος. διὸ δὴ καὶ τῶν κελευόντων εἴκειν Ἀρχελάῳ πρεσβυτέρῳ τε ὄντι κἀν ταῖς ἐπιδιαθήκαις ὑπὸ τοῦ πατρὸς ἐγγεγραμμένῳ βασιλεῖ οὐκ ἠνείχετο. ἐπεὶ δ’ εἰς τὴν Ῥώμην ἀφίκετο, καὶ πάντων τῶν συγγενῶν ἀπόστασις ἦν πρὸς αὐτόν, οὐκ εὐνοίᾳ τῇ ἐκείνου, μίσει δὲ τῷ πρὸς Ἀρχέλαον, μάλιστα μὲν ἐπιθυμοῦντες ἐλευθερίας καὶ ὑπὸ Ῥωμαίων στρατηγῷ τετάχθαι, εἰ δ’ ἄρα τι ἀντισταίη, λυσιτελέστερον Ἀρχελάου τὸν Ἀντίπαν λογιζόμενοι, συνέπραττον Ἀντίπᾳ τὴν βασιλείαν. καὶ Σαβῖνος κατηγόρει παρὰ Καίσαρι τοῦ Ἀρχελάου διὰ γραμμάτων.", "st": "17.9.4"}, {"sp": "N", "t": "Καῖσαρ δὲ Ἀρχελάου τε εἰσπέμψαντος ὡς αὐτὸν γράμματα, ἐν οἷς τὰ δικαιώματα προετίθει τε αὐτοῦ καὶ τὴν διαθήκην τοῦ πατρὸς καὶ τοὺς λογισμοὺς τῶν Ἡρώδου χρημάτων σὺν τῷ σημαντῆρι κομίζοντα Πτολεμαῖον, ἐκαραδόκει τὸ μέλλον. ὁ δὲ ταῦτά τε ἀναγνοὺς τὰ γράμματα καὶ τὰς Οὐάρου καὶ Σαβίνου ἐπιστολὰς ὁπόσα τε χρήματα ἦν καὶ τί ἐπ’ ἔτος ἐφοίτα καὶ ὅσα Ἀντίπας ἐπ’ οἰκειώσει τῆς βασιλείας ἐπεπόμφει γράμματα συνῆγεν ἐπὶ παροκωχῇ γνωμῶν τοὺς φίλους, σὺν οἷς καὶ Γάιον τὸν Ἀγρίππου μὲν καὶ Ἰουλίας τῆς αὐτοῦ θυγατρὸς υἱὸν ποιητὸν δὲ αὐτῷ γεγονότα πρῶτόν τε καθεδούμενον παρέλαβε, καὶ κελεύει λέγειν τοῖς βουλομένοις περὶ τῶν ἐνεστηκότων. καὶ πρῶτος ὁ Σαλώμης υἱὸς Ἀντίπατρος δεινότατός τε ὢν εἰπεῖν καὶ τῷ Ἀρχελάῳ ἐναντιώτατος ἔλεγεν Ἀρχελάῳ παιδιὰν τὸν περὶ τῆς ἀρχῆς εἶναι λόγον ἔργῳ τὴν δύναμιν αὐτῆς πρότερον ἢ Καίσαρα συγχωρῆσαι παρειληφότι, ἐπικαλῶν τὰ τετολμημένα ἐπὶ τοῖς ἀπολωλόσι κατὰ τὴν ἑορτήν· ὧν καὶ ἀδικούντων ἄλλως ἔσχεν τὴν τιμωρίαν εἰς τοὺς ἔξω χρῆσθαι δυναμένους ἀνακειμένην εἶναι, καὶ μὴ ὑπ’ ἀνδρὸς πεπρᾶχθαι, εἰ μὲν βασιλέως, ἀδικοῦντος τὸ Καίσαρος διαγνοίᾳ περὶ αὐτοῦ ἔτι χρώμενον, εἰ δὲ ἰδιώτου, πολὺ χειρόνως, διὰ τὸ μὴ βασιλείας ἀντιποιουμένῳ καλῶς ἂν συγκεχωρῆσθαι, διὰ τὸ Καίσαρα τῆς ἐπ’ αὐτοῖς ἐξουσίας ἀφαιρεῖσθαι. καθήπτετο δὲ αὐτοῦ ἡγεμόνων τινῶν ἐν τῷ στρατιωτικῷ μετάστασιν ἐπικαλῶν καὶ προκάθισιν ἐπὶ θρόνου βασιλείου καὶ δικῶν διάλυσιν ὡς ὑπὸ βασιλέως γενομένην κατανεύσεις τε αἰτήσεων τοῖς δημοσίᾳ αἰτουμένοις καὶ πάντων διάπραξιν, ὧν οὐδὲν ἂν μειζόνως ἐπινοῆσαι καθεσταμένον ὑπὸ τοῦ Καίσαρος εἰς τὴν ἀρχήν. ἀνετίθει δὲ αὐτῷ καὶ τῶν ἐκ τοῦ ἱπποδρόμου δεσμωτῶν τὴν ἄφεσιν καὶ πολλὰ τὰ μὲν γεγονότα τὰ δὲ καὶ πιστεύεσθαι δυνάμενα διὰ τὸ φύσιν ἔχειν γίνεσθαι ὑπό τε νεωτέρων καὶ φιλοτιμίᾳ τοῦ ἄρχειν προλαμβανόντων τὴν ἐξουσίαν, πένθους τε τοῦ ἐπὶ τῷ πατρὶ ἀμελείας καὶ κωμασμοὺς αὐτονυκτὶ τῇ ἐκείνου τελευτῇ γεγονότας, ἐφ’ οἷς δὴ καὶ τὴν πληθὺν ἀρχὴν τοῦ στασιάζειν λαβεῖν, εἰ τοιαῦτα εὐεργετήσαντος αὐτὸ τοῦ πατρὸς καὶ οὕτως μεγάλων ἠξιωκότος τοιοῖσδε ἀμείβεσθαι τὸν νέκυν, ὥσπερ ἐπὶ σκηνῆς δακρύειν μὲν προσποιούμενον τὰς ἡμέρας, ἀπολαύοντα δὲ ἡδονῇ τῇ ἐπὶ τῆς ἀρχῆς ὅσαι νύκτες. φανεῖσθαί τε καὶ περὶ τὸν Καίσαρα τοιόνδε ὄντα Ἀρχέλαον συγχωροῦντα τὴν βασιλείαν, ὁποῖος γένοιτο καὶ περὶ τὸν πατέρα· χορεύειν γὰρ καὶ ᾄδειν ὥσπερ ἐχθροῦ πεσόντος, ἀλλ’ οὐκ ἀνδρὸς οὕτως μὲν συγγενοῦς, τηλικαῦτα δ’ εὐεργετεῖν ἐξηγμένου. δεινότατόν τε πάντων ἀπέφηνε τὸ νῦν ἥκειν ἐπὶ Καίσαρος κατανεύσει τῇ ἐκείνου χρησόμενον τῇ βασιλείᾳ πάντων αὐτῷ προπεποιημένων, ὁπόσα γένοιτο ἂν ὑπὸ σοῦ βεβαίως ἤδη τοῦ αὐτοκράτορος παρεσχηκότος πρασσόμενα. μάλιστα δὲ τὴν σφαγὴν τῶν περὶ τὸ ἱερὸν ἐδείνου τῷ λόγῳ καὶ τὴν δυσσέβειαν, ὡς ἑορτῆς τε ἐνεστηκυίας καὶ ἱερείων ἐν τρόπῳ σφαχθεῖεν ἔνιοι μὲν ξένοι οἱ δὲ ἐγχώριοι, πλησθείη δὲ τὸ ἱερὸν νεκρῶν οὐχ ὑπ’ ἀλλοφύλου, ἀλλὰ τοῦ καὶ μετὰ νομίμων ὀνομάτων τῆς βασιλείας ἐφιεμένου τῆς πράξεως, ὅπως δυνηθείη πληρῶσαι τῆς φύσει τυραννίδος τὴν πᾶσιν ἀνθρώποις μεμισημένην ἀδικίαν. δι’ ἣν μηδὲ ὄναρ ποτὲ ἑωρᾶσθαι βασιλείας αὐτῷ τὴν διαδοχὴν ἀρετῇ τοῦ πατρός· ἐπίστασθαι γὰρ αὐτοῦ τὸν τρόπον καί τοι ἐχθρὸν αὐτῷ [ἐκ] τῶν διαθηκῶν ἰσχυρότερον Ἀντιπάτρῳ καθίστασθαι· κληθῆναι γὰρ ὑπὸ τοῦ πατρὸς ἐπὶ τὴν βασιλείαν οὐχὶ νοσοῦντος πρὸς τῷ σώματι καὶ τὴν ψυχήν, ἀλλὰ ἀκραιφνεῖ μὲν τῷ λογισμῷ χρωμένου, ἀλκῇ δὲ σώματος τοῖς πράγμασιν ἐφεστηκότος. εἰ δὲ καὶ πρότερον εἰς αὐτὸν ἐπίσης τοῖς νῦν διατεθεῖσθαι τὸν πατέρα, ἀποπεφάνθαι ποταπὸς ἂν γένοιτο βασιλεὺς τὸν μὲν κύριον παρασχεῖν τὴν βασιλείαν Καίσαρα ἀφῃρημένον τοῦ δοῦναι τὴν ἐξουσίαν, τοὺς δὲ πολίτας ἰδιώτην ὄντα ἀκμὴν σφάζειν ἐν ἱερῷ μὴ ἀποτετραμμένον.", "st": "17.9.5"}, {"sp": "N", "t": "Καὶ Ἀντίπατρος μὲν τοιάδε εἰπὼν καὶ μαρτύρων παραστάσεσιν τὰ εἰρημένα κρατυνάμενος πολλοῖς τῶν συγγενῶν παύεται τοῦ λέγειν. ἀνίσταται δὲ Νικόλαος ὑπὲρ Ἀρχελάου καὶ ἔλεγεν τὰ μὲν ἐν τῷ ἱερῷ γνώμῃ τῶν πεπονθότων ἀναθεὶς μᾶλλον ἢ ἐξουσίᾳ τῇ Ἀρχελάου· τοὺς γὰρ ἐπὶ τοιοῖσδε ἄρχοντας οὐ μόνον τῷ καθ’ αὑτοὺς ὑβρίζοντι εἶναι πονηρούς, ἀλλὰ καὶ τῷ ἀναγκάζοντι εἰς τὴν ἄμυναν τῶν εὐγνωμονεῖν προαιρουμένων. ὡς δὲ πολέμια ἔδρων λόγῳ μὲν κατ’ Ἀρχελάου τὸ δὲ ἀληθὲς εἰς Καίσαρα φανερὸν εἶναι· τοὺς γὰρ ὑβριοῦντας κωλυτὰς παραγενομένους ἢ ὑπ’ Ἀρχελάου πεπομφότος κτεῖναι ἐπιθεμένους οὔτε τοῦ θεοῦ οὔτε τοῦ νόμου τῆς ἑορτῆς ἐν φροντίδι γενομένους, ὧν Ἀντίπατρον οὐκ αἰσχύνεσθαι ἐκδικητὴν καθιστάμενον ἐπὶ θεραπείᾳ ἔχθρας τῆς αὐτοῦ πρὸς Ἀρχέλαον ἢ φύσει τοῦ ἀρετῇ δικαίου. οἱ παρελθόντες καὶ μὴ πρὸς διανοουμένους ἄρχοντες ἀδίκων ἔργων, οἵδε εἰσὶν οἱ βιαζόμενοι καὶ μὴ θέλοντας τοὺς ἀμυνομένους ἐφ’ ὅπλα χωρεῖν. ἀνετίθει δὲ καὶ τὰ λοιπὰ πᾶσι τοῖς ἐν βουλῇ τῶν κατηγόρων· οὐδὲν γὰρ ὅ τι μὴ οὐ μετὰ γνώμης τῆς αὐτῶν γεγενημένον αἰτίᾳ τοῦ ἀδικεῖν ὑπάγεσθαι, οὐ τῇ φύσει τῇ οὕτως αὐτὰ γεγονότα πονηρὰ εἶναι, ἀλλὰ τῷ βλάψειν ἂν δοκεῖν Ἀρχέλαον. τοσήνδε αὐτοῖς εἶναι βουλὴν τοῦ ὑβριοῦντος εἰς ἄνδρα συγγενῆ, καὶ πατρὸς μὲν εὐεργέτου, συνήθη δὲ αὐτοῖς καὶ διὰ παντὸς οἰκείως πεπολιτευμένον. τάς γε μὴν διαθήκας ὑπό τε σωφρονοῦντος γεγράφθαι τοῦ βασιλέως καὶ κυριωτέρας τῶν γεγραμμένων πρότερον διὰ τὸ Καίσαρι δεσπότῃ τῶν ὅλων καταλελεῖφθαι τὴν κρίσιν τῶν ἐν αὐταῖς γεγραμμένων. μιμήσεσθαί τε οὐδαμῶς Καίσαρα τὴν ὕβριν αὐτῶν, οἳ τῆς Ἡρώδου παντοίως ἀπολαύσαντες παρ’ ὃν ἔζη καιρὸν δυνάμεως τὰ πάντα ἐπὶ ὕβρει γνώμης ἐπείγοιντο αὐτοῦ, οὐδ’ αὐτῶν περὶ τὸν συγγενῆ τοιούτων γεγονότων. οὔκουν Καίσαρά γε ἀνδρὸς ἐπ’ αὐτῷ πεποιημένου τὰ πάντα καὶ φίλου καὶ συμμάχου καταλύσειν τὰς διαθήκας ἐπὶ πίστει τῇ αὐτοῦ γεγραμμένας, οὐδὲ μιμήσεσθαι κακίαν τὴν ἐκείνων τὴν Καίσαρος ἀρετὴν καὶ πίστιν πρὸς ἅπασαν τὴν οἰκουμένην ἀνενδοίαστον γενομένην, καὶ μανίαν καὶ λογισμῶν ἔκστασιν κατακρίνειν ἀνδρὸς βασιλέως, υἱεῖ μὲν ἀγαθῷ τὴν διαδοχὴν καταλελοιπότος, πίστει δὲ τῇ αὐτοῦ προσπεφευγότος· οὔτ’ ἁμαρτάνειν Ἡρώδην ποτὲ περὶ κρίσιν τοῦ διαδόχου σωφροσύνῃ κεχρημένον ἐπὶ τῇ Καίσαρος γνώμῃ τὰ πάντα ποιεῖσθαι.", "st": "17.9.6"}, {"sp": "N", "t": "Καὶ Νικόλαος μὲν τοιάδε διελθὼν καταπαύει τὸν λόγον· Καῖσαρ δὲ Ἀρχέλαον προσπεσόντα αὐτῷ πρὸς τὰ γόνατα φιλοφρόνως τε ἀνίστη φάμενος ἀξιώτατον εἶναι τῆς βασιλείας πολλήν τε ἀπέφαινε τροπὴν γνώμης τῆς αὐτοῦ οὐκ ἄλλα πράξειν, ἀλλ’ ὁπόσα αἵ τε διαθῆκαι ὑπηγόρευον καὶ Ἀρχελάῳ συνέφερεν. οὐ μέντοι γε ἐκεκύρωτο οὐδέν, ὡς ἂν ἐχεγγύῳ παραδείγματι χρώμενον ἐπ’ ἀδείας Ἀρχέλαον εἶναι. καὶ διαλύσεως τῶν ἀνδρῶν γενομένης ἐσκοπεῖτο καθ’ αὑτόν, εἴτε Ἀρχελάῳ τὴν βασιλείαν ἐπικυρωτέον, εἴτε νομὴν αὐτῆς ποιεῖσθαι παντὶ τῷ Ἡρώδου γένει καὶ ταῦτα πάντων πολλῆς ἐπικουρίας δεομένων.", "st": "17.9.7"}, {"sp": "N", "t": "Πρότερον δὲ ἢ κύρωσίν τινα τούτων γενέσθαι Μαλθάκη τε ἡ Ἀρχελάου μήτηρ νόσῳ τελευτᾷ καὶ παρὰ Οὐάρου τοῦ Συρίας στρατηγοῦ παρῆν γράμματα τὴν Ἰουδαίων ἀπόστασιν διασαφοῦντα· τοῦ γὰρ Ἀρχελάου μετὰ τὸν ἔκπλουν ἐθορυβήθη τὸ πᾶν ἔθνος. καὶ Οὔαρος αὐτὸς ἐπεὶ παρὼν ὡς τοὺς αἰτίους τῆς κινήσεως τιμωρίᾳ περιβαλὼν καὶ τοῦ πολλοῦ τῆς στάσεως ἐπίσχεσιν ποιησάμενος πολλῆς γενομένης ἐπ’ Ἀντιοχείας τὴν ἀναζυγὴν ἐποιεῖτο, τάγμα ἓν τῆς στρατιᾶς ἐν Ἱεροσολύμοις λειπόμενος τὴν Ἰουδαίων νεωτεροποιίαν ἐπιστομιοῦντας. οὐ μὴν ἐπεραίνετό γε οὐδὲν ἐπὶ παύλῃ τοῦ μὴ οὐ στασιάσοντος αὐτῶν. ὅτε γὰρ Οὔαρος ἀπῄει καὶ Σαβῖνος ὁ ἐπίτροπος τοῦ Καίσαρος ὑπομείνας αὐτόθι μεγάλως τοὺς στασιώτας κατεπόνει, στρατιᾷ τε τῇ καταλελειμμένῃ πιστεύων, ὡς καὶ περιέσοιτο αὐτῶν, καὶ τῷ πλήθει· πολλοὺς δὲ ὄντας ὁπλίσας δορυφόροις ἐχρῆτο αὐτοῖς ἐπείγων τοὺς Ἰουδαίους καὶ ἐκταράσσων ἐπὶ ἀποστάσει· τάς τε γὰρ ἄκρας ἐβιάζετο παραλαμβάνειν καὶ τῶν βασιλικῶν χρημάτων ἐπ’ ἐρεύνῃ προθύμως ὥρμητο βίᾳ διὰ κέρδη καὶ πλεονεξιῶν ἐπιθυμίας.", "st": "17.10.1"}, {"sp": "N", "t": "Ἐνστάσης δὲ τῆς πεντηκοστῆς, ἑορτὴ δὲ ἡμῶν ἐστιν πάτριος τοῦτο κεκλημένη, οὔτι κατὰ τὴν θρησκείαν μόνον παρῆσαν, ἀλλ’ ὀργῇ φέροντες τὴν παροινίαν τῆς Σαβίνου ὕβρεως μυριάδες συνηθροίσθησαν ἀνθρώπων καὶ πάνυ πολλαὶ Γαλιλαίων τε καὶ Ἰδουμαίων, Ἱεριχουντίων τε ἦν πληθὺς καὶ ὁπόσοι περάσαντι Ἰορδάνην ποταμὸν οἰκοῦσιν, αὐτῶν τε Ἰουδαίων πλῆθος πρὸς πάντας συνειλέχατο καὶ πολὺ προθυμότεροι τῶν ἄλλων ἐπὶ τιμωρίᾳ τῇ Σαβίνου ὡρμήκεσαν. καὶ τρία μέρη νεμηθέντες ἐπὶ τοσῶνδε στρατοπεδεύονται χωρίων, οἱ μὲν τὸν ἱππόδρομον ἀπολαβόντες, καὶ τῶν δὲ λοιπῶν δύο μερῶν οἱ μὲν τῷ βορείῳ τοῦ ἱεροῦ πρὸς μεσημβρίαν τετραμμένοι, οἱ δὲ ἑῴαν μοῖραν εἶχον, μοῖρα δὲ αὐτῶν ἡ τρίτη τὰ πρὸς δυόμενον ἥλιον, ἔνθα καὶ τὸ βασίλειον ἦν. ἐπράσσετο δὲ τὰ πάντα αὐτοῖς ἐπὶ πολιορκίᾳ τῶν Ῥωμαίων ἁπανταχόθεν αὐτοῖς ἀποκεκλεισμένων. καὶ Σαβῖνος, ἔδεισε γὰρ τό τε πλῆθος αὐτῶν καὶ τὰ φρονήματα ἀνδρῶν ἐν ὀλίγῳ τὸ θανεῖν ποιουμένων ὑπὸ τοῦ ἡττᾶσθαι μὴ ἐθέλειν ἐφ’ οἷς ἀρετὴν κρίνειαν τὸ νικᾶν, παραχρῆμά τε ὡς τὸν Οὔαρον ἔπεμπε γράμματα καὶ τὸ σύνηθες οὐκ ἀνίει κελεύων ἐκ τοῦ ὀξέος βοηθεῖν, ὡς κινδύνου μεγίστου τὸ ἐγκαταλειφθὲν στράτευμα περιεσχηκότος διὰ τὸ μὴ ἐς μακρὰν ἐλπίζειν κατακοπήσεσθαι ληφθέντας αὐτούς. αὐτὸς δὲ τοῦ φρουρίου τὸν ὑψηλότατον τῶν πύργων καταλαβόμενος Φασάηλον ἐπὶ τιμῇ τοῦ Ἡρώδου ἀδελφοῦ Φασαήλου ᾠκοδομημένον τε καὶ οὕτως εἰρημένον τελευτῆς ὑπὸ Παρθυαίων αὐτῷ γενομένης, κατέσειε τοῖς Ῥωμαίοις ἐπεξιέναι τοῖς Ἰουδαίοις, αὐτὸς μὲν οὐδ’ εἰς τοὺς φίλους τολμῶν κατιέναι, τοὺς δ’ ἄλλους προαποθνήσκειν αὐτοῦ τῆς πλεονεξίας δικαιῶν. τολμησάντων δ’ εἰς τὴν ἔξοδον τῶν Ῥωμαίων μάχη συνῄει καρτερά, καὶ οἱ Ῥωμαῖοι πολλῶν μὲν ἔργων ἐκράτουν, οὐ μὴν τὰ φρονήματά γε τοῖς Ἰουδαίοις ἔκαμνε τῇ ὄψει τοῦ δεινοῦ πολλῶν αὐτοῖς πεπτωκότων, περιοδεύσαντες δ’ ἀνίασιν ἐπὶ τὰς στοάς, αἵπερ ἦσαν τοῦ ἱεροῦ τὸν ἔξω περίβολον περιέχουσαι, καὶ πολλοῖς ἀμάχου γενομένης λίθους τε ἠφίεσαν τοὺς μὲν ἐκ χειρὸς ὑπάραντες, οὓς δὲ σφενδονῶν, ἀθληταὶ τρόπου τοιαύτης μάχης ὄντες. καὶ οἱ τοξόται πάντες παρατεταγμένοι μεγάλα ἔβλαπτον τοὺς Ῥωμαίους διὰ τὸ ὑπερδέξιοί τε εἶναι καὶ ἐπιχειρεῖσθαι μὲν ἄποροι διὰ τὸ ἀνέφικτον τοῖς εἰσακοντίζειν πειρωμένοις εἶναι, ῥᾴους δὲ κρατεῖσθαι τοὺς πολεμίους ἔχοντες. καὶ πολὺν μὲν χρόνον ἡ μάχη συνέστη τοιάδε οὖσα. ἔπειτα Ῥωμαῖοι δεινῶς φέροντες τοῖς δρωμένοις πῦρ ἐνιᾶσιν ταῖς στοαῖς λαθόντες Ἰουδαίων τοὺς ἀναβεβηκότας ἐπ’ αὐταῖς. καὶ τὸ πῦρ ὑπό τε πολλῶν προστεθειμένον καὶ μετὰ τῶν ἐγείρειν φλόγα δυναμένων ἥπτετο τοῦ ὀρόφου ᾗ τάχος. ὁ δὲ ξύλωσιν παρέχων πίσσης τε καὶ κηροῦ πλέον ἔτι δὲ χρυσὸν ἐπαληλιμμένον εὐθέως ήκειν, ἔργα τε μεγάλα ἐκεῖνα καὶ ἀξιολογώτατα ἠφανίζετο. καὶ τοὺς ὑπὲρ τῶν στοῶν ὄλεθρος οὗτος ἀπροσδόκητος κατέλαβεν· οἱ μὲν γὰρ τοῦ ὀρόφου καταρραγέντος συγκατεφέροντο αὐτῷ, τοὺς δὲ περισταδὸν ἔβαλλον οἱ πολέμιοι· πολλοὶ δὲ ἀπορίᾳ σωτηρίας τε καὶ ἐκπλήξει κακοῦ τοῦ περιεστηκότος, οἱ μὲν εἰς τὸ πῦρ ἵεσαν αὑτούς, οἱ δὲ καὶ τοῖς ξίφεσι χρώμενοι διάδρασιν αὐτοῦ ἐποιοῦντο, ὁπόσοι δὲ εἰς τὸ κατόπιν χωρήσαντες ὁδῷ ᾗ ἀναβεβήκεσαν ἐσώζοντο, οἱ Ῥωμαῖοι πάντας ἔκτεινον γυμνούς τε ὄντας καὶ τὰ φρονήματα ἐκλελυμένους, οὐδὲν τῆς ἀπονοίας διὰ τὸ ἄνοπλον βοηθεῖν δυναμένης. ἐσώθη τε τῶν ἀνελθόντων ἐπὶ τὸ τέγος οὐδ’ ὁστισοῦν. καὶ οἱ Ῥωμαῖοι διὰ τοῦ πυρὸς ᾗ παρείκοι ὠσθέντες ἐκράτουν τοῦ θησαυροῦ, καθ’ ὃν ἱερὰ ἦν χρήματα. καὶ διεκλάπη μὲν πολλὰ ὑπὸ τῶν στρατιωτῶν, Σαβῖνος δὲ περιεποίησεν εἰς τὸ φανερὸν τετρακόσια τάλαντα.", "st": "17.10.2"}, {"sp": "N", "t": "Ἰουδαίους δὲ ἐλύπει μὲν τὸ πάθος τῶν φίλων, οἳ ἐν τῇδε ἔπεσον τῇ μάχῃ, ἐλύπει δὲ καὶ τῶν ἀναθημάτων ἡ ἀφαίρεσις, οὐ μὴν ἀλλ’ ὅπερ αὐτῶν ἐτύγχανεν συνεστραμμένον καὶ μαχιμώτατον τούτῳ ἐμπεριέχοντες τὸ βασίλειον ἠπείλουν πῦρ τε ἐνήσειν αὐτῷ καὶ πάντας κτείνειν, κελεύοντες ᾗ τάχος ἀπιέναι καὶ πειθομένοις ὑπισχνούμενοι ἄδειαν καὶ Σαβίνῳ σὺν αὐτοῖς. καὶ τῶν βασιλικῶν τὸ πλεῖστον ηὐτομολήκεσαν σὺν αὐτοῖς, Ῥοῦφος δὲ καὶ Γρᾶτος τρισχιλίους τὸ μαχιμώτατον τοῦ Ἡρώδου στρατεύματος ἔχοντες ἄνδρας τοῖς σώμασι δραστηρίους Ῥωμαίοις προστίθενται. καί τι καὶ ἱππικὸν ἦν τῶν ὑπὸ τῷ Ῥούφῳ τεταγμένων, ὃ καὶ αὐτὸ προσθήκη τῶν Ῥωμαίων ἐγεγόνει. Ἰουδαίοις δὲ οὐκ ἠμέλητο ἡ πολιορκία, ἀλλὰ καὶ τὰ τείχη μετήλλευον καὶ τοῖς μεταβαλλομένοις ἐκέλευον μὴ ἐμποδισταῖς εἶναι τοῦ ἀποληψομένου χρόνῳ παροῦσαν αὐτοῖς ἐλευθερίαν τὴν πάτριον. Σαβίνῳ μὲν οὖν εὐκτὸν ἀπιέναι μετὰ τῶν στρατιωτῶν, πιστεύειν δ’ οὐχ οἷός τε ἦν διὰ τὰ πεπραγμένα καὶ τὸ λίαν εὔγνωμον τῶν πολεμίων ἐπ’ ἀποτροπῇ τοῦ κατασταθησομένου εἶχεν, ἅμα δὲ καὶ τὸν Οὔαρον ἥξειν προσδοκῶν ὑπέμενε τὴν πολιορκίαν.", "st": "17.10.3"}, {"sp": "N", "t": "Ἐν τούτῳ δὲ καὶ ἕτερα μυρία θορύβων ἐχόμενα τὴν Ἰουδαίαν κατελάμβανεν πολλῶν πολλαχόσε οἳ κατ’ οἰκείων ἐλπίδας κερδῶν καὶ Ἰουδαίων ἔχθρας ἐπὶ τὸ πολεμεῖν ὡρμημένων· δισχίλιοι μὲν τῶν ὑφ’ Ἡρώδῃ ποτὲ στρατευσαμένων καὶ ἤδη καταλελυκότες ἐν αὐτῇ Ἰουδαίᾳ συστάντες προσεπολέμουν τοῖς βασιλικοῖς ἀντιστατοῦντος αὐτοῖς Ἀχιάβου τοῦ Ἡρώδου ἀνεψιοῦ, καὶ τῶν μὲν πεδίων εἰς τὰ μετέωρα ἀνεωσμένου δι’ ἐμπειρίαν τὴν εἰς τὰ πολεμικὰ τῶν ἀνδρῶν, ταῖς δὲ δυσχωρίαις σώζοντος ὁπόσα δυνατά.", "st": "17.10.4"}, {"sp": "N", "t": "Ἰούδας δὲ ἦν Ἐζεκίου τοῦ ἀρχιλῃστοῦ υἱὸς ἐπὶ μέγα δυνηθέντος ὑφ’ Ἡρώδου δὲ μεγάλοις ληφθέντος πόνοις. οὗτος οὖν ὁ Ἰούδας περὶ Σέπφωριν τῆς Γαλιλαίας συστησάμενος πλῆθος ἀνδρῶν ἀπονενοημένων ἐπιδρομὴν τῷ βασιλείῳ ποιεῖται καὶ ὅπλων κρατήσας ὁπόσα αὐτόθι ἀπέκειτο ὥπλιζε τοὺς περὶ αὐτὸν καὶ ἀποφέρεται χρήματα ὁπόσα κατελήφθη αὐτόθι, φοβερός τε ἅπασιν ἦν ἄγων καὶ φέρων τοὺς προστυγχάνοντας ἐπιθυμίᾳ μειζόνων πραγμάτων καὶ ζηλώσει βασιλείου τιμῆς, οὐκ ἀρετῆς ἐμπειρίᾳ τοῦ δὲ ὑβρίζειν περιουσίᾳ κτήσεσθαι προσδοκῶν τὸ ἐντεῦθεν γέρας.", "st": "17.10.5"}, {"sp": "N", "t": "Ἦν δὲ καὶ Σίμων δοῦλος μὲν Ἡρώδου τοῦ βασιλέως, ἄλλως δὲ ἀνὴρ εὐπρεπὴς καὶ μεγέθει καὶ ῥώμῃ σώματος ἐπὶ μέγα προύχων τε καὶ πεπιστευμένος. οὗτος ἀρθεὶς τῇ ἀκρισίᾳ τῶν πραγμάτων διάδημά τε ἐτόλμησε περιθέσθαι, καί τινος πλήθους συστάντος καὶ αὐτὸς βασιλεὺς ἀναγγελθεὶς μανίᾳ τῇ ἐκείνων καὶ εἶναι ἄξιος ἐλπίσας παρ’ ὁντινοῦν τό τε ἐν Ἱεριχοῦντι βασίλειον πίμπρησιν δι’ ἁρπαγῆς ἄγων τὰ ἐγκατειλημμένα, πολλάς τε καὶ ἄλλας τῶν βασιλικῶν οἰκήσεων πολλαχοῦ τῆς χώρας πῦρ ἐνιεὶς ἠφάνιζεν, τοῖς συνεστηκόσιν λείαν ἄγειν τὰ ἐγκαταλελειμμένα ἐπιτρέπων. ἐπέπρακτο δ’ ἄν τι μεῖζον ὑπ’ αὐτοῦ μὴ ταχείας ἐπιστροφῆς γενομένης· ὁ γὰρ Γρᾶτος ὁ τῶν βασιλικῶν στρατιωτῶν Ῥωμαίοις προστεθειμένος μεθ’ ἧς εἶχεν δυνάμεως ὑπαντιάζει τὸν Σίμωνα, καὶ μάχης αὐτοῖς μεγάλης ἐπὶ πολὺ γενομένης τό τε πολὺ τῶν Περαίων ἀσύντακτοι ὄντες καὶ τόλμῃ μᾶλλον ἢ ἐπιστήμῃ μαχόμενοι ἐφθάρησαν, καὶ αὐτοῦ Σίμωνος διά τινος φάραγγος σώζοντος αὑτὸν Γρᾶτος ἐντυχὼν τὴν κεφαλὴν ἀποτέμνει. κατεπρήσθη δὲ καὶ τὰ ἐπ’ Ἰορδάνῃ ποταμῷ ἐν Ἀμμάθοις βασίλεια ὑπό τινων συστάντων ἀνδρῶν Σίμωνι παραπλησίων. οὕτως πολλὴ ἀφροσύνη ἐνεπολίτευσε τῷ ἔθνει διὰ τὸ βασιλέα μὲν οἰκεῖον οὐκ εἶναι τὸν καθέξοντα τὸ πλῆθος ἀρετῇ, τοὺς δ’ ἀλλοφύλους ἐπελθόντας σωφρονιστὰς τοῦ μὴ στασιάσοντος τῶν ἀνθρώπων ὑπέκκαυμα αὐτῶν διά τε τοῦ ὑβρίζειν καὶ πλεονεκτεῖν γενέσθαι.", "st": "17.10.6"}, {"sp": "N", "t": "Ἐπεὶ καὶ Ἀθρόγγης ἀνὴρ οὔτε προγόνων ἐπιφανὴς ἀξιώματι οὔτε ἀρετῆς περιουσίᾳ ἤ τινων πλήθει χρημάτων, ποιμὴν δὲ καὶ ἀνεπιφανὴς τοῖς πᾶσιν εἰς τὰ πάντα ὤν, ἄλλως δὲ μεγέθει σώματος καὶ τῇ κατὰ χεῖρας ἀλκῇ διαπρέπων, ἐτόλμησεν ἐπὶ βασιλείᾳ φρονῆσαι τῷ κτώμενόν τε αὐτὴν ἡδονῆς πλέον ὑβρίσαι καὶ θνήσκων οὐκ ἐν μεγάλοις τίθεσθαι τῆς ψυχῆς τὸ ἐπὶ τοιοῖσδε ἀνάλωμα γενησόμενον. ἦσαν δὲ αὐτῷ καὶ ἀδελφοὶ τέσσαρες μεγάλοι τε καὶ αὐτοὶ καὶ ἐπὶ μέγα προύχειν τῇ κατὰ χεῖρας ἀρετῇ πεπιστευμένοι, πρόεχμα εἶναι τῆς καθέξεως τῆς βασιλείας δοκοῦντες, λόχου τε αὐτῶν ἦρχεν ἕκαστος· συλλέγεται γὰρ μεγάλη πληθὺς πρὸς αὐτούς. καὶ οἵδε μὲν στρατηγοὶ ἦσαν καὶ ὑπεστράτευον αὐτῷ ὁπόσα εἰς τὰς μάχας φοιτῶντες δι’ αὐτῶν, ὁ δὲ διάδημα περιθέμενος βουλευτήριόν τε ἦγεν ἐπὶ τοῖς ποιητέοις καὶ τὰ πάντα γνώμῃ ἀνακείμενα εἶχεν τῇ αὐτοῦ. διέμενέ τε ἐπὶ πολὺ τῷδε τῷ ἀνδρὶ ἡ ἰσχὺς βασιλεῖ τε κεκλημένῳ καὶ ἃ πράσσειν ἐθέλοι μὴ ἀποστερουμένῳ, φόνῳ τε καὶ αὐτὸς καὶ οἱ ἀδελφοὶ ἦσαν ἐπὶ μέγα προσκείμενοι Ῥωμαίων τε καὶ βασιλικῶν μίσει πολιτεύοντες ὁμοίως πρὸς ἀμφοτέρους, τοῦτο μὲν ὕβρει ᾗ χρήσαιντο ἐπὶ τῆς Ἡρώδου ἀρχῆς, Ῥωμαίους δὲ ὧν τὸ παρὸν ἔδοξαν ἀδικεῖν. προϊόντος δὲ χρόνου καὶ ἐπὶ πλέον ὁμοίως ἐξηγριώθησαν διάφευξίς τε οὐκ ἦν τοῖς πᾶσιν ἐμπεσεῖν, τὰ μὲν κέρδους ἐλπίδι, τὰ δὲ καὶ συνηθείᾳ τοῦ φονεύειν. ἐπιτίθενται δέ ποτε καὶ Ῥωμαίων λόχῳ κατὰ Ἐμμαοῦντα, οἳ σῖτόν τε καὶ ὅπλα τῆς στρατιᾶς ἔφερον. καὶ περιστάντες Ἄρειον μὲν τὸν ἑκατόνταρχον, ὃς ἡγεῖτο τοῦ παντὸς καὶ τεσσαράκοντα τῶν περὶ αὐτὸν πεζῶν τοὺς κρατίστους κατηκόντισαν. οἱ δὲ λοιποὶ δείσαντες πρὸς τὸ πάθος αὐτῶν Γράτου σὺν τοῖς βασιλικοῖς, οἳ περὶ αὐτὸν ἦσαν, σκέπης αὐτοῖς γενομένης σώζονται τοὺς νεκροὺς καταλιπόντες. καὶ πολὺν μὲν τοιουτοτρόποις χρώμενοι χρόνον μάχαις Ῥωμαίους τε παρελύπησαν οὐκ εἰς ὀλίγα καὶ τὸ ἔθνος ἐκάκωσαν ἐπὶ μέγα. χειροῦται δὲ αὐτῶν χρόνῳ ὕστερον ὁ μὲν Γράτῳ συμβαλὼν ὁ δὲ Πτολεμαίῳ, καὶ τὸν πρεσβύτατον Ἀρχελάου λαβόντος ὁ τελευταῖος πάθει τε τῷ ἐκείνου λελυπημένος καὶ ἄπορον ἐπὶ πλέον ὁρῶν τὴν σωτηρίαν ὑπὸ μονώσεως καὶ καμάτου πολλοῦ ψιλωθεὶς τῆς δυνάμεως ἐπὶ δεξιαῖς καὶ πίστει τοῦ θείου Ἀρχελάῳ παραδίδωσιν αὑτόν. καὶ τάδε μὲν ὕστερον γίνεται.", "st": "17.10.7"}, {"sp": "N", "t": "Λῃστηρίων δὲ ἡ Ἰουδαία πλέως ἦν, καὶ ὃς παρατύχοι τινῶν οἳ συστασιάσοιεν αὐτῷ βασιλεὺς προϊστάμενος ἐπ’ ὀλέθρῳ τοῦ κοινοῦ ἠπείγετο, ὀλίγα μὲν καὶ ἐπ’ ὀλίγοις Ῥωμαίοις λυπηροὶ καθιστάμενοι, τοῦ δὲ ὁμοφύλου φόνον ἐπὶ μήκιστον ἐμποιοῦντες.", "st": "17.10.8"}, {"sp": "N", "t": "Οὔαρος δὲ ἐπειδὴ τὸ πρῶτον πυνθάνεται [τὰ πεπραγμένα] Σαβίνου γράψαντος πρὸς αὐτόν, δείσας περὶ τοῦ τάγματος δύο τὰ λοιπὰ ἀναλαβών, τρία γὰρ ἐπὶ Συρίας τὰ πάντα ἦν, καὶ ἴλας ἱππέων τέσσαρας ὁπόσα τε ἐπικουρικὰ καὶ οἱ βασιλεῖς οἵ τινες τετράρχαι τότε παρεῖχον, ἠπείγετο βοηθεῖν τοῖς ἐν Ἰουδαίᾳ τότε πολιορκουμένοις. εἴρητο δὲ πᾶσιν εἰς Πτολεμαΐδα ἐπείγεσθαι ὁπόσοι προεξεπέμποντο. διδόασί τε αὐτῷ καὶ Βηρύτιοι διιόντι αὐτῶν τὴν πόλιν ἐπικούρους πεντακοσίους καὶ χιλίους, πέμπει δὲ καὶ Ἀρέτας ὁ Πετραῖος ἔχθει τῷ Ἡρώδου φιλίαν τῶν Ῥωμαίων κτώμενος οὐκ ὀλίγην χεῖρα πεζῶν καὶ ἱππέων. σταθείσης δ’ ἐν Πτολεμαΐδι πάσης ἤδη τῆς δυνάμεως μέρος τι ταύτης τῷ υἱῷ παραδοὺς [καὶ] ἑνὶ τῶν αὐτοῦ φίλων Γαλιλαίους ἐξέπεμπεν πολεμεῖν, οἳ ὑπὲρ τῆς Πτολεμαΐδος ἐχόμενοι κατοικοῦσιν. ὃς ἐμβαλὼν τούς τε ἀντικαταστάντας εἰς μάχην τρέπεται καὶ Σέπφωριν ἑλὼν τοὺς μὲν οἰκήτορας ἠνδραποδίσατο, τὴν δὲ πόλιν ἐνέπρησεν. αὐτὸς δὲ Οὔαρος ἐπὶ Σαμαρείας τῷ παντὶ στρατῷ προιὼν τῆς μὲν πόλεως ἀπέσχετο διὰ τὸ ἀνέγκλητον ἐπὶ τοῖς νεωτερισμοῖς εἶναι, στρατοπεδεύεται δὲ ἔν τινι κώμῃ Πτολεμαίου κτήματι, Ἀροὺς ὄνομα αὐτῇ. καὶ οἱ Ἄραβες μίσει τῷ Ἡρώδου ἐμπιπρᾶσιν αὐτὴν ἐχθρῶς καὶ πρὸς φίλους τοὺς ἐκείνου ἔχοντες. κἀνθένδε προϊόντες Σαμφὼ κώμην ἑτέραν διήρπασάν τε οἱ Ἄραβες καὶ ἔκαυσαν πάνυ ἐρυμνὴν οὖσαν, καὶ ἔφυγεν ἐν τῇ προόδῳ οὐδὲν αὐτούς, ἀλλὰ πυρὸς καὶ φόνου τὰ πάντα μεστὰ ἦν. πίμπραται δὲ καὶ Ἐμμαοῦς Οὐάρου κελεύσαντος ἐπ’ ἐκδικίᾳ τῶν συντετελευτηκότων προεκλειφθεῖσα ὑπὸ τῶν οἰκητόρων. ἐντεῦθεν δὲ καὶ Ἱεροσολύμοις ἤδη συνῆπτε, καὶ Ἰουδαίων οἱ κατὰ πολιορκίαν τοῦ τάγματος τῇδε στρατοπεδευόμενοι τὴν ὄψιν τῆς προσόδου τῶν στρατευμάτων οὐχ ὑπομείναντες ᾤχοντο ἡμίεργον τὴν πολιορκίαν καταλιπόντες. οἱ δ’ ἐν τοῖς Ἱεροσολύμοις Ἰουδαῖοι δεινῶς τοῦ Οὐάρου σφίσιν ἐγκαλοῦντος ἀπελύοντο τὰς αἰτίας, ὡς τῆς μὲν συνόδου τῆς πληθύος διὰ τὴν ἑορτὴν γενομένης, τοῦ δὲ πολέμου μηδαμὰ γνώμῃ τῇ αὐτῶν, τόλμῃ δὲ τῶν ἐπηλύδων συνελθόντες αὐτοῖς καὶ συμπολιορκηθέντες Ῥωμαίοις μᾶλλον ἢ πολιορκεῖν προθυμίαν σχόντες. προαπηντήκασιν δὲ τῷ Οὐάρῳ Ἰώσηπός τε ἀνεψιὸς Ἡρώδου βασιλέως Γρᾶτος τε καὶ Ῥοῦφος τοὺς ὑπ’ αὐτοῖς τῶν στρατιωτῶν ἄγοντες καὶ τῶν Ῥωμαίων οἱ πολιορκούμενοι. Σαβῖνος δὲ οὐκ ἀφίκετο Οὐάρῳ εἰς ὄψιν, ἀλλ’ ὑπεξῆλθεν τῆς πόλεως ἐπὶ θάλασσαν.", "st": "17.10.9"}, {"sp": "N", "t": "Οὔαρος δὲ κατὰ τὴν χώραν πέμψας τοῦ στρατοῦ μέρος ἐπεζήτει τοὺς αἰτίους τῆς ἀποστάσεως. καὶ σημαινομένων τοὺς μὲν ἐκόλασεν ὡς αἰτιωτάτους, εἰσὶ δ’ οὓς καὶ ἀφῆκεν· ἐγίνοντο δὲ οἱ διὰ ταύτην τὴν αἰτίαν σταυρωθέντες δισχίλιοι. μετὰ δὲ τοῦτο τὴν μὲν αὐτοῦ στρατιὰν ἀποπέμπεται, χρήσιμον μὲν ὁρῶν ἐπ’ οὐδαμοῖς οὖσαν πράγμασιν· πολλὰ δὲ ἠτάκτητο αὐτοῖς καὶ παρήκουστο τῶν δογμάτων καὶ ὧν ἠξίου Οὔαρος ἐφέσει κερδῶν, ἃ ἐκ τοῦ κακουργεῖν περιεγίνοντο αὐτοῖς. αὐτὸς δὲ μυρίους Ἰουδαίους συνεστηκέναι πυνθανόμενος ἠπείγετο εἰς κατάληψιν αὐτῶν. οἱ δὲ οὐδ’ ἧκον εἰς χεῖρας, ἀλλὰ παρέδοσαν αὑτοὺς γνώμῃ τῇ Ἀχιάβου συνελθόντες. καὶ Οὔαρος τῷ πλήθει συγχωρῶν τὰς αἰτίας τῆς ἀποστάσεως ἔπεμπεν ἐπὶ Καίσαρα ὁπόσοι ἡγεμόνες ἦσαν αὐτῶν. Καῖσαρ δὲ τοὺς μὲν αὐτῶν πολλοὺς διῆκεν, ὁπόσοι δὲ συγγενεῖς ὄντες Ἡρώδου συνεστράτευον αὐτοῖς τούσδε ἐκόλασεν μόνους, εἰ μηδὲν φροντίσαντες τοῦ δικαίου κατὰ τῶν οἰκείων ἐστράτευον.", "st": "17.10.10"}, {"sp": "N", "t": "Οὔαρος μὲν δὴ ταῦτα καταστησάμενος καὶ φρουρὰν Ἱεροσολύμων τὸ καὶ πρότερον καταλιπὼν τάγμα ἐπ’ Ἀντιοχείας ἠπείγετο. Ἀρχελάῳ δ’ ἐπὶ Ῥώμης ἑτέρων πραγμάτων ἐφύοντο ἀρχαὶ κατὰ τοιαύτας αἰτίας. ἀφίκετο εἰς τὴν Ῥώμην πρεσβεία Ἰουδαίων Οὐάρου τὸν ἀπόστολον αὐτῶν τῷ ἔθνει ἐπικεχωρηκότος ὑπὲρ αἰτήσεως αὐτονομίας. καὶ ἦσαν οἱ μὲν πρέσβεις οἱ ἀποσταλέντες γνώμῃ τοῦ ἔθνους πεντήκοντα, συνίσταντο δὲ αὐτοῖς τῶν ἐπὶ Ῥώμης Ἰουδαίων ὑπὲρ ὀκτακισχίλιοι. Καίσαρός τε συνέδριον φίλων τε τῶν αὐτοῦ καὶ Ῥωμαίων τῶν πρώτων συνάγοντος ἐν ἱερῷ Ἀπόλλωνος μεγάλοις τέλεσιν ὑπ’ αὐτοῦ ἱδρυμένῳ, οἱ μὲν πρέσβεις μετὰ τοῦ πλήθους τῶν αὐτόθι Ἰουδαίων ἀφικνοῦνται, Ἀρχέλαος δὲ μετὰ τῶν φίλων. ὁπόσοι δὲ συγγενεῖς τοῦ βασιλέως ἦσαν Ἀρχελάῳ μὲν συντετάχθαι διὰ μῖσος τὸ πρὸς αὐτὸν ὑστέρουν, τοῖς δὲ πρέσβεσιν ὁμοψηφεῖν κατ’ αὐτοῦ δεινὸν ἡγοῦντο ἐν αἰσχύνῃ τῇ αὐτῶν οἰόμενοι γενήσεσθαι παρὰ Καίσαρι κατ’ ἀνδρὸς οἰκείου τοιάδε πράσσειν προθυμεῖσθαι. παρῆν δὲ ἤδη καὶ Φίλιππος ἀπὸ Συρίας ἐξοτρύναντος αὐτὸν Οὐάρου τὸ μὲν κεφάλαιον ἐπὶ συνηγορίᾳ τοῦ ἀδελφοῦ, πάνυ γὰρ εὐνόει Οὔαρος αὐτῷ, γινομένης δὲ τῇ βασιλείᾳ μεταπτώσεως, καὶ τάδε ὑπώπτευεν Οὔαρος νέμησιν αὐτῆς γενήσεσθαι διὰ τὸ πολλοὺς εἶναι τοὺς αὐτονομίας γλιχομένους, οὐχ ὑστεριῶν τοῦ κἂν αὐτὸς μοῖραν αὐτῆς τινα φέρεσθαι.", "st": "17.11.1"}, {"sp": "N", "t": "Λόγου οὖν τοῖς Ἰουδαίων πρέσβεσι δοθέντος, οἳ ἐπὶ καταλύσει τῆς βασιλείας ἤλπιζον λέγειν, ἐπὶ κατηγορίᾳ τῶν Ἡρώδου παρανομιῶν τρέπονται, βασιλέα μὲν ὀνόματι ἀποφαίνοντες αὐτόν, τῶν δ’ ἐν ταῖς τυραννίσιν ἑκάστης τὸ ἀνήκεστον ἀναδεξάμενον εἰς ταὐτὸν ἐπ’ ὀλέθρῳ τῶν Ἰουδαίων συνθέντα χρῆσθαι τὰ πολλὰ καὶ φύσει τῇ αὐτοῦ προσκαινουργεῖν οὐκ ἀπηλλαγμένον. πολλῶν γοῦν ὄντων, οἳ ὀλέθροις ἀπολώλοιεν οὐχ ἱστορήσειν πω πρότερον, πολλῷ δὲ δυστυχεστέρους πάθους ἐκείνων τοὺς ζῶντας εἶναι, οὐ μόνον ὧν ὄψει καὶ διανοίᾳ ἐπ’ αὐτοῖς ἀνιαθεῖεν, ἀλλὰ καὶ ὧν ταῖς οὐσίαις. πόλεις τε τὰς μὲν περιοικίδας καὶ ὑπὸ ἀλλοφύλων οἰκουμένας κοσμοῦντα ῶν ἐκ παύσασθαι καὶ καταλύσεώς τε καὶ ἀφανισμῷ τῶν ἐν τῇ ἀρχῇ αὐτοῦ κατῳκημένων. πενίας δὲ ἀπόρου τὸ ἔθνος ἀναπεπληκέναι σὺν ὀλίγοις εὔδαιμον παρειληφότα, τῶν τε εὐπατριδῶν ὁπότε κτείνειεν αὐτοὺς ἐπ’ ἀλόγοις αἰτίαις τὰς οὐσίας ἀποφερόμενον καὶ οἷς συγχωρήσειε τὴν ἀηδίαν τοῦ ζῆν ψίλωσιν χρημάτων καταδικάζοντα. καὶ χωρὶς μὲν πράσσεσθαι φόρους ἐπιβαλλομένους ἑκάστοις τὸ ἐπ’ ἔτος, χωρὶς δὲ εὐπορίας εἶναι παρακαταβολὰς αὐτῷ τε καὶ οἰκείοις καὶ φίλοις καὶ τῶν δούλων οἳ ἐπ’ ἐκπράξει τῶν φόρων ἐξίοιεν διὰ τὸ μὴ εἶναι κτήσει τοῦ ἀνυβρίστως μηδ’ ὅπως μηδ’ ἀργυρίων διδομένων. παρθένων μέντοι φθορὰς καὶ γυναικῶν αἰσχύνας, ὁπόσας ἐπὶ παροινίᾳ καὶ ἀπὸ τοῦ ἀνθρωπείου δρώμενα σιγᾶν διὰ τὸ ἡδονὴν ἴσην εἶναι τοῖς πεπονθόσι τοῦ μὴ γεγονέναι τὴν ἐκ τοῦ ἀνέκπυστα αὐτὰ εἶναι· τοσήνδε Ἡρώδην ἐπεισάγεσθαι τὴν ὕβριν αὐτοῖς, ὁπόσην οὐδ’ ἂν θηρίον ἀνθρώπων ἐπιστατεῖν δυνάμεως αὐτῷ παραγενομένης. πολλῶν γοῦν ἀναστάσεων καὶ μεταστάσεων παραλαβουσῶν τὸ ἔθνος οὐδεμίαν ἱστορεῖσθαι πώποτε τοιάνδε δυστυχίαν ἐπελθοῦσαν αὐτῷ, παράδειγμά τε κακώσεως ἣν αὐτῷ Ἡρώδης ἐπετίθει τὸ ἔθνος· καὶ ταῦτ’ εἰκότως ἂν γενέσθαι τὸ ἀσμένως Ἀρχέλαον βασιλέα προσειπεῖν οἰήσει τοῦ πάντ’ ὅντιν’ οὖν τὸν ἐπὶ τὴν βασιλείαν ἐσόμενον Ἡρώδου μετριώτερον φαίνεσθαι, καὶ τόν τε πατέρα συνολοφύρεσθαι αὐτῷ θεραπεύοντας, εἴ γε μετρίου τυγχάνειν δυνηθεῖεν, καὶ τἆλλα οἰκειουμένους. τοῦ δὲ δείσαντος μὴ οὐχὶ Ἡρώδου γνήσιος πιστεύοιτο υἱός, οὐδὲν εἰς ἀναβολὰς ἀλλ’ ἐκ τοῦ ὀξέος ἐπάξειν ἂν τῷ ἔθνει τὴν διάνοιαν αὐτοῦ καὶ ταῦτα μηδέπω τέλεον κρατυνάμενον ἡγεμονίαν διὰ τὸ ἐπὶ Καίσαρι δοῦναι καὶ μὴ τὴν ἐξουσίαν εἶναι, καὶ παράδειγμα τὴν τῆς εἰς αὖθις ἀρετῆς τιθέναι τοῖς ἀρχθησομένοις μετριότητος καὶ εὐνομίας, ᾗ χρήσαιτο ἂν πρὸς αὐτούς, ἀπὸ τῆς ἐν πρώτοις ἀποδειχθείσης πράξεως ἐπί τε τοῖς πολίταις καὶ τῷ θεῷ τρισχιλίων ὁμοφύλων ἀνδρῶν σφαγὴν ἐν τῷ τεμένει ποιησάμενον. πῶς οὐκ ἂν ἤδη καὶ δικαίῳ μίσει χρῆσθαι κατ’ αὐτῶν πρὸς τῇ λοιπῇ ὠμότητι καὶ ἔγκλημα τῆς ἀντιστάσεως καὶ ἀντιλογίας ἐπὶ τῇ ἀρχῇ προφερόμενον; ἦν δὲ κεφάλαιον αὐτοῖς τῆς ἀξιώσεως βασιλείας μὲν καὶ τοιῶνδε ἀρχῶν ἀπηλλάχθαι, προσθήκη δὲ Συρίας γεγονότες ὑποτάσσεσθαι τοῖς ἐκεῖσε πεμπομένοις στρατηγοῖς· φανερωθήσεσθαι γὰρ οὕτως, εἴτε ἀληθῶς στασιώδεις εἶεν καὶ νεωτερισμοῖς τὰ πολλὰ προσησκημένοι εἴτε καὶ οὔ, μετριωτέρων τυχόντες οἳ ἐπιστήσονται αὐτοῖς.", "st": "17.11.2"}, {"sp": "N", "t": "Τοιαῦτα δὲ τῶν Ἰουδαίων εἰρηκότων Νικόλαος τούς τε βασιλεῖς ἀπήλλασσε τῶν ἐγκλημάτων, Ἡρώδην μὲν διὰ τὸ παρ’ ὃν ἔζη χρόνον τυχεῖν ἀκατηγόρητον· οὐ γὰρ δὴ τοὺς ἐγκαλεῖν ἔχοντας ἐπὶ μετρίοις παρὰ τοῦ ζῶντος τιμωρίαν λαβεῖν δυναμένους ἐπὶ νεκρῷ κατηγορίαν συντιθέναι· τὰ δὲ ὑπ’ Ἀρχελάου πραχθέντα ὕβρει τῇ ἐκείνων ἀνετίθει, οἳ ὀριγνώμενοι πραγμάτων παρὰ τοὺς νόμους καὶ σφαγῆς ἄρξαντες τῶν κωλύειν ὑβρίζοντας προμηθουμένων ἀμύνης γενομένης ἐγκαλοῖεν. ἐνεκάλει δὲ νεωτεροποιίας αὐτοῖς καὶ τοῦ στασιάζειν ἡδονὴν ἀπαιδευσίᾳ τοῦ πείθεσθαι δίκῃ καὶ νομίμοις ὑπὸ τοῦ θέλειν τὰ πάντα νικᾶν. ταῦτα μὲν οὖν Νικόλαος.", "st": "17.11.3"}, {"sp": "N", "t": "Καῖσαρ δ’ ἀκούσας διαλύει μὲν τὸ συνέδριον, ὀλίγων δ’ ἡμερῶν ὕστερον Ἀρχέλαον βασιλέα μὲν οὐκ ἀποφαίνεται, τῆς δ’ ἡμίσεως χώρας ἥπερ Ἡρώδῃ ὑπετέλει ἐθνάρχην καθίσταται, τιμήσειν ἀξιώματι βασιλείας ὑπισχνούμενος, εἴπερ τὴν εἰς αὐτὴν ἀρετὴν προσφέροιτο. τὴν δ’ ἑτέραν ἡμίσειαν νείμας διχῇ δυσὶν Ἡρώδου παισὶν ἑτέροις παρεδίδου Φιλίππῳ καὶ Ἀντίπᾳ τῷ πρὸς Ἀρχέλαον τὸν ἀδελφὸν ἀμφισβητήσαντι περὶ τῆς ὅλης ἀρχῆς. καὶ τούτῳ μὲν ἥ τε Περαία καὶ τὸ Γαλιλαῖον ὑπετέλουν, φορά τε ἦν τάλαντα διακόσια τὸ ἐπ’ ἔτος. Βαταναία δὲ σὺν Τράχωνι καὶ Αὐρανῖτις σύν τινι μέρει οἴκου τοῦ Ζηνοδώρου λεγομένου Φιλίππῳ τάλαντα ἑκατὸν προσέφερεν· τὰ δ’ Ἀρχελάῳ συντελοῦντα Ἰδουμαῖοί τε καὶ Ἰουδαία τό τε Σαμαρειτικόν. τετάρτην μοῖραν οὗτοι τῶν φόρων παραλέλυντο Καίσαρος αὐτοῖς κούφισιν ψηφισαμένου διὰ τὸ μὴ συναποστῆναι τῇ λοιπῇ πληθύι. καὶ ἦσαν πόλεις αἳ Ἀρχελάῳ ὑπετέλουν Στράτωνός τε πύργος καὶ Σεβαστὴ σὺν Ἰόππῃ καὶ Ἱεροσολύμοις· Γάζαν γὰρ καὶ Γάδαρα καὶ Ἵππον, Ἑλληνίδες εἰσὶν πόλεις, ἀπορρήξας αὐτοῦ τῆς ἀκροάσεως Συρίας προσθήκην ποιεῖται. προσῄει δὲ Ἀρχελάῳ φορὰ χρημάτων τὸ κατ’ ἐνιαυτὸν εἰς τάλαντα ἑξακόσια ἐξ ἧς παρέλαβεν ἀρχῆς.", "st": "17.11.4"}, {"sp": "N", "t": "Καὶ τάδε μὲν τοῖς Ἡρώδου υἱέσιν τῶν πατρῴων παρῆν. Σαλώμῃ δὲ πρὸς οἷς ὁ ἀδελφὸς ἐν ταῖς διαθήκαις ἀπονέμει, Ἰάμνεια δὲ ἦν ταῦτα καὶ Ἄζωτος καὶ Φασαηλὶς καὶ ἀργυρίου ἐπισήμου μυριάδες πεντήκοντα, Καῖσαρ χαρίζεται καὶ τὴν ἐν Ἀσκάλωνι βασίλειον οἴκησιν. ἦν δὲ καὶ ταύτῃ πρόσοδος ἐκ πάντων ταλάντων ἑξήκοντα τὸ ἐπ’ ἔτος· καὶ αὐτῆς ὁ οἶκος ἦν ἐν τῇ Ἀρχελάου ἀρχῇ. κομίζονται δὲ καὶ οἱ λοιποὶ τοῦ βασιλέως συγγενεῖς ὁπόσα αἱ διαθῆκαι διηγόρευον. δυοῖν δ’ αὐτοῦ θυγατράσιν παρθένοις χωρὶς ὧν ὁ πατὴρ κατέλιπεν Καῖσαρ ἑκατέρᾳ δωρεὰν ἐπετίθει μυριάδων ἀνὰ πέντε καὶ εἴκοσι ἀργυρίου ἐπισήμου καὶ συνῴκισεν αὐτὰς τοῖς Φερώρου υἱέσιν. χαρίζεται δὲ καὶ ὁπόσα αὐτῷ καταλέλειπτο τοῖς παισὶν τοῦ βασιλέως ὄντα πεντακοσίων ταλάντων καὶ χιλίων, ὀλίγα τῶν σκευῶν ὑπεξελόμενος οὐχ οὕτως μεγέθει τέλους ὡς μνήμῃ τοῦ βασιλέως αὐτῷ κεχαρισμένα.", "st": "17.11.5"}, {"sp": "N", "t": "Τούτων δὲ ταύτῃ διαπεπραγμένων ὑπὸ Καίσαρος νεανίας Ἰουδαῖος μὲν τὸ γένος, ἐπὶ δὲ τῆς Σιδωνίων τεθραμμένος πόλεως παρά τινι τῶν Ῥωμαϊκῶν ἀπελευθέρων εἰσῴκισεν αὑτὸν εἰς τὴν Ἡρώδου συγγένειαν ὁμοιότητι μορφῆς, ἣ πρὸς Ἀλέξανδρον αὐτῷ τὸν ἀνῃρημένον Ἡρώδου υἱὸν ἐμαρτυρεῖτο παρὰ τοῖς θεωροῦσιν. καὶ τοῦτο παρόρμημα ἦν αὐτῷ εἰς τὸ μεταποιεῖσθαι τῆς ἡγεμονίας. καὶ ὁμοπράγμονα παραλαβὼν ὁμόφυλον ἄνδρα, ἔμπειρον δὲ τῶν ἀμφὶ τὸ βασίλειον πονηρόν τε ἄλλως καὶ ταράξαι μεγάλα πράγματα φύσιν ἔχοντα καὶ τοιαύτης κακίας διδάσκαλον αὐτῷ γενόμενον, ἀπέφαινεν αὑτὸν Ἀλέξανδρον καὶ Ἡρώδου παῖδα ὄντα διακεκλεμμένον ὑπὸ τῶν ἀνελεῖν αὐτὸν ἐσταλμένων· κτείναντα γὰρ ἑτέρους, οἳ ἀπατήσειν ἔμελλον τοὺς θεωροῦντας, αὐτόν τε περιποιῆσαι καὶ τὸν ἀδελφὸν Ἀριστόβουλον. καὶ τούτοις αὐτός τε ἀνεπτέρωτο, καὶ τοὺς ἐντυγχάνοντας οὐκ ἀπήλλακτο ἀπατᾶν, ἀλλὰ Κρήτῃ προσενεχθεὶς Ἰουδαίων ὁπόσοις εἰς ὁμιλίαν ἀφίκετο ἐπηγάγετο εἰς πίστιν, καὶ χρημάτων εὐπορηθεὶς δόσει τῇ ἐκείνων ἐπὶ Μήλου διῆρεν. πολὺ πλέονα δὲ ἦν ἐντεῦθεν ὁπόσα αὐτῷ προσῄει χρήματα πίστει τῆς βασιλείου συγγενείας καὶ ἐλπίδι τοῦ ἀπολαβεῖν τὴν πάτριον ἀρχὴν καὶ ἀμείψασθαι τοὺς εὐεργέτας. ἐπὶ Ῥώμης ἠπείγετο παραπομπῇ τῶν ἰδιοξένων, καὶ Δικαιαρχείᾳ προσβαλὼν οὐκ ἠτύχει καὶ τοὺς τῇδε Ἰουδαίους ἀφ’ ὁμοίας ἀπάτης προσαγαγέσθαι, προσῄεσάν τε ὥσπερ βασιλεῖ οἵ τε ἄλλοι καὶ ὁπόσοις ξενία πρὸς Ἡρώδην καὶ εὔνοια ἦν. αἴτιον δὲ ἦν τῶν ἀνθρώπων τὸ ἡδονῇ δεχόμενον τοὺς λόγους σὺν τῷ φερεγγύῳ τῆς μορφῆς· καὶ γὰρ τοῖς πάνυ ὡμιληκόσιν Ἀλεξάνδρῳ πολὺ τὸ πιστὸν ἐνετίθει τοῦ μὴ οὐχ ἕτερος ἀλλ’ αὐτὸς εἶναι, καὶ πρὸς τοὺς πλησίον ὤμνυσαν, ὥστε καὶ προελθόντος εἰς τὴν Ῥώμην λόγου τοῦ περὶ αὐτοῦ πᾶν τὸ τῇδε Ἰουδαίων ἔθνος ὑπαντιάζοντες ἐξῄεσαν τῷ παρὰ δόξαν τῆς σωτηρίας θειάζοντες τὸ ἔργον καὶ χάρμα ποιούμενοι διὰ τὸ μητρῷον αὐτῶν γένος, ὁπότε χωροίη κατὰ τοῦ στενωποῦ διφροφορούμενος· καὶ πάντα βασίλειον περὶ αὐτὸν σχῆμα ἦν ἀναλώμασιν τῶν ἰδιοξένων, μεγάλαι περιστάσεις ἐγίνοντο τῆς πληθύος ἐπιβοήσεις τε εὔφημοι ὁπόσα εἰκὸς τοῖς οὕτω παρ’ ἐλπίδα σωθεῖσιν συντυγχάνειν οὐδὲν ὅ τι οὐκ ἐπράσσετο.", "st": "17.12.1"}, {"sp": "N", "t": "Καίσαρι δὲ ὡς ἀφίκετο ἀγγελία ἡ περὶ αὐτοῦ, ἠπίστει μὲν διὰ τὸ μὴ ἂν ῥᾳδίως ἀπατηθῆναι Ἡρώδην ἐν πράγμασιν ἐπὶ μέγα ἀνήκουσιν αὐτῷ, διδοὺς δὲ τῇ ἐλπίδι Κέλαδον τῶν αὐτοῦ τινὰ ἐξελευθέρων ὡμιληκότα τοῖς μειρακίοις πέμπει κελεύσας ἀγαγεῖν εἰς ὄψιν αὐτῷ τὸν Ἀλέξανδρον. ὁ δὲ ἀνῆγεν οὐδέν τι βελτίων ἐπὶ τῇ κρίσει τῶν πολλῶν γενόμενος. οὐ μὴν Καῖσάρ γε ἠπατᾶτο, ἀλλ’ ἦν μὲν ἐμφερής, οὐ μὴν ὥστε ἀπατῆσαι τοὺς σωφρόνως ἐκλογίζεσθαι δυναμένους· αὐτουργίᾳ τε γὰρ ἐτέτρυτο ὁ ψευδαλέξανδρος καὶ παρὰ τὸ ἐκείνῳ ῥαδαλὸν τοῦ σώματος ὑπὸ τρυφῆς καὶ γενναιότητος συνερχόμενον διὰ τὰ ἐναντία τῷδε ἐπισκληρότερον ἐξεβεβήκει τὸ σῶμα. θεασάμενος οὖν συμπνευσμὸν ἐπὶ ψευδολογίᾳ διδασκάλου καὶ μαθητοῦ καὶ λόγων τολμηρῶν συγκρότησιν, ἐξήταζε περὶ Ἀριστοβούλου, τί καὶ γεγόνοι συνεκκλαπεὶς αὐτῷ, καὶ δι’ ἣν αἰτίαν οὐ παραγεγόνοι μεταποιούμενος τῆς ἀξίας, ἧς προσῆκε τυγχάνειν τοὺς οὕτω γεγονότας; φαμένου δ’ ἐπὶ νήσου τῆς Κυπρίων καταλελεῖφθαι κινδύνων ὑφοράσει τῶν κατὰ θάλασσαν, εἰ περὶ αὐτῷ συσταίη τι δεινόν, μὴ παντελὲς ἐξαλείφοιτο τὸ Μαριάμμης γένος ἀλλὰ περιὼν Ἀριστόβουλος μένοι τοὺς ἐπιβεβουλευκότας, ταῦτα διισχυριζομένου καὶ συνεστῶτος αὐτῷ τοῦ μηχανοποιοῦ τῆς πράξεως Καῖσαρ καταμόνας ἀπολαβὼν τὸ μειράκιον ἀλλὰ σοὶ μισθός, ἔφη, προκείσεται τοῦ μὴ καὶ πρὸς ἐμὲ ἀπάτῃ χρησομένου τὸ μὴ ἀπολούμενον τῆς σωτηρίας· φάθι δή μοι αὐτόν τε ὃς ὢν τυγχάνεις καὶ ὅς σε τοιάδε ᾖξε τολμῆσαι διανοεῖσθαι· μεῖζον γὰρ τὸ ἐπιβούλευμα κακίας ἐγκεχείρηκας χρόνων οὓς γεγονὼς τυγχάνεις. καὶ δή, οὐ γὰρ ἦν ἄλλως πράσσειν, φράζει πρὸς τὸν Καίσαρα τὸ ἐπιβούλευμα, ὅν τε τρόπον καὶ ὑφ’ οὗ τυγχάνοι συγκείμενον. καὶ ὁ Καῖσαρ τὸν μὲν ψευδαλέξανδρον, οὐ γὰρ ἐψεύσατο ὁμολογίαν τὴν πρὸς αὐτόν, δραστήριον ὁρῶν αὐτουργῆσαι τῷ σώματι ἐρέσσειν ἐν τοῖς ναύταις καταλέγει, τὸν δὲ ἀναπείσαντα κτείνει. καταδίκη δ’ ἤρκει Μηλίοις ὁπόσα ἐτετελέκεσαν εἰς τὸν Ψευδαλέξανδρον διακενῆς ἀναλωκέναι. καὶ τὰ μὲν περὶ τὸν ψευδαλέξανδρον τολμηρῶς συντεθέντα οὕτως ἀκλεῶς ἔσχεν.", "st": "17.12.2"}, {"sp": "N", "t": "Ἀρχέλαος δὲ τὴν ἐθναρχίαν παραλαβὼν ἐπεὶ εἰς Ἰουδαίαν ἀφικνεῖται, Ἰωάζαρον τὸν Βοηθοῦ ἀφελόμενος τὴν ἀρχιερωσύνην ἐπικαλῶν αὐτῷ συστάντι τοῖς στασιώταις Ἐλεάζαρον τὸν ἐκείνου ἐπικαθίσταται ἀδελφόν. ἀνοικοδομεῖ δὲ καὶ τὸ ἐν Ἱεριχοῦντι βασίλειον ἐκπρεπῶς, τῶν τε ὑδάτων ὁπόσα Νεαρὰν τὴν κώμην ὠφελεῖ ἐπιρρέοντα ἐξ ἡμισείας ἀπέστρεψεν ἐπαγωγὴν αὐτῷ ποιούμενος τῷ πεδίῳ φοίνιξιν ὑπ’ αὐτοῦ πεφυτευμένῳ, κώμην τε κτίσας Ἀρχελαΐδα ὄνομα αὐτῇ τίθεται. καὶ τοῦ πατρίου παράβασιν ποιησάμενος Γλαφύραν τὴν Ἀρχελάου μὲν θυγατέρα, Ἀλεξάνδρου δὲ τοῦ ἀδελφοῦ γαμετὴν γενομένην, ἐξ οὗ καὶ τέκνα ἦν αὐτῇ, ἀπώμοτον ὂν Ἰουδαίοις γαμετὰς ἀδελφῶν ἄγεσθαι, γαμεῖ. διατρίβει δὲ οὐδὲ ὁ Ἑλεάζαρος ἐν τῇ ἱερωσύνῃ ἐπικατασταθέντος αὐτῷ ζῶντι Ἰησοῦ τοῦ Σεὲ παιδός.", "st": "17.13.1"}, {"sp": "N", "t": "Δεκάτῳ δὲ ἔτει τῆς ἀρχῆς Ἀρχελάου οἱ πρῶτοι τῶν ἀνδρῶν ἔν τε Ἰουδαίοις καὶ Σαμαρεῦσι μὴ φέροντες τὴν ὠμότητα αὐτοῦ καὶ τυραννίδα κατηγοροῦσιν αὐτοῦ ἐπὶ Καίσαρος, καὶ μάλιστα ἐπεὶ ἔγνωσαν αὐτὸν παραβεβηκότα τὰς ἐντολὰς αὐτοῦ, ἵνα ἐπιεικῶς ἀναστραφῇ τὰ πρὸς αὐτούς. ὁ τοίνυν Καῖσαρ ὡς ἤκουσεν, ὀργῇ φέρων τὸν ἐπίτροπον τὸν Ἀρχελάου τῶν ἐν Ῥώμῃ πραγμάτων, Ἀρχέλαος δὲ καὶ τούτῳ ὄνομα ἦν, μετακαλέσας γράφειν μὲν Ἀρχελάῳ ταπεινὸν ἡγεῖται, σὺ δὲ παραχρῆμα, φησίν, πλέων μηδὲν εἰς ἀναβολὰς ἐπαναγαγεῖν αὐτὸν πρὸς ἡμᾶς. καὶ ὃς ἔκπλουν ἐκ τοῦ ὀξέος ποιησάμενος καὶ ἀφικόμενος εἰς Ἰουδαίαν λαμβάνει τὸν Ἀρχέλαον ἐν εὐωχίαις ὄντα μετὰ τῶν φίλων, τήν τε διάνοιαν ἀποσημαίνει τὴν Καίσαρος καὶ ὥρμησεν αὐτὸν εἰς τὴν ἔξοδον. καὶ ὁ Καῖσαρ ἀφικομένου ἐπί τινων κατηγόρων ἀκροᾶται καὶ αὐτοῦ λέγοντος ἐκεῖνον μὲν φυγάδα ἐλαύνει δοὺς οἰκητήριον αὐτῷ Βίενναν πόλιν τῆς Γαλατίας, τὰ δὲ χρήματα ἀπηνέγκατο.", "st": "17.13.2"}, {"sp": "N", "t": "Πρότερον δὲ ἢ κληθεὶς ἐπὶ Ῥώμης ἀνελθεῖν Ἀρχέλαος ὄναρ τοιόνδε ἐκδιηγεῖται τοῖς φίλοις θεασάμενος· ἀστάχυας δέκα τὸν ἀριθμὸν πλέους πυροῦ τὴν ἰδίαν ἀκμὴν ἀπειληφότας δόξα ἦν αὐτῷ βιβρωσκομένους ὑπὸ βοῶν θεωρεῖν. καὶ περιεγρόμενος φέρειν εἰς μέγα δόξαν τὴν ὄψιν αὐτῷ μεταστέλλεται τοὺς μάντεις, οἷς περὶ ὀνειράτων ἦσαν αἱ ἀναστροφαί. σκιδναμένων δὲ ἑτέρων ἐφ’ ἑτέροις, οὐ γὰρ εἰς ἕνα ἔκειτο πᾶσιν ἀφήγησις, Σίμων ἀνὴρ γένος Ἐσσαῖος ἀσφάλειαν αἰτησάμενος, μεταβολὴν πραγμάτων ἔλεγεν Ἀρχελάῳ φέρειν τὴν ὄψιν οὐκ ἐπ’ ἀγαθοῖς πράγμασιν· βόας μὲν γὰρ κακοπαθείας τε ἀποσαφεῖν διὰ τὸ ἔργοις ἐπιταλαιπωρεῖν τὸ ζῷον, μεταβολὰς δὲ αὖ πραγμάτων διὰ τὸ τὴν γῆν πόνῳ τῷ ἐκείνων ἀρουμένην ἐν ταὐτῷ μένειν οὐ δύνασθαι· τοὺς δὲ ἀστάχυας δέκα ὄντας τοσῶνδε ἀριθμὸν ἐνιαυτῶν ὁρίζειν, περιόδῳ γὰρ ἑνὸς παραγίνεσθαι θέρος, καὶ τὸν χρόνον ἐξήκειν Ἀρχελάῳ τῆς ἡγεμονίας. καὶ ὁ μὲν ταύτῃ ἐξηγήσατο τὸν ὄνειρον. πέμπτῃ δὲ ἡμέρᾳ μεθ’ ὃ τὸ πρῶτον αὐτοῦ ἡ ὄψις Ἀρχελάῳ συνῆλθεν ὁ ἀνακαλούμενος Ἀρχέλαος πεμπτὸς εἰς Ἰουδαίαν ἀφίκετο.", "st": "17.13.3"}, {"sp": "N", "t": "Παραπλήσια δὲ καὶ Γλαφύρᾳ τῇ γυναικὶ αὐτοῦ συντυγχάνει βασιλέως Ἀρχελάου θυγατρὶ οὔσῃ, ᾗ καὶ πρότερον εἶπον συνῴκει παρθένον λαβὼν Ἀλέξανδρος Ἡρώδου μὲν υἱὸς Ἀρχελάου δ’ ἀδελφός. ἐπεὶ δὲ συμβαίνει τὸν Ἀλέξανδρον ὑπὸ τοῦ πατρὸς τελευτῆσαι, Ἰόβᾳ τῷ Λιβύων βασιλεῖ γαμεῖται, μεταστάντος δὲ τοῦ Λίβυος χηρεύουσαν ἐν Καππαδοκίᾳ παρὰ τῷ πατρὶ Ἀρχέλαος ἄγεται τὴν συνοῦσαν αὐτῷ Μαριάμμην ἐκβαλών· τοσόσδε τῆς Γλαφύρας ἀνέστρεψεν ἔρως. καὶ συνοικοῦσα τῷ Ἀρχελάῳ τοιόνδε ὄναρ θεᾶται· ἐδόκει τὸν Ἀλέξανδρον ἐπιστάντα θεασαμένη χαίρειν καὶ περιβάλλειν προθύμως, τὸν δὲ κατάμεμψίν τε αὐτῆς ποιεῖσθαι καὶ φάναι· Γλαφύρα, συνηγορεῖς ἄρα λόγῳ, ὃς ἄπιστα ἔλεγεν εἶναι γυναιξίν, εἰ συνομόσασά τέ μοι καὶ συγκατοικισθεῖσα παρθένος παίδων ἡμῖν γεγονότων λήθῃ παραδίδως ἔρωτας τοὺς ἐμοὺς δευτέρων ἐπιθυμίᾳ γάμων. πληθώρα δέ σοι οὐδ’ οὕτως ὕβρεως, ἀλλὰ καὶ τρίτον ἐτόλμησας σαυτῇ παρακατακλῖναι νυμφίον ἀπρεπῶς καὶ ἀναισχύντως ἐπεισιοῦσα οἴκῳ τῷ ἐμῷ, καὶ γάμον συντιθεμένη πρὸς Ἀρχέλαον ἄνδρα μὲν σεαυτῆς ἀδελφὸν δὲ ἡμέτερον. ἀλλ’ οὐκ ἔγωγε λήθην ποιήσομαι εὐνοίας τῆς σῆς, ἀπαλλάξω δέ σε παντὸς τοῦ ὀνειδιοῦντος ἐμὴν ὥσπερ ἦν κατασκευασάμενος. ταῦτα διηγησαμένη πρὸς τὰς συνήθεις τῶν γυναικῶν μετ’ ὀλίγας ἡμέρας τελευτᾷ τὸν βίον.", "st": "17.13.4"}, {"sp": "N", "t": "Ἐγὼ δὲ οὐκ ἀλλότρια νομίσας αὐτὰ τῷδε τῷ λόγῳ εἶναι διὰ τὸ περὶ τῶν βασιλέων αὐτὸν ἐνεστηκέναι καὶ ἄλλως ἐπὶ παραδείγματι φέρειν τοῦ τε ἀμφὶ τὰς ψυχὰς ἀθανασίας ἐμφεροῦς καὶ τοῦ θείου προμηθείᾳ τὰ ἀνθρώπεια περιειληφότος τῇ αὐτοῦ, καλῶς ἔχειν ἐνόμισα εἰπεῖν. ὅτῳ δὲ ἀπιστεῖται τὰ τοιάδε γνώμης ὀνινάμενος τῆς ἑαυτοῦ κώλυμα οὐκ ἂν γένοιτο τῷ ἐπ’ ἀρετὴν αὐτῷ προστιθεμένῳ. τῆς δ’ Ἀρχελάου χώρας ὑποτελοῦς προσνεμηθείσης τῇ Σύρων πέμπεται Κυρίνιος ὑπὸ Καίσαρος ἀνὴρ ὑπατικὸς ἀποτιμησόμενός τε τὰ ἐν Συρίᾳ καὶ τὸν Ἀρχελάου ἀποδωσόμενος οἶκον.", "st": "17.13.5"}], []);})();
